Object.assign(window.OTPU_CODE,{"rtl/exp/vpu_pump/lists/batch.txt": "# multi-user: a batched decode step (opentpu/llm/batch.py: Qwen3 and the Llama-likes; LFM2,\n# Qwen3.5 and Gemma 4 images hold one sequence), B slots at position 544 each, the picks on the\n# device (greedy ARGMAX), fp4 + int8 head, whole model\nb4_q3 --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --batch 4\nb4_q3_novop --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --batch 4 --hack novop\nb4_q3_half --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --batch 4 --hack half\nb4_q3_comp1 --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --batch 4 --hack comp1\n# 8 users in one run at the pumped / MCOLS 8 MXU's rate (the card's MCOLS 4 runs them as two of b4)\nb8_q3 --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --batch 8 --mcols 8\nb8_q3_novop --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --batch 8 --mcols 8 --hack novop\nb8_q3_half --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --batch 8 --mcols 8 --hack half\n# a long context: 4 users at position 4000\nb4k_q3 --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 4000 --batch 4\nb4k_q3_novop --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 4000 --batch 4 --hack novop\nb4k_q3_half --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 4000 --batch 4 --hack half\n", "rtl/exp/vpu_pump/lists/big.txt": "# the card's larger models on zero images (tools/vpu_hack.py cosim: config.json only; a layer prefix,\n# no LM head except the batched step's: its 2- and 4-layer runs' difference), fp4 + int8 head, position 544\n# unless named. rows 1: a one-row run without logits, decode's layers' proxy\nz_q2_r4 zero: models/Qwen3.5-2B rows 4 544 --layers 4\nz_q2_r4_novop zero: models/Qwen3.5-2B rows 4 544 --layers 4 --hack novop\nz_q2_r4_half zero: models/Qwen3.5-2B rows 4 544 --layers 4 --hack half\nz_q2_r4_comp1 zero: models/Qwen3.5-2B rows 4 544 --layers 4 --hack comp1\nz_q2_r4_nose zero: models/Qwen3.5-2B rows 4 544 --layers 4 --hack nose\nz_q2_r4_halfse zero: models/Qwen3.5-2B rows 4 544 --layers 4 --hack halfse\nz_q2_r4_half_halfse zero: models/Qwen3.5-2B rows 4 544 --layers 4 --hack half,halfse\nz_q2_r4m8 zero: models/Qwen3.5-2B rows 4 544 --layers 4 --mcols 8\nz_q2_r4m8_novop zero: models/Qwen3.5-2B rows 4 544 --layers 4 --mcols 8 --hack novop\nz_q2_r4m8_half zero: models/Qwen3.5-2B rows 4 544 --layers 4 --mcols 8 --hack half\nz_q2_r4m8_nose zero: models/Qwen3.5-2B rows 4 544 --layers 4 --mcols 8 --hack nose\nz_q2_r4m8_half_halfse zero: models/Qwen3.5-2B rows 4 544 --layers 4 --mcols 8 --hack half,halfse\nz_q2_r1 zero: models/Qwen3.5-2B rows 1 544 --layers 4\nz_q2_r1_novop zero: models/Qwen3.5-2B rows 1 544 --layers 4 --hack novop\nz_q2_r1_nose zero: models/Qwen3.5-2B rows 1 544 --layers 4 --hack nose\nz_q2_r1_half_halfse zero: models/Qwen3.5-2B rows 1 544 --layers 4 --hack half,halfse\nz_q4_r2 zero: models/Qwen3.5-4B rows 2 544 --layers 4\nz_q4_r2_novop zero: models/Qwen3.5-4B rows 2 544 --layers 4 --hack novop\nz_q4_r2_half zero: models/Qwen3.5-4B rows 2 544 --layers 4 --hack half\nz_q4_r2_nose zero: models/Qwen3.5-4B rows 2 544 --layers 4 --hack nose\nz_q4_r2_halfse zero: models/Qwen3.5-4B rows 2 544 --layers 4 --hack halfse\nz_q4_r2_half_halfse zero: models/Qwen3.5-4B rows 2 544 --layers 4 --hack half,halfse\nz_q4_r1 zero: models/Qwen3.5-4B rows 1 544 --layers 4\nz_q4_r1_novop zero: models/Qwen3.5-4B rows 1 544 --layers 4 --hack novop\nz_q4_r1_nose zero: models/Qwen3.5-4B rows 1 544 --layers 4 --hack nose\nz_sm_r3 zero: models/SmolLM3-3B rows 3 544 --layers 2\nz_sm_r3_novop zero: models/SmolLM3-3B rows 3 544 --layers 2 --hack novop\nz_sm_r3_half zero: models/SmolLM3-3B rows 3 544 --layers 2 --hack half\nz_sm_r3_comp1 zero: models/SmolLM3-3B rows 3 544 --layers 2 --hack comp1\nz_sm_r4m8 zero: models/SmolLM3-3B rows 4 544 --layers 2 --mcols 8\nz_sm_r4m8_novop zero: models/SmolLM3-3B rows 4 544 --layers 2 --mcols 8 --hack novop\nz_sm_r4m8_half zero: models/SmolLM3-3B rows 4 544 --layers 2 --mcols 8 --hack half\nz_sm_b4l2 zero: models/SmolLM3-3B batch 4 544 --layers 2\nz_sm_b4l2_novop zero: models/SmolLM3-3B batch 4 544 --layers 2 --hack novop\nz_sm_b4l2_half zero: models/SmolLM3-3B batch 4 544 --layers 2 --hack half\nz_sm_b4l4 zero: models/SmolLM3-3B batch 4 544 --layers 4\nz_sm_b4l4_novop zero: models/SmolLM3-3B batch 4 544 --layers 4 --hack novop\nz_sm_b4l4_half zero: models/SmolLM3-3B batch 4 544 --layers 4 --hack half\nz_sm_r1k4 zero: models/SmolLM3-3B rows 1 4000 --layers 2\nz_sm_r1k4_novop zero: models/SmolLM3-3B rows 1 4000 --layers 2 --hack novop\nz_sm_r1k4_half zero: models/SmolLM3-3B rows 1 4000 --layers 2 --hack half\nz_sm_r1k4_comp1 zero: models/SmolLM3-3B rows 1 4000 --layers 2 --hack comp1\nz_ge_r4 zero: models/gemma-4-E2B-it rows 4 544 --layers 0,1,2,3,4\nz_ge_r4_novop zero: models/gemma-4-E2B-it rows 4 544 --layers 0,1,2,3,4 --hack novop\nz_ge_r4_half zero: models/gemma-4-E2B-it rows 4 544 --layers 0,1,2,3,4 --hack half\nz_ge_r4_comp1 zero: models/gemma-4-E2B-it rows 4 544 --layers 0,1,2,3,4 --hack comp1\nz_ge_r4m8 zero: models/gemma-4-E2B-it rows 4 544 --layers 0,1,2,3,4 --mcols 8\nz_ge_r4m8_novop zero: models/gemma-4-E2B-it rows 4 544 --layers 0,1,2,3,4 --mcols 8 --hack novop\nz_ge_r4m8_half zero: models/gemma-4-E2B-it rows 4 544 --layers 0,1,2,3,4 --mcols 8 --hack half\nz_ph_r3 zero: models/Phi-4-mini-instruct rows 3 544 --layers 2\nz_ph_r3_novop zero: models/Phi-4-mini-instruct rows 3 544 --layers 2 --hack novop\nz_ph_r3_half zero: models/Phi-4-mini-instruct rows 3 544 --layers 2 --hack half\nz_ph_r1k4 zero: models/Phi-4-mini-instruct rows 1 4000 --layers 2\nz_ph_r1k4_novop zero: models/Phi-4-mini-instruct rows 1 4000 --layers 2 --hack novop\nz_ph_r1k4_half zero: models/Phi-4-mini-instruct rows 1 4000 --layers 2 --hack half\nz_lf_r3 zero: models/LFM2-2.6B rows 3 544 --layers 6\nz_lf_r3_novop zero: models/LFM2-2.6B rows 3 544 --layers 6 --hack novop\nz_lf_r3_half zero: models/LFM2-2.6B rows 3 544 --layers 6 --hack half\nz_lf_r3_comp1 zero: models/LFM2-2.6B rows 3 544 --layers 6 --hack comp1\n", "rtl/exp/vpu_pump/lists/decode.txt": "# decode, whole model, position 544, fp4 + int8 head, LDC DDR3-1066, 133.33 MHz\nd_q3 --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544\nd_q3_novop --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --hack novop\nd_lf --model lfm2 --wformat fp4 --head-format int8 --layers 0 --pos 544\nd_lf_novop --model lfm2 --wformat fp4 --head-format int8 --layers 0 --pos 544 --hack novop\nd_q35 --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544\nd_q35_novop --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --hack novop\nd_q35_nose --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --hack nose\nd_q35_half_halfse --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --hack half,halfse\n# a long context: position 4000\nd4k_q3 --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 4000\nd4k_q3_novop --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 4000 --hack novop\nd4k_q3_half --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 4000 --hack half\nd4k_q3_comp1 --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 4000 --hack comp1\n", "rtl/exp/vpu_pump/lists/lanes16.txt": "# the real 16-lane VPU (otpu_vpu LANES 16 on 16 TMEM banks, the MXU and quantizer on 8: ULANES 8;\n# CL 4 long lanes for the composites; no stream engine, which needs 8 lanes): Qwen3 only (no\n# DSTEP / STREAM), bit-exact against the ISA (--check); against the same runs at 8 lanes\nx16_p_q3 env: OTPU_LANES=16 OTPU_ULANES=8 OTPU_DSTEP=0 OTPU_STREAM=0 -- --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --check\nx16_b4_q3 env: OTPU_LANES=16 OTPU_ULANES=8 OTPU_DSTEP=0 OTPU_STREAM=0 -- --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --batch 4 --check\nx16_d4k_q3 env: OTPU_LANES=16 OTPU_ULANES=8 OTPU_DSTEP=0 OTPU_STREAM=0 -- --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 4000\n", "rtl/exp/vpu_pump/lists/moe.txt": "# MoE (tools/moe_prefill_cosim.py, zero images from config.json, every expert present at its\n# layer's first slot, the routing's bookkeeping VOPs kept exact: vpu_hack.moe_keep).\n# rows --variant moe: one decode row with the MoE block; a layer's cost is a prefix difference\nm_g26 moe: rows models/gemma-4-26B-A4B-it --variant moe --R 1 --prefix 0:0,1:0,5\nm_g26_novop moe: rows models/gemma-4-26B-A4B-it --variant moe --R 1 --prefix 0:0,1:0,5 --hack novop\nm_g26_half moe: rows models/gemma-4-26B-A4B-it --variant moe --R 1 --prefix 0:0,1:0,5 --hack half\nm_g26_comp1 moe: rows models/gemma-4-26B-A4B-it --variant moe --R 1 --prefix 0:0,1:0,5 --hack comp1\nm_q35m moe: rows models/Qwen3.5-35B-A3B --variant moe --R 1 --prefix 1:3:4\nm_q35m_novop moe: rows models/Qwen3.5-35B-A3B --variant moe --R 1 --prefix 1:3:4 --hack novop\nm_q35m_half moe: rows models/Qwen3.5-35B-A3B --variant moe --R 1 --prefix 1:3:4 --hack half\nm_q35m_nose moe: rows models/Qwen3.5-35B-A3B --variant moe --R 1 --prefix 1:3:4 --hack nose\n# layer: the layer-major prefill's program of one layer (compile_layer_run), 2 rows (R k <= 16 ids: R_max 2 at k = 8)\nl_g26 moe: layer models/gemma-4-26B-A4B-it --R 2 --prefix 0,1:0,5\nl_g26_novop moe: layer models/gemma-4-26B-A4B-it --R 2 --prefix 0,1:0,5 --hack novop\nl_g26_half moe: layer models/gemma-4-26B-A4B-it --R 2 --prefix 0,1:0,5 --hack half\nl_q35m moe: layer models/Qwen3.5-35B-A3B --R 2 --prefix 1:4\nl_q35m_novop moe: layer models/Qwen3.5-35B-A3B --R 2 --prefix 1:4 --hack novop\nl_q35m_half moe: layer models/Qwen3.5-35B-A3B --R 2 --prefix 1:4 --hack half\nl_q35m_nose moe: layer models/Qwen3.5-35B-A3B --R 2 --prefix 1:4 --hack nose\nl_q35m_halfse moe: layer models/Qwen3.5-35B-A3B --R 2 --prefix 1:4 --hack halfse\n", "rtl/exp/vpu_pump/lists/prefill.txt": "# prefill: 4 rows (the card's R_max) at 544..547, no logits, whole model, fp4 + int8 head\np_q3 --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none\np_q3_novop --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack novop\np_q3_half --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack half\np_q3_comp1 --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack comp1\np_lf --model lfm2 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none\np_lf_novop --model lfm2 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack novop\np_lf_half --model lfm2 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack half\np_lf_comp1 --model lfm2 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack comp1\np_q35 --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none\np_q35_novop --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack novop\np_q35_half --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack half\np_q35_comp1 --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack comp1\np_q35_nose --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack nose\np_q35_halfse --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack halfse\np_q35_half_halfse --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --hack half,halfse\n# the pumped / MCOLS 8 MXU's rate (dsp-pump's upper bound): what is left is attention and vector work\np8_q3 --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --mcols 8\np8_q3_novop --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --mcols 8 --hack novop\np8_q3_half --model qwen3 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --mcols 8 --hack half\np8_q35 --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --mcols 8\np8_q35_novop --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --mcols 8 --hack novop\np8_q35_half --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --mcols 8 --hack half\np8_q35_halfse --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --mcols 8 --hack halfse\np8_q35_nose --model qwen35 --wformat fp4 --head-format int8 --layers 0 --pos 544 --rows 4 --logits none --mcols 8 --hack nose\n", "rtl/exp/vpu_pump/ooc_lane.tcl": "# EXPERIMENTAL (docs/vpu_pump.md): out-of-context synthesis + implementation of vpu_pump_top (the\n# pumped multiply-add pairs) on the YPCB's part, its clocks from an MMCM. On a Vivado host:\n#   vivado -mode batch -nojournal -source rtl/exp/vpu_pump/ooc_lane.tcl -tclargs <out> <VAR> \\\n#     [XR] [RETIME] [MULT DIV_S DIV_F] [PART]\n# VAR 0: 8 lanes of today's otpu_fmma at clk_s; 1: 4 pumped units (today's 6 stages) at clk_f;\n# 2: 4 pumped deep units (6 x (1 + XR) stages); 3: 4 pumped split units (10 stages). RETIME 1:\n# synth_design -retiming. Defaults: VCO 1066.67 (MULT 8), clk_s 133.33 (DIV_S 8), clk_f 266.67\n# (DIV_F 4). Prints OTPU_* lines.\nset out [file normalize [lindex $argv 0]]\nset var [lindex $argv 1]\nset xr     [expr {[llength $argv] > 2 ? [lindex $argv 2] : 1}]\nset retime [expr {[llength $argv] > 3 ? [lindex $argv 3] : 0}]\nset mult   [expr {[llength $argv] > 4 ? [lindex $argv 4] : 8}]\nset div_s  [expr {[llength $argv] > 5 ? [lindex $argv 5] : 8}]\nset div_f  [expr {[llength $argv] > 6 ? [lindex $argv 6] : 4}]\nset part   [expr {[llength $argv] > 7 ? [lindex $argv 7] : \"xc7k480tffg1156-2\"}]\nset root [file normalize [file join [file dirname [info script]] ../../..]]\nfile mkdir $out\n\ncreate_project -in_memory -part $part\nset_property source_mgmt_mode None [current_project]\nread_verilog -sv [list $root/rtl/vpu/otpu_fp.sv $root/rtl/vpu/otpu_fpipe.sv \\\n  $root/rtl/exp/vpu_pump/vpu_pump_lane.sv]\nset opts [list -top vpu_pump_top -part $part -mode out_of_context -flatten_hierarchy rebuilt \\\n  -verilog_define SYNTHESIS -generic VAR=$var -generic XR=$xr -generic MULT=$mult \\\n  -generic DIV_S=$div_s -generic DIV_F=$div_f]\nif {$retime} { lappend opts -retiming }\nsynth_design {*}$opts\ncreate_clock -period 7.5 -name clk_in [get_ports clk_in]\nset cs [get_clocks -quiet -of_objects [get_pins u_mmcm/CLKOUT0]]\nset cf [get_clocks -quiet -of_objects [get_pins u_mmcm/CLKOUT1]]\nforeach {t c} [list slow $cs fast $cf] {\n  if {[llength $c]} { puts \"OTPU_CLOCK $t [get_property NAME $c] [get_property PERIOD $c]\" }\n}\nreport_utilization -file $out/util_synth.txt\nopt_design\nplace_design\nphys_opt_design\nroute_design\nreport_utilization -file $out/util.txt\nreport_utilization -hierarchical -hierarchical_depth 4 -file $out/util_hier.txt\nreport_timing_summary -max_paths 10 -file $out/timing_summary.txt\nreport_clock_interaction -file $out/clock_interaction.txt\nreport_power -file $out/power.txt\nforeach {tag from to} [list SS $cs $cs FF $cf $cf SF $cs $cf FS $cf $cs] {\n  if {![llength $from] || ![llength $to]} { puts \"OTPU_PATH $tag none\"; continue }\n  set q [lindex [get_timing_paths -quiet -from $from -to $to -setup -max_paths 1 -nworst 1] 0]\n  set h [lindex [get_timing_paths -quiet -from $from -to $to -hold -max_paths 1 -nworst 1] 0]\n  if {[llength $q]} {\n    puts \"OTPU_PATH $tag setup [get_property SLACK $q] req [get_property REQUIREMENT $q] levels [get_property LOGIC_LEVELS $q] [get_property STARTPOINT_PIN $q] -> [get_property ENDPOINT_PIN $q] | hold [get_property SLACK $h]\"\n    report_timing -from $from -to $to -max_paths 10 -nworst 1 -file $out/timing_$tag.txt\n  } else {\n    puts \"OTPU_PATH $tag none\"\n  }\n}\nforeach {k pat} {LUT \"LUT as Logic\" LUTRAM \"LUT as Memory\" FF \"Slice Registers\" DSP \"DSPs\" SLICE \"Slice\"} {\n  set f [open $out/util.txt]; set t [read $f]; close $f\n  if {[regexp -line \"^\\\\|\\\\s*$pat\\\\s*\\\\|\\\\s*(\\[0-9.\\]+)\" $t -> v]} { puts \"OTPU_UTIL $k $v\" }\n}\nset p [lindex [get_timing_paths -setup -max_paths 1 -nworst 1] 0]\nset h [lindex [get_timing_paths -hold -max_paths 1 -nworst 1] 0]\nputs \"OTPU_WNS [get_property SLACK $p] OTPU_WHS [get_property SLACK $h]\"\nputs \"OTPU_DONE\"\n", "rtl/exp/vpu_pump/ooc_vpu.tcl": "# EXPERIMENTAL (docs/vpu_pump.md): out-of-context synthesis + implementation of otpu_vpu (the VPU\n# with the stream engine's core side, otpu_se_comp and otpu_se_tail) on the YPCB's part, at one\n# clock. Vivado on omarchy only:\n#   vivado -mode batch -nojournal -source rtl/exp/vpu_pump/ooc_vpu.tcl -tclargs <out> <PERIOD_NS> \\\n#     <LANES> <CL> <HAS_SE> [WBUF] [PART]\n# Production: 7.5 8 2 1 1 (CL is unused with the stream engine: COMP8). Prints OTPU_* lines.\nset out [file normalize [lindex $argv 0]]\nset period [lindex $argv 1]\nset lanes [lindex $argv 2]\nset cl [lindex $argv 3]\nset se [lindex $argv 4]\nset wbuf [expr {[llength $argv] > 5 ? [lindex $argv 5] : 1}]\nset part [expr {[llength $argv] > 6 ? [lindex $argv 6] : \"xc7k480tffg1156-2\"}]\nset root [file normalize [file join [file dirname [info script]] ../../..]]\nfile mkdir $out\n\ncreate_project -in_memory -part $part\nset_property source_mgmt_mode None [current_project]\nread_verilog -sv [list $root/rtl/vpu/otpu_fp.sv $root/rtl/vpu/otpu_fpipe.sv \\\n  $root/rtl/top/otpu_pkg.sv $root/rtl/tech/generic/otpu_tech_ram.sv $root/rtl/vpu/otpu_vtree.sv \\\n  $root/rtl/vpu/otpu_se_comp.sv $root/rtl/vpu/otpu_se_tail.sv $root/rtl/vpu/otpu_vpu.sv]\nsynth_design -top otpu_vpu -part $part -mode out_of_context -flatten_hierarchy rebuilt \\\n  -verilog_define SYNTHESIS -generic LANES=$lanes -generic CL=$cl -generic HAS_SE=$se \\\n  -generic WBUF=$wbuf -generic SID=0\ncreate_clock -period $period -name clk [get_ports clk]\nreport_utilization -file $out/util_synth.txt\nreport_utilization -hierarchical -hierarchical_depth 3 -file $out/util_hier_synth.txt\nopt_design\nplace_design\nphys_opt_design\nroute_design\nreport_utilization -file $out/util.txt\nreport_utilization -hierarchical -hierarchical_depth 3 -file $out/util_hier.txt\nreport_timing_summary -max_paths 20 -file $out/timing_summary.txt\nset f [open $out/util.txt]; set t [read $f]; close $f\nforeach {k pat} {LUT \"LUT as Logic\" LUTRAM \"LUT as Memory\" FF \"Slice Registers\" DSP \"DSPs\" SLICE \"Slice\" BRAM \"Block RAM Tile\"} {\n  if {[regexp -line \"^\\\\|\\\\s*$pat\\\\s*\\\\|\\\\s*(\\[0-9.\\]+)\" $t -> v]} { puts \"OTPU_UTIL $k $v\" }\n}\nset n 0\nforeach q [get_timing_paths -setup -max_paths 20 -nworst 1] {\n  if {$n < 5} {\n    puts \"OTPU_PATH [get_property SLACK $q] levels [get_property LOGIC_LEVELS $q] [get_property STARTPOINT_PIN $q] -> [get_property ENDPOINT_PIN $q]\"\n  }\n  incr n\n}\nset p [lindex [get_timing_paths -setup -max_paths 1 -nworst 1] 0]\nset h [lindex [get_timing_paths -hold -max_paths 1 -nworst 1] 0]\nputs \"OTPU_WNS [get_property SLACK $p] OTPU_WHS [get_property SLACK $h]\"\nputs \"OTPU_DONE\"\n", "rtl/exp/vpu_pump/run_cosim.sh": "#!/bin/bash\n# EXPERIMENTAL (docs/vpu_pump.md): co-simulation lists, P runs at a time. Each line of a list is\n# \"TAG perf_qwen-arguments\", \"TAG moe: moe_prefill_cosim-arguments\" or \"TAG zero: vpu_hack.py\n# cosim-arguments\" (a zero image from config.json, a layer prefix); every run is the board's\n# configuration (PAIR, DSTEP, STREAM; LiteDRAM's controller at DDR3-1066, the core at 133.33 MHz).\n# Results: <outdir>/<TAG>.log, and perf_qwen's JSON lines in <outdir>/<list name>.jsonl. A tag\n# whose log ends in rc=0 is skipped. LOCK=<file>: each run under lockf on that file (the Mac's\n# shared heavy-job lock). Usage, from anywhere:\n#   rtl/exp/vpu_pump/run_cosim.sh <outdir> <P> <list> ...\nROOT=$(cd \"$(dirname \"$0\")/../../..\" && pwd)\nO=${1:?outdir}; P=${2:?parallel}; shift 2\nmkdir -p \"$O\"\nexport OTPU_PAIR=1 OTPU_DSTEP=1 OTPU_STREAM=1 PYTHONPATH=$ROOT\none() {   # list tag args...\n  local js=$1 tag=$2; shift 2\n  grep -q \"^rc=0\" \"$O/$tag.log\" 2>/dev/null && return 0\n  local t0=$(date +%s)\n  cd \"$ROOT\" || return 1\n  if [ \"$1\" = \"env:\" ]; then     # \"env: K=V ... --\": the run's own environment\n    shift\n    while [ \"$1\" != \"--\" ]; do export \"$1\"; shift; done\n    shift\n  fi\n  local lk=()\n  [ -n \"$LOCK\" ] && lk=(lockf -k \"$LOCK\")\n  if [ \"$1\" = \"moe:\" ]; then\n    shift\n    \"${lk[@]}\" python3 tools/moe_prefill_cosim.py \"$@\" > \"$O/$tag.log\" 2>&1\n  elif [ \"$1\" = \"zero:\" ]; then\n    shift\n    \"${lk[@]}\" python3 tools/vpu_hack.py cosim \"$@\" > \"$O/$tag.log\" 2>&1\n  else\n    \"${lk[@]}\" python3 tools/perf_qwen.py --ddr 1066 --mhz 133.33 --ldc --json \"$js\" \"$@\" \\\n      > \"$O/$tag.log\" 2>&1\n  fi\n  echo \"rc=$? $(( $(date +%s) - t0 ))s\" >> \"$O/$tag.log\"\n  echo \"$(date '+%T') $tag $(tail -1 \"$O/$tag.log\")\" >> \"$O/progress.txt\"\n}\nexport -f one\nexport O ROOT LOCK\nfor list in \"$@\"; do\n  js=\"$O/$(basename \"$list\" .txt).jsonl\"\n  grep -v '^#' \"$list\" | grep -v '^ *$' | while read -r tag args; do echo \"$js $tag $args\"; done\ndone | xargs -P \"$P\" -L 1 bash -c 'one $0 \"$@\"'\necho \"EXIT $(date '+%F %T')\" >> \"$O/progress.txt\"\n", "rtl/exp/vpu_pump/run_ooc.sh": "#!/bin/bash\n# EXPERIMENTAL (docs/vpu_pump.md): the experiment's Vivado runs, one after another (omarchy only,\n# through ~/otpu-build/slot.sh). Usage, from the tree:\n#   rtl/exp/vpu_pump/run_ooc.sh <outdir> [step ...]\n# steps:\n#   lane0     8 lanes of today's otpu_fmma at 133.33 MHz (vpu_pump_top VAR 0)\n#   lane1     4 pumped units, today's 6 stages, at 266.67 MHz (VAR 1)\n#   lane2     4 pumped deep units, 12 stages (XR 1), synthesis retiming (VAR 2)\n#   lane2n    the same without retiming\n#   lane3     4 pumped deep units, 18 stages (XR 2), retiming\n#   lane4     4 pumped split units (vp_fmma_split: 10 stages, the two long ones split by hand)\n#   vpu8se    otpu_vpu as built (LANES 8, the stream engine: COMP8 + the tail) at 7.5 ns\n#   vpu8      otpu_vpu LANES 8 without the stream engine (CL 2 long lanes) at 7.5 ns\n#   vpu8cl4   the same with CL 4\n#   vpu16     otpu_vpu LANES 16 (no stream engine: SE needs 8 lanes), CL 4, at 7.5 ns\n#   vpu8se2x  otpu_vpu as built at 3.75 ns (the whole VPU at 266.67 MHz: a probe)\nROOT=$(cd \"$(dirname \"$0\")/../../..\" && pwd)\nO=${1:?outdir}; shift\nmkdir -p \"$O\"\nexport PATH=$HOME/.local/bin:$PATH\nviv() {   # name tcl args...\n  local n=$1; shift\n  echo \"START $n $(date '+%F %T')\" >> \"$O/progress.txt\"\n  local t0=$(date +%s)\n  (cd \"$O\" && timeout 5400 vivado -mode batch -nojournal -log \"$O/$n.log\" -source \"$@\" > \"$O/$n.out\" 2>&1)\n  echo \"DONE $n rc=$? $(( $(date +%s) - t0 ))s\" >> \"$O/progress.txt\"\n  grep -h \"^OTPU_\" \"$O/$n.out\" | sed \"s/^/$n /\" >> \"$O/progress.txt\"\n}\nL=$ROOT/rtl/exp/vpu_pump/ooc_lane.tcl\nV=$ROOT/rtl/exp/vpu_pump/ooc_vpu.tcl\nfor s in \"$@\"; do\n  case $s in\n    lane0)    viv lane0 \"$L\" -tclargs \"$O/lane0\" 0 1 0 ;;\n    lane1)    viv lane1 \"$L\" -tclargs \"$O/lane1\" 1 1 0 ;;\n    lane2)    viv lane2 \"$L\" -tclargs \"$O/lane2\" 2 1 1 ;;\n    lane2n)   viv lane2n \"$L\" -tclargs \"$O/lane2n\" 2 1 0 ;;\n    lane3)    viv lane3 \"$L\" -tclargs \"$O/lane3\" 2 2 1 ;;\n    lane4)    viv lane4 \"$L\" -tclargs \"$O/lane4\" 3 1 0 ;;\n    vpu8se)   viv vpu8se \"$V\" -tclargs \"$O/vpu8se\" 7.5 8 2 1 ;;\n    vpu8)     viv vpu8 \"$V\" -tclargs \"$O/vpu8\" 7.5 8 2 0 ;;\n    vpu8cl4)  viv vpu8cl4 \"$V\" -tclargs \"$O/vpu8cl4\" 7.5 8 4 0 ;;\n    vpu16)    viv vpu16 \"$V\" -tclargs \"$O/vpu16\" 7.5 16 4 0 ;;\n    vpu8se2x) viv vpu8se2x \"$V\" -tclargs \"$O/vpu8se2x\" 3.75 8 2 1 ;;\n    *) echo \"unknown step $s\" >> \"$O/progress.txt\" ;;\n  esac\ndone\necho \"EXIT $(date '+%F %T')\" >> \"$O/progress.txt\"\n", "rtl/exp/vpu_pump/run_tb.sh": "#!/bin/bash\n# EXPERIMENTAL (docs/vpu_pump.md): build and run tb_vpu_pump with Verilator. Usage, from anywhere:\n#   rtl/exp/vpu_pump/run_tb.sh [build dir]\nROOT=$(cd \"$(dirname \"$0\")/../../..\" && pwd)\nB=${1:-$ROOT/build/vpu_pump_tb}\nmkdir -p \"$B\"\nverilator --binary --timing -Wno-fatal -Wno-WIDTHEXPAND -Wno-WIDTHTRUNC -Wno-UNUSEDSIGNAL \\\n  --top-module tb_vpu_pump -Mdir \"$B\" \"$ROOT/rtl/vpu/otpu_fp.sv\" \"$ROOT/rtl/vpu/otpu_fpipe.sv\" \\\n  \"$ROOT/rtl/exp/vpu_pump/vpu_pump_lane.sv\" \"$ROOT/rtl/exp/vpu_pump/tb_vpu_pump.sv\" \\\n  > \"$B/build.log\" 2>&1 || { tail -30 \"$B/build.log\"; exit 1; }\n\"$B/Vtb_vpu_pump\"\n", "rtl/exp/vpu_pump/tb_vpu_pump.sv": "// EXPERIMENTAL (docs/vpu_pump.md): the pumped multiply-add pair against two of today's units.\n// clk_f toggles every time unit, clk_s every two (both rise together); random operands each core\n// cycle (with zeros, denormals, infinities and NaNs mixed in) and a random pipeline enable. Each\n// design's results are recorded on the enabled core cycles; the pumped streams must equal the\n// base's at a fixed offset (their latency difference in enabled cycles) for every lane.\n// Run: rtl/exp/vpu_pump/run_tb.sh (Verilator).\nmodule tb_vpu_pump;\n  import otpu_fp::*;\n  localparam int N = 20000;          // core cycles\n  // both rise at 10, 30, 50, ... (clk_s every other time: 10, 50, 90, ...; clk_f's 30, 70, ...\n  // are the mid edges)\n  logic clk_s = 0, clk_f = 0;\n  initial begin #10; forever begin clk_f = 1; #10; clk_f = 0; #10; end end\n  initial begin #10; forever begin clk_s = 1; #20; clk_s = 0; #20; end end\n  logic en = 0;\n  f32_t a0, b0, c0, e0, a1, b1, c1, e1;\n  f32_t yb0, yb1, yp0, yp1, yd0, yd1, ys0, ys1;\n  vp_pair_base u_b (.clk_s, .en, .a0, .b0, .c0, .e0, .a1, .b1, .c1, .e1, .y0(yb0), .y1(yb1));\n  vp_pair_pump #(.DEEP(0)) u_p (.clk_s, .clk_f, .en, .a0, .b0, .c0, .e0, .a1, .b1, .c1, .e1,\n                                   .y0(yp0), .y1(yp1));\n  vp_pair_pump #(.DEEP(1), .XR(1)) u_d (.clk_s, .clk_f, .en, .a0, .b0, .c0, .e0, .a1, .b1,\n                                        .c1, .e1, .y0(yd0), .y1(yd1));\n  vp_pair_pump #(.DEEP(2)) u_s (.clk_s, .clk_f, .en, .a0, .b0, .c0, .e0, .a1, .b1, .c1, .e1,\n                                .y0(ys0), .y1(ys1));\n  function automatic f32_t rnd();\n    int k;\n    k = $urandom_range(0, 99);\n    if (k < 4) return F_ZERO ^ {$urandom_range(0, 1) == 1, 31'd0};      // +-0\n    if (k < 7) return {$urandom_range(0, 1) == 1, 8'd0, 23'($urandom)};  // denormal\n    if (k < 9) return {$urandom_range(0, 1) == 1, 8'hFF, 23'd0};         // +-inf\n    if (k < 10) return F_NAN;\n    // normal, exponents near 127 so that products and sums meet (and cancel) often\n    return {$urandom_range(0, 1) == 1, 8'($urandom_range(100, 154)), 23'($urandom)};\n  endfunction\n  f32_t qb0 [$], qb1 [$], qp0 [$], qp1 [$], qd0 [$], qd1 [$], qs0 [$], qs1 [$];\n  initial begin\n    int bad, off_p, off_d, off_s, warm;\n    repeat (2) @(posedge clk_s);\n    for (int n = 0; n < N; n++) begin\n      // core cycle n: its enable and operands just after its slow edge; its results just\n      // before the next slow edge, kept when it is enabled (what a clk_s register with that\n      // enable takes at the edge)\n      @(posedge clk_s);\n      #1;\n      en = ($urandom_range(0, 99) < 75);\n      a0 = rnd(); b0 = rnd(); c0 = rnd(); e0 = (n % 3 == 0) ? F_ONE : rnd();\n      a1 = rnd(); b1 = rnd(); c1 = rnd(); e1 = (n % 5 == 0) ? F_ONE : rnd();\n      #37;\n      if (en) begin\n        qb0.push_back(yb0); qb1.push_back(yb1);\n        qp0.push_back(yp0); qp1.push_back(yp1);\n        qd0.push_back(yd0); qd1.push_back(yd1);\n        qs0.push_back(ys0); qs1.push_back(ys1);\n      end\n    end\n    if ($test$plusargs(\"dump\"))\n      for (int i = 100; i < 112; i++)\n        $display(\"%0d base %h %h pump %h %h deep %h %h\", i, qb0[i], qb1[i], qp0[i], qp1[i],\n                 qd0[i], qd1[i]);\n    if ($test$plusargs(\"dump\"))\n      for (int i = 40; i < qb0.size() - 20; i++)\n        if (qp0[i] != qb0[i + 2] || qp1[i] != qb1[i + 2]) begin\n          $display(\"first pump mismatch at %0d: base %h %h pump %h %h\", i, qb0[i+2], qb1[i+2],\n                   qp0[i], qp1[i]);\n          break;\n        end\n    warm = 40;\n    off_p = -1; off_d = -1; off_s = -1;\n    for (int d = -12; d <= 12 && off_p < 0; d++) begin\n      int ok;\n      ok = 1;\n      for (int i = warm; i < qb0.size() - 20; i++)\n        if (qp0[i] != qb0[i + d] || qp1[i] != qb1[i + d]) begin ok = 0; break; end\n      if (ok) off_p = d + 100;\n    end\n    for (int d = -12; d <= 12 && off_d < 0; d++) begin\n      int ok;\n      ok = 1;\n      for (int i = warm; i < qb0.size() - 20; i++)\n        if (qd0[i] != qb0[i + d] || qd1[i] != qb1[i + d]) begin ok = 0; break; end\n      if (ok) off_d = d + 100;\n    end\n    for (int d = -12; d <= 12 && off_s < 0; d++) begin\n      int ok;\n      ok = 1;\n      for (int i = warm; i < qb0.size() - 20; i++)\n        if (qs0[i] != qb0[i + d] || qs1[i] != qb1[i + d]) begin ok = 0; break; end\n      if (ok) off_s = d + 100;\n    end\n    $display(\"enabled cycles %0d; pumped (today's unit at clk_f): %s, latency %0d enabled core cycles vs the base's 6\",\n             qb0.size(), off_p >= 0 ? \"BIT-EXACT\" : \"MISMATCH\", off_p >= 0 ? 6 - (off_p - 100) : -1);\n    $display(\"pumped deep (XR 1): %s, latency %0d enabled core cycles vs the base's 6\",\n             off_d >= 0 ? \"BIT-EXACT\" : \"MISMATCH\", off_d >= 0 ? 6 - (off_d - 100) : -1);\n    $display(\"pumped split (10 fast stages): %s, latency %0d enabled core cycles vs the base's 6\",\n             off_s >= 0 ? \"BIT-EXACT\" : \"MISMATCH\", off_s >= 0 ? 6 - (off_s - 100) : -1);\n    if (off_p < 0 || off_d < 0 || off_s < 0) $fatal(1, \"tb_vpu_pump: MISMATCH\");\n    $display(\"PASS\");\n    $finish;\n  end\nendmodule\n", "rtl/exp/vpu_pump/vpu_pump_lane.sv": "// EXPERIMENTAL (docs/vpu_pump.md): a VPU lane's multiply-add unit pumped at twice the core clock.\n//\n// Today every VPU lane has its own slot-0 unit, otpu_fmma (y = a*b + c*e: two otpu_fmul, LM = 2\n// stages, and an otpu_fadd, LA = 4 stages, at the core clock). A pumped unit takes two lanes'\n// operands each core cycle and runs them one after the other through one unit at clk_f =\n// 2 x clk_s: half the units for the same element rate, or twice the rate from the same units.\n//\n//   vp_pair_base   two otpu_fmma at clk_s (today)\n//   vp_pair_pump   one unit at clk_f: a 2:1 operand mux into its input registers, the result\n//                  into one of two holding registers by phase, both read by clk_s. DEEP = 0:\n//                  today's otpu_fmma (6 stages); DEEP = 1: vp_fmma_deep with XR extra register\n//                  stages after each of its six (for synthesis retiming to spread: 6 x (1 + XR)\n//                  stages at clk_f); DEEP = 2: vp_fmma_split (the two long stages split by hand,\n//                  10 stages at clk_f)\n//\n// Both advance on the VPU's pipeline enable `en` (a clk_s signal: a frozen core cycle freezes\n// both of its fast cycles), so the pumped pair is the same per lane, cycle for cycle of `en`, as\n// two units with a longer latency; tb_vpu_pump.sv checks the results bit for bit against the\n// base pair (and both against each other with random enables).\n//\n// The phase: clk_s's toggle t_s sampled by clk_f (t_f); ph = t_s ^ t_f is 1 in the first fast\n// cycle after a slow edge and 0 in the second (no reset needed: both clocks come from one MMCM\n// at phase 0, every slow edge is a fast edge). The input registers take lane 0 at the mid edge\n// (ph = 1) and lane 1 at the slow edge (ph = 0); with an even fast latency L, lane 0's result\n// is in the unit's output register during a second half (ph = 0) and lane 1's during a first.\nmodule vp_fmma_deep\n  import otpu_fp::*;\n#(parameter int XR = 1) (\n  input  logic clk,\n  input  logic en,\n  input  f32_t a, b, c, e,\n  output f32_t y\n);\n  // today's six register stages (fmul s1 | s2 in parallel for both products, fadd s1 .. s4),\n  // each followed by XR plain registers that retiming may pull into the logic\n  fmul_mid_t m_ab, m_ce;\n  f32_t p_ab, p_ce;\n  fadd_p1_t s1;\n  fadd_p2_t s2;\n  fadd_nm_t s3;\n  f32_t r;\n  fmul_mid_t dm_ab [XR + 1], dm_ce [XR + 1];\n  f32_t dp_ab [XR + 1], dp_ce [XR + 1], dr [XR + 1];\n  fadd_p1_t d1 [XR + 1];\n  fadd_p2_t d2 [XR + 1];\n  fadd_nm_t d3 [XR + 1];\n  always_ff @(posedge clk) if (en) begin\n    dm_ab[0] <= fp_mul_s1(a, b);\n    dm_ce[0] <= fp_mul_s1(c, e);\n    for (int k = 1; k <= XR; k++) begin\n      dm_ab[k] <= dm_ab[k-1];\n      dm_ce[k] <= dm_ce[k-1];\n    end\n    dp_ab[0] <= fp_mul_s2(dm_ab[XR]);\n    dp_ce[0] <= fp_mul_s2(dm_ce[XR]);\n    for (int k = 1; k <= XR; k++) begin\n      dp_ab[k] <= dp_ab[k-1];\n      dp_ce[k] <= dp_ce[k-1];\n    end\n    d1[0] <= fp_add_s1(dp_ab[XR], dp_ce[XR]);\n    for (int k = 1; k <= XR; k++) d1[k] <= d1[k-1];\n    d2[0] <= fp_add_s2(d1[XR]);\n    for (int k = 1; k <= XR; k++) d2[k] <= d2[k-1];\n    d3[0] <= fp_add_s3(d2[XR]);\n    for (int k = 1; k <= XR; k++) d3[k] <= d3[k-1];\n    dr[0] <= fp_add_s4(d3[XR]);\n    for (int k = 1; k <= XR; k++) dr[k] <= dr[k-1];\n  end\n  assign y = dr[XR];\nendmodule\n\n// The two stages that do not fit a 3.75 ns period on the -2 Kintex-7 (vp_fmma_deep at 266.67 MHz:\n// the multiplier's rounding fp_mul_s2 and the adder's normalize fp_add_s3), each split in two by\n// hand (synthesis retiming did not move them): bit for bit the same functions.\ntypedef struct packed {\n  logic               sp;\n  logic [31:0]        sv;\n  logic               s;\n  logic [23:0]        mm;\n  logic               inc;        // the round-up\n  logic [7:0]         e8;         // e0's low byte\n  logic               ovf, e254, neg, zero, all1;\n} vp_mul_r_t;\n\nfunction automatic vp_mul_r_t vp_mul_s2a(input otpu_fp::fmul_mid_t m);\n  vp_mul_r_t r;\n  logic g, st;\n  logic signed [10:0] e0;\n  r = '0;\n  r.sp = m.sp; r.sv = m.sv; r.s = m.s;\n  if (m.p[47]) begin\n    r.mm = m.p[47:24]; g = m.p[23]; st = |m.p[22:0];\n  end else begin\n    r.mm = m.p[46:23]; g = m.p[22]; st = |m.p[21:0];\n  end\n  e0 = m.e + 11'(m.p[47]);\n  r.inc = g && (st || r.mm[0]);\n  r.e8 = e0[7:0];\n  r.ovf = e0 >= 11'sd255;\n  r.e254 = e0 == 11'sd254;\n  r.neg = e0 < 11'sd0;\n  r.zero = e0 == 11'sd0;\n  r.all1 = &r.mm;\n  return r;\nendfunction\n\nfunction automatic otpu_fp::f32_t vp_mul_s2b(input vp_mul_r_t r);\n  logic [24:0] mr;\n  logic c;\n  if (r.sp) return r.sv;\n  mr = {1'b0, r.mm} + {24'd0, r.inc};\n  c = mr[24];\n  if (r.ovf || (r.e254 && c)) return {r.s, 8'hFF, 23'd0};\n  if (r.neg) return {r.s, 31'd0};\n  if (r.zero) return r.all1 ? {r.s, 8'd1, 23'd0} : {r.s, 31'd0};\n  return {r.s, r.e8 + {7'd0, c}, mr[22:0]};\nendfunction\n\ntypedef struct packed {\n  logic        sp;\n  logic [2:0]  sv;\n  logic        sa;\n  logic        sub;\n  logic [7:0]  e;\n  logic [1:0]  n43;       // norm28's first two shift levels (16, 8)\n  logic [27:0] y;\n} vp_add_h_t;\n\nfunction automatic vp_add_h_t vp_add_s3a(input otpu_fp::fadd_p2_t q);\n  vp_add_h_t h;\n  h.sp = q.sp; h.sv = q.sv; h.sa = q.sa; h.sub = q.sub; h.e = q.e;\n  h.y = q.sum; h.n43 = '0;\n  if (h.y[27:12] == 0) begin h.n43[1] = 1'b1; h.y = h.y << 16; end\n  if (h.y[27:20] == 0) begin h.n43[0] = 1'b1; h.y = h.y << 8; end\n  return h;\nendfunction\n\nfunction automatic otpu_fp::fadd_nm_t vp_add_s3b(input vp_add_h_t h);\n  otpu_fp::fadd_nm_t n;\n  logic [4:0] k;\n  logic [27:0] y;\n  y = h.y; k = {h.n43, 3'b000};\n  if (y[27:24] == 0) begin k[2] = 1'b1; y = y << 4; end\n  if (y[27:26] == 0) begin k[1] = 1'b1; y = y << 2; end\n  if (y[27] == 0)    begin k[0] = 1'b1; y = y << 1; end\n  n.sp = h.sp;\n  n.sv = h.sv;\n  n.s = h.sa;\n  if (h.sub && !y[27] && !h.sp) begin\n    n.sp = 1'b1;\n    n.sv = otpu_fp::FADD_SV_ZERO;\n  end\n  n.mn = {y[27:2], y[1] | y[0]};\n  n.e = 9'(h.e) - 9'(k);\n  return n;\nendfunction\n\n// today's unit with those two stages split and a second product register (the DSP's M and P):\n// 10 stages at clk_f (5 core cycles), against today's 6 at clk_s\nmodule vp_fmma_split\n  import otpu_fp::*;\n(\n  input  logic clk,\n  input  logic en,\n  input  f32_t a, b, c, e,\n  output f32_t y\n);\n  fmul_mid_t m1_ab, m1_ce, m2_ab, m2_ce;\n  vp_mul_r_t r_ab, r_ce;\n  f32_t p_ab, p_ce, y1, y2;\n  fadd_p1_t s1;\n  fadd_p2_t s2;\n  vp_add_h_t s3a;\n  fadd_nm_t s3;\n  always_ff @(posedge clk) if (en) begin\n    m1_ab <= fp_mul_s1(a, b);\n    m1_ce <= fp_mul_s1(c, e);\n    m2_ab <= m1_ab;\n    m2_ce <= m1_ce;\n    r_ab <= vp_mul_s2a(m2_ab);\n    r_ce <= vp_mul_s2a(m2_ce);\n    p_ab <= vp_mul_s2b(r_ab);\n    p_ce <= vp_mul_s2b(r_ce);\n    s1 <= fp_add_s1(p_ab, p_ce);\n    s2 <= fp_add_s2(s1);\n    s3a <= vp_add_s3a(s2);\n    s3 <= vp_add_s3b(s3a);\n    y1 <= fp_add_s4(s3);\n    y2 <= y1;\n  end\n  assign y = y2;\nendmodule\n\nmodule vp_pair_base\n  import otpu_fp::*;\n(\n  input  logic clk_s,\n  input  logic en,\n  input  f32_t a0, b0, c0, e0, a1, b1, c1, e1,\n  output f32_t y0, y1\n);\n  otpu_fmma #(.LM(2), .LA(4)) u_0 (.clk(clk_s), .en, .a(a0), .b(b0), .c(c0), .e(e0), .y(y0));\n  otpu_fmma #(.LM(2), .LA(4)) u_1 (.clk(clk_s), .en, .a(a1), .b(b1), .c(c1), .e(e1), .y(y1));\nendmodule\n\nmodule vp_pair_pump\n  import otpu_fp::*;\n#(parameter int DEEP = 0, parameter int XR = 1) (\n  input  logic clk_s,\n  input  logic clk_f,\n  input  logic en,                  // clk_s: both fast cycles of a frozen core cycle freeze\n  input  f32_t a0, b0, c0, e0, a1, b1, c1, e1,   // clk_s registers (the lanes' operands)\n  output f32_t y0, y1               // clk_s registers\n);\n  localparam int L = DEEP == 2 ? 10 : DEEP == 1 ? 6 * (1 + XR) : 6;   // the unit's fast latency\n  initial if (L % 2) $fatal(1, \"vp_pair_pump: the unit's fast latency must be even\");\n  logic t_s, t_f;\n  always_ff @(posedge clk_s) t_s <= ~t_s;\n  always_ff @(posedge clk_f) t_f <= t_s;\n  wire ph = t_s ^ t_f;              // 1: the first fast cycle of a core cycle\n  // the input registers of the unit: lane 0 at the mid edge, lane 1 at the slow edge. en is\n  // a clk_s register: it holds over both fast edges of its core cycle (a slow -> fast path of one\n  // fast period, as are the operands of lane 0)\n  f32_t ra, rb, rc, re, y;\n  always_ff @(posedge clk_f) if (en) begin\n    ra <= ph ? a0 : a1;\n    rb <= ph ? b0 : b1;\n    rc <= ph ? c0 : c1;\n    re <= ph ? e0 : e1;\n  end\n  if (DEEP == 2) begin : g_split\n    vp_fmma_split u_u (.clk(clk_f), .en, .a(ra), .b(rb), .c(rc), .e(re), .y);\n  end else if (DEEP == 1) begin : g_deep\n    vp_fmma_deep #(.XR(XR)) u_u (.clk(clk_f), .en, .a(ra), .b(rb), .c(rc), .e(re), .y);\n  end else begin : g_flat\n    otpu_fmma #(.LM(2), .LA(4)) u_u (.clk(clk_f), .en, .a(ra), .b(rb), .c(rc), .e(re), .y);\n  end\n  // lane 0's result in a second half (ph = 0), lane 1's in a first half\n  f32_t h0, h1;\n  always_ff @(posedge clk_f) if (en) begin\n    if (!ph) h0 <= y;\n    else     h1 <= y;\n  end\n  assign y0 = h0;\n  assign y1 = h1;\nendmodule\n\n// the out-of-context top: the clocks from one MMCME2_ADV (VCO 133.33 x MULT, clk_s = VCO / DIV_S,\n// clk_f = VCO / DIV_F) through BUFGs; NP pairs side by side; every input and output registered\n// at clk_s. VAR 0: vp_pair_base; 1: vp_pair_pump (today's unit at clk_f); 2: vp_pair_pump with\n// the deep unit (XR); 3: vp_pair_pump with the split unit.\nmodule vpu_pump_top\n  import otpu_fp::*;\n#(\n  parameter int VAR = 1,\n  parameter int NP = 4,             // pairs (8 lanes: one VPU's slot 0)\n  parameter int XR = 1,\n  parameter real MULT = 8.0,\n  parameter real DIV_S = 8.0,\n  parameter int DIV_F = 4\n) (\n  input  logic clk_in,\n  input  logic en_in,\n  input  f32_t a_in [2*NP], b_in [2*NP], c_in [2*NP], e_in [2*NP],\n  output f32_t y_out [2*NP]\n);\n  logic clkfb, clk_s_u, clk_f_u, clk_s, clk_f, locked;\n`ifdef SYNTHESIS\n  MMCME2_ADV #(\n    .BANDWIDTH(\"OPTIMIZED\"), .COMPENSATION(\"INTERNAL\"), .DIVCLK_DIVIDE(1),\n    .CLKFBOUT_MULT_F(MULT), .CLKFBOUT_PHASE(0.0), .CLKIN1_PERIOD(7.5),\n    .CLKOUT0_DIVIDE_F(DIV_S), .CLKOUT0_PHASE(0.0), .CLKOUT0_DUTY_CYCLE(0.5),\n    .CLKOUT1_DIVIDE(DIV_F), .CLKOUT1_PHASE(0.0), .CLKOUT1_DUTY_CYCLE(0.5)\n  ) u_mmcm (\n    .CLKIN1(clk_in), .CLKIN2(1'b0), .CLKINSEL(1'b1), .CLKFBIN(clkfb), .CLKFBOUT(clkfb),\n    .CLKFBOUTB(), .CLKOUT0(clk_s_u), .CLKOUT0B(), .CLKOUT1(clk_f_u), .CLKOUT1B(),\n    .CLKOUT2(), .CLKOUT2B(), .CLKOUT3(), .CLKOUT3B(), .CLKOUT4(), .CLKOUT5(), .CLKOUT6(),\n    .LOCKED(locked), .PWRDWN(1'b0), .RST(1'b0),\n    .DADDR(7'd0), .DCLK(1'b0), .DEN(1'b0), .DI(16'd0), .DO(), .DRDY(), .DWE(1'b0),\n    .PSCLK(1'b0), .PSEN(1'b0), .PSINCDEC(1'b0), .PSDONE(), .CLKINSTOPPED(), .CLKFBSTOPPED());\n  BUFG u_bs (.I(clk_s_u), .O(clk_s));\n  BUFG u_bf (.I(clk_f_u), .O(clk_f));\n`else\n  assign clk_s = clk_in;            // (simulation: tb_vpu_pump drives the pairs directly)\n  assign clk_f = clk_in;\n`endif\n  (* max_fanout = 64 *) logic en;\n  f32_t a [2*NP], b [2*NP], c [2*NP], e [2*NP], y [2*NP];\n  always_ff @(posedge clk_s) begin\n    en <= en_in;\n    a <= a_in; b <= b_in; c <= c_in; e <= e_in;\n    y_out <= y;\n  end\n  for (genvar p = 0; p < NP; p++) begin : g_p\n    if (VAR == 0) begin : g_b\n      vp_pair_base u_p (.clk_s, .en, .a0(a[2*p]), .b0(b[2*p]), .c0(c[2*p]), .e0(e[2*p]),\n                        .a1(a[2*p+1]), .b1(b[2*p+1]), .c1(c[2*p+1]), .e1(e[2*p+1]),\n                        .y0(y[2*p]), .y1(y[2*p+1]));\n    end else begin : g_q\n      vp_pair_pump #(.DEEP(VAR == 3 ? 2 : VAR == 2 ? 1 : 0), .XR(XR)) u_p (\n        .clk_s, .clk_f, .en, .a0(a[2*p]), .b0(b[2*p]), .c0(c[2*p]), .e0(e[2*p]),\n        .a1(a[2*p+1]), .b1(b[2*p+1]), .c1(c[2*p+1]), .e1(e[2*p+1]),\n        .y0(y[2*p]), .y1(y[2*p+1]));\n    end\n  end\nendmodule\n", "rtl/mem/otpu_actram.sv": "// ACT RAM: the MXU's stationary operand. ROWS rows x BLOCKS blocks x D int8, plus one 64-bit\n// scale record per (row, block): {da3, da2, da1, da0, Sa}, the row's fp32 Sa and the block's four\n// sub-block offsets (QACT, docs/isa.md \"Quantization\"). The quantizer writes up to LANES consecutive bytes (and one scale) per\n// cycle; its byte index is LANES aligned, so the bytes sit in one block. With `w_dup` (QACT DUP)\n// the bytes and the scale also go to row w_row + w_off (w_off: the QACT's row count; DUP rows\n// stay below MCOLS). The MXU reads one block of MCOLS rows per cycle: rows g*MCOLS ..\n// g*MCOLS+MCOLS-1 of group `r_grp` (ROWS > MCOLS: the MXU replays a weight chunk for each group\n// of an MM), block r_blk, or r_blk2 for the rows in r_hi (MM PAIR: the odd blocks).\n//\n// Block RAM: one memory per column j (rows j, j+MCOLS, ...) and piece p (bytes p*PB ..\n// p*PB+PB-1: four 64-bit block RAMs at PB = 32), GROUPS*BLOCKS words of PB bytes with byte\n// write enables, group-major. The read is registered (the MXU's first pipeline register) and\n// advances with the column's `ren` bit (otpu_mxu: the columns of the MM's rows); a read of a block written at the same edge returns the old bytes. Writes\n// land three cycles after they are presented: the quantizer's write is registered as it arrives\n// and again (LANES bytes, their index and row, the scale), so it crosses from the quantizer in\n// that narrow form in two hops and the lane placement (LANES -> D bytes) starts at a flip-flop\n// by the block RAMs, then registered again in place (bytes; the block address, column select\n// and group once per column and piece). The quantizer reports done two cycles after its last\n// write and the sequencer releases a dependent MM two cycles after that (otpu_quant), so a\n// consumed read (r_use, the MXU's pop) never names a block whose write is still in flight: the\n// simulation checks it.\nmodule otpu_actram #(\n  parameter int D      = 32,\n  parameter int MCOLS  = 8,\n  parameter int ROWS   = MCOLS,     // a multiple of MCOLS, MCOLS a power of two if more\n  parameter int BLOCKS = 64,\n  parameter int LANES  = 8\n) (\n  input  logic                   clk,\n  input  logic [LANES-1:0]       we,          // lane l writes byte w_idx + l\n  input  logic [7:0]             w_row,\n  input  logic [31:0]            w_idx,       // byte index within the row: block*D + i\n  input  logic [LANES-1:0][7:0]  w_data,\n  input  logic                   w_dup,\n  input  logic [7:0]             w_off,\n  input  logic                   swe,\n  input  logic [7:0]             s_row,\n  input  logic [15:0]            s_blk,\n  input  logic [63:0]            s_data,\n  input  logic [MCOLS-1:0]       ren,         // per column\n  input  logic                   r_use,       // this edge's read is consumed (simulation checks)\n  input  logic [15:0]            r_blk,\n  input  logic [15:0]            r_blk2,\n  input  logic [MCOLS-1:0]       r_hi,\n  input  logic [7:0]             r_grp,\n  output wire  [MCOLS*D*8-1:0]   r_data,      // row j at [j*D*8 +: D*8], byte i at [+8i]\n  output wire  [MCOLS*64-1:0]    r_scale\n);\n  localparam int BW = $clog2(BLOCKS);\n  localparam int DW = $clog2(D);\n  localparam int GROUPS = ROWS / MCOLS;\n  localparam int GW = (GROUPS > 1) ? $clog2(GROUPS) : 1;\n  localparam int PB = (D > 32) ? 32 : D;      // bytes per piece\n  localparam int NP = D / PB;\n  localparam int RAW = $clog2(GROUPS * BLOCKS);  // the RAMs' address bits\n  initial if (D % LANES != 0) $fatal(1, \"otpu_actram: LANES must divide D\");\n  initial if (D % PB != 0) $fatal(1, \"otpu_actram: D must be a multiple of 32 above 32\");\n  initial if (ROWS % MCOLS != 0 || (GROUPS > 1 && (MCOLS & (MCOLS - 1)) != 0))\n    $fatal(1, \"otpu_actram: ROWS must be a multiple of MCOLS, a power of two if larger\");\n  // a row's column and group\n  function automatic int col(input logic [7:0] r);\n    return (MCOLS > 1) ? int'(r) % MCOLS : 0;\n  endfunction\n  function automatic logic [GW-1:0] grp(input logic [7:0] r);\n    return (GROUPS > 1) ? GW'(int'(r) / MCOLS) : '0;\n  endfunction\n  // a write to row r (with dup, also to row r + off) selects column j, in the group returned\n  function automatic logic sel(input int j, input logic [7:0] r, input logic dup,\n                               input logic [7:0] off);\n    return (col(r) == j) || (dup && col(8'(r + off)) == j);\n  endfunction\n  function automatic logic [GW-1:0] sgrp(input int j, input logic [7:0] r, input logic [7:0] off);\n    return (col(r) == j) ? grp(r) : grp(8'(r + off));\n  endfunction\n  // the quantizer's write as it arrives (_i) and again (_h): the long hop from the quantizer is\n  // these two narrow registers (on 959b425 at 133.33 MHz the quantizer sat 600 RPM units from\n  // these block RAMs and the wide write register below, fed straight from it, missed timing; on\n  // 812bb01, with one, its replicas by the placement logic were the worst path, 96% route)\n  (* shreg_extract = \"no\" *) logic [LANES-1:0]      we_i, we_h;\n  (* shreg_extract = \"no\" *) logic [7:0]            w_row_i, w_off_i, s_row_i;\n  (* shreg_extract = \"no\" *) logic [7:0]            w_row_h, w_off_h, s_row_h;\n  (* shreg_extract = \"no\" *) logic [DW+BW-1:0]      w_idx_i, w_idx_h;\n  (* shreg_extract = \"no\" *) logic [LANES-1:0][7:0] w_data_i, w_data_h;\n  (* shreg_extract = \"no\" *) logic                  w_dup_i, swe_i, w_dup_h, swe_h;\n  (* shreg_extract = \"no\" *) logic [BW-1:0]         s_blk_i, s_blk_h;\n  (* shreg_extract = \"no\" *) logic [63:0]           s_data_i, s_data_h;\n  always_ff @(posedge clk) begin\n    we_i <= we;\n    w_row_i <= w_row;\n    w_idx_i <= w_idx[DW+BW-1:0];\n    w_data_i <= w_data;\n    w_dup_i <= w_dup;\n    w_off_i <= w_off;\n    swe_i <= swe;\n    s_row_i <= s_row;\n    s_blk_i <= s_blk[BW-1:0];\n    s_data_i <= s_data;\n    we_h <= we_i;\n    w_row_h <= w_row_i;\n    w_idx_h <= w_idx_i;\n    w_data_h <= w_data_i;\n    w_dup_h <= w_dup_i;\n    w_off_h <= w_off_i;\n    swe_h <= swe_i;\n    s_row_h <= s_row_i;\n    s_blk_h <= s_blk_i;\n    s_data_h <= s_data_i;\n  end\n\n  // the write, as byte enables and bytes in place (registered; the block address, column select\n  // and group per column and piece in g_row), and the scale write (registered); per column:\n  // selected, and the group of the row it writes\n  logic [D-1:0]     wbe;\n  logic [D*8-1:0]   wd;\n  logic [MCOLS-1:0] ssel;\n  logic [GW-1:0]    sg [MCOLS];\n  logic [BW-1:0]    sb;\n  logic [63:0]      sd;\n  // the placement register's inputs: per column, selected and the group of the row it writes\n  logic [MCOLS-1:0] wsel_n, ssel_n;\n  logic [GW-1:0]    wg_n [MCOLS], sg_n [MCOLS];\n  always_comb\n    for (int j = 0; j < MCOLS; j++) begin\n      wsel_n[j] = sel(j, w_row_h, w_dup_h, w_off_h) && (|we_h);\n      ssel_n[j] = swe_h && sel(j, s_row_h, w_dup_h, w_off_h);\n      wg_n[j] = sgrp(j, w_row_h, w_off_h);\n      sg_n[j] = sgrp(j, s_row_h, w_off_h);\n    end\n  always_ff @(posedge clk) begin\n    wbe <= '0;\n    wd <= '0;\n    for (int l = 0; l < LANES; l++) begin\n      wbe[w_idx_h[DW-1:0] + DW'(l)] <= we_h[l];\n      wd[8 * (w_idx_h[DW-1:0] + DW'(l)) +: 8] <= w_data_h[l];\n    end\n    ssel <= ssel_n;\n    for (int j = 0; j < MCOLS; j++) sg[j] <= sg_n[j];\n    sb <= s_blk_h;\n    sd <= s_data_h;\n  end\n`ifndef SYNTHESIS\n  initial begin we_i = '0; swe_i = 1'b0; we_h = '0; swe_h = 1'b0; ssel = '0; end\n`endif\n\n  for (genvar j = 0; j < MCOLS; j++) begin : g_row\n    logic [63:0]    rs;\n    wire [BW-1:0] rb = r_hi[j] ? r_blk2[BW-1:0] : r_blk[BW-1:0];\n    wire [GW+BW-1:0] ra = (GROUPS > 1) ? {r_grp[GW-1:0], rb} : (GW+BW)'(rb);\n    wire [GW+BW-1:0] sa = (GROUPS > 1) ? {sg[j], sb} : (GW+BW)'(sb);\n    // a piece's block RAMs take their write address from a copy of the block address (and\n    // select, group) of their own: on 812bb01 one wb drove all MCOLS * D / 8 of them across\n    // the systolic array's span, 6.7 ns of wire with no logic\n    for (genvar p = 0; p < NP; p++) begin : g_pc\n      (* keep *) logic [BW-1:0] wb;\n      (* keep *) logic          wsel;\n      (* keep *) logic [GW-1:0] wg;\n      logic [PB*8-1:0] rd;\n      always_ff @(posedge clk) begin\n        wb <= w_idx_h[DW +: BW];\n        wsel <= wsel_n[j];\n        wg <= wg_n[j];\n      end\n      wire [GW+BW-1:0] wa = (GROUPS > 1) ? {wg, wb} : (GW+BW)'(wb);\n      // the piece's bytes: a technology RAM with byte enables (rtl/tech)\n      otpu_ram_1r1w_be #(.W(PB*8), .N(GROUPS*BLOCKS), .STYLE(\"auto\")) u_act (\n        .clk, .we(wsel), .wbe(wbe[p*PB +: PB]), .wa(wa[RAW-1:0]), .wd(wd[p*PB*8 +: PB*8]),\n        .re(ren[j]), .ra(ra[RAW-1:0]), .rd);\n      assign r_data[j*D*8 + p*PB*8 +: PB*8] = rd;\n`ifndef SYNTHESIS\n      initial wsel = 1'b0;\n`endif\n    end\n    // the column's block scale records\n    otpu_ram_1r1w #(.W(64), .N(GROUPS*BLOCKS), .STYLE(\"auto\")) u_asc (\n      .clk, .we(ssel[j]), .wa(sa[RAW-1:0]), .wd(sd), .re(ren[j]), .ra(ra[RAW-1:0]), .rd(rs));\n    assign r_scale[j*64 +: 64] = rs;\n`ifndef SYNTHESIS\n    // a consumed read of a block (or its scale) with a write in any register: it would return\n    // the old bytes\n    wire [GW+BW-1:0] wa = g_pc[0].wa;\n    wire             wsel_1 = sel(j, w_row_i, w_dup_i, w_off_i) && (|we_i);\n    wire             ssel_1 = swe_i && sel(j, s_row_i, w_dup_i, w_off_i);\n    wire [GW+BW-1:0] wa_1 = (GROUPS > 1) ? {sgrp(j, w_row_i, w_off_i), w_idx_i[DW +: BW]}\n                                         : (GW+BW)'(w_idx_i[DW +: BW]);\n    wire [GW+BW-1:0] sa_1 = (GROUPS > 1) ? {sgrp(j, s_row_i, w_off_i), s_blk_i} : (GW+BW)'(s_blk_i);\n    wire [GW+BW-1:0] wa_n = (GROUPS > 1) ? {wg_n[j], w_idx_h[DW +: BW]} : (GW+BW)'(w_idx_h[DW +: BW]);\n    wire [GW+BW-1:0] sa_n = (GROUPS > 1) ? {sg_n[j], s_blk_h} : (GW+BW)'(s_blk_h);\n    always @(posedge clk)\n      if (ren[j] && r_use && ((g_pc[0].wsel && wa == ra) || (wsel_n[j] && wa_n == ra) ||\n                           (wsel_1 && wa_1 == ra) || (ssel[j] && sa == ra) ||\n                           (ssel_n[j] && sa_n == ra) || (ssel_1 && sa_1 == ra)))\n        $fatal(1, \"otpu_actram: column %0d block %0d read while its write is in flight at %0t\",\n               j, ra, $time);\n`endif\n  end\nendmodule\n", "rtl/mem/otpu_dram.sv": "// Behavioural per-slice DRAM for simulation (the board version sits behind a DDR3/HBM\n// controller). Port A: one read of the aligned 32 bytes holding word a_addr (the MXU's scale\n// lines) or one byte-enabled word write per cycle; port SW: one\n// byte-enabled word write per cycle (the quantizer's QST stores). Port B: one\n// D-byte burst per cycle, read (the MXU's streamed operand, DMA loads) or word-masked write\n// (DMA stores). Reads return LAT cycles later, in order; data is sampled at the request.\nmodule otpu_dram #(\n  parameter int WORDS = 1 << 18,\n  parameter int D     = 32,\n  parameter int LAT   = 8,\n  parameter int SID   = 0\n) (\n  input  logic              clk,\n  input  logic              a_req,\n  input  logic              a_we,\n  input  logic [31:0]       a_addr,     // word address\n  input  logic [31:0]       a_wdata,\n  input  logic [3:0]        a_be,\n  output logic              a_rvalid,\n  output logic [255:0]      a_rdata,    // words (a_addr & ~7) .. (a_addr | 7), the lowest first\n  input  logic              sw_req,\n  input  logic [31:0]       sw_addr,\n  input  logic [31:0]       sw_wdata,\n  input  logic [3:0]        sw_be,\n  input  logic              b_req,\n  input  logic              b_tag,      // requester tag, returned with the read data\n  input  logic              b_we,\n  input  logic [D/4-1:0]    b_wmask,    // word enables for a burst write\n  input  logic [D*8-1:0]    b_wdata,\n  input  logic [31:0]       b_addr,     // word address of the chunk\n  output logic              b_rvalid,\n  output logic              b_rtag,\n  output logic [D*8-1:0]    b_rdata,\n  output logic              rd_idle,    // no read in flight\n  input  logic              dump\n);\n  localparam int AW = $clog2(WORDS);\n  localparam int CW = D / 4;\n\n  logic [31:0] mem [WORDS];\n\n  logic [LAT-1:0]    av, bv, bt;\n  logic [255:0]      ad [LAT];\n  logic [D*8-1:0]    bd [LAT];\n\n`ifndef SYNTHESIS\n  // the host's writes during the run (WAITW's tests): <dir>/poke_<SID>.txt, lines \"cycle word\n  // value\" (hex, in cycle order), each word written as the cycle count reaches its cycle\n  localparam int NPOKE = 64;\n  longint      pk_c [NPOKE];\n  logic [31:0] pk_a [NPOKE], pk_v [NPOKE];\n  int          pk_n = 0, pk_i = 0;\n  longint      pk_cyc = 0;\n`endif\n  always_ff @(posedge clk) begin\n`ifndef SYNTHESIS\n    pk_cyc <= pk_cyc + 1;\n    if (pk_i < pk_n && pk_cyc >= pk_c[pk_i]) begin\n      mem[pk_a[pk_i][AW-1:0]] <= pk_v[pk_i];\n      pk_i <= pk_i + 1;\n    end\n`endif\n    if (a_req && a_we) begin\n      for (int b = 0; b < 4; b++)\n        if (a_be[b]) mem[a_addr[AW-1:0]][8*b +: 8] <= a_wdata[8*b +: 8];\n    end\n    if (sw_req) begin\n      for (int b = 0; b < 4; b++)\n        if (sw_be[b]) mem[sw_addr[AW-1:0]][8*b +: 8] <= sw_wdata[8*b +: 8];\n    end\n    av[0] <= a_req && !a_we;\n    for (int w = 0; w < 8; w++) ad[0][32*w +: 32] <= mem[{a_addr[AW-1:3], 3'(w)}];\n    bv[0] <= b_req && !b_we;\n    bt[0] <= b_tag;\n    for (int w = 0; w < CW; w++) bd[0][32*w +: 32] <= mem[AW'(b_addr + w)];\n    if (b_req && b_we)\n      for (int w = 0; w < CW; w++) if (b_wmask[w]) mem[AW'(b_addr + w)] <= b_wdata[32*w +: 32];\n    for (int k = 1; k < LAT; k++) begin\n      av[k] <= av[k-1];\n      ad[k] <= ad[k-1];\n      bv[k] <= bv[k-1];\n      bt[k] <= bt[k-1];\n      bd[k] <= bd[k-1];\n    end\n  end\n  assign a_rvalid = av[LAT-1];\n  assign a_rdata  = ad[LAT-1];\n  assign b_rvalid = bv[LAT-1];\n  assign b_rtag   = bt[LAT-1];\n  assign b_rdata  = bd[LAT-1];\n  assign rd_idle  = !(|av) && !(|bv);\n\n`ifndef SYNTHESIS\n  // Images are raw binary: dram_<SID>.bin holds big-endian words ($fread order) and the dump\n  // dram_out_<SID>.bin is little-endian (the byte order of the DRAM itself).\n  string dir;\n  integer fd, nread;\n  initial begin\n    av = '0;\n    bv = '0;\n    bt = '0;\n    for (int i = 0; i < WORDS; i++) mem[i] = '0;\n    if ($value$plusargs(\"dir=%s\", dir)) begin\n      fd = $fopen($sformatf(\"%s/dram_%0d.bin\", dir, SID), \"rb\");\n      if (fd != 0) begin\n        nread = $fread(mem, fd);\n        $fclose(fd);\n      end\n      fd = $fopen($sformatf(\"%s/poke_%0d.txt\", dir, SID), \"r\");\n      if (fd != 0) begin\n        while (pk_n < NPOKE && $fscanf(fd, \"%h %h %h\", pk_c[pk_n], pk_a[pk_n], pk_v[pk_n]) == 3)\n          pk_n++;\n        $fclose(fd);\n      end\n    end\n  end\n  always @(posedge clk) if (dump) begin\n    fd = $fopen($sformatf(\"%s/dram_out_%0d.bin\", dir, SID), \"wb\");\n    for (int i = 0; i < WORDS; i++) $fwrite(fd, \"%u\", mem[i]);\n    $fclose(fd);\n  end\n`endif\nendmodule\n", "rtl/mem/otpu_native_dram.sv": "// Slice DRAM ports (as otpu_dram) on the two DDR3 channels' native ports, 512-bit data: one\n// command per 64-byte beat (LiteDRAM's native port behind otpu_mem_ch; docs/litedram.md section\n// 3). The slice side, the address map and the behaviour are those of otpu_axi_dram, the MIG AXI\n// builds' adapter it replaced. What existed only for AXI and the MIG's AXI front end, whose\n// transactions cost a lot, is gone: read and write bursts, their gather timers and 4 KB splits,\n// AXI IDs, write responses and err. A native command costs nothing per transaction, so a request\n// goes out as soon as it may, one command per beat.\n//\n// Address map: the slice's byte address space is interleaved over the channels in 64-byte beats:\n// logical beat b = addr / 64 (chunk m = b / 2) is channel beat m (n_caddr: the channel address's\n// bits 30:6, 2 GiB per channel) on channel c = b % 2, or with CHASH on c = (b % 2) ^ parity(m). A\n// D = 128-byte chunk (port B; requests are chunk aligned) is therefore one beat on each channel,\n// and a streamed operand uses both channels evenly. CHASH swaps the chunks' halves by the parity\n// of the chunk index, so the beats at a power-of-two stride of chunks (a transposed V's column:\n// one byte per cache row) fall half on each channel instead of all on one. The host applies the\n// same map when it fills and reads the memory (opentpu/host/board.py; CAPS bit7 = CHASH).\n//\n// The native port, per channel (core clock): a command stream (we, beat); one write-data beat\n// (data, byte mask with 1 = write the byte) per write command, in write-command order, which may\n// be taken before or after its command; read data in read-command order with no backpressure;\n// n_wdone, the count of write beats the controller has taken. One master's commands on one\n// channel execute in command order (LiteDRAM: one port, in-order bank queues; the MIG keeps the\n// order of accesses to one address): a read issued after a write to its beat returns the written\n// data without waiting for n_wdone, and a write counted in n_wdone is visible to the other master\n// (XDMA, the host) too.\n//\n// Per channel, one command a cycle, from (in this priority) the A queue (a read's run of APF\n// commands, or a write), the SW queue's next fill read, the SW queue's oldest write, the B queue\n// (a read or a write). A command shown and not taken is shown again unchanged (hv); a write shows\n// its command and its data together, until both are taken (c_done, d_done). Reads need response\n// room, reserved as the command goes: a B read one entry of its channel's RD-beat FIFO, an A run\n// APF entries of the AD-beat FIFO; an SW fill read's data goes to its queue slot. Each channel's\n// reads return in command order, so a tag FIFO per channel (source, SW slot; its head registered)\n// routes every returning beat to B, A or the SW slot. The response FIFOs check for overflow in\n// simulation: read data never arrives without reserved room.\n//\n// Port B: chunk reads and word-masked chunk writes; a partial beat goes out with its byte mask\n// (the channel module does the controller's read-modify-write, or the MIG's wr_bytes). Port A:\n// single-word reads and byte-enabled word writes (a partial beat). Port SW: byte-enabled word\n// writes (the quantizer's QST stores), independent of A so that they never hold up the MXU's\n// scale reads. SW writes gather per channel in a one-beat buffer: writes to the same beat merge,\n// and the beat goes to the SW queue when a write to another beat arrives, when all its bytes are\n// written, or after WGATHER cycles without an SW write (so a QST's byte stream costs one write per\n// beat, not per byte). wr_idle stays low while a beat is gathered, so a QST still completes only\n// once its writes are in memory. Gathered beats go out in order through one queue per channel; a\n// beat with bytes missing (a transposed V column: one byte per beat) first reads its beat (a fill\n// read) and is written whole, so the controller's read-modify-write, which holds the channel for a\n// read's whole latency, never runs for a QST. The queue holds WQD beats per channel, so that the\n// fill reads of a transposed V column overlap (a slot lives from its push until its write goes\n// out: about a read latency). The queue's writes wait while its fill reads still go out (unless\n// it is half full), so the controller sees runs of reads, then runs of writes.\n// A reads that fall in the beat of the previous A read (the MXU's scale stream: 16 scales per\n// beat) reuse it without a DRAM access. An A read that misses fetches a run of APF\n// channel-consecutive beats (APF read commands); the A reads that follow the run in order take\n// its beats without a DRAM access, and a read off the run (or after an A write) drops the beats\n// not yet taken.\n//\n// Ordering. otpu_axi_dram waited for AXI write responses; here the command stream orders instead.\n// Once a command has entered a channel's stream, stream order is memory order. Before that, the\n// A, SW and B queues may reorder against each other, as AXI's read and write channels did: the\n// slice orders what depends across ports (a read that depends on a QST or a B write comes after\n// wr_idle). Within a queue, requests go out in order. So:\n// - An SW fill read waits until every older SW write of its beat has entered the stream (not\n//   until it is done): a counter per bucket (a hash of the beat) counts the slots past the read\n//   point whose write has not gone out, and a read waits while its bucket's count is not zero (a\n//   collision only delays it). The fill read then follows those writes in the stream and reads\n//   their data.\n// - A fill read and its beat's write are not atomic: a B write, or the host's, to the beat's\n//   other bytes between them would be lost. The slice keeps B writes out (a QST's scoreboard\n//   footprint covers every word of its beats, otpu_pkg beats(), so an ST, DSTEP or STREAM into\n//   one waits for the QST or the QST for it); the host must not write the beats of a running\n//   QST (docs/isa.md, QST).\n// - A write drops channel c's A run, or the reused beat, when it has gone out on c (command and\n//   data taken; the stream carries nothing else meanwhile) and its beat is in them: the run's\n//   commands before it read the old beat, the ones after it the new. The drop lands at the end\n//   of the cycle after the write goes out. An A read taken before then may still take the old\n//   beat; it does not depend on the write: the slice waits for wr_idle, which is high in that\n//   cycle at the earliest, and an A request then waits a cycle in its port A register. An A\n//   write also drops them when it is taken: the A reads after it in the A queue would otherwise\n//   take a beat fetched before it. So the QSTs that stream while an MM runs, and DSTEP's state\n//   write-back, cost the MXU's scale stream no runs.\n// - wr_idle: every accepted write has gone out and is counted in n_wdone.\n// - rd_idle: every A and B read taken has returned its data (a read still in one of the slice's\n//   port registers is the slice's: otpu_slice, otpu_board).\n//   This adapter does not reset with the run (the board's RUN), so a run the host stops leaves\n//   its reads to come back after it: the loader and the next run wait for rd_idle (otpu_slice,\n//   otpu_board). An A run's beats not asked for are not in it (the next miss drops them).\n// - The host's writes come through the channels' other master (XDMA), which this adapter does not\n//   see, so they drop neither the reused beat nor the runs. a_flush drops both where the host may\n//   have written since the beats were fetched: between runs (the core's reset), at a program load\n//   and when a WAITW's word holds (the host writes the words a program reads after a WAITW before\n//   the word it waits for). Their beats not yet taken are dropped by the next miss, as after a\n//   write. Without it a run's first A reads took the previous run's beat over the host's rewrite\n//   (the 35B's back-to-back embed runs: token 0's block scales for tokens 1 and 2).\n// Requests are taken when req && rdy; rdy depends on registered state only. Reads return in\n// order per port (the B tag with its data).\nmodule otpu_native_dram #(\n  parameter int D = 128,\n  parameter int QD = 16,                             // request queue depth per channel and port\n  parameter int WQD = 32,                            // SW (gathered beat) queue depth per channel\n  parameter bit CHASH = 1'b1,                        // address map: see the top\n  parameter int WGATHER = 4,                         // idle cycles before a gathered SW beat goes out\n  parameter int RD = 128,                            // B read beats in flight per channel\n  parameter int AD = 64,                             // A read beats in flight per channel\n  // A read run (prefetch), beats. 32: decode's knee (docs/litedram.md section 11; 8 -> 32 is\n  // 0.9-1.3% fewer cycles per token, 64 no better): fewer runs, so fewer row and bank changes\n  // between the scale stream and the others\n  parameter int APF = 32\n) (\n  input  logic              clk,\n  input  logic              rst,\n  input  logic              a_flush,    // drop port A's reused beat and runs (see Ordering)\n  // slice side\n  output logic              a_rdy_x,\n  input  logic              a_req_x,\n  input  logic              a_we_x,\n  input  logic [31:0]       a_addr_x,   // word address\n  input  logic [31:0]       a_wdata_x,\n  input  logic [3:0]        a_be_x,\n  output logic              a_rvalid,\n  output logic [255:0]      a_rdata,    // the aligned 32 bytes holding word a_addr (half a beat)\n  output logic              sw_rdy,\n  input  logic              sw_req,\n  input  logic [31:0]       sw_addr,    // word address\n  input  logic [31:0]       sw_wdata,\n  input  logic [3:0]        sw_be,\n  output logic              b_rdy,\n  input  logic              b_req,\n  input  logic              b_tag,\n  input  logic              b_we,\n  input  logic [D/4-1:0]    b_wmask,\n  input  logic [D*8-1:0]    b_wdata,\n  input  logic [31:0]       b_addr,     // word address (chunk aligned)\n  input  logic              b_par,      // ^b_addr[31:5] (the channel hash; see b_sw)\n  output logic              b_rvalid,\n  output logic              b_rtag,\n  output logic [D*8-1:0]    b_rdata,\n  output logic              wr_idle,\n  output logic              rd_idle,    // no A or B read in flight (taken, its data not yet out)\n  // native memory masters, one per channel ([1:0] = channel)\n  output logic [1:0]        n_cvalid,\n  input  logic [1:0]        n_cready,\n  output logic [1:0]        n_cwe,\n  output logic [1:0][24:0]  n_caddr,    // the beat in the channel (channel address bits 30:6)\n  output logic [1:0]        n_wvalid,   // write data: one beat per write command, in order\n  input  logic [1:0]        n_wready,\n  output logic [1:0][511:0] n_wdata,\n  output logic [1:0][63:0]  n_wmask,    // 1 = write the byte\n  input  logic [1:0]        n_rvalid,   // read data, in read-command order, no backpressure\n  input  logic [1:0][511:0] n_rdata,\n  input  logic [1:0][15:0]  n_wdone     // write beats taken by the controller (mod 2^16)\n);\n  initial if (D != 128) $fatal(1, \"otpu_native_dram: D must be 128 (one beat per channel)\");\n  // (AD >= 2 APF - 1: a run can start while the previous run's untaken beats are stored)\n  initial if (APF < 1 || APF > 64 || AD < 2 * APF - 1) $fatal(1, \"otpu_native_dram: bad APF\");\n  localparam int QW = $clog2(QD);\n  localparam int WW = $clog2(WQD);\n  localparam int NH = 64;                            // SW hazard buckets (see w_blk)\n  localparam int HW = $clog2(NH);\n  localparam int RW = $clog2(RD);\n  localparam int AW_ = $clog2(AD);\n  localparam int RNW = (APF > 1) ? $clog2(APF) : 1;  // a run's beat index\n  localparam int OD = 2 * RD;                        // B tags / A order entries in flight (2^k)\n  localparam int OW = $clog2(OD);\n  localparam int TD = 2 ** $clog2(RD + AD + WQD);    // reads in flight per channel (tags)\n  localparam int TW = $clog2(TD);\n  localparam int PW = $clog2(4 * QD + 2 * WQD + 1);  // writes accepted and not gone out\n  localparam logic [1:0] K_B = 2'd0, K_A = 2'd1, K_W = 2'd2;          // a read's source\n  localparam logic [1:0] S_A = 2'd0, S_WR = 2'd1, S_WW = 2'd2, S_B = 2'd3;  // a command's\n\n  // the hazard bucket of a channel beat: an XOR fold, so that the strided beats of a transposed\n  // V column spread over the buckets\n  function automatic logic [HW-1:0] whash(input logic [24:0] a);\n    return a[5:0] ^ a[11:6] ^ a[17:12] ^ a[23:18] ^ {5'd0, a[24]};\n  endfunction\n\n  // n + inc - dec as a choice among n - 1, n and n + 1: the counts the slice's requests move\n  // (the B and SW queues, the B tags) take their late strobes after the adders, not before\n  function automatic logic [15:0] updn(input logic [15:0] n, input logic inc, input logic dec);\n    return inc == dec ? n : inc ? n + 1'b1 : n - 1'b1;\n  endfunction\n\n  // the channel of a word address's beat\n  function automatic logic chan_of(input logic [31:0] word_addr);\n    return word_addr[4] ^ (CHASH && ^word_addr[31:5]);\n  endfunction\n\n  // ------------------------------------------------------------------ request queues\n  // per channel: qb (port B beats), qa (port A beats), qw (gathered SW beats); m: the channel beat\n  typedef struct packed {\n    logic         we;\n    logic [24:0]  m;\n    logic [511:0] data;\n    logic [15:0]  wmask;       // word enables\n  } qb_t;\n  typedef struct packed {\n    logic         we;\n    logic [24:0]  m;\n    logic [3:0]   idx;         // word in the beat\n    logic [31:0]  data;\n    logic [3:0]   be;\n  } qa_t;\n  typedef struct packed {      // a gathered SW beat\n    logic [24:0]  m;\n    logic [511:0] data;\n    logic [63:0]  strb;\n  } qw_t;\n  typedef struct packed {      // a read in flight: its source, and an SW fill read's slot\n    logic [1:0]    k;\n    logic [WW-1:0] slot;\n  } tg_t;\n\n  logic [QW:0] qb_n [2];\n  logic [QW:0] qb_h [2];                    // (2 QD slots: see qbm)\n  logic [QW:0] qa_n [2];\n  logic [QW:0] qa_h [2];                    // (2 QD slots: see qbm)\n  logic [RNW-1:0] a_iss [2];                // the head A read's run: beats already issued\n  // port SW (gathered beats): live entries (until their write goes out) from qw_f, the next to\n  // write; qw_r the next whose fill read is due (qw_rn from qw_r on)\n  logic [WW:0] qw_n [2], qw_rn [2];\n  logic [WW-1:0] qw_f [2], qw_r [2];\n  // the queue's data and fill data (u_qwd, u_wrm: 512 bits a slot), block RAMs read ahead at the\n  // next write's next value (qw_fn); as LUT RAMs qw_f reached every cell (the m8 card: 11,980\n  // address pins each, over both channels)\n  logic [WW-1:0] qw_fn [2];\n  logic [WQD-1:0] wpart [2], wgot [2];      // per slot: bytes missing; its fill data is in\n  // read-after-write hazards: whb counts, per bucket (a hash of the beat), the live entries past\n  // the read point (from qw_f up to qw_r: fill read issued, or whole); wnz: whb != 0. A count is\n  // read only while its bucket is live (wnz): the reset clears wnz alone (on core_rst's fan-out,\n  // the counts' 2 x NH x (WW+1) flip-flops missed 100 MHz on 9.1 ns of route) and an increment\n  // of a bucket that is not live starts it at 1\n  logic [WW:0]  whb [2][NH];\n  logic [NH-1:0] wnz [2];\n  logic [1:0]   h_inc, h_dec;               // slot qw_r passes the read point / qw_f's write goes\n  // reads in flight per channel, in command order; the oldest one's tag registered (tgh)\n  logic [TW:0]  tg_n [2];\n  logic [TW-1:0] tg_h [2];\n  tg_t          tgh [2], tg_in [2], tg_nx1 [2];\n  // SW gather buffers (see the top): valid, beat and bytes written, cycles since the last merge.\n  // Their data (gd) takes an SW write a cycle after it is taken (gw_*: taken last cycle, to the\n  // buffer's beat), so the take (at the end of QUANT's TMEM grant) enables only gb's 89\n  // flip-flops per channel, not the data's 512 (the 5e5a build's widest DMA -> memory group:\n  // sleft -> gb data, 2048 endpoints); a gathered beat's data goes into the SW queue a cycle\n  // after it is pushed (u_qwd)\n  typedef struct packed {\n    logic [24:0]  m;\n    logic [63:0]  strb;\n  } gs_t;\n  logic [1:0]   gv;\n  gs_t          gb [2];\n  logic [511:0] gd [2];\n  logic [2:0]   gage [2];\n  logic [1:0]   gw_v, gw_same;\n  logic [3:0]   gw_word, gw_be;\n  // the write's data, a copy per channel's gd (each bit feeds 16 of a channel's flip-flops;\n  // one copy for both, 32 loads over both channels' buffers, was the 812bb01 build's worst\n  // native memory path: gw_wdata -> gd, 0 levels, 96% route, +0.175 at 133.33 MHz); keep: not\n  // merged back into one\n  (* keep = \"true\" *) logic [31:0] gw_wdata [2];\n\n  // order of B reads (tags) and of A reads (channel, word, reuse)\n  logic [1:0]   bt_q [OD];                     // LUT RAM: tag, halves swapped (CHASH)\n  logic [OW:0]  bt_n;\n  logic [OW-1:0] bt_h;\n  // A reads in order: channel, word, reuse of the last beat, run beats to drop before this one\n  typedef struct packed { logic c; logic [3:0] idx; logic reuse; logic [RNW-1:0] drop; } ao_t;\n  ao_t          ao_q [OD];\n  ao_t          aoh;                           // the oldest A read\n  logic [OW:0]  ao_n;\n  logic [OW-1:0] ao_h;\n\n  // A beat reuse: the logical beat (bits 29:4 of the word address) and channel of the last A read\n  logic         al_v, al_c;\n  logic [25:0]  al_beat;\n\n  assign b_rdy = (qb_n[0] < QD) && (qb_n[1] < QD) && (bt_n < OD);\n  // Port A's requests come from the slice's port A register (otpu_slice; this adapter's own, on\n  // the way in, until it moved there): the slice's grant chain (DMA busy -> port arbitration ->\n  // the MXU's issue -> the scale address) does not run on into the channel hash, the run compare\n  // and the queue writes in one cycle.\n  logic        a_req, a_we, a_rdy;\n  logic [31:0] a_addr, a_wdata;\n  logic [3:0]  a_be;\n  assign a_req = a_req_x; assign a_we = a_we_x; assign a_addr = a_addr_x;\n  assign a_wdata = a_wdata_x; assign a_be = a_be_x;\n  assign a_rdy = (qa_n[0] < QD) && (qa_n[1] < QD) && (ao_n < OD);\n  assign a_rdy_x = a_rdy;\n  assign sw_rdy = (qw_n[0] < WQD) && (qw_n[1] < WQD);\n  wire sw_take = sw_req && sw_rdy;\n  wire sw_ch = chan_of(sw_addr);\n  wire [24:0] sw_m = sw_addr[29:5];\n  wire b_take = b_req && b_rdy;\n  wire a_take = a_req && a_rdy;\n  wire a_ch = chan_of(a_addr);\n  // the chunk's high half is on channel 0. b_addr comes at the end of the slice's grant chain\n  // (DMA request -> the MXU's grant and request -> the port's address mux), and its 27-bit parity\n  // then ran into every queue write (b_par: the slice muxes its sources' parities instead)\n  wire b_sw = CHASH && b_par;\n  wire [1:0] b_hnz = {b_wmask[31:16] != 0, b_wmask[15:0] != 0};   // the halves a B write writes\n  wire [25:0] a_beat = a_addr[29:4];\n  wire a_reuse = !a_we && al_v && al_beat == a_beat;\n  // A runs per channel: the next channel beat of the run, valid (no write since), beats not\n  // yet taken (in flight or stored)\n  logic [24:0]  pnx [2];\n  logic [1:0]   pv;\n  logic [RNW-1:0] pfl [2];\n  wire  [24:0]  a_cb = a_addr[29:5];              // the channel beat\n  wire  a_hit = !a_we && !a_reuse && pv[a_ch] && a_cb == pnx[a_ch] && pfl[a_ch] != 0;\n\n  // ------------------------------------------------------------------ response FIFOs\n  logic [RW:0]  rb_n [2], rb_res [2];          // stored; stored + in flight\n  logic [RW-1:0] rb_h [2], rb_t [2];\n  // the B FIFO's memory (u_rbm) in RBP pieces of 512 / RBP bits, block RAMs read ahead\n  // (otpu_ram_1r1w_ra) at the head's next value (rb_hn). As LUT RAMs (RAMD64Es) the head and the\n  // tail reached every cell (the card's m8: 38,528 address pins), and the tail took a kept copy\n  // per piece (110ec6d at 133.33 MHz: rb_t_rep -> rbm WADR, fanout 577, 0 levels, 6.9 ns of\n  // route, +0.195 ns); on block RAMs each reaches RBP of them\n  localparam int RBP = 8;\n  logic [RW-1:0] rb_hn [2];\n  logic [AW_:0] ra_n [2], ra_res [2];\n  logic [AW_-1:0] ra_h [2], ra_t [2];\n\n  // ------------------------------------------------------------------ queue and FIFO memories\n  // (per channel; written in their own processes so they map to LUT RAM)\n  logic [1:0]   qb_push, qa_push, qw_push;\n  qb_t          qb_e [2];\n  qa_t          qa_e [2];\n  qb_t          hb [2];\n  qa_t          ha [2];\n  qw_t          hw [2];\n  // slot qw_r (the read point): its beat, bucket and whether it is partial, registered (wadr_r,\n  // wh_r, wp_r; see their process); the next slot's beat and bucket; the bucket of slot qw_f\n  logic [24:0]  wadr_r [2], wadr_n [2];\n  logic [HW-1:0] wh_r [2], wh_n [2], wh_f [2];\n  logic [1:0]   wp_r;\n`ifndef SYNTHESIS\n  logic [24:0]  wadr_o [2];\n  logic [HW-1:0] wh_o [2];\n`endif\n  logic [511:0] rb_head [2], ra_head [2], wr_head [2];\n  logic [1:0]   rtk;                               // a read command taken (tag push)\n  always_comb begin\n    for (int c = 0; c < 2; c++) begin\n      // channel c holds the chunk's half c ^ b_sw\n      qb_push[c] = b_take && (!b_we || b_hnz[c ^ b_sw]);\n      qb_e[c].we = b_we;\n      qb_e[c].m = b_addr[29:5];\n      qb_e[c].data = b_wdata[512 * (c ^ b_sw) +: 512];\n      qb_e[c].wmask = b_we ? b_wmask[16 * (c ^ b_sw) +: 16] : '0;\n      qa_push[c] = a_take && a_ch == c[0] && !a_reuse && !a_hit;\n      qa_e[c].we = a_we;\n      qa_e[c].m = a_cb;\n      qa_e[c].idx = a_addr[3:0];\n      qa_e[c].data = a_wdata;\n      qa_e[c].be = a_be;\n      // the gathered beat goes out: another beat's SW write (room is sure: sw_rdy), or, with\n      // no SW write this cycle and room in the queue, full or idle\n      qw_push[c] = gv[c] && (sw_take && sw_ch == c[0] ? gb[c].m != sw_m\n                   : qw_n[c] < WQD && (&gb[c].strb || gage[c] >= 3'(WGATHER)));\n    end\n  end\n  // the SW gather buffers' data: last cycle's write merged (see gd); last cycle's tail slot\n  logic [WW-1:0] ql_t [2];\n  logic [1:0]    ql_v;\n  always_ff @(posedge clk) begin\n    for (int c = 0; c < 2; c++) begin\n      ql_t[c] <= WW'(qw_f[c] + qw_n[c]);\n      ql_v[c] <= !qw_n[c][WW];\n      gw_same[c] <= gv[c] && gb[c].m == sw_m;\n      if (gw_v[c])\n        for (int k = 0; k < 64; k++)\n          gd[c][8 * k +: 8] <= gw_word == 4'(k / 4) && gw_be[k % 4]\n                               ? gw_wdata[c][8 * (k % 4) +: 8]\n                               : gw_same[c] ? gd[c][8 * k +: 8] : 8'h00;\n      gw_wdata[c] <= sw_wdata;\n    end\n    gw_word <= sw_addr[3:0]; gw_be <= sw_be;\n  end\n\n  for (genvar c = 0; c < 2; c++) begin : g_mem\n    // flat vectors: Vivado builds a RAM of structs from registers\n    // qbm: 2 QD slots for at most QD entries (b_rdy), so the slot at the tail is never live and\n    // is written every cycle; a push only moves the tail. Its write enable was the push, which\n    // comes at the end of the slice's grant chain and fanned out to all of the queue's LUT RAM\n    // (qb_t's 554 bits: 745 cells per channel; the 959b425 build's worst DMA -> memory paths,\n    // -0.390 ns at 133.33 MHz). At QD = 16 the RAM32Ms hold 32 slots already. qam the same: its\n    // push (a_take at the end of the channel decode and the run compare, 12 levels from the\n    // slice's port A register) ran into its write enables (the m8 card at a 150 MHz equivalent)\n    logic [$bits(qb_t)-1:0] qbm [2 * QD];\n    logic [$bits(qa_t)-1:0] qam [2 * QD];\n    logic [$bits(gs_t)-1:0] qwm [WQD];      // per slot: the beat and its bytes written\n    logic [511:0] hw_d;                     // and their data (u_qwd, see gd)\n    logic [24:0] wam [WQD];                 // per slot: the beat\n    logic [HW-1:0] whm [WQD];               // per slot: its hazard bucket\n    logic [$bits(tg_t)-1:0] tgm [TD];       // the reads in flight\n    logic [511:0] ram [AD];\n    always_ff @(posedge clk) qbm[(QW + 1)'(qb_h[c] + qb_n[c])] <= qb_e[c];\n    always_ff @(posedge clk) qam[(QW + 1)'(qa_h[c] + qa_n[c])] <= qa_e[c];\n    // the SW queue's tail slot (not live unless the queue is full) takes the gathered beat every\n    // cycle: its write enables are registers, not the push (an SW write's take comes at the end\n    // of QUANT's TMEM grant; the 5e5a build's worst DMA -> memory paths ran into qwm's WE). The\n    // data goes into last cycle's tail slot (ql_t, ql_v) a cycle later, as gd has it: a slot\n    // pushed last cycle is at the read point or before it, and its data is read (hw) only past it\n    always_ff @(posedge clk) if (!qw_n[c][WW]) qwm[WW'(qw_f[c] + qw_n[c])] <= gb[c];\n    otpu_ram_1r1w_ra #(.W(512), .N(WQD), .STYLE(\"block\")) u_qwd (\n      .clk, .we(ql_v[c]), .wa(ql_t[c]), .wd(gd[c]), .ra_n(qw_fn[c]), .rd(hw_d));\n    always_ff @(posedge clk) if (!qw_n[c][WW]) wam[WW'(qw_f[c] + qw_n[c])] <= gb[c].m;\n    always_ff @(posedge clk) if (!qw_n[c][WW]) whm[WW'(qw_f[c] + qw_n[c])] <= whash(gb[c].m);\n    always_ff @(posedge clk) if (rtk[c]) tgm[TW'(tg_h[c] + tg_n[c])] <= tg_in[c];\n    assign tg_nx1[c] = tg_t'(tgm[TW'(tg_h[c] + 1'b1)]);\n    assign wadr_n[c] = wam[WW'(qw_r[c] + 1'b1)];\n    assign wh_n[c] = whm[WW'(qw_r[c] + 1'b1)];\n`ifndef SYNTHESIS\n    assign wadr_o[c] = wam[qw_r[c]];                // (the registers' reference)\n    assign wh_o[c] = whm[qw_r[c]];\n`endif\n    assign wh_f[c] = whm[qw_f[c]];\n    for (genvar k = 0; k < RBP; k++) begin : g_rb\n      localparam int PB = 512 / RBP;\n      otpu_ram_1r1w_ra #(.W(PB), .N(RD), .STYLE(\"block\")) u_rbm (\n        .clk, .we(n_rvalid[c] && tgh[c].k == K_B), .wa(rb_t[c]), .wd(n_rdata[c][PB * k +: PB]),\n        .ra_n(rb_hn[c]), .rd(rb_head[c][PB * k +: PB]));\n    end\n    always_ff @(posedge clk)\n      if (n_rvalid[c] && tgh[c].k == K_A) ram[ra_t[c]] <= n_rdata[c];\n    // the SW queue's fill data, per slot\n    otpu_ram_1r1w_ra #(.W(512), .N(WQD), .STYLE(\"block\")) u_wrm (\n      .clk, .we(n_rvalid[c] && tgh[c].k == K_W), .wa(tgh[c].slot), .wd(n_rdata[c]),\n      .ra_n(qw_fn[c]), .rd(wr_head[c]));\n    assign hb[c] = qb_t'(qbm[qb_h[c]]);\n    assign ha[c] = qa_t'(qam[qa_h[c]]);\n    gs_t hs;\n    assign hs = gs_t'(qwm[qw_f[c]]);\n    assign hw[c] = qw_t'{m: hs.m, data: hw_d, strb: hs.strb};\n    assign ra_head[c] = ram[AW_'(ra_h[c] + AW_'(aoh.drop))];\n  end\n\n  // ------------------------------------------------------------------ per-channel issue\n  logic [1:0] hv;                                // a command shown and not taken (or a write\n  logic [1:0] hsrc [2];                          //   not yet out): shown again; its source\n  logic [1:0] c_done, d_done;                    // the shown write's command / data taken\n  logic [1:0] sv;                                // a command is shown\n  logic [1:0] src [2];                           // its source (S_*)\n  logic [1:0] swr;                               // it is a write\n  logic [1:0] ctk, dtk;                          // command / write data taken this cycle\n  logic [1:0] wiss;                              // a write goes out (both taken)\n  logic [1:0] w_blk, w_hold;                     // the fill read waits (an older write of its\n                                                 //   beat); the SW writes wait\n  always_comb begin\n    for (int c = 0; c < 2; c++) begin\n      logic e_a, e_wr, e_ww, e_b;\n      // the SW queue's next partial beat: blocked while an older live entry may have its\n      // address (one in its bucket; a hash collision only delays the read)\n      w_blk[c] = wnz[c][wh_r[c]];\n      // the queue's writes wait while its fill reads still go out (not blocked), unless half full\n      w_hold[c] = (qw_rn[c] != 0) && wp_r[c] && !w_blk[c] && qw_n[c] < (WW + 1)'(WQD / 2);\n      // A: a read's run (response room for the whole run as it starts), or a write\n      e_a = (qa_n[c] != 0) && (ha[c].we || a_iss[c] != 0 || ra_res[c] <= (AW_ + 1)'(AD - APF));\n      e_wr = (qw_rn[c] != 0) && wp_r[c] && !w_blk[c];\n      // an SW write once its slot is past the read point and, if partial, has its fill data\n      e_ww = (qw_n[c] != qw_rn[c]) && (!wpart[c][qw_f[c]] || wgot[c][qw_f[c]]) && !w_hold[c];\n      e_b = (qb_n[c] != 0) && (hb[c].we || rb_res[c] < (RW + 1)'(RD));\n      sv[c] = hv[c] || e_a || e_wr || e_ww || e_b;\n      src[c] = hv[c] ? hsrc[c] : e_a ? S_A : e_wr ? S_WR : e_ww ? S_WW : S_B;\n      swr[c] = (src[c] == S_A && ha[c].we) || src[c] == S_WW || (src[c] == S_B && hb[c].we);\n      n_cvalid[c] = sv[c] && !(swr[c] && c_done[c]);\n      n_wvalid[c] = sv[c] && swr[c] && !d_done[c];\n      n_cwe[c] = swr[c];\n      case (src[c])\n        S_A:  n_caddr[c] = ha[c].m + 25'(a_iss[c]);\n        S_WR: n_caddr[c] = wadr_r[c];\n        S_WW: n_caddr[c] = hw[c].m;\n        default: n_caddr[c] = hb[c].m;\n      endcase\n      n_wdata[c] = '0;\n      n_wmask[c] = '0;\n      if (src[c] == S_WW) begin\n        for (int k = 0; k < 64; k++)\n          n_wdata[c][8 * k +: 8] = hw[c].strb[k] ? hw[c].data[8 * k +: 8] : wr_head[c][8 * k +: 8];\n        n_wmask[c] = '1;\n      end else if (src[c] == S_A) begin\n        n_wdata[c][32 * ha[c].idx +: 32] = ha[c].data;\n        n_wmask[c][4 * ha[c].idx +: 4] = ha[c].be;\n      end else begin\n        n_wdata[c] = hb[c].data;\n        for (int k = 0; k < 16; k++) n_wmask[c][4 * k +: 4] = {4{hb[c].wmask[k]}};\n      end\n      ctk[c] = n_cvalid[c] && n_cready[c];\n      dtk[c] = n_wvalid[c] && n_wready[c];\n      wiss[c] = sv[c] && swr[c] && (c_done[c] || ctk[c]) && (d_done[c] || dtk[c]);\n      rtk[c] = ctk[c] && !swr[c];\n      tg_in[c].k = src[c] == S_A ? K_A : src[c] == S_WR ? K_W : K_B;\n      tg_in[c].slot = qw_r[c];\n    end\n  end\n\n  // a write that went out on channel c (last cycle: wk_v, its beat wk_m) drops c's A run, or the\n  // reused beat, when its beat is in them (see the top); a cycle late, off the path from the\n  // command select and the channel's readies, and still before any A read that depends on the\n  // write is taken (that comes after wr_idle, and waits a cycle in the A register)\n  logic [1:0] wk_v, wk_r, wk_a;\n  logic [24:0] wk_m [2];\n  always_ff @(posedge clk) begin\n    wk_v <= rst ? '0 : wiss;\n    for (int c = 0; c < 2; c++) wk_m[c] <= n_caddr[c];\n  end\n  always_comb\n    for (int c = 0; c < 2; c++) begin\n      wk_r[c] = wk_v[c] && pv[c] && 25'(wk_m[c] - pnx[c]) < 25'(pfl[c]);\n      wk_a[c] = wk_v[c] && al_v && al_c == c[0] && al_beat[25:1] == wk_m[c];\n    end\n\n  // ------------------------------------------------------------------ merge\n  wire b_out = (bt_n != 0) && (rb_n[0] != 0) && (rb_n[1] != 0);\n  // the B FIFO's head's next value, as the state block below moves it (a pop of both channels)\n  for (genvar c = 0; c < 2; c++) begin : g_rbh\n    assign rb_hn[c] = rst ? '0 : b_out ? RW'(rb_h[c] + 1'b1) : rb_h[c];\n  end\n  // the SW queue's next write's next value (its pop: popw in the state block)\n  for (genvar c = 0; c < 2; c++) begin : g_qwf\n    assign qw_fn[c] = rst ? '0 : (src[c] == S_WW && wiss[c]) ? WW'(qw_f[c] + 1'b1) : qw_f[c];\n  end\n  // the oldest A read, registered (the order FIFO's LUT RAM read stays out of the run-beat and\n  // word select into a_rdata): after a pop the next entry (written at least a cycle before), or\n  // the entry pushed into an empty queue\n  ao_t          ao_nx1, ao_in;\n  assign ao_nx1 = ao_q[OW'(ao_h + 1'b1)];\n  assign ao_in = '{c: a_ch, idx: a_addr[3:0], reuse: a_reuse,\n                   drop: (a_reuse || a_hit) ? RNW'(0) : pfl[a_ch]};\n  logic [511:0] a_last;                          // the beat of the last fetched A read\n  wire a_out = (ao_n != 0) && (aoh.reuse || ra_n[aoh.c] > (AW_ + 1)'(aoh.drop));\n  wire [511:0] a_src = aoh.reuse ? a_last : ra_head[aoh.c];\n  always_ff @(posedge clk)\n    if (a_out) aoh <= (ao_n == (OW + 1)'(1)) ? ao_in : ao_nx1;\n    else if (ao_n == 0) aoh <= ao_in;\n  // the oldest read in flight's tag, registered likewise (it steers the response FIFO writes)\n  always_ff @(posedge clk)\n    for (int c = 0; c < 2; c++)\n      if (n_rvalid[c]) tgh[c] <= (tg_n[c] == (TW + 1)'(1)) ? tg_in[c] : tg_nx1[c];\n      else if (tg_n[c] == 0) tgh[c] <= tg_in[c];\n  assign b_rvalid = b_out;\n  wire [1:0] bth = bt_q[bt_h];\n  assign b_rtag = bth[0];\n  assign b_rdata = bth[1] ? {rb_head[0], rb_head[1]} : {rb_head[1], rb_head[0]};\n  // the A read data registered on the way out (the head's run-beat and word select ran into the\n  // MXU's scale FIFO block RAM in one cycle)\n  always_ff @(posedge clk) begin\n    a_rvalid <= !rst && a_out;\n    a_rdata <= a_src[256 * aoh.idx[3] +: 256];\n  end\n\n  // the tag FIFO writes its tail every cycle too (the slot is not live unless the FIFO is full),\n  // so its write enable is a register, not b_take\n  always_ff @(posedge clk) begin\n    if (!bt_n[OW]) bt_q[OW'(bt_h + bt_n)] <= {b_sw, b_tag};\n    if (a_take && !a_we)\n      ao_q[OW'(ao_h + ao_n)] <= ao_in;\n  end\n\n  // ------------------------------------------------------------------ writes outstanding\n  // wq_n counts the writes (beats) accepted before the last cycle that have not gone out; wacc_q\n  // holds the last cycle's accepts (folded in a cycle late, off the rdy -> take path). A write\n  // goes out at least a cycle after its accept, so wq_n never goes negative. iss_w[c] counts\n  // channel c's writes gone out (mod 2^16), which n_wdone reaches once the controller has them;\n  // it starts at n_wdone's value in reset (the channel module's count need not reset with rst,\n  // as long as no write of ours is still on its way to the controller then).\n  logic [PW-1:0] wq_n;\n  logic [4:0]    wacc_q;\n  logic [15:0]   iss_w [2];\n  assign wr_idle = (wq_n == 0) && (wacc_q == '0) && (gv == '0) &&\n                   (iss_w[0] == n_wdone[0]) && (iss_w[1] == n_wdone[1]);\n  assign rd_idle = (bt_n == 0) && (ao_n == 0);\n\n  always_ff @(posedge clk) begin\n    if (rst) begin\n      for (int c = 0; c < 2; c++) begin\n        qb_n[c] <= '0; qb_h[c] <= '0; qa_n[c] <= '0; qa_h[c] <= '0; a_iss[c] <= '0;\n        qw_n[c] <= '0; qw_f[c] <= '0; qw_r[c] <= '0; qw_rn[c] <= '0; wnz[c] <= '0;\n        tg_n[c] <= '0; tg_h[c] <= '0;\n        rb_n[c] <= '0; rb_res[c] <= '0; rb_h[c] <= '0; rb_t[c] <= '0;\n        ra_n[c] <= '0; ra_res[c] <= '0; ra_h[c] <= '0; ra_t[c] <= '0;\n        iss_w[c] <= n_wdone[c];\n      end\n      bt_n <= '0; bt_h <= '0; ao_n <= '0; ao_h <= '0;\n      al_v <= 1'b0;\n      pv <= '0; pfl[0] <= '0; pfl[1] <= '0;\n      wq_n <= '0; wacc_q <= '0;\n      gv <= '0; gage[0] <= '0; gage[1] <= '0; gw_v <= '0;\n      hv <= '0; c_done <= '0; d_done <= '0;\n    end else begin\n      // writes accepted (the take strobes: an A or an SW write goes to exactly one channel, so\n      // a_reuse and the channel decode stay off this path; a B write to each channel whose half\n      // it writes) and gone out\n      wq_n <= wq_n + PW'(wacc_q[0]) + PW'(wacc_q[1]) + PW'(wacc_q[2]) + PW'(wacc_q[3]) +\n              PW'(wacc_q[4]) - PW'(wiss[0]) - PW'(wiss[1]);\n      wacc_q <= {qw_push[1], qw_push[0], a_take && a_we,\n                 b_take && b_we && b_wmask[31:16] != 0,\n                 b_take && b_we && b_wmask[15:0]  != 0};\n      for (int c = 0; c < 2; c++) begin\n        logic [QW:0] na;\n        logic [RW:0] rbn, rbr;\n        logic [AW_:0] ran, rar;\n        logic [TW:0] ntg;\n        logic popb, popa, popw;\n        na = qa_n[c]; ntg = tg_n[c];\n        rbn = rb_n[c]; rbr = rb_res[c]; ran = ra_n[c]; rar = ra_res[c];\n        // ---- accept\n        if (qa_push[c]) na = na + 1;\n        if (!qw_n[c][WW]) begin                // the tail slot, as qwm (see g_mem)\n          logic [WW-1:0] t;\n          t = WW'(qw_f[c] + qw_n[c]);\n          wpart[c][t] <= !(&gb[c].strb);\n          wgot[c][t] <= 1'b0;\n        end\n        // ---- the command stream: a shown command is shown again until taken, a write until\n        // its command and its data are taken\n        hv[c] <= sv[c] && (swr[c] ? !wiss[c] : !ctk[c]);\n        hsrc[c] <= src[c];\n        c_done[c] <= swr[c] && !wiss[c] && (c_done[c] || ctk[c]);\n        d_done[c] <= swr[c] && !wiss[c] && (d_done[c] || dtk[c]);\n        popa = src[c] == S_A && (swr[c] ? wiss[c] : ctk[c] && a_iss[c] == RNW'(APF - 1));\n        popb = src[c] == S_B && (swr[c] ? wiss[c] : ctk[c]);\n        popw = src[c] == S_WW && wiss[c];\n        if (rtk[c]) ntg = ntg + 1;\n        if (src[c] == S_A && rtk[c]) begin      // an A run's beat; the run reserves its room\n          a_iss[c] <= (a_iss[c] == RNW'(APF - 1)) ? RNW'(0) : a_iss[c] + 1'b1;\n          if (a_iss[c] == 0) rar = rar + (AW_ + 1)'(APF);\n        end\n        if (src[c] == S_B && rtk[c]) rbr = rbr + 1;\n        // a fill read passes the read point; a whole beat needs no fill read (e_wr is never set\n        // for one): it passes the read point at once, so before its write can go (h_inc: either)\n        if (h_inc[c]) qw_r[c] <= qw_r[c] + 1;\n        if (popb) qb_h[c] <= qb_h[c] + 1;\n        if (popa) begin qa_h[c] <= qa_h[c] + 1; na = na - 1; end\n        if (popw) qw_f[c] <= qw_f[c] + 1;\n        if (wiss[c]) iss_w[c] <= iss_w[c] + 1'b1;\n        // ---- read data, routed by the oldest read's tag\n        if (n_rvalid[c]) begin\n          case (tgh[c].k)\n            K_B: begin\n              rb_t[c] <= rb_t[c] + 1; rbn = rbn + 1;\n            end\n            K_A: begin ra_t[c] <= ra_t[c] + 1; ran = ran + 1; end\n            default: wgot[c][tgh[c].slot] <= 1'b1;   // the SW fill read: its slot has the data\n          endcase\n          tg_h[c] <= tg_h[c] + 1;\n          ntg = ntg - 1;\n        end\n        // ---- merge pops\n        if (b_out) begin\n          rb_h[c] <= rb_h[c] + 1;\n          rbn = rbn - 1; rbr = rbr - 1;\n        end\n        if (a_out && !aoh.reuse && aoh.c == c[0]) begin    // (and the dropped run beats)\n          ra_h[c] <= ra_h[c] + AW_'(aoh.drop) + 1'b1;\n          ran = ran - (AW_ + 1)'(aoh.drop) - 1'b1;\n          rar = rar - (AW_ + 1)'(aoh.drop) - 1'b1;\n        end\n        // ---- hazard buckets: slot qw_r passes the read point, slot qw_f's write goes out\n        for (int k = 0; k < NH; k++)\n          if (h_ik[c][k] || h_dk[c][k]) wnz[c][k] <= h_iv[c][k] || whb[c][wh_f[c]] != (WW + 1)'(1);\n        qb_n[c] <= (QW + 1)'(updn(16'(qb_n[c]), qb_push[c], popb));\n        qw_n[c] <= (WW + 1)'(updn(16'(qw_n[c]), qw_push[c], popw));\n        qw_rn[c] <= (WW + 1)'(updn(16'(qw_rn[c]), qw_push[c], h_inc[c]));\n        qa_n[c] <= na; tg_n[c] <= ntg;\n        rb_n[c] <= rbn; rb_res[c] <= rbr; ra_n[c] <= ran; ra_res[c] <= rar;\n      end\n      // ---- order FIFOs\n      begin\n        logic [OW:0] aon;\n        aon = ao_n;\n        if (b_out) bt_h <= bt_h + 1;\n        if (a_take && !a_we) aon = aon + 1;\n        if (a_out) begin\n          ao_h <= ao_h + 1; aon = aon - 1;\n          if (!aoh.reuse) a_last <= ra_head[aoh.c];\n        end\n        bt_n <= (OW + 1)'(updn(16'(bt_n), b_take && !b_we, b_out));\n        ao_n <= aon;\n      end\n      // ---- SW gather: merge into the beat, or start a new one (the old one was pushed)\n      for (int c = 0; c < 2; c++) begin\n        gw_v[c] <= sw_take && sw_ch == c[0];\n        if (sw_take && sw_ch == c[0]) begin\n          logic same;\n          same = gv[c] && gb[c].m == sw_m;\n          gv[c] <= 1'b1;\n          gage[c] <= '0;\n          gb[c].m <= sw_m;\n          for (int k = 0; k < 64; k++)\n            gb[c].strb[k] <= (sw_addr[3:0] == 4'(k / 4) && sw_be[k % 4]) || (same && gb[c].strb[k]);\n        end else if (qw_push[c]) begin\n          gv[c] <= 1'b0;\n        end else if (gv[c] && gage[c] != '1) begin\n          gage[c] <= gage[c] + 1;\n        end\n      end\n      // ---- A runs: a hit takes the next beat, a miss starts a run (dropping the rest)\n      if (a_take && !a_we && !a_reuse) begin\n        if (a_hit) begin\n          pnx[a_ch] <= pnx[a_ch] + 1;\n          pfl[a_ch] <= pfl[a_ch] - 1;\n        end else begin\n          pnx[a_ch] <= a_cb + 1;\n          pfl[a_ch] <= RNW'(APF - 1);\n          pv[a_ch] <= 1'b1;\n        end\n      end\n      for (int c = 0; c < 2; c++) if (wk_r[c]) pv[c] <= 1'b0;\n      if (a_take && a_we) pv <= '0;\n      // ---- A beat reuse: the beat of the last A read, forgotten on an A write or a write to it\n      if ((a_take && a_we) || (|wk_a)) al_v <= 1'b0;\n      else if (a_take && !a_we) begin\n        al_v <= 1'b1;\n        al_beat <= a_beat;\n        al_c <= a_ch;\n      end\n      // ---- the host may have written since (last: an A read taken now decided with the old\n      // state, and its run is dropped too)\n      if (a_flush) begin\n        pv <= '0;\n        al_v <= 1'b0;\n      end\n    end\n  end\n\n  // the hazard buckets' counts (no reset: see whb). Per bucket k: incremented (h_ik: slot qw_r,\n  // bucket wh_r, passes the read point) or decremented (h_dk: slot qw_f's write, bucket wh_f,\n  // goes out), neither when both hit it; each a function of the late h_inc / h_dec and of the\n  // bucket decodes, and an increment's value where the bucket is wh_r and h_inc is set (h_iv)\n  logic [NH-1:0] h_ik [2], h_dk [2], h_iv [2];\n  always_comb\n    for (int c = 0; c < 2; c++) begin\n      h_inc[c] = (src[c] == S_WR && ctk[c]) || (qw_rn[c] != 0 && !wp_r[c]);\n      h_dec[c] = src[c] == S_WW && wiss[c];\n      for (int k = 0; k < NH; k++) begin\n        h_ik[c][k] = h_inc[c] && wh_r[c] == HW'(k) && !(h_dec[c] && wh_f[c] == wh_r[c]);\n        h_dk[c][k] = h_dec[c] && wh_f[c] == HW'(k) && !(h_inc[c] && wh_f[c] == wh_r[c]);\n        h_iv[c][k] = h_inc[c] && wh_r[c] == HW'(k);\n      end\n    end\n  // slot qw_r's beat, bucket and partial flag, registered: read from the LUT RAMs and wpart by\n  // qw_r, they started the fill read's hazard check (w_blk) and so the command select and the\n  // hazard count updates (the 5e5a build's nmem > nmem paths: qw_r -> whm -> wnz -> ... -> whb).\n  // qw_r moves by one exactly on h_inc; the slot it then points to is the tail, whose write\n  // (see g_mem) lands in it this cycle, when no entry past the read point is left (qw_rn 1, or 0\n  // while it stays), otherwise the next slot as stored\n  always_ff @(posedge clk)\n    for (int c = 0; c < 2; c++) begin\n      logic tw;\n      tw = !qw_n[c][WW] && qw_rn[c] == (h_inc[c] ? (WW + 1)'(1) : (WW + 1)'(0));\n      if (tw) begin\n        wadr_r[c] <= gb[c].m; wh_r[c] <= whash(gb[c].m); wp_r[c] <= !(&gb[c].strb);\n      end else if (h_inc[c]) begin\n        wadr_r[c] <= wadr_n[c]; wh_r[c] <= wh_n[c]; wp_r[c] <= wpart[c][WW'(qw_r[c] + 1'b1)];\n      end\n    end\n  always_ff @(posedge clk)\n    for (int c = 0; c < 2; c++)\n      for (int k = 0; k < NH; k++)\n        if (h_ik[c][k] || h_dk[c][k])\n          whb[c][k] <= !h_iv[c][k] ? whb[c][wh_f[c]] - 1'b1 :\n                       wnz[c][wh_r[c]] ? whb[c][wh_r[c]] + 1'b1 : (WW + 1)'(1);\n\n`ifndef SYNTHESIS\n  // The hazard counts are read only while live: a write goes out only from a live bucket, and\n  // every live count is what a count reset with the rest would hold (whb_ref). The counts start\n  // with anything, as after a reset in the middle of a run\n  logic [WW:0] whb_ref [2][NH];\n  initial for (int c = 0; c < 2; c++) for (int k = 0; k < NH; k++) whb[c][k] = (WW + 1)'($urandom);\n  always_ff @(posedge clk)\n    if (rst) begin\n      for (int c = 0; c < 2; c++) for (int k = 0; k < NH; k++) whb_ref[c][k] <= '0;\n    end else\n      for (int c = 0; c < 2; c++) begin\n        if (h_dec[c] && !wnz[c][wh_f[c]])\n          $fatal(1, \"otpu_native_dram: channel %0d bucket %0d written out while not live\", c, wh_f[c]);\n        for (int k = 0; k < NH; k++)\n          if (wnz[c][k] != (whb_ref[c][k] != 0) || (wnz[c][k] && whb[c][k] != whb_ref[c][k]))\n            $fatal(1, \"otpu_native_dram: channel %0d bucket %0d count %0d (live %0d), expected %0d\",\n                   c, k, whb[c][k], wnz[c][k], whb_ref[c][k]);\n        if (h_inc[c] && !(h_dec[c] && wh_f[c] == wh_r[c]))\n          whb_ref[c][wh_r[c]] <= whb_ref[c][wh_r[c]] + 1'b1;\n        if (h_dec[c] && !(h_inc[c] && wh_f[c] == wh_r[c]))\n          whb_ref[c][wh_f[c]] <= whb_ref[c][wh_f[c]] - 1'b1;\n      end\n\n  // b_par is the parity of the address. The A and B queues and the tag FIFO write their tails\n  // every cycle: the head of each (the entry a command or a read's data takes) is what a queue\n  // written on a push only holds (qar, qbr, btr: the old write enables)\n  always_ff @(posedge clk)\n    if (!rst && b_req && b_par != ^b_addr[31:5])\n      $fatal(1, \"otpu_native_dram: b_par %0d, address %h\", b_par, b_addr);\n  logic [$bits(qb_t)-1:0] qbr [2][QD];\n  logic [$bits(qa_t)-1:0] qar [2][QD];\n  logic [1:0] btr [OD];\n  always_ff @(posedge clk) begin\n    for (int c = 0; c < 2; c++) if (qb_push[c]) qbr[c][QW'(qb_h[c] + qb_n[c])] <= qb_e[c];\n    for (int c = 0; c < 2; c++) if (qa_push[c]) qar[c][QW'(qa_h[c] + qa_n[c])] <= qa_e[c];\n    if (b_take && !b_we) btr[OW'(bt_h + bt_n)] <= {b_sw, b_tag};\n  end\n  always_ff @(posedge clk)\n    if (!rst) begin\n      if (qb_n[0] != 0 && hb[0] != qb_t'(qbr[0][QW'(qb_h[0])]))\n        $fatal(1, \"otpu_native_dram: channel 0 B queue head (slot %0d) differs\", qb_h[0]);\n      if (qb_n[1] != 0 && hb[1] != qb_t'(qbr[1][QW'(qb_h[1])]))\n        $fatal(1, \"otpu_native_dram: channel 1 B queue head (slot %0d) differs\", qb_h[1]);\n      for (int c = 0; c < 2; c++)\n        if (qa_n[c] != 0 && ha[c] != qa_t'(qar[c][QW'(qa_h[c])]))\n          $fatal(1, \"otpu_native_dram: channel %0d A queue head (slot %0d) differs\", c, qa_h[c]);\n      if (bt_n != 0 && bth != btr[bt_h])\n        $fatal(1, \"otpu_native_dram: B tag %0d at %0d, expected %0d\", bth, bt_h, btr[bt_h]);\n    end\n\n  // the B FIFO's read ahead named the head: rb_hn was rb_h's next value\n  // and the SW queue's: qw_fn was qw_f's next value\n  bit rst_seen;                                 // (registers start arbitrary)\n  logic [RW-1:0] rb_hq [2];\n  logic [WW-1:0] qw_fq [2];\n  initial rst_seen = 1'b0;\n  always_ff @(posedge clk) begin\n    if (rst) rst_seen <= 1'b1;\n    rb_hq <= rb_hn;\n    qw_fq <= qw_fn;\n    if (!rst && rst_seen)\n      for (int c = 0; c < 2; c++) begin\n        if (rb_hq[c] != rb_h[c])\n          $fatal(1, \"otpu_native_dram: channel %0d B head %0d, its read ahead %0d\", c, rb_h[c],\n                 rb_hq[c]);\n        if (qw_fq[c] != qw_f[c])\n          $fatal(1, \"otpu_native_dram: channel %0d SW head %0d, its read ahead %0d\", c, qw_f[c],\n                 qw_fq[c]);\n      end\n  end\n\n  // gb and, a cycle later, gd are, while valid, what a buffer merging each write as it is taken\n  // holds (gb_ref)\n  qw_t gb_ref [2];\n  logic [511:0] gd_ref [2];\n  logic [1:0] gd_rv;\n  always_ff @(posedge clk)\n    for (int c = 0; c < 2; c++) begin\n      if (!rst && gv[c] && (gb[c].m != gb_ref[c].m || gb[c].strb != gb_ref[c].strb))\n        $fatal(1, \"otpu_native_dram: channel %0d SW gather buffer %h differs from %h\", c, gb[c].m,\n               gb_ref[c].m);\n      if (!rst && gd_rv[c] && gd[c] != gd_ref[c])\n        $fatal(1, \"otpu_native_dram: channel %0d SW gather data differs\", c);\n      gd_ref[c] <= gb_ref[c].data;\n      gd_rv[c] <= gv[c];\n      if (sw_take && sw_ch == c[0]) begin\n        logic same;\n        same = gv[c] && gb_ref[c].m == sw_m;\n        gb_ref[c].m <= sw_m;\n        for (int k = 0; k < 64; k++) begin\n          logic hit;\n          hit = sw_addr[3:0] == 4'(k / 4) && sw_be[k % 4];\n          gb_ref[c].data[8 * k +: 8] <= hit ? sw_wdata[8 * (k % 4) +: 8]\n                                        : same ? gb_ref[c].data[8 * k +: 8] : 8'h00;\n          gb_ref[c].strb[k] <= hit || (same && gb_ref[c].strb[k]);\n        end\n      end\n    end\n\n  // The SW queue's slots are written at the tail every cycle as well: its slots at the read point\n  // (qw_r) and at the head (qw_f) are what a queue written on a push only holds (the head's beat,\n  // once past the read point: see u_qwd); the read point's registers (wadr_r, wh_r, wp_r) are what\n  // its slot holds\n  logic [$bits(qw_t)-1:0] qwr [2][WQD];\n  logic [24:0] war [2][WQD];\n  logic [WQD-1:0] wpr [2], wgr [2];\n  always_ff @(posedge clk)\n    for (int c = 0; c < 2; c++) begin\n      if (qw_push[c]) begin\n        qwr[c][WW'(qw_f[c] + qw_n[c])] <= gb_ref[c];\n        war[c][WW'(qw_f[c] + qw_n[c])] <= gb[c].m;\n        wpr[c][WW'(qw_f[c] + qw_n[c])] <= !(&gb[c].strb);\n        wgr[c][WW'(qw_f[c] + qw_n[c])] <= 1'b0;\n      end\n      if (n_rvalid[c] && tgh[c].k == K_W) wgr[c][tgh[c].slot] <= 1'b1;\n    end\n  always_ff @(posedge clk)\n    if (!rst)\n      for (int c = 0; c < 2; c++) begin\n        if ((src[c] == S_WR && ctk[c]) && (qw_rn[c] != 0 && !wp_r[c]))\n          $fatal(1, \"otpu_native_dram: channel %0d fill read of a whole beat\", c);\n        if (qw_rn[c] != 0 && (wadr_r[c] != wadr_o[c] || wh_r[c] != wh_o[c] ||\n                              wp_r[c] != wpart[c][qw_r[c]]))\n          $fatal(1, \"otpu_native_dram: channel %0d read point slot %0d: registered %h %0d %0d, stored %h %0d %0d\",\n                 c, qw_r[c], wadr_r[c], wh_r[c], wp_r[c], wadr_o[c], wh_o[c], wpart[c][qw_r[c]]);\n        if (qw_rn[c] != 0 && (wadr_r[c] != war[c][qw_r[c]] || wh_r[c] != whash(war[c][qw_r[c]]) ||\n                              wp_r[c] != wpr[c][qw_r[c]]))\n          $fatal(1, \"otpu_native_dram: channel %0d SW slot %0d at the read point differs\", c, qw_r[c]);\n        if (qw_n[c] != 0 && (wh_f[c] != whash(war[c][qw_f[c]]) || wpart[c][qw_f[c]] != wpr[c][qw_f[c]] ||\n                             wgot[c][qw_f[c]] != wgr[c][qw_f[c]]))\n          $fatal(1, \"otpu_native_dram: channel %0d SW head slot %0d differs\", c, qw_f[c]);\n        if (qw_n[c] != qw_rn[c] && hw[c] != qw_t'(qwr[c][qw_f[c]]))\n          $fatal(1, \"otpu_native_dram: channel %0d SW head slot %0d's beat differs\", c, qw_f[c]);\n      end\n\n  // Read data never arrives without a read in flight or without room reserved for it (the\n  // native port has no backpressure on read data)\n  always_ff @(posedge clk)\n    if (!rst)\n      for (int c = 0; c < 2; c++) begin\n        if (n_rvalid[c] && tg_n[c] == 0)\n          $fatal(1, \"otpu_native_dram: channel %0d read data with no read in flight\", c);\n        if (n_rvalid[c] && tg_n[c] != 0 && tgh[c].k == K_B && rb_n[c] == (RW + 1)'(RD))\n          $fatal(1, \"otpu_native_dram: channel %0d B read FIFO overflow\", c);\n        if (n_rvalid[c] && tg_n[c] != 0 && tgh[c].k == K_A && ra_n[c] == (AW_ + 1)'(AD))\n          $fatal(1, \"otpu_native_dram: channel %0d A read FIFO overflow\", c);\n        if (n_rvalid[c] && tg_n[c] != 0 && tgh[c].k == K_W && wgot[c][tgh[c].slot])\n          $fatal(1, \"otpu_native_dram: channel %0d SW fill data for a filled slot\", c);\n        if (rtk[c] && tg_n[c] == (TW + 1)'(TD) && !n_rvalid[c])\n          $fatal(1, \"otpu_native_dram: channel %0d read tag FIFO overflow\", c);\n      end\n\n  // Counters for the simulation's statistics (otpu_top prints them): per channel, A runs and\n  // their read commands, B reads, SW fill reads; writes by source, and those with a byte mask\n  // that is not whole (a read-modify-write in the channel module)\n  longint st_arun [2], st_ard [2], st_brd [2], st_srd [2];\n  longint st_bwr [2], st_awr [2], st_swr [2], st_pb [2], st_pa [2], st_ps [2];\n  initial\n    for (int c = 0; c < 2; c++) begin\n      st_arun[c] = 0; st_ard[c] = 0; st_brd[c] = 0; st_srd[c] = 0; st_bwr[c] = 0;\n      st_awr[c] = 0; st_swr[c] = 0; st_pb[c] = 0; st_pa[c] = 0; st_ps[c] = 0;\n    end\n  always_ff @(posedge clk)\n    for (int c = 0; c < 2; c++) begin\n      if (rtk[c] && src[c] == S_A) begin\n        st_ard[c] <= st_ard[c] + 1;\n        if (a_iss[c] == 0) st_arun[c] <= st_arun[c] + 1;\n      end\n      if (rtk[c] && src[c] == S_B) st_brd[c] <= st_brd[c] + 1;\n      if (rtk[c] && src[c] == S_WR) st_srd[c] <= st_srd[c] + 1;\n      if (wiss[c]) begin\n        logic part;\n        part = n_wmask[c] != '1;\n        case (src[c])\n          S_A: begin st_awr[c] <= st_awr[c] + 1; if (part) st_pa[c] <= st_pa[c] + 1; end\n          S_WW: begin st_swr[c] <= st_swr[c] + 1; if (part) st_ps[c] <= st_ps[c] + 1; end\n          default: begin st_bwr[c] <= st_bwr[c] + 1; if (part) st_pb[c] <= st_pb[c] + 1; end\n        endcase\n      end\n    end\n`endif\nendmodule\n", "rtl/mem/otpu_tmem.sv": "// TMEM: fp32 scratchpad organised as LANES banks (bank = word address mod LANES). Units present\n// lane-wide requests on their own ports; the slice's arbiter grants each unit all-or-nothing\n// per cycle so that no bank takes more than WPB writes (and RPB reads) per cycle, and a unit\n// that is not granted holds its state.\n//\n// Implementation (the same for simulation and the FPGA): every read port has its own copy of\n// the memory, LANES banks of WORDS/LANES words, so reads never compete across ports -- except\n// the guest ports (SH_MASK), rarely busy, which share one port's copy in priority order. Writes are\n// broadcast to every copy: each bank takes up to WPB writes per cycle, picked from all write\n// ports' lanes (WPB = 1 on the FPGA, where each bank copy is a simple dual-port BRAM with\n// read-first behaviour). A read returns the old word if it is written in the same cycle.\n// Each read lane's data is held until that lane reads again, so a frozen unit keeps its\n// operands.\n//\n// Timing: the grants are the end of the slice's deepest logic (unit requests -> arbiter), and\n// a write reaches every copy of its bank (NRP * the bank's block RAMs, spread over the die). So\n// the selected writes are registered here and land in the block RAMs a cycle later, and a read\n// of a word whose write is still in that register takes the registered data (a bypass): to the\n// units the memory behaves exactly as if the write had landed in its own cycle. Likewise the\n// block RAM read enables come from the requests, not the grants: a read that is not granted\n// only changes a block RAM output nobody looks at (the lanes take it only the cycle after a\n// granted read, and hold it otherwise).\n//\n// Lane routing. Every port except those in GEN_R / GEN_W (the MXU's: its drain writes scattered\n// rows) carries a contiguous run: enabled lane l holds word a0 + l, where a0 is lane 0's\n// address (the units drive it whenever any lane is enabled). Such a port reaches the banks\n// through barrel rotators by a0 mod LANES (the lanes' bank rows are a0's row, +1 for the banks before a0's), LANES x\n// log2(LANES) multiplexers instead of a LANES x LANES crossbar; the simulation stops if a\n// rotator port's lanes are not contiguous. The GEN ports keep the crossbar.\n//\n// Within one port the enabled lanes must hit distinct banks (or read the same word); the\n// simulation stops on a violation, so the timing it reports is honest.\n//\n// IMPL 1 (banked; an ASIC, whose SRAM macros cannot be replicated per read port at no cost):\n// NCP copies instead of one per read port, each LANES banks of one 1R1W RAM (otpu_ram_1r1w, the\n// target's technology cell). CPY[p] is read port p's copy; ports of one unit (the slice's\n// arbitration group) sit on different copies, so a unit alone always fits. Each copy's bank\n// serves one read per cycle: the slice's arbiter admits at most one port per copy and bank (a\n// port's lanes in one bank read one word), and the bank's address comes from that port's granted\n// lanes (r_en), not its requests. Writes are broadcast to every copy, one per bank (WPB = 1).\n// The registered write stage, the bypass and the lanes' data path are IMPL 0's.\n// RQ (IMPL 1): a copy's bank address comes from the requests instead, the port first in the\n// slice's priority order (PRANK, smaller first) among those on the copy that ask for the bank;\n// the slice's arbiter then grants a unit only where it is that port (otpu_slice TMEM_RQ), so the\n// granted port's address is the one at the RAM and the grants reach no RAM pin (on the FPGA, the\n// grant-to-address path of IMPL 1 does not close at the core clock: docs/tmem_pump.md).\nmodule otpu_tmem #(\n  parameter int WORDS = 1 << 16,\n  parameter int LANES = 8,\n  parameter int NRP   = 6,\n  parameter int NWP   = 4,\n  parameter int WPB   = 1,\n  parameter logic [NRP-1:0] GEN_R = '1,   // read ports with the general crossbar\n  parameter logic [NRP-1:0] PBR   = '0,   // GEN_R ports whose unit merges its lanes by bank\n                                          //   (r_ben / r_bad: from its flip-flops, see g_preq)\n  parameter logic [NWP-1:0] GEN_W = '1,   // write ports with the general crossbar (WPB = 1)\n  parameter int SH_HOST = 0,              // the read port whose copy SH_MASK's ports share\n  parameter logic [NRP-1:0] SH_MASK = '0, // guests on SH_HOST's copy (the arbiter lets a guest\n                                          // read only when no port before it on the copy asks)\n  parameter int SID   = 0,\n  parameter int IMPL  = 0,                // 0: a copy per read port (block RAM); 1: banked (see top)\n  parameter int NCP   = 1,                // IMPL 1: copies\n  parameter logic [NRP-1:0][2:0] CPY = '0, // IMPL 1: each read port's copy (< NCP)\n  parameter bit   RQ    = 1'b0,           // IMPL 1: bank addresses from the requests (see top)\n  parameter logic [NRP-1:0][2:0] PRANK = '0, // RQ, IMPL 3: each read port's priority (0 first)\n  parameter int   NSB   = 8,              // IMPL 3: RAMs (sub-banks) per bank\n  parameter int   SBP   = 3,              // IMPL 3: the sub-bank field's lowest word-address bit\n  parameter bit   SHARE = 1'b1,           // IMPL 3: ports reading one word share its RAM read\n  parameter logic [NRP-1:0][2:0] GRP = '0, // IMPL 3: each read port's group (the slice's unit)\n  parameter int   SBH   = 0,              // IMPL 3: the sub-bank hashed with the row bits above\n                                          //   it (1: the next field, 2: every field, XORed)\n  parameter bit   RPL   = 1'b0,           // IMPL 3: a lost read is replayed the next cycle (see\n                                          //   IMPL 3 below)\n  parameter logic [NRP-1:0] RPLM = '1,    // RPL: the ports whose reads may be replayed\n  parameter int   TOPP  = 0,              // RPL: the port whose request comes before the replays\n  parameter bit   TDP   = 1'b0,           // IMPL 3: true dual-port RAMs (see IMPL 3 below)\n  parameter logic [NRP-1:0] SIDE = '0,    // TDP: each read port's RAM port (1: A, the writes')\n  parameter bit   GST   = 1'b0,           // IMPL 3: SH_MASK's ports are SH_HOST's guests (see IMPL 3)\n  parameter int   PMP   = 0,              // TDP: 1 the RAMs pumped at 2x on clk_f (otpu_pump_bank), 2\n                                          //   its model at the core clock (see IMPL 3)\n  parameter bit   IQ    = 1'b0            // the input stage: the granted writes registered (below)\n) (\n  input  logic                                clk,\n  input  logic                                clk_f,    // PMP 1: 2 x clk, aligned (else unused)\n  input  logic [NRP-1:0][LANES-1:0]           r_en,     // granted reads\n  input  logic [NRP-1:0][LANES-1:0]           r_req,    // requested reads (r_en before the grant)\n  input  logic [NRP-1:0][LANES-1:0][31:0]     r_addr,\n  input  logic [NRP-1:0][LANES-1:0]           r_ben,    // PBR: r_req by bank (bank b's)\n  input  logic [NRP-1:0][LANES-1:0][31:0]     r_bad,    // PBR: the address of bank b's lane\n  output logic [NRP-1:0][LANES-1:0][31:0]     r_data,\n  input  logic [NWP-1:0][LANES-1:0]           w_en,     // granted writes\n  input  logic [NWP-1:0][LANES-1:0]           w_req,    // requested writes (w_en before the grant)\n  input  logic [NWP-1:0]                      w_gnt,    // the grant of each write port's unit\n  input  logic [NWP-1:0][LANES-1:0][31:0]     w_addr,\n  input  logic [NWP-1:0][LANES-1:0][31:0]     w_data,\n  output logic [NRP-1:0]                      blk_x,    // IMPL 3: a port of another group\n  output logic [NRP-1:0]                      blk_s,    //   / of its own took a RAM it reads\n  output logic [NRP-1:0]                      lost,     // IMPL 3 RPL: the port's read this cycle\n                                                        //   lost a RAM (replayed next cycle)\n  output logic [NRP-1:0]                      frz,      // IMPL 3 RPL: the port replays now\n  input  logic                                dump\n);\n  localparam int BW = $clog2(LANES);\n  localparam int BD = WORDS / LANES;        // words per bank\n  localparam int IW = $clog2(BD);\n  initial if ((IMPL == 1 || IMPL == 3) && WPB != 1) $fatal(1, \"otpu_tmem: IMPL %0d needs WPB = 1\", IMPL);\n  initial if (TDP && IMPL != 3) $fatal(1, \"otpu_tmem: TDP needs IMPL 3\");\n  initial if (GST && (IMPL != 3 || (RPL && SH_HOST != TOPP)))\n    $fatal(1, \"otpu_tmem: GST needs IMPL 3, and SH_HOST = TOPP with RPL (no replay of a guest's read)\");\n  initial if (IMPL == 3 && (NSB < 1 || (1 << $clog2(NSB)) != NSB || SBP < BW || SBP + $clog2(NSB) > BW + IW))\n    $fatal(1, \"otpu_tmem: IMPL 3 sub-banks NSB %0d (a power of 2) at bit SBP %0d\", NSB, SBP);\n  initial if (PMP != 0 && !TDP) $fatal(1, \"otpu_tmem: PMP needs TDP (its read ports' sides)\");\n  initial if (IMPL == 1) for (int p = 0; p < NRP; p++)\n    if (CPY[p] >= NCP) $fatal(1, \"otpu_tmem: port %0d's copy %0d >= NCP %0d\", p, CPY[p], NCP);\n  // the read port that holds each port's copy: IMPL 0, the port itself or SH_HOST (a guest);\n  // IMPL 1, the first port on its copy\n  function automatic int host_of(input int p);\n    if (IMPL == 0) return SH_MASK[p] ? SH_HOST : p;\n    for (int q = 0; q < NRP; q++) if (CPY[q] == CPY[p]) return q;\n    return p;\n  endfunction\n\n\n  // ---- IQ, the input stage (release r2, docs/tmem_nocopy.md 7): the granted writes (their\n  // lanes, addresses and data, the ports' grants) are registered here, and the lane routing, the\n  // write selection and the registered write stage run on them a cycle later, so the selection\n  // starts at flip-flops instead of at the units' write logic and the arbiter's grants. The units\n  // register their read requests (the reads come a cycle after they form, with the same grants),\n  // so reads and writes both move a cycle and the memory's order is unchanged: no bypass of the\n  // stage. Without IQ the inputs pass through.\n  logic [NWP-1:0][LANES-1:0]       wi_en;\n  logic [NWP-1:0]                  wi_gnt;\n  logic [NWP-1:0][LANES-1:0][31:0] wi_addr, wi_data;\n  if (IQ) begin : g_iq\n    always_ff @(posedge clk) begin\n      wi_en <= w_en;\n      wi_gnt <= w_gnt;\n      // with WPB 1 every cycle (the selection takes a port's lanes only under its registered\n      // grant, wi_gnt, so the words are the granted ones there): the grant, the arbiter's logic,\n      // then enables no address and data flip-flops (on the m8 card one LUT of it enabled\n      // 11,254, the MXU's lanes with them)\n      for (int p = 0; p < NWP; p++)\n        if (w_gnt[p] || WPB == 1) begin\n          wi_addr[p] <= w_addr[p];\n          wi_data[p] <= w_data[p];\n        end\n    end\n`ifndef SYNTHESIS\n    initial begin wi_en = '0; wi_gnt = '0; end\n`endif\n  end else begin : g_niq\n    assign wi_en = w_en, wi_gnt = w_gnt, wi_addr = w_addr, wi_data = w_data;\n  end\n  // (the selection takes each port's lanes from its requests and the port by its grant: with IQ\n  // the registered granted lanes and grants)\n  wire [NWP-1:0][LANES-1:0] wi_req = IQ ? wi_en : w_req;\n\n  // ---- write selection: per bank, the enabled lanes of all write ports. The arbiter admits at\n  // most WPB of them, so with WPB = 1 a flat AND-OR tree selects the one (no priority chain).\n  logic [LANES-1:0][WPB-1:0]         bw_v;\n  logic [LANES-1:0][WPB-1:0][IW-1:0] bw_a;\n  logic [LANES-1:0][WPB-1:0][31:0]   bw_d;\n  if (WPB == 1) begin : g_w1\n    // each port's lanes are merged per bank from its requests (a port belongs to one unit, its\n    // lanes hit distinct banks), then the ports by their grants: the grant enters at the last\n    // AND-OR level instead of at every lane (the arbiter admits one granted writer per bank)\n    // per port, its lanes in bank order (a rotator, or the crossbar of the port's lanes, which\n    // hit distinct banks), then the ports merged by their grants: the grant enters at the last\n    // AND-OR level instead of at every lane (the arbiter admits one granted writer per bank)\n    logic [NWP-1:0][LANES-1:0]         pv;\n    logic [NWP-1:0][LANES-1:0][IW-1:0] pa;\n    logic [NWP-1:0][LANES-1:0][31:0]   pdt;\n    for (genvar p = 0; p < NWP; p++) begin : g_wp\n      if (GEN_W[p]) begin : g_x\n        always_comb begin\n          pv[p] = '0; pa[p] = '0; pdt[p] = '0;\n          for (int b = 0; b < LANES; b++)\n            for (int l = 0; l < LANES; l++)\n              if (wi_req[p][l] && wi_addr[p][l][BW-1:0] == BW'(b)) begin\n                pv[p][b] = 1'b1;\n                pa[p][b] = pa[p][b] | wi_addr[p][l][BW +: IW];\n                pdt[p][b] = pdt[p][b] | wi_data[p][l];\n              end\n        end\n      end else begin : g_r\n        wire [BW+IW-1:0] a0 = wi_addr[p][0][BW+IW-1:0];\n        wire [BW-1:0]    rot = a0[BW-1:0];\n        always_comb begin\n          logic [LANES-1:0]       v, tv;\n          logic [LANES-1:0][31:0] d, td;\n          v = wi_req[p]; d = wi_data[p]; tv = '0; td = '0;\n          for (int k = 0; k < BW; k++)\n            if (rot[k]) begin\n              tv = v; td = d;\n              for (int l = 0; l < LANES; l++) begin\n                v[(l + (1 << k)) % LANES] = tv[l];\n                d[(l + (1 << k)) % LANES] = td[l];\n              end\n            end\n          pv[p] = v; pdt[p] = d;\n          for (int b = 0; b < LANES; b++) pa[p][b] = a0[BW +: IW] + IW'(BW'(b) < rot);\n        end\n      end\n    end\n    always_comb begin\n      bw_v = '0; bw_a = '0; bw_d = '0;\n      for (int p = 0; p < NWP; p++)\n        if (wi_gnt[p])\n          for (int b = 0; b < LANES; b++)\n            if (pv[p][b]) begin\n              bw_v[b][0] = 1'b1;\n              bw_a[b][0] = bw_a[b][0] | pa[p][b];\n              bw_d[b][0] = bw_d[b][0] | pdt[p][b];\n            end\n    end\n  end else begin : g_wn\n    always_comb begin\n      for (int b = 0; b < LANES; b++) begin\n        int n;\n        n = 0;\n        bw_v[b] = '0; bw_a[b] = '0; bw_d[b] = '0;\n        for (int p = 0; p < NWP; p++)\n          for (int l = 0; l < LANES; l++)\n            if (wi_en[p][l] && wi_addr[p][l][BW-1:0] == BW'(b) && n < WPB) begin\n              bw_v[b][n] = 1'b1;\n              bw_a[b][n] = wi_addr[p][l][BW +: IW];\n              bw_d[b][n] = wi_data[p][l];\n              n = n + 1;\n            end\n      end\n    end\n  end\n\n  // ---- the registered write stage: this cycle's selected writes land next cycle (pw_*); the\n  // data of the writes landing now is kept one more cycle (pd) for the reads that bypass them.\n  // Each pw bit reaches every copy of its bank (the copies' block RAMs spread over the die):\n  // synthesis replicates the registers so each copy gets nearby ones (one copy's net to the\n  // block RAM address pins was the worst core_clk path at 120 MHz, 0 logic levels). With PMP 1\n  // each pumped RAM takes its own copy instead (pk_*, IMPL 3); pw stays for the bypass, the\n  // replays' checks and the dump.\n  (* max_fanout = 16 *) logic [LANES-1:0][WPB-1:0]         pw_v;\n  (* max_fanout = 16 *) logic [LANES-1:0][WPB-1:0][IW-1:0] pw_a;\n  (* max_fanout = 16 *) logic [LANES-1:0][WPB-1:0][31:0]   pw_d;\n  logic [LANES-1:0][WPB-1:0][31:0]                         pd;\n  always_ff @(posedge clk) begin\n    pw_v <= bw_v;\n    pw_a <= bw_a;\n    pw_d <= bw_d;\n    pd <= pw_d;\n  end\n`ifndef SYNTHESIS\n  initial pw_v = '0;\n`endif\n\n  // ---- read ports: each port's bank enables and rows (from its requests)\n  logic [NRP-1:0][LANES-1:0]         pb_en;\n  logic [NRP-1:0][LANES-1:0][IW-1:0] pb_a;\n  logic [NRP-1:0][LANES-1:0][31:0]   pq;      // the bank data each port's copy returns\n  // IMPL 3 without the bypass (PMP 1), a host port (pdir): its side's RAM words, bank b's RAM k at\n  // b * NSB + k (pr), and the RAM each bank read (pss); its lanes select a word by {bank, RAM}, one\n  // NSB x LANES : 1 select from the RAMs (LUT6s, MUXF7s, a MUXF8 in a slice at NSB 2), not the\n  // bank's RAM select and then the lane's bank select (two LUTs and a route between: the m8 card\n  // at 150 MHz, the pumped RAMs -> 4 levels -> the VPU's, the quantizer's, the DMA's capture,\n  // -0.112 ns of a full core cycle, 3.9 ns of route)\n  localparam int PSB = (NSB > 1) ? $clog2(NSB) : 1;\n  logic [NRP-1:0][LANES*NSB-1:0][31:0] pr;\n  logic [NRP-1:0][LANES-1:0][PSB-1:0]  pss;\n  logic [NRP-1:0]                      pdir;\n  logic [NRP-1:0][LANES-1:0]         rpf;     // IMPL 3 RPL: the lanes a replay reads now\n  for (genvar p = 0; p < NRP; p++) begin : g_preq\n    // per bank: the address of the lane that reads it (lanes of one port hit distinct banks or\n    // read the same word, so an AND-OR merge is exact). A port belongs to one unit and the\n    // grant is all-or-nothing per unit, so the address and the enable are merged from the\n    // requests: the grant reaches no block RAM pin (it only decides which lanes take the data)\n    logic [LANES-1:0]         b_en;\n    logic [LANES-1:0][IW-1:0] b_a;\n    wire  [BW+IW-1:0]         a0 = r_addr[p][0][BW+IW-1:0];\n    wire  [BW-1:0]            rot = a0[BW-1:0];\n    // IMPL 1: a copy's bank serves the one port granted in it, so its enables are the grants\n    // (RQ: the requests, the copy picks by priority)\n    wire  [LANES-1:0]         rs = (IMPL == 1 && !RQ) ? r_en[p] : r_req[p];\n    // the port's own merge: the crossbar's (GEN_R: per bank, the lanes that read it), else the\n    // rotator's (lanes contiguous from lane 0's word: bank b is lane (b - rot)'s, one row on\n    // where the lanes wrap)\n    logic [LANES-1:0]         x_en;\n    logic [LANES-1:0][IW-1:0] x_a;\n    always_comb begin\n      x_en = '0; x_a = '0;\n      if (GEN_R[p]) begin\n        for (int b = 0; b < LANES; b++)\n          for (int l = 0; l < LANES; l++)\n            if (r_addr[p][l][BW-1:0] == BW'(b) && rs[l]) begin\n              x_en[b] = 1'b1;\n              x_a[b] = x_a[b] | r_addr[p][l][BW +: IW];\n            end\n      end else begin\n        logic [LANES-1:0] t;\n        t = '0;\n        x_en = rs;\n        for (int k = 0; k < BW; k++)\n          if (rot[k]) begin\n            t = x_en;\n            for (int l = 0; l < LANES; l++) x_en[(l + (1 << k)) % LANES] = t[l];\n          end\n        for (int b = 0; b < LANES; b++) x_a[b] = a0[BW +: IW] + IW'(BW'(b) < rot);\n      end\n    end\n    // PBR: the unit's merge, from its flip-flops (otpu_mxu TQ: rb_q / rb_a; otpu_tmem_breq's\n    // decode registered in the DMA, the VPU and the quantizer), without the lanes' merge in front\n    // of the ranks, the compares and the RAM pins\n    always_comb begin\n      b_en = x_en; b_a = x_a;\n      if (PBR[p]) begin\n        b_en = r_ben[p];\n        for (int b = 0; b < LANES; b++) b_a[b] = r_bad[p][b][BW +: IW];\n      end\n    end\n    assign pb_en[p] = b_en;\n    assign pb_a[p] = b_a;\n`ifndef SYNTHESIS\n    // PBR: the unit's merge is the port's own (the banks read; their rows where read)\n    if (PBR[p]) begin : g_pbr_chk\n      always @(posedge clk) begin\n        if (r_ben[p] != x_en)\n          $fatal(1, \"TMEM%0d: port %0d's banks %b are not its lanes' %b at %0t\", SID, p, r_ben[p],\n                 x_en, $time);\n        for (int b = 0; b < LANES; b++)\n          if (x_en[b] && r_bad[p][b][BW +: IW] != x_a[b])\n            $fatal(1, \"TMEM%0d: port %0d's bank %0d row %0h is not its lane's %0h at %0t\", SID, p, b,\n                   r_bad[p][b][BW +: IW], x_a[b], $time);\n      end\n    end\n`endif\n  end\n\n`ifndef SYNTHESIS\n  // ---- the dump (simulation): the memory itself, not the writes asked of it. On `dump` the first\n  // copy's banks (DP) put their words into img, word i = bank i mod LANES's row i / LANES; a cycle\n  // later every other copy is checked against them (a copy that differs stops the simulation)\n  // and img goes to <dir>/tmem_<SID>.hex. +tmem_fault=<SID>,<word>: every write to the word\n  // lands with bit 0 flipped, in every copy, or with +tmem_fault_port=<port> in that port's\n  // (tests: the dump and the check see a fault in the registered write stage, the RAM or one\n  // copy)\n  function automatic int first_copy();\n    for (int p = 0; p < NRP; p++) if (host_of(p) == p) return p;\n    return 0;\n  endfunction\n  localparam int DP = first_copy();\n  logic [31:0] img [WORDS];\n  logic        dump_q;\n  int          fault_w, fault_p;\n  initial begin\n    string arg;\n    int sid, w, p;\n    dump_q = 1'b0; fault_w = -1; fault_p = -1;\n    if ($value$plusargs(\"tmem_fault=%s\", arg) && $sscanf(arg, \"%d,%d\", sid, w) == 2 && sid == SID)\n    begin\n      fault_w = w;\n      if ($value$plusargs(\"tmem_fault_port=%d\", p)) fault_p = p;\n    end\n  end\n  always @(posedge clk) dump_q <= dump;\n  function automatic logic [31:0] fault(input int p, input int b, input logic [IW-1:0] row);\n    return 32'(fault_w >= 0 && fault_w == int'(row) * LANES + b && (fault_p < 0 || fault_p == p));\n  endfunction\n`endif\n\n  // ---- the copies: one per read port, except the guests (SH_MASK), which read SH_HOST's copy:\n  // it serves the first port that requests, the host, then the guests in port order. IMPL 1:\n  // one per CPY value, held by its first port; each bank serves the port granted in it.\n  // ---- IMPL 3 (EXPERIMENTAL, docs/tmem_nocopy.md): one copy. Each bank is NSB RAMs with their\n  // own addresses: a word's sub-bank is its bank row's bits [SBP-BW +: log2 NSB] (SBP = BW: the\n  // 8-word groups interleave over the RAMs; higher: regions), XORed with the row's fields above\n  // them (SBH 1: the next one, 2: all of them: a hash). A RAM's address is that of the asker\n  // first in rank, from the requests (no grant on a RAM's address path, as RQ). An asker that\n  // asks a RAM an asker before it took for another word (SHARE: one word read by two is one read)\n  // loses it.\n  // Without RPL the ranks are PRANK's and a port that would lose is blocked: by a port of\n  // another group (blk_x: the slice does not grant the unit) or of its own (blk_s: the slice reads\n  // the group's ports over successive cycles, otpu_slice TMEM_IMPL 3).\n  // RPL (replay): the units read as if no RAM were shared (the slice's grant ignores the RAMs) and\n  // a read that lost is read again the next cycle: the port's banks and rows are registered with\n  // the read, and the next cycle they ask again (frz) ranked before every request but TOPP's (the\n  // DMA's, which has no hold), and among the replays the oldest first (age, a forward-progress\n  // guarantee); their words reach the port's lanes the cycle after (the lanes\n  // fresh again, without the bypass: the replay returns what the first read would have, the\n  // writes landed since are the ones that were before it). `lost` tells the slice to hold the\n  // port's unit for the cycle the replay takes (its lanes' words of the lost read are not the\n  // ones asked). blk_x is then a port's request losing (for units that cannot hold, which the\n  // slice keeps from reading instead), blk_s 0.\n  // A port asks with its request, or with its replay while one is pending (the slice then holds\n  // its unit, so its request does not ask): one asker a port, whose rank the replay registers pick.\n  // Writes: one per bank and cycle, as IMPL 0 and 1, to the RAM of its sub-bank; the registered\n  // write stage and its bypass are IMPL 0's.\n  // TDP: true dual-port RAMs, each read port on one of a RAM's two ports (SIDE: 0 port B, 1 port\n  // A), ranked among the ports on its side only; a write takes its RAM's port A, so an asker on\n  // port A of a RAM being written loses unless it reads the written word (a read takes the\n  // bypass, a replay port A's read-first word). On the 7-series a true dual-port RAMB36 is at most\n  // 36 bits wide: a RAM of 1K words is one RAMB36, as in the simple dual-port.\n  // PMP (with TDP): the RAMs pumped at twice the core clock (1: otpu_pump_bank on clk_f, as P3's\n  // copies, docs/tmem_pump.md): both RAM ports read at the core edge and the write lands at the fast\n  // edge between, so a write takes no read port (no port-A conflicts) and a read at the core edge\n  // sees the landing write in the RAM (no bypass). A replay then must not meet a write of its word\n  // landing in its winning cycle either (the ordering of docs/tmem_nocopy.md 5.1 keeps it out). 2:\n  // the same at the core clock for simulation (a write port of its own, the bypass kept): the\n  // same words and cycles as 1, without the second clock.\n  // NSB 1: one RAM a bank (no sub-banks, no data select).\n  // GST: IMPL 0's guests (SH_MASK, the slice's QUANT 3 and COLL): a guest reads only while SH_HOST\n  // and the guests before it ask nothing (the slice's q3_blk / coll_blk), so it has no asker of its\n  // own: SH_HOST's asker asks for the first guest that reads, and the guests take its data (one\n  // data select for the three). With RPL the host is TOPP, which never loses.\n  // an asker's rank (0 first): without RPL PRANK's; with it TOPP's request, the replays in PRANK\n  // order (on a side with three or more replay askers the oldest first: age, below; PRANK's for\n  // those begun in one cycle), then the other requests in PRANK order. rlive: the port's reads\n  // may be replayed\n  function automatic int rnk(input int p, input bit rp);\n    if (!RPL) return int'(PRANK[p]);\n    if (rp) return 1 + int'(PRANK[p]);\n    if (p == TOPP) return 0;\n    return 1 + NRP + int'(PRANK[p]);\n  endfunction\n  function automatic bit rlive(input int p);\n    return RPL && RPLM[p] && p != TOPP;\n  endfunction\n  function automatic int sd_of(input int p);   // the RAM port a read port asks on (0: B)\n    return (TDP && SIDE[p]) ? 1 : 0;\n  endfunction\n  // OTPU_TMEM_ABL_* (EXPERIMENTAL, out-of-context LUT breakdown only, docs/tmem_nocopy.md 6.3: the\n  // TMEM is wrong with any of them): _DSEL a port takes two fixed RAMs' words XORed (no data\n  // select; every RAM output still used), _CMP no\n  // conflict compares (nothing lost), _RPL no replay buffers (an asker is its request), _AMUX a\n  // RAM's address is its side's first port's (no priority multiplexer)\n  if (IMPL == 3) begin : g_one\n    localparam int LSB = $clog2(NSB);\n    localparam int LW  = (LSB > 0) ? LSB : 1;  // a sub-bank number's width (NSB 1: always 0)\n    localparam int SO  = SBP - BW;             // the sub-bank field's offset in a bank row\n    localparam bit BYP = PMP != 1;             // the bypass (a pumped RAM has the landing write)\n    localparam int RW  = IW - LSB;             // a RAM's address bits\n    localparam int RD  = BD / NSB;             // a RAM's words\n    localparam int NS  = TDP ? 2 : 1;          // a RAM's read ports\n    function automatic logic [LW-1:0] hash(input logic [IW-1:0] hi);\n      logic [LW-1:0] x;\n      x = '0;\n      if (LSB > 0 && SBH == 1) x = LW'(hi);\n      if (LSB > 0 && SBH == 2) for (int f = 0; f < IW; f += LW) x = x ^ LW'(hi >> f);\n      return x;\n    endfunction\n    function automatic logic [RW-1:0] ram_row(input logic [IW-1:0] row);\n      logic [IW-1:0] hi, lo;\n      hi = row >> (SO + LSB);\n      lo = row & ((IW'(1) << SO) - IW'(1));\n      return RW'((hi << SO) | lo);\n    endfunction\n    function automatic logic [LW-1:0] sub_of(input logic [IW-1:0] row);\n      if (LSB == 0) return '0;\n      return LW'(row >> SO) ^ hash(row >> (SO + LSB));\n    endfunction\n`ifndef SYNTHESIS\n    // the bank row held in RAM k's row r (the dump)\n    function automatic int row_of(input int k, input int r);\n      logic [IW-1:0] hi, lo, f;\n      hi = IW'(r >> SO);\n      lo = IW'(r & ((1 << SO) - 1));\n      f = (LSB == 0) ? '0 : IW'(LW'(k) ^ hash(hi));\n      return int'((hi << (SO + LSB)) | (f << SO) | lo);\n    endfunction\n`endif\n    // the replays: a lost read's banks, rows and lanes, registered with it\n    logic [NRP-1:0]                    rpv;\n    // ... and rpv's copy per bank (rpvb: kept, each loaded with lost as rpv is): bank b's asker\n    // multiplexers, its replay registers' loads, its data select and its lane's replay take theirs,\n    // so no one register's replicas reach every bank's (r150c, the m8 card at a real 150 MHz:\n    // rpv's replica, fanout 42, into the pumped RAMs' read pins +0.041 ns, into lost_q +0.028)\n    (* keep = \"true\" *) logic [NRP-1:0][LANES-1:0] rpvb;\n    logic [NRP-1:0][LANES-1:0]         rpe;\n    logic [NRP-1:0][LANES-1:0][IW-1:0] rpa;\n    logic [NRP-1:0][LANES-1:0]         rpl;\n    logic [NRP-1:0]                    rp;      // the port's asker is its replay\n    // each port's requested banks and rows (GST: the host's are the first reading guest's while\n    // it asks nothing itself; a guest asks nothing)\n    logic [NRP-1:0][LANES-1:0]         qe;\n    logic [NRP-1:0][LANES-1:0][IW-1:0] qa;\n    always_comb begin\n      logic take;\n      qe = pb_en; qa = pb_a;\n      take = |r_req[SH_HOST];\n      if (GST)\n        for (int g = 0; g < NRP; g++)\n          if (SH_MASK[g]) begin\n            if (!take && |r_req[g]) begin\n              qe[SH_HOST] = pb_en[g]; qa[SH_HOST] = pb_a[g]; take = 1'b1;\n            end\n            qe[g] = '0;\n          end\n    end\n    // each asker's banks, bank rows, sub-banks and RAM rows\n    logic [NRP-1:0][LANES-1:0]          ae;\n    logic [NRP-1:0][LANES-1:0][IW-1:0]  aa;\n    logic [NRP-1:0][LANES-1:0][LW-1:0]  asb;\n    logic [NRP-1:0][LANES-1:0][RW-1:0]  arw;\n    for (genvar i = 0; i < NRP; i++) begin : g_as\n`ifdef OTPU_TMEM_ABL_RPL\n      assign rp[i] = 1'b0;\n`else\n      assign rp[i] = rlive(i) && rpv[i];\n`endif\n      for (genvar b = 0; b < LANES; b++) begin : g_b\n`ifdef OTPU_TMEM_ABL_RPL\n        wire rpb = 1'b0;\n`else\n        wire rpb = rlive(i) && rpvb[i][b];         // rp[i], bank b's copy\n`endif\n        assign ae[i][b] = rpb ? rpe[i][b] : qe[i][b];\n        assign aa[i][b] = rpb ? rpa[i][b] : qa[i][b];\n        assign asb[i][b] = sub_of(aa[i][b]);\n        assign arw[i][b] = ram_row(aa[i][b]);\n      end\n    end\n    // The replays' age (RPL, a forward-progress guarantee): of two replays the older ranks first\n    // (begun in one cycle, in PRANK order). A replay then loses only to TOPP's ask and to replays\n    // older than it, and the oldest wins as soon as TOPP leaves its RAMs. A fixed order let two\n    // ports that took turns replaying hold off a third: each lost a read to the third's pending\n    // replay (which took that RAM, losing another) and its replay then beat the third's. With two\n    // replay askers on a side that needs TOPP every other cycle, so the age is kept only on a side\n    // of three or more (the pick's port B: the MXU, VPU B, QUANT 2; GST's guests have no asker).\n    function automatic bit asker_rl(input int p);   // a replayable port with an asker of its own\n      return rlive(p) && !(GST && SH_MASK[p]);\n    endfunction\n    function automatic bit aged(input int i, input int o);\n      int n;\n      n = 0;\n      for (int p = 0; p < NRP; p++) if (asker_rl(p) && sd_of(p) == sd_of(i)) n++;\n      return i != o && asker_rl(i) && asker_rl(o) && sd_of(i) == sd_of(o) && n >= 3;\n    endfunction\n    // age[i][o] (o < i): o's replay began before i's (meaningful while both replay). A replay\n    // begins the cycle after its port's read loses (lost, rpv low): o's beginning makes it the\n    // younger, unless i's begins with it\n    logic [NRP-1:0][NRP-1:0] age;\n    always_ff @(posedge clk)\n      for (int i = 0; i < NRP; i++)\n        for (int o = 0; o < i; o++)\n          if (aged(i, o)) begin\n            if (lost[o] && !rpv[o])\n              age[i][o] <= (lost[i] && !rpv[i]) ? rnk(o, 1'b1) < rnk(i, 1'b1) : 1'b0;\n            else if (lost[i] && !rpv[i]) age[i][o] <= 1'b1;\n          end\n`ifndef SYNTHESIS\n    initial age = '0;\n`endif\n    // bf[i][o]: asker o ranks before asker i this cycle (on i's side; the replays' registers pick\n    // the case of four: three constant ones, and with both replaying their age where it is kept)\n    logic [NRP-1:0][NRP-1:0] bf;\n    for (genvar i = 0; i < NRP; i++) begin : g_bf\n      for (genvar o = 0; o < NRP; o++) begin : g_o\n        if (o == i || sd_of(o) != sd_of(i)) begin : g_n\n          assign bf[i][o] = 1'b0;\n        end else begin : g_y\n          localparam bit B00 = rnk(o, 1'b0) < rnk(i, 1'b0);\n          localparam bit B01 = rnk(o, 1'b0) < rnk(i, 1'b1);\n          localparam bit B10 = rnk(o, 1'b1) < rnk(i, 1'b0);\n          localparam bit B11 = rnk(o, 1'b1) < rnk(i, 1'b1);\n          wire ol = !aged(i, o) ? B11 : (o < i) ? age[i][o] : !age[o][i];\n          assign bf[i][o] = rp[o] ? (rp[i] ? ol : B10) : (rp[i] ? B01 : B00);\n        end\n      end\n    end\n    // wk[i][b]: TDP, asker i asks port A of a RAM the write in bank b takes\n    logic [NRP-1:0][LANES-1:0] wk;\n    for (genvar i = 0; i < NRP; i++) begin : g_wk\n      for (genvar b = 0; b < LANES; b++) begin : g_b\n        if (sd_of(i) == 1 && PMP == 0) begin : g_a\n          assign wk[i][b] = pw_v[b][0] && sub_of(pw_a[b][0]) == asb[i][b];\n        end else begin : g_b0\n          assign wk[i][b] = 1'b0;\n        end\n      end\n    end\n    // the RAMs' addresses: per RAM and side, the asker first in rank (an AND-OR multiplexer of\n    // the askers' rows)\n    logic [LANES-1:0][NSB-1:0][NS-1:0]         s_en;\n    logic [LANES-1:0][NSB-1:0][NS-1:0][RW-1:0] s_a;\n    for (genvar b = 0; b < LANES; b++) begin : g_ra\n      for (genvar k = 0; k < NSB; k++) begin : g_k\n        logic [NRP-1:0] rq, win;\n        for (genvar i = 0; i < NRP; i++) begin : g_i\n          assign rq[i] = ae[i][b] && asb[i][b] == LW'(k);\n          assign win[i] = rq[i] && !(|(rq & bf[i]));\n        end\n        always_comb\n          for (int s = 0; s < NS; s++) begin\n            bit got;\n            got = 1'b0;\n            s_en[b][k][s] = 1'b0;\n            s_a[b][k][s] = '0;\n            for (int i = 0; i < NRP; i++)\n              if (sd_of(i) == s) begin\n                s_en[b][k][s] = s_en[b][k][s] | rq[i];\n`ifdef OTPU_TMEM_ABL_AMUX\n                if (!got) s_a[b][k][s] = arw[i][b];\n                got = 1'b1;\n`else\n                if (win[i]) s_a[b][k][s] = s_a[b][k][s] | arw[i][b];\n`endif\n              end\n          end\n      end\n    end\n    // cp[i][o] (o < i, one side): the two askers ask one RAM for different words; hm[i][o]: o,\n    // ranked before i, does so (on port A of a RAM being written the write decides: wm)\n    logic [NRP-1:0][NRP-1:0] cp, hm;\n    logic [NRP-1:0]          wm;\n    for (genvar i = 0; i < NRP; i++) begin : g_cf\n      for (genvar o = 0; o < NRP; o++) begin : g_o\n        if (o < i && sd_of(o) == sd_of(i)) begin : g_c\n          logic [LANES-1:0] hb;\n          for (genvar b = 0; b < LANES; b++) begin : g_b\n            assign hb[b] = ae[i][b] && ae[o][b] && asb[o][b] == asb[i][b] && !wk[i][b] &&\n                           (!SHARE || aa[o][b] != aa[i][b]);\n          end\n`ifdef OTPU_TMEM_ABL_CMP\n          assign cp[i][o] = 1'b0;\n`else\n          assign cp[i][o] = |hb;\n`endif\n        end else begin : g_n\n          assign cp[i][o] = 1'b0;\n        end\n      end\n      logic [LANES-1:0] wb;\n      for (genvar b = 0; b < LANES; b++) begin : g_w\n        assign wb[b] = ae[i][b] && wk[i][b] && pw_a[b][0] != aa[i][b];\n      end\n`ifdef OTPU_TMEM_ABL_CMP\n      assign wm[i] = 1'b0;\n`else\n      assign wm[i] = |wb;\n`endif\n    end\n    always_comb\n      for (int i = 0; i < NRP; i++)\n        for (int o = 0; o < NRP; o++)\n          hm[i][o] = (o < i ? cp[i][o] : cp[o][i]) && bf[i][o];\n    always_comb\n      for (int p = 0; p < NRP; p++) begin\n        blk_x[p] = wm[p]; blk_s[p] = 1'b0;\n        for (int o = 0; o < NRP; o++)\n          if (hm[p][o]) begin\n            if (!RPL && GRP[o] == GRP[p]) blk_s[p] = 1'b1;\n            else blk_x[p] = 1'b1;\n          end\n      end\n    // a read lost: the port read (its unit was granted, r_en) or replayed, and lost a RAM\n    always_comb\n      for (int p = 0; p < NRP; p++)\n        lost[p] = rlive(p) && (rpv[p] || (|r_en[p])) && ((|hm[p]) || wm[p]);\n    always_ff @(posedge clk)\n      for (int p = 0; p < NRP; p++) begin\n        rpv[p] <= lost[p];\n        for (int b = 0; b < LANES; b++) begin\n          rpvb[p][b] <= lost[p];\n          if (!rpvb[p][b]) begin rpe[p][b] <= qe[p][b]; rpa[p][b] <= qa[p][b]; rpl[p][b] <= r_en[p][b]; end\n        end\n      end\n`ifndef SYNTHESIS\n    initial rpv = '0;\n    initial rpvb = '0;\n    always @(posedge clk)\n      for (int p = 0; p < NRP; p++)\n        if (rpvb[p] != {LANES{rpv[p]}}) $fatal(1, \"TMEM%0d: port %0d's rpv copies %b are not rpv %b\", SID, p,\n                                               rpvb[p], rpv[p]);\n    // the replays' premise: no write lands on a word awaiting its replay before the replay wins\n    // (it would read the new word). A write landing in the cycle the replay wins is fine (the\n    // RAM reads first); one landing while it loses again is not.\n    always @(posedge clk)\n      for (int p = 0; p < NRP; p++)\n        if (RPL && rpv[p] && (lost[p] || PMP == 1))\n          for (int b = 0; b < LANES; b++)\n            if (rpe[p][b] && pw_v[b][0] && pw_a[b][0] == rpa[p][b])\n              $fatal(1, \"TMEM%0d: port %0d's word %0d awaiting a replay was written at %0t\", SID, p,\n                     int'(rpa[p][b]) * LANES + b, $time);\n    // forward progress: a replay that loses RPLW cycles in a row stops the simulation (a livelock:\n    // what holds a replay off, TOPP's asks and older replays, lasts that long only when it waits on\n    // the replaying unit itself)\n    localparam int RPLW = 1 << 22;\n    int rpn [NRP];\n    initial for (int p = 0; p < NRP; p++) rpn[p] = 0;\n    always @(posedge clk)\n      for (int p = 0; p < NRP; p++) begin\n        rpn[p] <= (RPL && rpv[p] && lost[p]) ? rpn[p] + 1 : 0;\n        if (rpn[p] >= RPLW)\n          $fatal(1, \"TMEM%0d: port %0d's replay lost %0d cycles in a row at %0t\", SID, p, rpn[p],\n                 $time);\n      end\n`endif\n    assign frz = RPL ? rpv : '0;\n    always_comb\n      for (int p = 0; p < NRP; p++)\n        for (int l = 0; l < LANES; l++) rpf[p][l] = RPL && rpvb[p][l] && rpl[p][l];\n    logic [LANES-1:0][NSB-1:0][NS-1:0][31:0] s_q;\n    for (genvar b = 0; b < LANES; b++) begin : g_bank\n      for (genvar k = 0; k < NSB; k++) begin : g_sub\n        logic [31:0] wd;\n`ifdef SYNTHESIS\n        assign wd = pw_d[b][0];\n`else\n        assign wd = pw_d[b][0] ^ fault(0, b, pw_a[b][0]);\n`endif\n        wire wh = pw_v[b][0] && sub_of(pw_a[b][0]) == LW'(k);\n        // (inferred here: 64 otpu_ram_1r1w cells of this size in the slice crash Verilator 5.046's\n        // front end, an internal fault; the cell is this RAM)\n        if (PMP == 1) begin : g_pmp\n          // pumped at 2x: port A reads side 1, port B side 0 at the core edge, the write lands at\n          // the fast edge between (P3's bank). The write's inputs are this RAM's own copy of the\n          // registered write stage (pk_*, release r2): its sub-bank's decode and the RAM row are\n          // taken before the register, so the bank's write pins (on clk_f, a half core cycle\n          // from the register) come straight from flip-flops kept next to it, not through the\n          // bank-level pw's decode and fanout (r2m4: pw_* -> the pumped banks, clk -> clk2x).\n          // The RAM is PSN slices of PSW bits, each one block RAM at RD rows (RAMB36: 32K bits),\n          // each with its own copy of the write stage and its own phase (u_pb): a register drives\n          // one RAM's write pins, not the PSN RAMs Vivado tiles 32 bits into (r22's m8: one pk_a\n          // through the ad_a mux to 8 RAMs spread over 22 RAM rows, clk -> clk2x -0.202 ns)\n          localparam int PSW = (RD >= 32768) ? 1 : (32768 / RD >= 32) ? 32 : 32768 / RD;\n          localparam int PSN = 32 / PSW;\n          logic [PSN-1:0]           pk_v;\n          logic [PSN-1:0][RW-1:0]   pk_a;\n          logic [31:0]              pk_d, pkd;\n          for (genvar z = 0; z < PSN; z++) begin : g_sl\n            (* keep = \"true\" *) logic           sv;\n            (* keep = \"true\" *) logic [RW-1:0]  sa;\n            (* keep = \"true\" *) logic [PSW-1:0] sd;\n            always_ff @(posedge clk) begin\n              sv <= bw_v[b][0] && sub_of(bw_a[b][0]) == LW'(k);\n              sa <= ram_row(bw_a[b][0]);\n              sd <= bw_d[b][0][z*PSW +: PSW];\n            end\n            assign pk_v[z] = sv;\n            assign pk_a[z] = sa;\n            assign pk_d[z*PSW +: PSW] = sd;\n`ifndef SYNTHESIS\n            initial sv = 1'b0;\n`endif\n            otpu_pump_bank #(.N(RD), .W(PSW), .STYLE(\"block\"), .FW(1'b1)) u_pb (\n              .clk, .clk_f, .wv(sv), .wa(sa), .wd(pkd[z*PSW +: PSW]),\n              .rena(s_en[b][k][1]), .ra(s_a[b][k][1]), .renb(s_en[b][k][0]), .rb(s_a[b][k][0]),\n              .qa(s_q[b][k][1][z*PSW +: PSW]), .qb(s_q[b][k][0][z*PSW +: PSW]));\n          end\n`ifdef SYNTHESIS\n          assign pkd = pk_d;\n`else\n          assign pkd = pk_d ^ fault(0, b, pw_a[b][0]);\n          // every slice's copy is the bank's write stage at this RAM\n          always @(posedge clk)\n            for (int z = 0; z < PSN; z++)\n              if (pk_v[z] != wh || (wh && (pk_a[z] != ram_row(pw_a[b][0]) || pk_d != pw_d[b][0])))\n                $fatal(1, \"TMEM%0d: bank %0d RAM %0d slice %0d's write copy differs from the write stage\",\n                       SID, b, k, z);\n`endif\n`ifndef SYNTHESIS\n          // the dump: a shadow of the RAM's words (the same writes), not a reference into u_pb\n          logic [31:0] shd [RD];\n          initial for (int r = 0; r < RD; r++) shd[r] = '0;\n          always @(posedge clk) begin\n            if (dump)\n              for (int r = 0; r < RD; r++) img[row_of(k, r) * LANES + b] = shd[r];\n            if (pk_v[0]) shd[pk_a[0]] <= pkd;\n          end\n`endif\n        end else begin : g_ram\n        (* ram_style = \"block\" *) logic [31:0] mem [RD];\n        if (PMP == 2) begin : g_pm2\n          // the model of PMP 1 at the core clock: the write on a port of its own, both read ports\n          always_ff @(posedge clk) begin\n            if (wh) mem[ram_row(pw_a[b][0])] <= wd;\n            if (s_en[b][k][1]) s_q[b][k][1] <= mem[s_a[b][k][1]];\n          end\n          always_ff @(posedge clk)\n            if (s_en[b][k][0]) s_q[b][k][0] <= mem[s_a[b][k][0]];\n        end else if (TDP) begin : g_tdp\n          // port A: the write, else its side's read; read-first (a replay of the written word\n          // takes the word before the write)\n          wire [RW-1:0] ra = wh ? ram_row(pw_a[b][0]) : s_a[b][k][1];\n`ifdef SYNTHESIS\n          // synthesis: the technology RAM (rtl/tech: inferred alike on an FPGA, the 1RW1R\n          // macros on an ASIC, which leave mem empty); simulation keeps it inferred here (above)\n          otpu_ram_1rw1r #(.W(32), .N(RD), .STYLE(\"block\")) u_ram (\n            .clk, .ena(wh || s_en[b][k][1]), .wea(wh), .aa(ra), .wda(wd), .rda(s_q[b][k][1]),\n            .enb(s_en[b][k][0]), .ab(s_a[b][k][0]), .rdb(s_q[b][k][0]));\n`else\n          always_ff @(posedge clk)\n            if (wh || s_en[b][k][1]) begin\n              if (wh) mem[ra] <= wd;\n              s_q[b][k][1] <= mem[ra];\n            end\n          always_ff @(posedge clk)\n            if (s_en[b][k][0]) s_q[b][k][0] <= mem[s_a[b][k][0]];\n`endif\n        end else begin : g_sdp\n          always_ff @(posedge clk) begin\n            if (wh) mem[ram_row(pw_a[b][0])] <= wd;\n            if (s_en[b][k][0]) s_q[b][k][0] <= mem[s_a[b][k][0]];\n          end\n        end\n`ifndef SYNTHESIS\n        initial for (int r = 0; r < RD; r++) mem[r] = '0;\n        always @(posedge clk)\n          if (dump)\n            for (int r = 0; r < RD; r++) img[row_of(k, r) * LANES + b] = mem[r];\n`endif\n        end\n      end\n    end\n    // each port's data: per bank, the RAM it asked on its side (registered with the read), or the\n    // write still in the registered stage that its word hit (a replay: the RAM's word, see above)\n    for (genvar p = 0; p < NRP; p++) begin : g_pq\n     if (GST && SH_MASK[p]) begin : g_gu\n      assign pq[p] = pq[SH_HOST];\n      assign pr[p] = '0;\n      assign pss[p] = '0;\n      assign pdir[p] = 1'b0;\n     end else begin : g_ho\n      localparam int SD = sd_of(p);\n      logic [LANES-1:0][LW-1:0]  ss;\n      logic [LANES-1:0]          bh;\n      for (genvar b = 0; b < LANES; b++) begin : g_pr\n        for (genvar k = 0; k < NSB; k++) begin : g_k\n          assign pr[p][b * NSB + k] = s_q[b][k][SD];\n        end\n        assign pss[p][b] = PSB'(ss[b]);\n      end\n`ifdef OTPU_TMEM_ABL_DSEL\n      assign pdir[p] = 1'b0;\n`else\n      assign pdir[p] = !BYP;\n`endif\n      always_ff @(posedge clk)\n        for (int b = 0; b < LANES; b++)\n`ifdef OTPU_TMEM_ABL_RPL\n          if (1'b0) begin\n`else\n          if (RPL && rpvb[p][b] && rpe[p][b]) begin\n`endif\n            ss[b] <= sub_of(rpa[p][b]);\n            bh[b] <= 1'b0;\n          end else if (qe[p][b]) begin\n            ss[b] <= sub_of(qa[p][b]);\n            bh[b] <= BYP && pw_v[b][0] && pw_a[b][0] == qa[p][b];\n          end\n      always_comb\n`ifdef OTPU_TMEM_ABL_DSEL\n        for (int b = 0; b < LANES; b++)\n          pq[p][b] = bh[b] ? pd[b][0] : s_q[b][p % NSB][SD] ^ s_q[b][(p + NSB / 2) % NSB][SD];\n`else\n        for (int b = 0; b < LANES; b++) pq[p][b] = bh[b] ? pd[b][0] : s_q[b][ss[b]][SD];\n`endif\n`ifndef SYNTHESIS\n      initial bh = '0;\n`endif\n     end\n    end\n  end else begin : g_nosb\n    assign blk_x = '0;\n    assign blk_s = '0;\n    assign lost = '0;\n    assign frz = '0;\n    assign rpf = '0;\n    for (genvar p = 0; p < NRP; p++) begin : g_npr\n      assign pr[p] = '0;\n    end\n    assign pss = '0;\n    assign pdir = '0;\n  end\n  for (genvar p = 0; p < NRP; p++) begin : g_port\n   if (IMPL != 3 && host_of(p) == p) begin : g_copy\n    logic [LANES-1:0]         b_en;\n    logic [LANES-1:0][IW-1:0] b_a;\n    if (IMPL == 1 && RQ) begin : g_bq\n      // per bank, the asking port on this copy first in priority (ranks are distinct per copy)\n      always_comb begin\n        b_en = '0; b_a = '0;\n        for (int b = 0; b < LANES; b++)\n          for (int r = NRP - 1; r >= 0; r--)\n            for (int g = 0; g < NRP; g++)\n              if (CPY[g] == CPY[p] && int'(PRANK[g]) == r && pb_en[g][b]) begin\n                b_en[b] = 1'b1;\n                b_a[b] = pb_a[g][b];\n              end\n      end\n    end else if (IMPL == 1) begin : g_bk\n      always_comb begin\n        b_en = '0; b_a = '0;\n        for (int g = 0; g < NRP; g++)\n          if (CPY[g] == CPY[p])\n            for (int b = 0; b < LANES; b++)\n              if (pb_en[g][b]) begin\n                b_en[b] = 1'b1;\n                b_a[b] = b_a[b] | pb_a[g][b];\n              end\n      end\n    end else if (p == SH_HOST && SH_MASK != '0) begin : g_sh\n      always_comb begin\n        logic take;\n        b_en = pb_en[p]; b_a = pb_a[p];\n        take = |r_req[p];\n        for (int g = 0; g < NRP; g++)\n          if (SH_MASK[g] && !take && |r_req[g]) begin\n            b_en = pb_en[g]; b_a = pb_a[g]; take = 1'b1;\n          end\n      end\n    end else begin : g_own\n      assign b_en = pb_en[p];\n      assign b_a = pb_a[p];\n    end\n    logic [LANES-1:0][31:0]    q, qb;\n    logic [LANES-1:0][WPB-1:0] bh;      // the read hit these writes, still registered\n    for (genvar b = 0; b < LANES; b++) begin : g_bank\n      logic [31:0] mem [BD];               // IMPL 0's (IMPL 1: unused, the RAM cell holds them)\n      if (IMPL == 1) begin : g_ram\n        logic [31:0] wd;\n`ifdef SYNTHESIS\n        assign wd = pw_d[b][0];\n`else\n        assign wd = pw_d[b][0] ^ fault(p, b, pw_a[b][0]);\n`endif\n        otpu_ram_1r1w #(.W(32), .N(BD), .STYLE(\"block\")) u_ram (\n          .clk, .we(pw_v[b][0]), .wa(pw_a[b][0]), .wd, .re(b_en[b]), .ra(b_a[b]), .rd(q[b]));\n      end else begin : g_inf\n        always_ff @(posedge clk) begin\n          if (b_en[b]) q[b] <= mem[b_a[b]];\n          for (int w = 0; w < WPB; w++)\n`ifdef SYNTHESIS\n            if (pw_v[b][w]) mem[pw_a[b][w]] <= pw_d[b][w];\n`else\n            if (pw_v[b][w]) mem[pw_a[b][w]] <= pw_d[b][w] ^ fault(p, b, pw_a[b][w]);\n`endif\n        end\n      end\n      always_ff @(posedge clk)\n        if (b_en[b])\n          for (int w = 0; w < WPB; w++) bh[b][w] <= pw_v[b][w] && pw_a[b][w] == b_a[b];\n      // the last hit wins, as in the write loop\n      always_comb begin\n        qb[b] = q[b];\n        for (int w = 0; w < WPB; w++) if (bh[b][w]) qb[b] = pd[b][w];\n      end\n`ifndef SYNTHESIS\n      initial for (int i = 0; i < BD; i++) mem[i] = '0;\n      initial bh[b] = '0;\n      // the dump: DP's words, then the others against them\n      if (IMPL == 1) begin : g_dump1\n        always @(posedge clk) begin\n          if (dump && p == DP)\n            for (int r = 0; r < BD; r++) img[r * LANES + b] = g_ram.u_ram.g_bram.mem[r];\n          if (dump_q && p != DP)\n            for (int r = 0; r < BD; r++)\n              if (g_ram.u_ram.g_bram.mem[r] != img[r * LANES + b])\n                $fatal(1, \"TMEM%0d: copy %0d's word %0d is %h, copy %0d's %h\", SID, p,\n                       r * LANES + b, g_ram.u_ram.g_bram.mem[r], DP, img[r * LANES + b]);\n        end\n      end else begin : g_dump0\n        always @(posedge clk) begin\n          if (dump && p == DP)\n            for (int r = 0; r < BD; r++) img[r * LANES + b] = mem[r];\n          if (dump_q && p != DP)\n            for (int r = 0; r < BD; r++)\n              if (mem[r] != img[r * LANES + b])\n                $fatal(1, \"TMEM%0d: copy %0d's word %0d is %h, copy %0d's %h\", SID, p,\n                       r * LANES + b, mem[r], DP, img[r * LANES + b]);\n        end\n      end\n`endif\n    end\n    assign pq[p] = qb;\n   end else if (IMPL != 3) begin : g_guest\n    assign pq[p] = pq[host_of(p)];\n   end\n    wire  [BW-1:0]            rot = r_addr[p][0][BW-1:0];\n    wire  [LANES-1:0][31:0]   qb = pq[p];\n    // lane data: the bank it read (the crossbar: each lane's bank; a rotator: the run's\n    // rotation), fresh the cycle after the read, then held. A rotator keeps the rotation once\n    // per lane (rot_q[l], all loaded with the run's): lane l takes bank (l + rot_q[l]) mod LANES,\n    // so each copy drives one lane's select and hold, not every lane's (133.33 MHz, 110ec6d /\n    // 812bb01: g_port[6].rot_q[2] -> 1 LUT -> held, fanout 513, 6.8 ns of route, +0.152 ns)\n    logic [LANES-1:0][BW-1:0] sel;\n    logic [LANES-1:0][BW-1:0] rq;         // a rotator's rotation, per lane\n    logic [LANES-1:0]         fresh;\n    logic [LANES-1:0][31:0]   held, lq;\n    if (GEN_R[p]) begin : g_xb\n      assign rq = '0;\n    end else begin : g_rot\n      (* keep *) logic [LANES-1:0][BW-1:0] rot_q;\n      always_ff @(posedge clk)\n        for (int l = 0; l < LANES; l++) if (|r_en[p]) rot_q[l] <= rot;\n      assign rq = rot_q;\n`ifndef SYNTHESIS\n      // the lanes' copies are one rotation (the run's), from the first read on\n      bit ld;\n      initial ld = 1'b0;\n      always @(posedge clk) begin\n        if (|r_en[p]) ld <= 1'b1;\n        for (int l = 1; l < LANES; l++)\n          if (ld && rot_q[l] != rot_q[0])\n            $fatal(1, \"otpu_tmem: port %0d lane %0d's rotation %0d is not lane 0's %0d\", p, l,\n                   rot_q[l], rot_q[0]);\n      end\n`endif\n    end\n    always_ff @(posedge clk)\n      for (int l = 0; l < LANES; l++) begin\n        fresh[l] <= r_en[p][l] | rpf[p][l];   // (rpf: IMPL 3 RPL's replays)\n        if (GEN_R[p] && r_en[p][l]) sel[l] <= r_addr[p][l][BW-1:0];\n        if (fresh[l]) held[l] <= lq[l];\n      end\n    logic [LANES-1:0][BW-1:0] bk;          // the lane's bank\n    always_comb\n      for (int l = 0; l < LANES; l++) begin\n        bk[l] = GEN_R[p] ? sel[l] : BW'((l + int'(rq[l])) % LANES);\n        // pdir: the word by {bank, the bank's RAM}, both from flip-flops (pq's select in the index)\n        lq[l] = pdir[p] ? pr[p][int'(bk[l]) * NSB + int'(pss[p][bk[l]])] : qb[bk[l]];\n        r_data[p][l] = fresh[l] ? lq[l] : held[l];\n      end\n`ifndef SYNTHESIS\n    // the select by {bank, RAM} is the bank's word (pq), lane by lane\n    always @(posedge clk)\n      for (int l = 0; l < LANES; l++)\n        if (pdir[p] && fresh[l] && lq[l] !== qb[bk[l]])\n          $fatal(1, \"TMEM%0d: port %0d lane %0d's word %h is not bank %0d's %h\", SID, p, l, lq[l],\n                 bk[l], qb[bk[l]]);\n`endif\n  end\n\n`ifndef SYNTHESIS\n  function automatic bit conflict(input logic [LANES-1:0] en, input logic [LANES-1:0][31:0] a,\n                                  input bit is_write);\n    for (int i = 0; i < LANES; i++)\n      for (int j = i + 1; j < LANES; j++)\n        if (en[i] && en[j] && (a[i] % LANES) == (a[j] % LANES) && (is_write || a[i] != a[j]))\n          return 1;\n    return 0;\n  endfunction\n  function automatic bit contiguous(input logic [LANES-1:0] en, input logic [LANES-1:0][31:0] a);\n    for (int l = 0; l < LANES; l++)\n      if (en[l] && a[l] != a[0] + 32'(l)) return 0;\n    return 1;\n  endfunction\n  always @(posedge clk) begin\n    for (int p = 0; p < NRP; p++)\n      if (IMPL == 0 && SH_MASK[p] && |r_en[p]) begin\n        if (|r_req[SH_HOST]) $fatal(1, \"TMEM%0d: guest port %0d read beside its host at %0t\", SID, p, $time);\n        for (int g = 0; g < p; g++)\n          if (SH_MASK[g] && |r_req[g]) $fatal(1, \"TMEM%0d: guest port %0d read beside port %0d at %0t\", SID, p, g, $time);\n      end\n    for (int p = 0; p < NRP; p++)\n      if (conflict(r_en[p], r_addr[p], 0)) $fatal(1, \"TMEM%0d read port %0d bank conflict at %0t\", SID, p, $time);\n    for (int p = 0; p < NWP; p++)\n      if (conflict(w_en[p], w_addr[p], 1)) $fatal(1, \"TMEM%0d write port %0d bank conflict at %0t\", SID, p, $time);\n    for (int b = 0; b < LANES; b++) begin\n      int n;\n      n = 0;\n      for (int p = 0; p < NWP; p++)\n        for (int i = 0; i < LANES; i++)\n          if (w_en[p][i] && w_addr[p][i] % LANES == b) n++;\n      if (n > WPB) $fatal(1, \"TMEM%0d: %0d writes to bank %0d at %0t\", SID, n, b, $time);\n    end\n    for (int p = 0; p < NRP; p++)\n      if (!GEN_R[p] && !contiguous(r_req[p], r_addr[p]))\n        $fatal(1, \"TMEM%0d read port %0d: lanes not contiguous at %0t\", SID, p, $time);\n    for (int p = 0; p < NWP; p++)\n      if (WPB == 1 && !GEN_W[p] && !contiguous(w_req[p], w_addr[p]))\n        $fatal(1, \"TMEM%0d write port %0d: lanes not contiguous at %0t\", SID, p, $time);\n    for (int p = 0; p < NRP; p++)\n      for (int l = 0; l < LANES; l++)\n        if (r_en[p][l] && r_addr[p][l] >= WORDS) $fatal(1, \"TMEM%0d read beyond %0d words\", SID, WORDS);\n    for (int p = 0; p < NWP; p++)\n      for (int l = 0; l < LANES; l++)\n        if (w_en[p][l] && w_addr[p][l] >= WORDS) $fatal(1, \"TMEM%0d write beyond %0d words\", SID, WORDS);\n  end\n  string dir;\n  initial void'($value$plusargs(\"dir=%s\", dir));\n  always @(posedge clk) if (dump_q) begin\n    int fd;\n    fd = $fopen($sformatf(\"%s/tmem_%0d.hex\", dir, SID), \"w\");\n    for (int i = 0; i < WORDS; i++) $fwrite(fd, \"%08x\\n\", img[i]);\n    $fclose(fd);\n  end\n`endif\nendmodule\n\n// One bank of a pumped copy: a true dual-port RAM on clk_f (= 2 x clk, aligned). Even fast edges\n// (the core edges): port A reads ra (rena), port B reads rb (renb). Odd fast edges (mid core\n// cycle): port A writes wd at wa (wv), its output held (NO_CHANGE). qa / qb change only after even\n// edges and hold through the next core cycle. Its hierarchy is kept: the timing contract names its\n// read inputs and its outputs (boards/ypcb-00338/constraints/otpu_clk2x.tcl, both boards' and the\n// out-of-context runs' with the one copy; rtl/exp/tmem_pump/ooc.tcl's for P3). Here since the one\n// copy (otpu_tmem IMPL 3 PMP 1) builds it; P3 (rtl/exp/tmem_pump) too.\n(* keep_hierarchy = \"yes\" *)\nmodule otpu_pump_bank #(\n  parameter int    N     = 8192,\n  parameter int    W     = 32,       // the word's bits (otpu_tmem: a slice of the 32, one RAM)\n  parameter string STYLE = \"block\",\n  parameter bit    FW    = 1'b1      // the phase from a fast-domain register (below)\n) (\n  input  logic                 clk,\n  input  logic                 clk_f,\n  input  logic                 wv,\n  input  logic [$clog2(N)-1:0] wa,\n  input  logic [W-1:0]         wd,\n  input  logic                 rena,\n  input  logic [$clog2(N)-1:0] ra,\n  input  logic                 renb,\n  input  logic [$clog2(N)-1:0] rb,\n  output logic [W-1:0]         qa,\n  output logic [W-1:0]         qb\n);\n  // the phase: tog flips at every core edge; tq is its copy a fast edge later. They differ during\n  // a core cycle's first half (the next fast edge is odd) and agree in its second (even next).\n  // FW: ev is a fast-domain register loaded with that at every fast edge (the edge after next's\n  // parity is the opposite of the next's), so no core-domain net reaches the RAM's enables; it\n  // aligns itself at the first fast edge, as tq does.\n  (* keep *) logic tog;\n  (* keep *) logic tq;\n  logic evr;\n  always_ff @(posedge clk) tog <= !tog;\n  always_ff @(posedge clk_f) begin\n    tq <= tog;\n    evr <= tq != tog;\n  end\n  wire ev = FW ? evr : (tq == tog);\n`ifndef SYNTHESIS\n  initial begin tog = 1'b0; tq = 1'b0; evr = 1'b1; end\n`endif\n  wire                 en_a = ev ? rena : wv;\n  wire                 we_a = !ev && wv;\n  wire [$clog2(N)-1:0] ad_a = ev ? ra : wa;\n  wire                 en_b = ev && renb;\n  if (STYLE == \"ultra\") begin : g_u\n    (* ram_style = \"ultra\" *) logic [W-1:0] mem [N];\n    always_ff @(posedge clk_f)\n      if (en_a) begin\n        if (we_a) mem[ad_a] <= wd;\n        else qa <= mem[ad_a];\n      end\n    always_ff @(posedge clk_f)\n      if (en_b) qb <= mem[rb];\n`ifndef SYNTHESIS\n    initial for (int i = 0; i < N; i++) mem[i] = '0;\n`endif\n  end else begin : g_b\n    (* ram_style = \"block\" *) logic [W-1:0] mem [N];\n    always_ff @(posedge clk_f)\n      if (en_a) begin\n        if (we_a) mem[ad_a] <= wd;\n        else qa <= mem[ad_a];\n      end\n    always_ff @(posedge clk_f)\n      if (en_b) qb <= mem[rb];\n`ifndef SYNTHESIS\n    initial for (int i = 0; i < N; i++) mem[i] = '0;\n`endif\n  end\nendmodule\n", "rtl/mxu/otpu_mxu.sv": "// MXU, the MX column (docs/isa.md MM, docs/mx_mxu.md): streams N rows x KB blocks of weights from\n// DRAM (port B, one D-byte chunk per cycle, prefetched through a FIFO) and their scale rows (port\n// A, 32-byte lines), and reuses each chunk across up to MCOLS stationary rows held in ACT RAM. Each\n// output is one exact integer, accumulated in its column end over the whole row:\n//   c   = sum_{i in g} act[j][i] * w[i]              group g: D/8 elements, a chain of the array\n//   sh  = W - dw(n, k, g) - da[j][k][g/2]            W 16 (int8x), 11 (int4x, fp4x6), 13 (nvfp4)\n//   acc = sum_k sum_g (sh >= 0 ? m(n, k, g) << sh : 0) * c                 48 bits, exact\n// and one fp32 epilogue per output, in E lanes the columns share (the result FIFO between them):\n//   y   = (i2f(acc) * Sw[n]) * (Sa[j] * 2^-W)          then ACC / ASCALE / RMAX as before\n// 4-bit weights (flags[5:4] = WF: 1 int4, 2 E2M1, 3 NVFP4): a D-byte chunk holds two blocks (the\n// low half first) and is consumed in two advances. PAIR (flags[6], 4-bit, 2M <= MCOLS; \"Column\n// reuse\"): a chunk is consumed in one advance, columns j < M take its low block 2c (ACT block\n// ab+2c), columns j+M its high block 2c+1 (ACT block ab+2c+1); the two columns accumulate\n// separately and their integers are added before the result FIFO (+0 for the missing block of an\n// odd KB: its multipliers are 0). RSC (flags[7]): each scale row is Sw alone. UNIT: Sw 1, dw 0, m 1.\n//\n// The array is the systolic one (docs/mxu_systolic.md): chains of CLS = min(CL, D/8) products\n// (DSP48 cascades), so that every chain end is one group. A column end (otpu_mxce, rtl/tech) takes\n// the column's eight group sums, multiplies each by its B = m << sh (the shift in fabric, two\n// cycles ahead), sums them down a cascade and accumulates the row in a ninth DSP. The columns are\n// skewed by a cycle each; their row sums are deskewed and registered, PAIR's halves added, and the\n// row (MCOLS integers, the rows' Sa * 2^-W and Sw) written to the result FIFO. The drain picks up\n// to E results of the head row a cycle (fewer at a TMEM bank conflict) into the lanes: i2f48 (round\n// to nearest even), the two multiplies, then the TMEM write or the read-modify-write (ACC, ASCALE)\n// as before; everything after the result FIFO advances only while the TMEM grant is given.\n//\n// The scale reader: for every advance the issuer asks port A for the 32-byte line that holds the\n// advance's block data (int8x: one byte; int4x / fp4x6: a word, PAIR two; NVFP4: eight bytes,\n// PAIR sixteen; RSC: Sw), and for a row's Sw: in the same line when Sw is in the line of the row's\n// first advance or of the previous row's last one, else in a request of its own (a cycle without\n// a chunk). A tag per request says what the line holds; the responses fill one scale entry per\n// chunk ({Sw, the low block's data}, {the high block's data}) in the scale FIFO.\n//\n// Replay (ROWS > MCOLS, M > MCOLS): each streamed row is consumed G = ceil(M / MCOLS) times, once\n// per group of MCOLS stationary rows (ACT RAM rows g*MCOLS ..). Group 0 pops the row's chunks from\n// the FIFO without freeing them, the later groups read the same FIFO entries again (head + k) and\n// the last group frees them, so a weight is streamed from DRAM once for all M rows (a row must fit\n// the FIFO: KB <= DEPTH). Each (row, group) is a row of the pipeline and the drain; the drain steps\n// its TMEM addresses by MCOLS * ors per group.\n//\n// The MXU holds two commands: the issuer streams the newer one's chunks while the consumer\n// finishes (and drains) the older one. The issuer yields DRAM ports to the DMA and QST\n// (a_gnt/b_gnt). A row's first advance pops only once all of the row's chunks and scales are in\n// the FIFOs, so a row never stalls in its middle and the array needs no clock enable.\nmodule otpu_mxu\n  import otpu_pkg::*;\n  import otpu_fp::*;\n#(\n  parameter int D     = 32,\n  parameter int MCOLS = 8,\n  parameter int ROWS  = MCOLS,   // ACT RAM rows: the most stationary rows of a command\n  parameter int DEPTH = 16,\n  parameter int LANES = 8,       // TMEM banks (the drain's lanes write distinct banks)\n  parameter int TLANES = LANES,  // TMEM's banks (t_rben; its lanes, at least LANES)\n  parameter int IMPL  = 2,       // the dot product: 2 systolic (the only one; CFG_UARCH reports it)\n  parameter int CL    = 16,      // products per cascade chain (at most D/8)\n  parameter int E     = 0,       // epilogue lanes (0: MCOLS / 2, at least 1; more than MCOLS: MCOLS)\n  parameter bit TQ    = 1'b0,    // reads not granted (TMEM replays them), writes through a queue,\n                                 //   the epilogue's advance from flip-flops (the slice: TMEM_IMPL 3 RPL)\n  parameter int SID   = 0\n) (\n  input  logic                  clk,\n  input  logic                  rst,\n  input  logic                  start,       // accept: the issuer may stream it\n  input  logic                  go,          // release: the consumer may use it (in order)\n  input  cmd_t                  cmd,\n  output logic                  rdy,\n  output logic                  done,\n  output logic                  computing,   // a chunk is consumed this cycle (profiling)\n  // profiling: this cycle's stream state (the FIFO level; work but no chunk / chunks but no\n  // consumption) and, a cycle after a command ends, its counters {deny, frz, bp, starve}\n  output logic [$clog2(DEPTH):0] pf_level,\n  output logic                  pf_starve,\n  output logic                  pf_block,\n  output logic                  pf_u,\n  output logic [3:0][31:0]      pf_uv,\n  // ACT RAM read\n  output logic [15:0]           act_blk,\n  output logic [15:0]           act_blk2,    // PAIR: the odd block, read by the rows in act_hi\n  output logic [MCOLS-1:0]      act_hi,\n  output logic [7:0]            act_grp,\n  output logic [MCOLS-1:0]      act_ren,     // per column: its ACT RAM read register advances\n  input  logic [MCOLS*D*8-1:0]  act_data,\n  input  logic [MCOLS*64-1:0]   act_scale,   // per column the record {da3, da2, da1, da0, Sa}\n  // DRAM port A (scale lines) and B (chunks)\n  output logic                  a_req,\n  output logic [31:0]           a_addr,\n  input  logic                  a_gnt,\n  input  logic                  a_rvalid,\n  input  logic [255:0]          a_rdata,     // the aligned 32 bytes holding word a_addr\n  output logic                  b_req,\n  output logic [31:0]           b_addr,\n  input  logic                  b_gnt,\n  input  logic                  b_rvalid,\n  input  logic [D*8-1:0]        b_rdata,\n  // TMEM (read port for ACC, write port)\n  output logic [LANES-1:0]        t_ren,\n  output logic [LANES-1:0][31:0]  t_raddr,\n  input  logic [LANES-1:0][31:0]  t_rdata,\n  output logic [LANES-1:0]        t_wen,\n  output logic [LANES-1:0][31:0]  t_waddr,\n  output logic [LANES-1:0][31:0]  t_wdata,\n  input  logic                    t_gnt,\n  input  logic                    t_lost,     // TQ: this cycle's read (or its replay) lost (replayed)\n  // the read by TMEM bank (TLANES banks): bank b's enable and the address of the lane reading it\n  // (t_ren / t_raddr's lanes merged per bank, as otpu_tmem's crossbar does; TQ: registers)\n  output logic [TLANES-1:0]       t_rben,\n  output logic [TLANES-1:0][31:0] t_rbad\n);\n  localparam int BW = $clog2(LANES);\n  localparam int PW = $clog2(DEPTH);\n  localparam int LM = 2, LA = 4;\n  // epilogue lanes; NL: the drain's lanes per step\n  // (a target's E holds at a smaller MCOLS too: the card's 4 is 2 at MCOLS 2)\n  localparam int EL = (E > MCOLS) ? MCOLS : (E > 0) ? E : ((MCOLS >= 2) ? MCOLS / 2 : 1);\n  localparam int NL = EL;\n  // chains of CLS products, CPG of them per group of D/8 elements (1, or 2 above D = 128)\n  localparam int CLS = (D / 8 < CL) ? D / 8 : CL;\n  localparam int CPG = D / 8 / CLS;\n  // S0 to the columns' row sums, deskewed (the column end's accumulator is valid CLS + 6 + j\n  // edges after S0, column j deskewed by MCOLS - 1 - j)\n  localparam int LROW = CLS + MCOLS + 5;\n  // result FIFO rows: a row pops only while fewer than RF are between the pop and the drain, so\n  // RF covers the pipeline's rows in flight (one-advance rows: one per cycle of its latency)\n  localparam int RF = (LROW + 7 <= 32) ? 32 : 64;\n  localparam int RFW = $clog2(RF);\n  localparam int MW = $clog2(MCOLS) + 1;\n  localparam int TD = 128;                  // port A requests in flight (their tags)\n  localparam int TDW = $clog2(TD);\n  // a lane: the pick, i2f48 (4), x Sw, x Sa'\n  localparam int LLAT = 1 + 4 + 2 * LM;\n  initial if (IMPL != 2) $fatal(1, \"otpu_mxu: IMPL 2 (systolic) is the only dot product\");\n  initial if (D % 16 != 0 || (D / 8) % CLS != 0 || CPG > 2)\n    $fatal(1, \"otpu_mxu: D a multiple of 16, D/8 a multiple of CLS, at most two chains a group\");\n  initial if (EL > LANES) $fatal(1, \"otpu_mxu: E %0d > LANES\", EL);\n  initial if (ROWS < MCOLS || ROWS > 255) $fatal(1, \"otpu_mxu: MCOLS <= ROWS < 256\");\n\n  // conflict-free drain run for a row stride: LANES / gcd(ors, LANES), at most NL\n  function automatic logic [MW-1:0] drain_run(input logic [15:0] ors);\n    int d;\n    d = 1;                                   // ors a multiple of LANES: one lane per cycle\n    for (int t = BW - 1; t >= 0; t--)        // the lowest set bit t: gcd = 2^t\n      if (ors[t]) d = LANES >> t;\n    return MW'((d < NL) ? d : NL);\n  endfunction\n  localparam logic [1:0] WF_W8 = 2'd0, WF_NV = 2'd3;\n`ifndef SYNTHESIS\n  // a replayed row (M > MCOLS) must fit the FIFO: its chunks (4-bit: two blocks each)\n  always @(posedge clk) if (!rst && start) begin\n    if (int'(cmd.w6[23:16]) > ROWS) $fatal(1, \"otpu_mxu: M %0d > ROWS %0d\", cmd.w6[23:16], ROWS);\n    if (int'(cmd.w6[23:16]) > MCOLS && ((cmd.flags[5:4] != WF_W8) ?\n        (int'(cmd.w4[23:16]) + 1) / 2 : int'(cmd.w4[23:16])) > DEPTH)\n      $fatal(1, \"otpu_mxu: a replayed row (M > MCOLS) must fit the FIFO: KB %0d, DEPTH %0d\",\n             cmd.w4[23:16], DEPTH);\n    if (cmd.flags[6] && cmd.flags[5:4] != WF_W8 && 2 * int'(cmd.w6[23:16]) > MCOLS)\n      $fatal(1, \"otpu_mxu: PAIR needs 2*M <= MCOLS\");\n  end\n`endif\n\n  // ================================================================== issuer\n  logic        i_act, i_unit, i_w4, i_pair, i_rsc;\n  logic        i_ini;                       // the command's first cycle: its addresses load\n  logic [1:0]  i_wf;\n  logic [7:0]  i_k0;\n  logic [31:0] i_left, i_rs, i_srs;\n  logic [15:0] i_KB, i_k;\n  logic        i_klast, i_l1;               // i_k + 1 == i_KB; i_left == 1\n  logic [31:0] row_addr, chunk_addr;\n  logic [31:0] srow_addr, srow_next;        // the row's scale row; the next row's\n  logic [31:0] scale_addr;                  // the advance's block data in the scale row\n  logic [31:0] i_soff;                      // block k0's data offset in a scale row\n  logic [4:0]  i_sstep;                     // the data address step per advance\n  logic        i_swd;                       // the row's Sw came with an earlier line\n  logic        i_swh;                       // the row's Sw is in the line of its first advance\n  logic        i_swn;                       // the next row's Sw is in the advance's line\n  logic        i_sws;                       // a request for the row's Sw alone comes first\n  logic [PW:0] occ;                         // chunks issued and not yet popped (<= DEPTH)\n  logic [TDW:0] tg_n;                       // port A requests in flight\n\n  // ================================================================== command queue (2)\n  // PAIR: 4-bit only; a row is ceil(KB/2) advances of one chunk each. KB is 8 bits, k0 above it\n  wire        cmd_pair = cmd.flags[6] && cmd.flags[5:4] != WF_W8;\n  wire [7:0]  cmd_KB8 = cmd.w4[23:16];\n  wire [15:0] cmd_KBa = cmd_pair ? (16'(cmd_KB8) + 16'd1) >> 1 : 16'(cmd_KB8);\n  wire [31:0] cmd_total = 32'(cmd.w4[15:0]) * 32'(cmd_KBa);   // advances (chunk requests)\n  // cmd_total == 0 without the multiply (a product of two factors is zero iff one is)\n  wire        cmd_tz = (cmd.w4[15:0] == 16'd0) || (cmd_KB8 == 8'd0);\n`ifndef SYNTHESIS\n  always @(posedge clk)\n    if (!rst && start && cmd_tz != (cmd_total == 0))\n      $fatal(1, \"otpu_mxu: cmd_tz %0d but total %0d\", cmd_tz, cmd_total);\n`endif\n  // The two entries are the head (h) and the next command (n), not two slots and a head pointer:\n  // every head field is its own flop, with no 2:1 mux on a pointer in front of the consumer and\n  // the drain. Completing the head swaps them (n keeps the old head, as the idle slot did).\n  typedef struct packed {\n    logic [31:0]      out, total;\n    logic             tz;              // total == 0 (registered: off the drain path)\n    logic [15:0]      KB, KBa;         // KBa: advances per row\n    logic [15:0]      KBm1;            // KBa - 1: the last advance's ck (last_k a compare, no adder)\n    logic             pair;\n    logic [MCOLS-1:0] hi;              // PAIR: the columns that take the odd blocks (j >= M)\n    logic [31:0]      mxo;             // RMAX output base: out + M * ors (no multiply later)\n    logic [7:0]       M, ab;\n    logic [MW-1:0]    run;             // drain lanes per cycle without a bank conflict\n    logic             unit, acc, rmax, asc, go, rsc;\n    logic [1:0]       wf;\n    logic [31:0]      asa;\n    logic [MCOLS-1:0][31:0] jo;        // j * ors\n    logic [7:0]       G;               // groups: ceil(M / MCOLS)\n    logic [MW-1:0]    Ml;              // rows of the last group\n    logic [31:0]      gs;              // drain address step to the next group (MCOLS * ors)\n    logic             g1;              // G == 1: a row's first group is its last\n    logic [MW-1:0]    dnl;             // the last group's first drain step: its lanes (min(run,\n    logic             dfl;             // Ml)) and whether it drains the group (Ml <= run)\n    logic [MCOLS-1:0] cm;              // the columns its advances read (act_ren)\n  } qent_t;\n  qent_t       h, n;                    // the head, the next command\n  qent_t       cmd_e;                   // cmd as an entry (not yet released)\n  logic [1:0]  q_n;\n\n  always_comb begin\n    int g;\n    cmd_e = '0;\n    cmd_e.out   = cmd.w3;\n    cmd_e.total = cmd_total;\n    cmd_e.tz    = cmd_tz;\n    cmd_e.KB    = 16'(cmd_KB8);\n    cmd_e.KBa   = cmd_KBa;\n    cmd_e.KBm1  = cmd_KBa - 16'd1;\n    cmd_e.pair  = cmd_pair;\n    for (int j = 0; j < MCOLS; j++) cmd_e.hi[j] = cmd_pair && 32'(j) >= 32'(cmd.w6[23:16]);\n    cmd_e.mxo   = cmd.w3 + 32'(cmd.w6[23:16]) * 32'(cmd.w6[15:0]);\n    cmd_e.M     = cmd.w6[23:16];\n    cmd_e.run   = drain_run(cmd.w6[15:0]);\n    cmd_e.ab    = cmd.w6[31:24];\n    cmd_e.unit  = cmd.flags[0];\n    cmd_e.rsc   = cmd.flags[7] && !cmd.flags[0];\n    cmd_e.wf    = cmd.flags[5:4];\n    cmd_e.acc   = cmd.flags[1];\n    cmd_e.rmax  = cmd.flags[2];\n    cmd_e.asc   = cmd.flags[3];\n    cmd_e.go    = 1'b0;\n    cmd_e.asa   = cmd.w2;\n    for (int j = 0; j < MCOLS; j++) cmd_e.jo[j] = 32'(j) * 32'(cmd.w6[15:0]);\n    g = (int'(cmd.w6[23:16]) + MCOLS - 1) / MCOLS;\n    if (g < 1) g = 1;\n    cmd_e.G     = 8'(g);\n    cmd_e.Ml    = MW'(int'(cmd.w6[23:16]) - (g - 1) * MCOLS);\n    cmd_e.gs    = 32'(MCOLS) * 32'(cmd.w6[15:0]);\n    cmd_e.g1    = (g == 1);\n    cmd_e.dnl   = (cmd_e.run < cmd_e.Ml) ? cmd_e.run : cmd_e.Ml;\n    cmd_e.dfl   = (cmd_e.Ml <= cmd_e.run);\n    // the ACT RAM columns its advances read: every column with replay (G > 1), else rows j < M\n    // (PAIR: and the high rows j < 2M); the others are no output's\n    for (int j = 0; j < MCOLS; j++)\n      cmd_e.cm[j] = (g > 1) || 32'(j) < (cmd_pair ? 32'd2 : 32'd1) * 32'(cmd.w6[23:16]);\n  end\n\n  // Two heads (docs/mxu_systolic.md): the drain's head is h, the oldest command: its results are\n  // drained, its completion signalled. The pop head is h, or n once the head's chunks have all\n  // popped (pn), if the pipeline treats n alike (the same PAIR and M, the per-command state read\n  // after S0): the next command's rows then enter the pipeline behind the head's instead of after\n  // its drain. pop_q is the pop head's entry, a register loaded with h and n (pn ? n : h), so\n  // neither the pop nor the drain reads its command through a mux.\n  logic        pn;\n  qent_t       pop_q, pop_e;\n  assign pop_e = pop_q;\n\n  wire [31:0] c_out = h.out;\n  wire        c_tz = h.tz;\n  // the pop head's (c_KB .. c_wf, p_*) and the drain head's (the rest)\n  wire [15:0] c_KB = pop_e.KB, c_KBa = pop_e.KBa;\n  wire        c_pair = pop_e.pair;\n  wire [MCOLS-1:0] c_hi = pop_e.hi;\n  wire [7:0]  c_M = h.M, c_ab = pop_e.ab;\n  wire [7:0]  p_M = pop_e.M, p_G = pop_e.G;\n  wire        p_act = (q_n != 0) && pop_e.go;\n  wire [MW-1:0] c_run = h.run;\n  wire        c_unit = pop_e.unit, c_rsc = pop_e.rsc, c_acc = h.acc, c_rmax = h.rmax;\n  wire        c_asc = h.asc;\n  wire [1:0]  c_wf = pop_e.wf;\n  wire        c_w4 = (c_wf != WF_W8);\n  wire [31:0] c_asa = h.asa;\n  wire        c_act = (q_n != 0) && h.go;\n  wire [7:0]  c_G = h.G;\n  logic [31:0] alpha [MCOLS];\n  logic [1:0]  al_st;                       // ASCALE factors: 0 to load, 1 requested (in TMEM's\n                                            // request register), 3 read (the words arrive), 2 loaded\n  logic [7:0]  al_i, mx_i;                  // next ASCALE factor to load / RMAX value to write\n\n  // FIFOs of chunks and of their scale entries (one per chunk; the two DRAM ports return\n  // independently, in order; an issued chunk's slot is reserved, so neither FIFO can overflow)\n  // block RAM: written in their own reset-free process below. The chunk FIFO is its own module\n  // (kept as a hierarchy): inline, Vivado absorbed its read register into the DSP input\n  // registers of the products, which left an asynchronous read.\n  logic [PW-1:0]  f_head, f_tail;\n  logic [PW-1:0]  s_head, s_tail;\n  logic [PW:0]    f_count, s_count;\n  // FIFO read addresses, kept equal to (last group ? head : head + entry k of the row) by the\n  // pops: a register, so no adder sits in front of the block RAM address\n  logic [PW-1:0]  f_rd, s_rd;\n  // The chunk FIFO is FG block RAM column groups (whole 36-bit BRAM columns each), each with its\n  // own copies of the write and read addresses (f_tl, f_rdl: f_tail's and f_rd's updates): one\n  // register no longer drives every block RAM of the chunk across its span. f_tail and f_rd remain\n  // for the checks.\n  localparam int FW = D * 8;\n  localparam int FC = (FW + 35) / 36;       // 36-bit block RAM columns\n  localparam int FG = (FC < 4) ? FC : 4;\n  function automatic int fg_lo(input int g);\n    int c;\n    c = 0;\n    for (int i = 0; i < g; i++) c = c + FC / FG + ((i < FC % FG) ? 1 : 0);\n    return (36 * c < FW) ? 36 * c : FW;\n  endfunction\n  (* keep *) logic [FG-1:0][PW-1:0] f_tl, f_rdl;\n\n  // ================================================================== consumer control\n  logic [15:0] ck;\n  logic [7:0]  cg;                          // the group of the row being consumed (replay)\n  logic [31:0] c_left;                      // chunks of the pop head not yet freed\n  // c_left == 0, a flip-flop loaded with c_left (an entry's tz, or c_left == 1 at its decrement):\n  // the drain's test (c_drained -> c_done -> the drain lanes' address enables) and the pop's\n  // (more) start at it, not at a 32-bit compare of c_left (fanout 136; the m8 card at 150 MHz:\n  // c_left -> c_drained -> dal's enables, 8 levels, 5.7 ns of route, -0.080 ns)\n  logic        c_lz;\n  // a command accepted last cycle became the head: c_left takes its total now, from h (a flop),\n  // not from cmd_total in the start cycle. It cannot pop yet (released a cycle after its start at\n  // the earliest), and nothing may treat the stale c_left == 0 as drained meanwhile\n  logic        cl_ld;\n  logic [RFW:0] rows_live;                  // the head's rows popped (first block), not drained\n  logic [RFW:0] rows_p;                     // the pop head's, while it is not the head\n  wire last_k   = (ck == pop_e.KBm1);         // (ck + 1 == c_KBa)\n`ifndef SYNTHESIS\n  always @(posedge clk) if (!rst && p_act && last_k != (32'(ck) + 1 == 32'(c_KBa)))\n    $fatal(1, \"otpu_mxu: last_k %0d, ck %0d, KBa %0d\", last_k, ck, c_KBa);\n  bit cl_seen;                                 // a reset seen (registers start arbitrary)\n  initial cl_seen = 1'b0;\n  always @(posedge clk) if (rst) cl_seen <= 1'b1;\n  always @(posedge clk) if (!rst && cl_seen && c_lz != (c_left == 0))\n    $fatal(1, \"otpu_mxu: c_lz %0d, c_left %0d\", c_lz, c_left);\n`endif\n  wire last_g   = (cg + 1 == p_G);          // the row's last group: its pops free FIFO entries\n  wire more     = p_act && !c_lz;\n  // the chunk of advance ck (4-bit without PAIR: two advances a chunk) and whether the advance\n  // finishes it\n  wire [15:0] ckc = (c_w4 && !c_pair) ? {1'b0, ck[15:1]} : ck;\n  wire cdone    = !c_w4 || c_pair || ck[0] || last_k;\n  // advance ck's chunk and scale entry are in the FIFOs: the next entries (one group), or entry\n  // ckc of the row (group 0 of several; the later groups find the whole row)\n  wire f_av     = (p_G == 8'd1) ? (f_count != 0) : (cg != 0 || 32'(f_count) > 32'(ckc));\n  wire s_av     = (p_G == 8'd1) ? (s_count != 0) : (cg != 0 || 32'(s_count) > 32'(ckc));\n  // pop: one block (PAIR: one chunk) advances into the pipeline; fpop: its chunk leaves the FIFO\n  // (4-bit without PAIR: after the high half, or after the row's last block; replay: in the row's\n  // last group). A row's first advance pops only once all of the row's chunks and scale entries\n  // are in the FIFOs (a later group finds them there), so a row never stalls in its middle: a\n  // cycle without a pop is a bubble between rows\n  wire [15:0] c_rch = (c_w4 && !c_pair) ? 16'((32'(c_KBa) + 1) / 2) : c_KBa;   // chunks a row\n  wire row_in   = cg != 0 ||\n                  (32'(f_count) >= 32'(c_rch) && (c_unit || 32'(s_count) >= 32'(c_rch)));\n  wire pop      = more && f_av && (c_unit || s_av) &&\n                  (ck != 0 || (row_in && (RFW+2)'(rows_live) + (RFW+2)'(rows_p) < (RFW+2)'(RF)));\n  wire fpop     = pop && last_g && cdone;\n`ifndef SYNTHESIS\n  always @(posedge clk) if (!rst) begin\n    if (more && ck != 0 && !pop) $fatal(1, \"otpu_mxu: row stalled at advance %0d\", ck);\n    if (more && 32'(c_rch) > DEPTH) $fatal(1, \"otpu_mxu: a row (%0d chunks) must fit the FIFO\", c_rch);\n  end\n  always @(posedge clk) if (!rst && more) begin\n    if (f_rd != (last_g ? f_head : f_head + PW'(ckc)))\n      $fatal(1, \"otpu_mxu: FIFO read address %0d, head %0d, k %0d\", f_rd, f_head, ck);\n    if (!c_unit && s_rd != (last_g ? s_head : s_head + PW'(ckc)))\n      $fatal(1, \"otpu_mxu: scale read address %0d, head %0d, k %0d\", s_rd, s_head, ck);\n  end\n`endif\n  // The issuer walks advances: a chunk request with every 8-bit block, every even 4-bit block (an\n  // odd one's chunk is already on its way, so it needs no FIFO slot) and every PAIR chunk; a scale\n  // line request with each advance (RSC: with each chunk), and the row's Sw line first when it is\n  // in neither neighbour's line (i_sws: a cycle of its own, port A only).\n  wire adv_b    = !i_w4 || i_pair || !i_k[0];\n  wire need_b   = !i_sws && adv_b;\n  wire need_a   = !i_unit && (i_sws || !i_rsc || adv_b);\n  wire want_iss = i_act && (!need_b || occ < (PW+1)'(DEPTH)) && (!need_a || !tg_n[TDW]);\n  wire go_iss   = want_iss && (!need_b || b_gnt) && (!need_a || a_gnt);\n  // the tag of this cycle's port A request\n  typedef struct packed {\n    logic [1:0] wf;\n    logic       pair, rsc;\n    logic [4:0] doff;          // the block data's byte in the line\n    logic [1:0] hv;            // the entry's halves it writes (01 low, 10 high, 11 both)\n    logic       ent;           // it writes the entry (data, or RSC's Sw)\n    logic       cpl;           // ... and completes it\n    logic       swe;           // the entry's Sw is this line's word swo\n    logic [2:0] swo;\n    logic       swr;           // the next rows' Sw is this line's word sro (Sw-only: the row's)\n    logic [2:0] sro;\n  } atag_t;\n  atag_t a_tag;\n  always_comb begin\n    a_tag = '0;\n    a_tag.wf = i_wf; a_tag.pair = i_pair; a_tag.rsc = i_rsc;\n    a_tag.doff = scale_addr[4:0];\n    a_tag.swo = srow_addr[4:2];\n    a_tag.sro = i_sws ? srow_addr[4:2] : srow_next[4:2];\n    if (i_sws) begin\n      a_tag.swr = 1'b1;\n    end else if (i_rsc) begin\n      a_tag.ent = 1'b1; a_tag.cpl = 1'b1; a_tag.swe = 1'b1;\n    end else begin\n      a_tag.ent = 1'b1;\n      a_tag.hv = (i_pair || !i_w4) ? (i_pair ? 2'b11 : 2'b01) : (i_k[0] ? 2'b10 : 2'b01);\n      a_tag.cpl = !i_w4 || i_pair || i_k[0] || i_klast;\n      a_tag.swe = (i_k == 0) && !i_swd && i_swh;\n      a_tag.swr = i_klast && !i_l1 && i_swn;\n    end\n  end\n\n  assign rdy = !i_act && !i_ini && (q_n < 2);\n  assign computing = pop;\n  assign pf_level  = f_count;\n  assign pf_starve = more && f_count == 0;\n  assign pf_block  = more && f_count != 0 && !pop;\n  assign b_req  = go_iss && need_b;\n  // not gated with b_req: the address (and the slice's parity of it) does not wait for b_gnt\n  assign b_addr = chunk_addr >> 2;\n  assign a_req  = go_iss && need_a;\n  assign a_addr = !a_req ? '0 : (i_sws || i_rsc) ? (srow_addr >> 2) : (scale_addr >> 2);\n  assign act_blk = 16'(c_ab) + (c_pair ? {ck[14:0], 1'b0} : ck);\n  // past an odd KB the high block is not the MM's (block ab + KB, outside its ACT range: a later\n  // QACT may be writing it, and the scoreboard does not hold that one back): the high rows read\n  // the even block again, which their zero multipliers (m0.o low) ignore\n  // (both blocks' addresses from flip-flops, last_k picking at the end: it was the adder's carry in,\n  // and the address goes on to the ACT RAMs' block RAM pins, the m8 card's -0.044 ns at 150 MHz)\n  wire [15:0] act_b0 = 16'(c_ab) + {ck[14:0], 1'b0}, act_b1 = 16'(c_ab) + {ck[14:0], 1'b1};\n  assign act_blk2 = (last_k && c_KB[0]) ? act_b0 : act_b1;\n  assign act_hi = c_hi;\n  assign act_grp = cg;\n`ifndef SYNTHESIS\n  // co-sim statistic of the scale reads: port A line requests, and those that fetch a row's Sw\n  // alone (i_sws: its Sw in neither neighbour's line). Totals in xs_a / xs_sw (otpu_slice prints\n  // them at the dump: rtlsim's stats[\"mxu_scale\"]); under +trace one line a command as its\n  // issue ends, \"MXS<sid> a=<requests> sw=<Sw alone>\", in issue order (= the MMs' order;\n  // tools/perf_qwen.py's MM table). Not a trace event: the board does not record it.\n  longint unsigned xs_a, xs_sw;\n  int unsigned     xc_a, xc_sw;\n  bit              xs_trace;\n  initial begin\n    xs_a = 0; xs_sw = 0; xc_a = 0; xc_sw = 0;\n    xs_trace = $test$plusargs(\"trace\");\n  end\n  always @(posedge clk)\n    if (rst) begin\n      xc_a = 0; xc_sw = 0;\n    end else if (go_iss) begin\n      if (a_req) begin\n        xs_a++; xc_a++;\n        if (i_sws) begin xs_sw++; xc_sw++; end\n      end\n      if (!i_sws && i_left == 1) begin\n        if (xs_trace) $display(\"MXS%0d a=%0d sw=%0d\", SID, xc_a, xc_sw);\n        xc_a = 0; xc_sw = 0;\n      end\n    end\n`endif\n  // The ACT RAM's read enables (one per column): an advance reads its block in the cycle it pops\n  // (S0 takes the read register's output), and only the columns of an output row read it. A\n  // column's enable is the pop head's cm, gated with the head being released (p_act: every pop\n  // has it), so a command of M < MCOLS rows (decode: M = 1) reads M of the MCOLS columns, and no\n  // column reads while no command is released. Both are registers (pop_q, q_n) one LUT from the\n  // block RAMs' enables: pop itself is not on that path. A column that does not read holds its\n  // last block, which only its own products (no output's) take.\n  assign act_ren = {MCOLS{p_act}} & pop_e.cm;\n`ifndef SYNTHESIS\n  // every column of an output row reads its block when the advance pops: rows j < Ml of a\n  // command's last group (PAIR: and its high rows j < 2M), every row of the earlier groups\n  always @(posedge clk)\n    if (!rst && pop)\n      for (int j = 0; j < MCOLS; j++)\n        if (!act_ren[j] && (!last_g || 32'(j) < (c_pair ? 32'd2 : 32'd1) * 32'(pop_e.Ml)))\n          $fatal(1, \"otpu_mxu: column %0d of an output row does not read its ACT block (M %0d)\",\n                 j, p_M);\n  // co-sim statistic of the ACT RAM reads (otpu_slice prints them at the dump: rtlsim's\n  // stats[\"act_reads\"]): cycles, column reads (enabled), pops, and the columns of output rows at\n  // the pops, and the columns that ever read. Each column read is D bytes and an 8-byte scale\n  // record.\n  longint unsigned xa_cyc, xa_rd, xa_pop, xa_use;\n  logic [MCOLS-1:0] xa_any;\n  initial begin xa_cyc = 0; xa_rd = 0; xa_pop = 0; xa_use = 0; xa_any = '0; end\n  always @(posedge clk)\n    if (!rst) begin\n      xa_cyc++;\n      xa_rd += longint'($countones(act_ren));\n      xa_any |= act_ren;\n      if (pop) begin\n        xa_pop++;\n        for (int j = 0; j < MCOLS; j++)\n          if (!last_g || 32'(j) < (c_pair ? 32'd2 : 32'd1) * 32'(pop_e.Ml)) xa_use++;\n      end\n    end\n`endif\n\n  // ---- the tags of the requests in flight (LUT RAM) and the responses: a response is\n  // registered with its tag (R1), then written into the scale entry at s_tail (R2)\n  atag_t       tgm [TD];\n  logic [TDW-1:0] tg_t, tg_h;\n  always_ff @(posedge clk) if (a_req) tgm[tg_t] <= a_tag;\n  logic        rv1;\n  logic [255:0] ln1;\n  atag_t       tg1;\n  always_ff @(posedge clk) begin\n    rv1 <= !rst && a_rvalid;\n    if (a_rvalid) begin\n      ln1 <= a_rdata;\n      tg1 <= tgm[tg_h];\n    end\n  end\n  // the entry's data from the line: {Sw, the low block's}, {the high block's}\n  logic [31:0] r_sw, r_swe, r_swr;          // the current rows' Sw; the line's words\n  logic [95:0] r_wd0;\n  logic [63:0] r_wd1;\n  logic        r_we0, r_we1;\n  always_comb begin\n    logic [7:0]   xb;\n    logic [31:0]  xw;\n    logic [63:0]  x8;\n    logic [127:0] x16;\n    logic [63:0]  h0, h1;\n    xb  = ln1[8 * tg1.doff +: 8];\n    xw  = ln1[32 * tg1.doff[4:2] +: 32];\n    x8  = ln1[64 * tg1.doff[4:3] +: 64];\n    x16 = ln1[128 * tg1.doff[4] +: 128];\n    if (tg1.rsc) begin\n      h0 = '0; h1 = '0;\n    end else if (tg1.wf == WF_W8) begin\n      h0 = {56'd0, xb}; h1 = '0;\n    end else if (tg1.wf == WF_NV) begin\n      h0 = tg1.pair ? x16[63:0] : x8; h1 = tg1.pair ? x16[127:64] : x8;\n    end else begin\n      h0 = {32'd0, tg1.pair ? x8[31:0] : xw}; h1 = {32'd0, tg1.pair ? x8[63:32] : xw};\n    end\n    r_swe = ln1[32 * tg1.swo +: 32];\n    r_swr = ln1[32 * tg1.sro +: 32];\n    r_wd0 = {tg1.swe ? r_swe : r_sw, h0};\n    r_wd1 = h1;\n    r_we0 = rv1 && tg1.ent && tg1.hv != 2'b10;\n    r_we1 = rv1 && tg1.ent && tg1.hv[1];\n  end\n  wire r_cpl = rv1 && tg1.ent && tg1.cpl;\n  always_ff @(posedge clk)\n    if (rv1) begin\n      if (tg1.swr) r_sw <= r_swr;\n      else if (tg1.swe) r_sw <= r_swe;\n    end\n  logic [95:0] sr0;                          // the S0 scale entry: {Sw, low block}, high block\n  logic [63:0] sr1;\n  otpu_ram_1r1w #(.W(96), .N(DEPTH), .STYLE(\"block\")) u_fs0 (\n    .clk, .we(r_we0), .wa(s_tail), .wd(r_wd0), .re(1'b1), .ra(s_rd), .rd(sr0));\n  otpu_ram_1r1w #(.W(64), .N(DEPTH), .STYLE(\"block\")) u_fs1 (\n    .clk, .we(r_we1), .wa(s_tail), .wd(r_wd1), .re(1'b1), .ra(s_rd), .rd(sr1));\n\n  // ================================================================== compute pipeline\n  typedef struct packed {\n    logic       v;\n    logic       last;     // last block of its row (the row's group)\n    logic       first;    // first block of its row (the row's group)\n    logic       h;        // 4-bit: the chunk's high half\n    logic       o;        // PAIR: the chunk's high block is in the row (not past an odd KB)\n  } cm_t;\n\n  cm_t                 m0;\n  logic [D*8-1:0]      w0;                  // the chunk (FIFO read register)\n  logic [MCOLS*D*8-1:0] a0;\n  // S0's ACT RAM block and scale records are the ACT RAM's registered read\n  assign a0 = act_data;\n  logic cu0, pr0, rs0;\n  logic [1:0] wf0;\n  logic [MCOLS-1:0] hi0;                    // PAIR: the columns of the high block\n  logic [7:0] M0;                           // the command's M (constant while its blocks flow)\n  wire  w40 = (wf0 != WF_W8);\n  // 4-bit elements: nibble i of the chunk half; int4 two's complement, E2M1 as twice its value\n  // ({0, 1, 2, 3, 4, 6, 8, 12}, sign in bit 3); NVFP4 elements are E2M1's\n  function automatic logic [7:0] dec4(input logic [3:0] c, input logic fp);\n    if (!fp) return {{4{c[3]}}, c};\n    case (c)\n      4'd5: return 8'd6;\n      4'd6: return 8'd8;\n      4'd7: return 8'd12;\n      4'd8: return 8'd0;\n      4'd9: return -8'sd1;\n      4'd10: return -8'sd2;\n      4'd11: return -8'sd3;\n      4'd12: return -8'sd4;\n      4'd13: return -8'sd6;\n      4'd14: return -8'sd8;\n      4'd15: return -8'sd12;\n      default: return 8'(c);\n    endcase\n  endfunction\n  // the weight of position i for a column that takes the high block (PAIR) or the high half\n  function automatic logic [7:0] wsel(input logic [D*8-1:0] w, input int i, input logic hb,\n                                      input logic [1:0] wf);\n    if (wf == WF_W8) return w[i*8 +: 8];\n    return dec4(w[(hb ? D*4 : 0) + 4*i +: 4], wf != 2'd1);\n  endfunction\n\n  // FIFO writes (the slot was reserved when the chunk was issued; see occ); the RAMs are\n  // technology RAMs (rtl/tech)\n  for (genvar g = 0; g < FG; g++) begin : g_fd\n    localparam int LO = fg_lo(g);\n    localparam int W = ((g == FG - 1) ? FW : fg_lo(g + 1)) - LO;\n    (* keep_hierarchy = \"yes\" *)\n    otpu_ram_1r1w #(.W(W), .N(DEPTH), .STYLE(\"block\")) u_fd (\n      .clk, .we(b_rvalid), .wa(f_tl[g]), .wd(b_rdata[LO +: W]), .re(1'b1), .ra(f_rdl[g]),\n      .rd(w0[LO +: W]));\n  end\n`ifndef SYNTHESIS\n  // the groups' address copies are f_tail and f_rd (all reset together)\n  bit fd_rst;                                         // (registers start arbitrary)\n  initial fd_rst = 1'b0;\n  always @(posedge clk) begin\n    if (rst) fd_rst <= 1'b1;\n    for (int g = 0; g < FG; g++)\n      if (!rst && fd_rst && (f_tl[g] != f_tail || f_rdl[g] != f_rd))\n        $fatal(1, \"otpu_mxu: FIFO group %0d addresses %0d / %0d, not %0d / %0d\", g, f_tl[g],\n               f_rdl[g], f_tail, f_rd);\n  end\n`endif\n\n  // S0: the popped chunk, its ACT RAM block and records, its scale entry\n  always_ff @(posedge clk) begin\n    m0 <= '0;\n    if (pop) begin\n      m0.v <= 1'b1;\n      m0.last <= last_k;\n      m0.first <= (ck == 16'd0);\n      m0.h <= c_w4 && !c_pair && ck[0];\n      m0.o <= c_pair && !(last_k && c_KB[0]);\n    end\n    cu0 <= c_unit;\n    rs0 <= c_rsc;\n    wf0 <= c_wf;\n    pr0 <= c_pair;\n    hi0 <= c_hi;\n    M0 <= p_M;\n  end\n\n  // ---- the shifts: per block its eight groups' W - dw and m (S1), per column and group\n  // B = sh >= 0 ? m << sh : 0 with sh = W - dw - da (S2), skewed to the column end\n  typedef struct packed {\n    logic [7:0][10:0] s;       // W - dw, signed\n    logic [7:0][5:0]  m;\n  } bdec_t;\n  function automatic bdec_t bdec(input logic [63:0] b, input logic [1:0] wf, input logic u);\n    bdec_t r;\n    logic [10:0] w;\n    w = (wf == WF_W8) ? 11'd16 : (wf == WF_NV) ? 11'd13 : 11'd11;\n    for (int g = 0; g < 8; g++) begin\n      logic [3:0] ex;\n      ex = b[8*g + 3 +: 4];\n      if (u) begin\n        r.s[g] = w; r.m[g] = 6'd1;\n      end else if (wf == WF_W8) begin\n        r.s[g] = w - 11'(b[7:0]); r.m[g] = 6'd1;\n      end else if (wf == WF_NV) begin\n        // E4M3 s = {0, E, M}: m = E ? 8 + M : M, dw = 15 - max(E, 1): W - dw = max(E, 1) - 2\n        r.m[g] = (ex != 4'd0) ? {3'b001, b[8*g +: 3]} : {3'b000, b[8*g +: 3]};\n        r.s[g] = 11'((ex == 4'd0) ? 4'd1 : ex) - 11'd2;\n      end else begin\n        r.s[g] = w - 11'(b[7:0]); r.m[g] = b[8 + 6*(g/2) +: 6];\n      end\n    end\n    return r;\n  endfunction\n  // the low block: the advance's half (4-bit without PAIR) or the entry's low block\n  wire [63:0] blo0 = (w40 && !pr0 && m0.h) ? sr1 : sr0[63:0];\n  // the decoded blocks (S1), a registered copy per column (g_bd: kept instances, since identical\n  // registers merge) beside the column's shifts: one register driving every column's was the\n  // ASIC card's worst path (r4: a DFF_X1 of dhi1 into the four columns' bm2 across the die,\n  // 1.01 ns of clock-to-Q into its load)\n  bdec_t dlo0, dhi0;\n  always_comb begin\n    dlo0 = bdec(blo0, wf0, cu0 || rs0);\n    dhi0 = bdec(sr1, wf0, cu0 || rs0);\n  end\n  bdec_t dlo1 [MCOLS];\n  bdec_t dhi1 [MCOLS];\n  logic [MCOLS-1:0] vlo1, vhi1;\n  for (genvar j = 0; j < MCOLS; j++) begin : g_bd\n    (* keep_hierarchy = \"yes\" *)\n    otpu_delay #(.W(2 * $bits(bdec_t) + 2), .N(1)) u_bd (.clk, .en(1'b1),\n      .d({dlo0, dhi0, m0.v, m0.v && m0.o}), .q({dlo1[j], dhi1[j], vlo1[j], vhi1[j]}));\n  end\n  logic [MCOLS-1:0][3:0][7:0] da1;\n  logic [MCOLS-1:0] hi1;\n  always_ff @(posedge clk)\n    for (int j = 0; j < MCOLS; j++) begin\n      da1[j] <= act_scale[j*64 + 32 +: 32];\n      hi1[j] <= hi0[j];\n    end\n  logic [MCOLS-1:0][7:0][16:0] bm2;\n  always_ff @(posedge clk)\n    for (int j = 0; j < MCOLS; j++)\n      for (int g = 0; g < 8; g++) begin\n        logic [10:0] sh;\n        logic [10:0] s;\n        logic [5:0]  m;\n        logic        v;\n        s = hi1[j] ? dhi1[j].s[g] : dlo1[j].s[g];\n        m = hi1[j] ? dhi1[j].m[g] : dlo1[j].m[g];\n        v = hi1[j] ? vhi1[j] : vlo1[j];\n        sh = s - 11'(da1[j][g / 2]);\n        bm2[j][g] <= (v && !sh[10]) ? 17'(17'(m) << sh[4:0]) : 17'd0;\n      end\n  // the row's Sw (UNIT: 1) and each column's Sa * 2^-W, with every advance (the row's last\n  // carries them to the result FIFO): fp_mul's flush and rounding at the bottom of the range\n  wire [31:0] sw0 = cu0 ? F_ONE : sr0[95:64];\n  wire [31:0] wpow = (wf0 == WF_W8) ? 32'h3780_0000 : (wf0 == WF_NV) ? 32'h3900_0000\n                                                                     : 32'h3A00_0000;\n  // x * 2^-k as fp_mul computes it (flushed operands and result, the canonical NaN), without a\n  // multiplier: the exponent less k; a result under the normal range flushes to a signed zero,\n  // except the one that rounds up to the smallest normal (exponent k, fraction all ones)\n  function automatic f32_t fp_pow2m(input f32_t x, input logic [4:0] k);\n    logic [8:0] e;\n    if (x[30:23] == 8'd0) return {x[31], 31'd0};\n    if (x[30:23] == 8'hFF) return (x[22:0] != 0) ? F_NAN : x;\n    e = 9'(x[30:23]) - 9'(k);\n    if (!e[8] && e != 0) return {x[31], e[7:0], x[22:0]};\n    if (e == 0 && x[22:0] == 23'h7F_FFFF) return {x[31], 8'd1, 23'd0};\n    return {x[31], 31'd0};\n  endfunction\n  wire [4:0] wk = (wf0 == WF_W8) ? 5'd16 : (wf0 == WF_NV) ? 5'd13 : 5'd11;\n  logic [31:0] sw1;\n  logic [MCOLS-1:0][31:0] sap1;\n  always_ff @(posedge clk) begin\n    sw1 <= sw0;\n    for (int j = 0; j < MCOLS; j++) sap1[j] <= fp_pow2m(act_scale[j*64 +: 32], wk);\n  end\n`ifndef SYNTHESIS\n  always @(posedge clk)\n    for (int j = 0; j < MCOLS; j++)\n      if (fp_pow2m(act_scale[j*64 +: 32], wk) != fp_mul(act_scale[j*64 +: 32], wpow))\n        $fatal(1, \"otpu_mxu: Sa %h * 2^-%0d is not fp_mul's\", act_scale[j*64 +: 32], wk);\n`endif\n\n  // ---- the systolic array (docs/mxu_systolic.md). The chunk is decoded once (S1), position i\n  // is delayed by its chain stage k = i % CLS, and the weights then move one register hop per\n  // column: column j sees them j cycles after column 0. Both streams flow: the low block (or the\n  // 4-bit half of a non-PAIR advance) and PAIR's high block; each column takes one in its DSPs'\n  // pre-adder (A = low, D = high, INMODE by its per-command hi0[j]). Column j's activation byte i\n  // is delayed k + j (shift registers) into the DSP's B register. Along D: chains of CLS products,\n  // one per DSP48 (otpu_pe: M register, P = PCIN + M); a chain's end (S0 + CLS + 2 + j, in the\n  // column end's input registers) is one group's sum. Exact integers.\n  logic [D-1:0][15:0] wd;                             // S1: {high block, low block / half}\n  always_ff @(posedge clk)\n    for (int i = 0; i < D; i++) wd[i] <= {wsel(w0, i, 1'b1, wf0), wsel(w0, i, m0.h, wf0)};\n  logic [D-1:0][15:0] wc [MCOLS];                    // the streams at column j\n  for (genvar i = 0; i < D; i++) begin : g_wsk\n    otpu_skew #(.W(16), .N(i % CLS)) u_w (.clk, .en(1'b1), .d(wd[i]), .q(wc[0][i]));\n  end\n  always_ff @(posedge clk)\n    for (int j = 1; j < MCOLS; j++) wc[j] <= wc[j-1];\n  logic [7:0] as_k [MCOLS][D];\n  logic signed [23:0] preg [MCOLS][D];                // running sums (the DSPs' P registers;\n                                                      // a chain's last: its P, unregistered)\n  logic [47:0] pc [MCOLS][D];                         // their cascade outputs\n`ifndef SYNTHESIS\n  bit hi_v;                                           // hi0 and the PEs' selects are loaded\n  initial hi_v = 1'b0;\n  always @(posedge clk) hi_v <= 1'b1;\n`endif\n  for (genvar j = 0; j < MCOLS; j++) begin : g_ask\n    for (genvar i = 0; i < D; i++) begin : g_p\n      otpu_skew #(.W(8), .N(i % CLS + j)) u_a (.clk, .en(1'b1), .d(a0[(j*D + i)*8 +: 8]),\n                                             .q(as_k[j][i]));\n      // columns past the first register their weights in the DSP (WREG), from the previous\n      // column's hop: a copy of wc[j]\n      localparam int JW = (j == 0) ? 0 : j - 1;\n      otpu_pe #(.FIRST(i % CLS == 0), .LAST(i % CLS == CLS - 1), .WREG(j != 0)) u_pe (\n        .clk, .en(1'b1), .act(as_k[j][i]), .wlo(wc[JW][i][7:0]), .whi(wc[JW][i][15:8]),\n        .sel(c_hi[j]),\n        .pcin((i % CLS == 0) ? 48'd0 : pc[j][(i % CLS == 0) ? i : i - 1]), .pcout(pc[j][i]),\n        .p(preg[j][i]));\n`ifndef SYNTHESIS\n      // the DSP's select register is hi0[j] (both are c_hi[j], loaded every cycle)\n      always @(posedge clk) begin\n        if (hi_v && u_pe.selr != hi0[j])\n          $fatal(1, \"otpu_mxu: PE %0d.%0d's select %0d is not hi0 %0d\", j, i, u_pe.selr, hi0[j]);\n        if (hi_v && j != 0 && {u_pe.whr, u_pe.wlr} != wc[j][i])\n          $fatal(1, \"otpu_mxu: PE %0d.%0d's weights are not wc\", j, i);\n      end\n`endif\n    end\n  end\n\n  // ---- column ends: group g's chain ends (CPG of them: the first on A, the second on D) with\n  // their B (skewed from S2 to the column end's input registers, S0 + CLS + 2 + j), the row's\n  // first block at the accumulator's OPMODE register (two cycles later), the row sum in the\n  // accumulator CLS + 6 + j edges after S0, deskewed to S0 + LROW\n  logic [MCOLS-1:0][47:0] acc_al;\n  for (genvar j = 0; j < MCOLS; j++) begin : g_col_end\n    logic [7:0][23:0] ca, cd;\n    logic [7:0][16:0] bmd;\n    logic             fst;\n    logic [47:0]      acc;\n    always_comb\n      for (int g = 0; g < 8; g++) begin\n        ca[g] = preg[j][g * CPG * CLS + CLS - 1];\n        cd[g] = (CPG == 2) ? preg[j][(g * CPG + 1) * CLS + CLS - 1] : 24'd0;\n      end\n    otpu_skew #(.W(8 * 17), .N(CLS - 1 + j)) u_bm (.clk, .en(1'b1), .d(bm2[j]), .q(bmd));\n    otpu_skew #(.W(1), .N(CLS + 4 + j)) u_f (.clk, .en(1'b1), .d(m0.v && m0.first), .q(fst));\n    otpu_mxce #(.CPG(CPG)) u_ce (.clk, .a(ca), .d(cd), .bm(bmd), .first(fst), .acc);\n    otpu_skew #(.W(48), .N(MCOLS - 1 - j)) u_dsk (.clk, .en(1'b1), .d(acc), .q(acc_al[j]));\n  end\n  // the row's last block, PAIR and M at S0 + LROW; Sw and the Sa' from S1\n  logic             tl_v, tl_pr;\n  logic [7:0]       tl_M;\n  logic [31:0]      tl_sw;\n  logic [MCOLS-1:0][31:0] tl_sa;\n  otpu_delay #(.W(1 + 1 + 8), .N(LROW)) u_tl (.clk, .en(1'b1), .d({m0.v && m0.last, pr0, M0}),\n                                             .q({tl_v, tl_pr, tl_M}));\n  otpu_skew #(.W(32 + MCOLS * 32), .N(LROW - 1)) u_ts (.clk, .en(1'b1), .d({sw1, sap1}),\n                                                      .q({tl_sw, tl_sa}));\n  // PAIR: row j (j < M <= MCOLS/2) adds its partner column j + M's integer; registered for the\n  // result FIFO (rv: push)\n  logic             rv;\n  logic [MCOLS-1:0][47:0] rowi;\n  logic [MCOLS-1:0][31:0] rsa;\n  logic [31:0]      rsw;\n  always_ff @(posedge clk) begin\n    rv <= !rst && tl_v;\n    for (int j = 0; j < MCOLS; j++) begin\n      logic [47:0] pb;\n      pb = '0;\n      for (int m = 1; m <= MCOLS / 2; m++)\n        if (j < MCOLS / 2 && j + m < MCOLS && tl_M == 8'(m)) pb = acc_al[j + m];\n      rowi[j] <= (tl_pr && j < MCOLS / 2) ? acc_al[j] + pb : acc_al[j];\n    end\n    rsa <= tl_sa;\n    rsw <= tl_sw;\n  end\n\n  // ================================================================== result FIFO\n  // Rows in LUT RAM; the drain reads the head row from flip-flops. rf_q trails the head by the\n  // last cycle's pop (rf_hs: the head is rf_q + rf_hs), so the rows are read at rf_q, rf_q + 1\n  // and rf_q + 2 (a row written this cycle bypassed) with no grant on the address; each cycle the\n  // head row and the row after it are registered (rh0, rh1) and the last pop picks the head\n  // (rfh). One RAM copy per read address: a single read port each infers as LUT RAM.\n  // A row: MCOLS integers, MCOLS Sa', Sw\n  localparam int RW_ = MCOLS * 48 + MCOLS * 32 + 32;\n  logic [RFW-1:0] rf_q, rf_t;\n  logic [RFW:0]   rf_n;\n  logic           rf_hs;                     // the last cycle popped a row\n  wire            rf_push = rv;\n  logic [RW_-1:0] rowp, rh0, rh1, rfh;\n  logic [2:0][RW_-1:0] rq;                   // rows rf_q + c, as they are after this cycle\n  logic [2:0][RFW-1:0] rf_qc;\n  always_comb begin\n    rowp = {rsw, rsa, rowi};\n    for (int c = 0; c < 3; c++) rf_qc[c] = rf_q + RFW'(c);\n  end\n  // each copy has its own write enable and address (replicas of rv and rf_t): one register\n  // driving the three copies' write ports was the worst slow-clock path of the MX experiment's\n  // 4-column OOC (docs/mx_mxu.md section 5, +0.329 ns). The copies are block RAMs read ahead\n  // (otpu_ram_1r1w_ra: at rf_q's next value, rf_qn, plus c; the RAM bypasses the row written at\n  // the last edge, the copy the one written at this one). As LUT RAMs a copy was some 1,100 cells\n  // whose every one each address bit reached (the card's m8: 37,632 address pins), and the write\n  // took a kept wv / wt per column slice (r22's m8: one wt at fanout 1,125, 6.7 ns of route)\n  wire [RFW-1:0] rf_qn = rst ? '0 : RFW'(rf_q + RFW'(rf_hs));\n`ifndef SYNTHESIS\n  logic [RW_-1:0] msh [RF];                  // the rows as written (the checks)\n  always_ff @(posedge clk) if (!rst && rf_push) msh[rf_t] <= rowp;\n`endif\n  for (genvar c = 0; c < 3; c++) begin : g_rfm\n    logic [RW_-1:0] rqm;                     // row rf_q + c as the RAM has it (to the last edge)\n`ifndef SYNTHESIS\n    logic [RW_-1:0] mh;                      // the row at the head (the check below)\n`endif\n    logic           wv;\n    logic [RFW-1:0] wt;\n    always_ff @(posedge clk) begin\n      wv <= !rst && tl_v;\n      if (rst) wt <= '0;\n      else if (wv) wt <= wt + 1'b1;\n    end\n    otpu_ram_1r1w_ra #(.W(RW_), .N(RF), .STYLE(\"block\")) u_m (\n      .clk, .we(!rst && wv), .wa(wt), .wd(rowp), .ra_n(RFW'(rf_qn + RFW'(c))), .rd(rqm));\n    assign rq[c] = (wv && wt == rf_qc[c]) ? rowp : rqm;\n`ifndef SYNTHESIS\n    assign mh = msh[RFW'(rf_q + RFW'(rf_hs))];\n    always @(posedge clk) begin\n      if (!rst && (wv != rf_push || wt != rf_t))\n        $fatal(1, \"otpu_mxu: result FIFO copy %0d's write is not rf_push / rf_t\", c);\n      if (!rst && rqm != msh[rf_qc[c]])\n        $fatal(1, \"otpu_mxu: result FIFO copy %0d's read ahead is not row %0d\", c, rf_qc[c]);\n    end\n`endif\n  end\n  always_ff @(posedge clk) begin\n    rh0 <= rf_hs ? rq[1] : rq[0];           // the head (rf_q + rf_hs) as it is after this cycle\n    rh1 <= rf_hs ? rq[2] : rq[1];           // the row after it\n  end\n  assign rfh = rf_hs ? rh1 : rh0;\n  wire [MCOLS-1:0][47:0] rfh_i  = rfh[0 +: MCOLS * 48];\n  wire [MCOLS-1:0][31:0] rfh_sa = rfh[MCOLS * 48 +: MCOLS * 32];\n  wire [31:0]            rfh_sw = rfh[MCOLS * 80 +: 32];\n\n  // ================================================================== drain\n  // lanes this cycle: results dj .. dj+ncnt-1 of the head row, stopping at a bank conflict\n  logic [31:0] drow [MCOLS];                 // replay: dad of the head row's group 0\n  logic [31:0] dad [MCOLS];                  // head row's TMEM addresses: out + n + j * ors,\n                                             // kept incrementally\n  logic [MW-1:0] dj;\n  logic [MW-1:0] ncnt;\n  logic [7:0]    dg;                         // the group of the row being drained\n  logic [7:0]    dg1;                        // dg + 1, kept alongside\n  // The drain's step is registered, with its next value computed a cycle ahead (below, at the\n  // head's entries): no compare or subtract between the head's entry and the pick. d_last: dg1\n  // == c_G; ncnt = min(run, c_Mn - dj) and dln its lanes (k < ncnt); d_fin: the step drains the\n  // group's last results (dj + ncnt == c_Mn). drain_go's counts are tested by registered flags\n  // (rf_nz: rf_n != 0, rl_nz: rows_live != 0) for the same reason.\n  logic          d_last, d_fin, rf_nz, rl_nz;\n  logic [NL-1:0] dln;\n  wire  [MW-1:0] c_Mn = d_last ? h.Ml : MW'(MCOLS);   // its results\n  // The drain lanes' addresses, dad[dj + k], are registered (dal): set wherever dj or dad move\n  logic [NL-1:0][31:0] dal;\n  function automatic logic [NL-1:0][31:0] dlane_a(input logic [31:0] a [MCOLS],\n                                                  input logic [MW-1:0] j);\n    for (int k = 0; k < NL; k++) dlane_a[k] = (32'(j) + 32'(k) < MCOLS) ? a[MW'(j) + MW'(k)] : '0;\n  endfunction\n  logic [NL-1:0][47:0] dx_l;\n  logic [NL-1:0][31:0] dsa_l;\n  logic [NL-1:0][7:0]  dcol_l;\n  // (the result FIFO's head row is the head command's while it has rows not yet drained)\n  wire  drain_go = rf_nz && rl_nz && (!c_asc || al_st == 2'd2);\n`ifndef SYNTHESIS\n  always @(posedge clk) if (!rst && drain_go && dg1 != dg + 8'd1) $fatal(1, \"otpu_mxu: dg1 %0d, dg %0d\", dg1, dg);\n`endif\n  // Results j and j' of a row sit ors * (j' - j) words apart: the same bank iff that is a multiple\n  // of LANES. So consecutive results are conflict-free in runs of LANES / gcd(ors, LANES)\n  // (capped at NL), a per-command constant: the lane count is min(run, M - dj).\n  // A step of a group with `left` results still to drain: {drains them all, lanes}\n  function automatic logic [MW:0] dstep(input logic [MW-1:0] left, input logic [MW-1:0] run);\n    return {left <= run, (run < left) ? run : left};\n  endfunction\n  function automatic logic [NL-1:0] dlanes(input logic [MW-1:0] cnt);\n    for (int k = 0; k < NL; k++) dlanes[k] = 32'(k) < 32'(cnt);\n  endfunction\n`ifndef SYNTHESIS\n  // the registered step is its definition from the head's entry, dg1, dj and the counts\n  always @(posedge clk) if (!rst && q_n != 0) begin\n    logic [MW-1:0] mn, lf;\n    mn = (dg1 == c_G) ? h.Ml : MW'(MCOLS);\n    lf = mn - dj;\n    if (d_last != (dg1 == c_G) || ncnt != ((c_run < lf) ? c_run : lf) || dln != dlanes(ncnt) ||\n        d_fin != (MW'(dj + ncnt) == mn))\n      $fatal(1, \"otpu_mxu: drain step d_last %0d ncnt %0d d_fin %0d (dg1 %0d G %0d dj %0d M %0d run %0d)\",\n             d_last, ncnt, d_fin, dg1, c_G, dj, mn, c_run);\n  end\n  always @(posedge clk) if (!rst && q_n != 0 && dal != dlane_a(dad, dj))\n    $fatal(1, \"otpu_mxu: the drain lanes' addresses are not dad[dj + k] (dj %0d)\", dj);\n  always @(posedge clk) if (!rst && (rf_nz != (rf_n != 0) || rl_nz != (rows_live != 0)))\n    $fatal(1, \"otpu_mxu: rf_nz %0d (rf_n %0d), rl_nz %0d (rows_live %0d)\", rf_nz, rf_n, rl_nz, rows_live);\n`endif\n  always_comb begin\n    dx_l = '0; dsa_l = '0; dcol_l = '0;\n    for (int k = 0; k < NL; k++)\n      if (32'(dj) + 32'(k) < MCOLS) begin\n        dx_l[k] = rfh_i[MW'(dj) + MW'(k)];\n        dsa_l[k] = rfh_sa[MW'(dj) + MW'(k)];\n        dcol_l[k] = 8'(dj) + 8'(k);\n      end\n  end\n`ifndef SYNTHESIS\n  // PAIR reads a block's data and its partner's in one line\n  always @(posedge clk)\n    if (a_req && i_pair && !i_sws && !i_rsc && scale_addr[2])\n      $fatal(1, \"otpu_mxu: PAIR scales must be 8-byte aligned\");\n  // the lane count is what a greedy pick that stops at the first bank conflict would take\n  always @(posedge clk) if (drain_go) begin\n    logic [LANES-1:0] used;\n    int n;\n    used = '0; n = 0;\n    for (int k = 0; k < NL && 32'(dj) + 32'(k) < 32'(c_Mn); k++) begin\n      if (used[dad[MW'(dj) + MW'(k)][BW-1:0]]) break;\n      used[dad[MW'(dj) + MW'(k)][BW-1:0]] = 1'b1;\n      n++;\n    end\n    if (n != 32'(ncnt)) $fatal(1, \"otpu_mxu: drain lanes %0d, greedy pick %0d\", ncnt, n);\n  end\n`endif\n  wire drain_row_done = drain_go && d_fin;   // dj + ncnt == c_Mn\n  // the next drain step's candidates, from registers (the grant only picks one): the rest of the\n  // group, or (d_fin) the next group, the row's last (d_nl) or not; a new head's is its entry's\n  wire [MW-1:0]    d_rest = c_Mn - dj - ncnt;\n  wire             d_nl = d_last ? h.g1 : (dg1 + 8'd1 == c_G);\n  wire [MW:0]      st_mid = dstep(d_rest, c_run);\n  wire [MW:0]      st_grp = d_nl ? {h.dfl, h.dnl} : dstep(MW'(MCOLS), c_run);\n  wire [NL-1:0]    ln_mid = dlanes(st_mid[MW-1:0]), ln_grp = dlanes(st_grp[MW-1:0]);\n  logic            ea;          // the epilogue's advance: the TMEM grant (TQ 0) or flip-flops'\n  logic [1:0]      tq_n;        // TQ: the epilogue's TMEM writes waiting (the TMEM interface)\n  wire             d_pop = ea && drain_row_done;      // a row leaves the result FIFO\n`ifndef SYNTHESIS\n  always @(posedge clk) if (!rst && rf_n != 0 && rfh != g_rfm[0].mh)\n    $fatal(1, \"otpu_mxu: registered head row is not row %0d\", rf_q + RFW'(rf_hs));\n`endif\n\n  // ---- the epilogue lanes: the pick registered (P1), i2f48, x Sw, x Sa' (otpu_mx_lane), the\n  // pick's lanes, addresses and columns alongside; everything advances with ea (the TMEM grant,\n  // or with TQ a function of flip-flops: the TMEM interface below). The\n  // lane output (lo_*) is the drain's TMEM request: a write, or ACC's read of the old values\n  typedef struct packed {\n    logic                   v;\n    logic [NL-1:0]          m;\n    logic [NL-1:0][31:0]    ad;\n    logic [NL-1:0][7:0]     col;\n  } lmeta_t;\n  lmeta_t p1, lo;\n  logic [NL-1:0][31:0] lo_ad;\n  logic [NL-1:0][7:0]  lo_col;\n  logic [NL-1:0][47:0] p1_x;\n  logic [NL-1:0][31:0] p1_sa;\n  logic [31:0]         p1_sw;\n  f32_t                lo_y [NL];\n  always_ff @(posedge clk)\n    if (rst) p1 <= '0;\n    else if (ea) begin\n      p1.v <= drain_go;\n      p1.m <= drain_go ? dln : '0;\n      p1.ad <= dal;\n      p1.col <= dcol_l;\n    end\n  always_ff @(posedge clk)\n    if (ea) begin\n      p1_x <= dx_l; p1_sa <= dsa_l; p1_sw <= rfh_sw;\n    end\n  for (genvar k = 0; k < NL; k++) begin : g_lane\n    otpu_mx_lane #(.LM(LM)) u_l (.clk, .en(ea), .x(p1_x[k]), .sw(p1_sw), .sa(p1_sa[k]),\n                                 .y(lo_y[k]));\n  end\n  // the picks' addresses and columns in a delay line; their valid and lane bits in reset\n  // registers (a run stopped in the middle of a drain leaves no write to come out after rst)\n  lmeta_t lo_p;\n  otpu_delay #(.W($bits(lmeta_t)), .N(LLAT - 2)) u_lm (.clk, .en(ea), .d(p1), .q(lo_p));\n  logic [LLAT-2:0][NL:0] lvm;\n  always_ff @(posedge clk)\n    if (rst) lvm <= '0;\n    else if (ea) begin\n      lvm[0] <= {p1.v, p1.m};\n      for (int s = 1; s <= LLAT - 2; s++) lvm[s] <= lvm[s-1];\n    end\n  always_ff @(posedge clk)\n    if (ea) begin\n      lo_ad <= lo_p.ad;\n      lo_col <= lo_p.col;\n    end\n  always_comb begin\n    {lo.v, lo.m} = lvm[LLAT-2];\n    lo.ad = lo_ad;\n    lo.col = lo_col;\n  end\n  logic [3:0] ln_n;                          // picks in the lanes (any nonzero = busy)\n\n  // read-modify-write pipeline for ACC: request now, read from the request register next cycle\n  // (rA, TMEM's input stage), data the cycle after (r0), (old*alpha)+new, write\n  typedef struct packed {\n    logic                   v;\n    logic [NL-1:0]          m;\n    logic [NL-1:0][31:0]    ad, nv;\n    logic [NL-1:0][7:0]     col;\n  } rmw_t;\n  rmw_t r0, rw;                               // r0: data arriving now; rw: at the write stage\n  rmw_t rA;                                   // the read in the request register (t_ren)\n  rmw_t rx;                                   // RMAX (no ACC): written lanes, compared next cycle\n  f32_t ry [NL];\n  // r1: r0 one granted cycle later, with the old values registered (xo): no path from the TMEM\n  // block RAMs into the fmadd's DSP inputs in one cycle. The ASCALE factor (alr) is selected from\n  // r0 as it moves into r1, so the fmadd's b operand is a flop too (no mux in front of the DSP);\n  // c_asc and alpha cannot change while a valid entry sits in r0/r1 (the head changes only once\n  // drained, alpha loads only before an ASCALE command drains)\n  rmw_t r1;\n  f32_t xo [NL], alr [NL];\n  always_ff @(posedge clk)\n    if (rst) r1 <= '0;\n    else if (ea) begin\n      r1 <= r0;\n      for (int k = 0; k < NL; k++) begin\n        xo[k]  <= t_rdata[k];\n        alr[k] <= c_asc ? alpha[r0.col[k][MW-2:0]] : F_ONE;\n      end\n    end\n  for (genvar k = 0; k < NL; k++) begin : g_rmw\n    otpu_fmadd #(.LM(LM), .LA(LA)) u_y (.clk, .en(ea), .a(xo[k]), .b(alr[k]), .c(r1.nv[k]),\n                                        .y(ry[k]));\n  end\n  otpu_delay #(.W($bits(rmw_t)), .N(LM + LA)) u_rw (.clk, .en(ea), .d(r1), .q(rw));\n  logic [3:0] rmw_n;                          // rows' lanes in flight (any nonzero = busy)\n\n  // RMAX: the running max is kept as its sort key (mk = fkey(max); the max is always stored\n  // ftz'd, so fkey(max) is the key it is compared by); written out through unkey.\n  logic [31:0] mk [MCOLS];\n  logic [MCOLS-1:0] mx_have;\n  logic mx_done;\n  function automatic f32_t unkey(input logic [31:0] k);\n    return k[31] ? {1'b0, k[30:0]} : ~k;\n  endfunction\n  // rw's column hits, one-hot, computed from r1 and carried alongside u_rw (same length and\n  // enable); the last stage is a reset flop, not an SRL tap. c_rmax is fixed while entries are\n  // in flight (the head changes only once drained)\n  logic [NL-1:0][MCOLS-1:0] rh, rh_p, rwh, rxh;\n  always_comb\n    for (int k = 0; k < NL; k++)\n      for (int j = 0; j < MCOLS; j++) begin\n        rh[k][j]  = r1.v && c_rmax && r1.m[k] && (r1.col[k][MW-2:0] == (MW-1)'(j));\n        rxh[k][j] = rx.v && rx.m[k] && (rx.col[k][MW-2:0] == (MW-1)'(j));\n      end\n  otpu_delay #(.W(NL * MCOLS), .N(LM + LA - 1)) u_rwh (.clk, .en(ea), .d(rh), .q(rh_p));\n  always_ff @(posedge clk) if (rst) rwh <= '0; else if (ea) rwh <= rh_p;\n  // per column: the candidate key is selected by the hits alone. At most one lane hits a column\n  // per cycle (lanes drain distinct columns) and rx / rw are exclusive (rx only for !c_acc\n  // commands, rw only for c_acc ones). The compare is a stage later: each column's hit and key\n  // are registered at the advance (mq_h, mq_k) and compared with mk, and applied, the cycle after,\n  // advance or not (fkey of the fmadd's sum, the lanes' selection, a 32-bit compare and the\n  // update's enable were one cycle: the m8 card at a 150 MHz equivalent, -0.057 ns, 10 levels).\n  // The running max holds: each column's keys reach mk one at a time, in order, each compared\n  // with the max of those before it; a command completes only with the stage empty (c_drained)\n  logic [MCOLS-1:0] mx_hit, mx_upd, mq_h;\n  logic [31:0] mx_cand [MCOLS], mq_k [MCOLS];\n  always_comb\n    for (int j = 0; j < MCOLS; j++) begin\n      mx_hit[j] = 1'b0; mx_cand[j] = '0;\n      for (int k = 0; k < NL; k++) begin\n        if (rxh[k][j]) begin\n          mx_hit[j] = 1'b1;\n          mx_cand[j] = mx_cand[j] | fkey(rx.nv[k]);\n        end\n        if (rwh[k][j]) begin\n          mx_hit[j] = 1'b1;\n          mx_cand[j] = mx_cand[j] | fkey(ry[k]);\n        end\n      end\n      mx_upd[j] = mq_h[j] && (!mx_have[j] || mq_k[j] > mk[j]);\n    end\n  always_ff @(posedge clk) if (ea) for (int j = 0; j < MCOLS; j++) mq_k[j] <= mx_cand[j];\n`ifndef SYNTHESIS\n  always_ff @(posedge clk)\n    if (!rst && ea)\n      for (int j = 0; j < MCOLS; j++) begin\n        int n;\n        n = 0;\n        for (int k = 0; k < NL; k++) n = n + int'(rxh[k][j]) + int'(rwh[k][j]);\n        if (n > 1) $fatal(1, \"otpu_mxu: several RMAX updates of column %0d in one cycle\", j);\n      end\n`endif\n\n  wire c_drained = c_act && !cl_ld && (pn || c_lz) && (rows_live == 0) && (rmw_n == 0) &&\n                   (ln_n == 0) && !rA.v && !r0.v && !r1.v && !rx.v && mq_h == '0;\n  // RMAX writes start a cycle after the head has drained: mx_q registers the test, so the\n  // drained compares (c_left == 0, rows_live, rmw_n, ...) are off the TMEM write request and the\n  // grant it feeds. The test holds while drained (nothing new enters the head until it\n  // completes, which needs mx_done), and it is false in the completing cycle (mx_done), so a new\n  // head never sees a stale mx_q.\n  logic mx_q;\n  // mx_go (mx_q && !mx_done) is a register of its own (mx_gq, r2.1): it starts the MXU's TMEM\n  // write request (the RMAX lanes), which the slice's write-bank arbiter turns into the grant;\n  // from mx_done through the request, the arbiter, the grant's read enables and the TMEM's\n  // replay logic was r2.1's m8 163ab46d's one failing path (-0.003 ns, 14 levels)\n  logic mx_gq;\n  wire mx_go     = mx_gq;\n`ifndef SYNTHESIS\n  always @(posedge clk) if (!rst && mx_gq != (mx_q && !mx_done))\n    $fatal(1, \"otpu_mxu: mx_gq %0d, mx_q %0d, mx_done %0d\", mx_gq, mx_q, mx_done);\n`endif\n  wire c_fin     = c_drained && (!c_rmax || mx_done || c_tz) && tq_n == 2'd0;\n  // the head completes (while the pop head may pop the next command's chunks)\n  wire c_done    = c_fin;\n  wire al_go     = c_act && c_asc && al_st == 2'd0;\n\n  // RMAX lanes (mx_i + k < c_M), registered as the drain's; next: mx_i + LANES. Their TMEM\n  // addresses h.mxo + mx_i + k are registered too (mxl, loaded from h.mxo while no RMAX write\n  // runs: mx_go is never set in a head's first cycle), so no adder precedes the write request\n  logic [LANES-1:0] mxm, mxm_nx;\n  logic [LANES-1:0][31:0] mxl;\n  always_comb for (int k = 0; k < LANES; k++) mxm_nx[k] = 32'(mx_i) + LANES + 32'(k) < 32'(c_M);\n`ifndef SYNTHESIS\n  always @(posedge clk) if (!rst && q_n != 0)\n    for (int k = 0; k < LANES; k++)\n      if (mxm[k] != (32'(mx_i) + 32'(k) < 32'(c_M)))\n        $fatal(1, \"otpu_mxu: RMAX lane %0d: mxm %0d, mx_i %0d, M %0d\", k, mxm[k], mx_i, c_M);\n  always @(posedge clk) if (!rst && mx_go)\n    for (int k = 0; k < LANES; k++)\n      if (mxl[k] != h.mxo + 32'(mx_i) + 32'(k))\n        $fatal(1, \"otpu_mxu: RMAX lane %0d address %0h, mxo %0h, mx_i %0d\", k, mxl[k], h.mxo, mx_i);\n`endif\n\n  // TMEM's input stage (release r2, docs/tmem_nocopy.md 7): the read request is a register\n  // (rq_*), a stage of the epilogue (it advances with ea), so no unit logic (the ASCALE\n  // addresses' adder and compare, the drain's lane mux) precedes TMEM's lane routing, ranks and\n  // block RAM pins; the word arrives a cycle after TMEM reads it (rA, al_st 3)\n  logic [LANES-1:0]       t_ren_c, rq_en;\n  logic [LANES-1:0][31:0] t_raddr_c, rq_ad;\n  logic [LANES-1:0]       tw_en;                 // this cycle's writes\n  logic [LANES-1:0][31:0] tw_ad, tw_d;\n  always_ff @(posedge clk)\n    if (rst) rq_en <= '0;\n    else if (ea) begin rq_en <= t_ren_c; rq_ad <= t_raddr_c; end\n  always_comb begin\n    t_ren_c = '0; t_raddr_c = '0; tw_en = '0; tw_ad = '0; tw_d = '0;\n    if (lo.v) begin\n      for (int k = 0; k < NL; k++) begin\n        if (c_acc) begin\n          t_ren_c[k] = lo.m[k];\n          t_raddr_c[k] = lo.ad[k];\n        end else begin\n          tw_en[k] = lo.m[k];\n          tw_ad[k] = lo.ad[k];\n          tw_d[k] = lo_y[k];\n        end\n      end\n    end\n    if (rw.v) begin\n      for (int k = 0; k < NL; k++) begin\n        if (rw.m[k]) begin\n          tw_en[k] = 1'b1;\n          tw_ad[k] = rw.ad[k];\n          tw_d[k] = ry[k];\n        end\n      end\n    end\n    // ASCALE factors and RMAX values move LANES words per cycle (consecutive words: distinct\n    // banks)\n    if (al_go) begin\n      for (int k = 0; k < LANES; k++) begin\n        if (32'(al_i) + 32'(k) < 32'(c_M)) begin\n          t_ren_c[k] = 1'b1;\n          t_raddr_c[k] = c_asa + 32'(al_i) + 32'(k);\n        end\n      end\n    end\n    if (mx_go) begin\n      for (int k = 0; k < LANES; k++) begin\n        if (mxm[k]) begin\n          tw_en[k] = 1'b1;\n          tw_ad[k] = mxl[k];\n          tw_d[k] = unkey(mk[MW'(32'(mx_i) + 32'(k))]);\n        end\n      end\n    end\n  end\n\n  // ---- the TMEM interface. The epilogue gives TMEM, at each advance, the read in the request\n  // register and this cycle's writes; it takes a read's word at the advance after the read's.\n  // TQ 0: the slice grants the MXU's read and write ports as one group, and the epilogue\n  // advances on the grant itself (ea = t_gnt), which reached every register of the epilogue in\n  // the cycle the slice decides it (the m8 card: ~11.3 k enables at the end of the arbitration;\n  // at a 150 MHz equivalent the MXU's worst paths, 720 endpoints within 0.2 ns).\n  // TQ 1 (the slice's MXU_TQ: TMEM_IMPL 3 with replays): the reads are not granted. TMEM reads\n  // what the MXU asks, as the VPU's (a read that loses a RAM is replayed the next cycle, t_lost),\n  // and the grant takes only the writes, which wait for it in a queue of three (s: flip-flops,\n  // the tail written every cycle it is free, so no grant or push reaches their enables; with\n  // the queue empty TMEM takes the writes as they are issued). ea is then a function of\n  // flip-flops, none of which the grant or t_lost reach in the cycle they decide: the room for\n  // one more beat's writes, counted without this cycle's pop (room_q), no replay pending\n  // (lost_q: the lost read's word comes the cycle after its replay), and, with a read in the\n  // request register, no write waiting (tq_z: a read never passes an older write; it is read\n  // with its advance's own writes, as one granted beat was). The request register is TMEM's\n  // read address as it was (no logic before TMEM's lane routing). The grant reaches the queue's\n  // counters only. A command completes once its writes have left the queue (c_fin).\n  assign t_raddr = rq_ad;\n  // a read's lanes by TMEM bank (bank b: the lane whose address's low bits are b; lanes of one\n  // read hit distinct banks or read one word, so the AND-OR merge is exact): otpu_tmem's crossbar\n  localparam int TBW = (TLANES > 1) ? $clog2(TLANES) : 1;\n  initial if (TLANES < LANES) $fatal(1, \"otpu_mxu: TLANES %0d < LANES %0d\", TLANES, LANES);\n  function automatic logic [TLANES-1:0] bk_en(input logic [LANES-1:0][31:0] ad,\n                                              input logic [LANES-1:0] en);\n    bk_en = '0;\n    for (int b = 0; b < TLANES; b++)\n      for (int l = 0; l < LANES; l++)\n        if (en[l] && (TLANES == 1 || ad[l][TBW-1:0] == TBW'(b))) bk_en[b] = 1'b1;\n  endfunction\n  function automatic logic [TLANES-1:0][31:0] bk_ad(input logic [LANES-1:0][31:0] ad,\n                                                    input logic [LANES-1:0] en);\n    bk_ad = '0;\n    for (int b = 0; b < TLANES; b++)\n      for (int l = 0; l < LANES; l++)\n        if (en[l] && (TLANES == 1 || ad[l][TBW-1:0] == TBW'(b))) bk_ad[b] = bk_ad[b] | ad[l];\n  endfunction\n  if (TQ) begin : g_tq\n    typedef struct packed {\n      logic [LANES-1:0]       wen;\n      logic [LANES-1:0][31:0] waddr;\n      logic [LANES-1:0][31:0] wdata;\n    } wbeat_t;\n    wbeat_t     s [3];                           // the waiting writes, a ring\n    wbeat_t     hd;                              // its head\n    logic [1:0] tq_h, tl;                        // the head's slot, the tail's (0..2)\n    (* max_fanout = 64 *) logic room_q, tq_z, lost_q;\n    logic       rq_any;                          // a read in the request register (|rq_en)\n    logic [LANES-1:0] t_ren_q;                   // the read TMEM sees: rq_en while room_q, tq_z\n    (* max_fanout = 128 *) wire ea_t = room_q && !lost_q && (tq_z || !rq_any);\n    wire        rd   = room_q && !lost_q && tq_z;  // the request register's read happens now\n    wire        iw   = ea_t && (|tw_en);           // writes issued\n    wire        take = tq_z && t_gnt;              // ... and taken as issued\n    wire        pop  = !tq_z && t_gnt;\n    wire        push = iw && !take;\n    wire [1:0]  tq_nn = tq_n + 2'(push) - 2'(pop);\n    assign ea = ea_t;\n    assign tl = (32'(tq_h) + 32'(tq_n) >= 3) ? 2'(32'(tq_h) + 32'(tq_n) - 3) : tq_h + tq_n;\n    assign hd = s[tq_h];\n    // TMEM's read enable is a register (its next value from rq_en's, room_q's and tq_z's: no LUT\n    // in front of TMEM's read selection, whose conflicts decide the other ports' replays; the\n    // m8 card at 150 MHz: room_q -> rd -> TMEM -> the VPU's hold, -0.041 ns). It leaves out\n    // lost_q: in a replay's cycle the read stays up and the slice does not read it (rpl_frz, as\n    // lost_q a register of TMEM's lost); the epilogue does not advance then, and reads it after\n    assign t_ren = t_ren_q;\n    // ... and by bank (t_rben / t_rbad, otpu_tmem PBR) from flip-flops too, decoded before the\n    // registers from their next values (rb_v / rb_a: the request register's banks and their\n    // lanes' addresses, loaded with rq_ad; rb_q: t_ren_q's banks), so TMEM's ranks, conflict\n    // compares and block RAM addresses start at flip-flops, not at the lanes' bank decode (r150c,\n    // the m8 card at a real 150 MHz: rq_ad -> the decode -> TMEM's compares -> lost_q, 11 levels,\n    // -0.007 ns; rq_ad and rpv -> the decode -> the pumped RAMs' read pins, +0.03 to +0.04)\n    logic [TLANES-1:0]       rb_v, rb_q;\n    logic [TLANES-1:0][31:0] rb_a;\n    assign t_rben = rb_q;\n    assign t_rbad = rb_a;\n    always_ff @(posedge clk) if (!rst && ea_t) rb_a <= bk_ad(t_raddr_c, t_ren_c);\n    assign t_wen = tq_z ? (ea_t ? tw_en : '0) : hd.wen;\n    assign t_waddr = tq_z ? tw_ad : hd.waddr;\n    assign t_wdata = tq_z ? tw_d : hd.wdata;\n    for (genvar i = 0; i < 3; i++) begin : g_s\n      always_ff @(posedge clk)\n        if (tq_n != 2'd3 && tl == 2'(i)) s[i] <= '{wen: tw_en, waddr: tw_ad, wdata: tw_d};\n    end\n    always_ff @(posedge clk)\n      if (rst) begin\n        tq_n <= '0; tq_h <= '0; tq_z <= 1'b1; room_q <= 1'b0; lost_q <= 1'b0; rq_any <= 1'b0;\n        t_ren_q <= '0; rb_v <= '0; rb_q <= '0;\n      end else begin\n        tq_n <= tq_nn;\n        tq_z <= tq_nn == 2'd0;\n        if (pop) tq_h <= (tq_h == 2'd2) ? 2'd0 : tq_h + 2'd1;\n        room_q <= 3'(tq_n) + 3'(iw) <= 3'd2;\n        lost_q <= t_lost;\n        if (ea_t) rq_any <= |t_ren_c;\n        t_ren_q <= (ea_t ? t_ren_c : rq_en) & {LANES{3'(tq_n) + 3'(iw) <= 3'd2 && tq_nn == 2'd0}};\n        if (ea_t) rb_v <= bk_en(t_raddr_c, t_ren_c);\n        rb_q <= (ea_t ? bk_en(t_raddr_c, t_ren_c) : rb_v) &\n                {TLANES{3'(tq_n) + 3'(iw) <= 3'd2 && tq_nn == 2'd0}};\n      end\n`ifndef SYNTHESIS\n    bit rst_seen;                                // (registers start arbitrary)\n    initial rst_seen = 1'b0;\n    always @(posedge clk) if (rst) rst_seen <= 1'b1;\n    always @(posedge clk)\n      if (!rst && rst_seen) begin\n        if (push && tq_n == 2'd3) $fatal(1, \"otpu_mxu: TMEM write queue overflow\");\n        if (rq_any != (|rq_en)) $fatal(1, \"otpu_mxu: rq_any is not the request register's\");\n        if (tq_z != (tq_n == 2'd0)) $fatal(1, \"otpu_mxu: tq_z is not the queue's\");\n        if ((|t_ren) && !tq_z) $fatal(1, \"otpu_mxu: a read passes a waiting write\");\n        if (t_ren_q != (rq_en & {LANES{room_q && tq_z}}))\n          $fatal(1, \"otpu_mxu: t_ren_q is not the request register's read\");\n        // the read by bank is the request register's, decoded\n        if (rb_v != bk_en(rq_ad, rq_en)) $fatal(1, \"otpu_mxu: rb_v is not the request register's banks\");\n        if (rb_q != bk_en(rq_ad, t_ren_q)) $fatal(1, \"otpu_mxu: rb_q is not t_ren_q's banks\");\n        for (int b = 0; b < TLANES; b++)\n          if (rb_v[b] && rb_a[b] != bk_ad(rq_ad, rq_en)[b])\n            $fatal(1, \"otpu_mxu: rb_a[%0d] %0h is not the request register's %0h\", b, rb_a[b],\n                   bk_ad(rq_ad, rq_en)[b]);\n        // TMEM loses only a read the MXU asked this cycle (and the slice took) or its replay\n        if (t_lost && !((|t_ren) && rd) && !lost_q) $fatal(1, \"otpu_mxu: TMEM lost a read not asked\");\n      end\n`endif\n  end else begin : g_ng\n    assign ea = t_gnt;\n    assign t_ren = rq_en, t_wen = tw_en, t_waddr = tw_ad, t_wdata = tw_d;\n    assign t_rben = bk_en(rq_ad, rq_en), t_rbad = bk_ad(rq_ad, rq_en);\n    assign tq_n = '0;              // (a lost read: the slice holds the grant for its replay)\n  end\n\n  // ASCALE factors: alpha takes the words every cycle they are there (al_st 3), not only at the\n  // advance that moves al_st on. TMEM holds the MXU's read data until its next read (r1's xo\n  // takes it there too; TQ: a lost read's lanes are wrong for a cycle, and the replay's word is\n  // there by the advance) and al_i moves only with the advance, so after it alpha is what it was;\n  // alpha is read (alr) only with the advance, and no ASCALE row is in r0 while it loads (drain_go\n  // waits for al_st 2). Its MCOLS x 32 enables are off the grant's fan-out (the m8 card at a 150\n  // MHz equivalent: 90 of the grant net's 127 failing endpoints). One write per entry (a constant\n  // index): a variable-index write of several lanes makes Vivado try, and crash while\n  // dissolving, a RAM for these MCOLS registers\n  always_ff @(posedge clk)\n    if (!rst && al_st == 2'd3)\n      for (int j = 0; j < MCOLS; j++)\n        if (32'(j) >= 32'(al_i) && 32'(j) < 32'(al_i) + LANES)\n          alpha[j] <= t_rdata[$clog2(LANES)'(32'(j) - 32'(al_i))];\n`ifndef SYNTHESIS\n  // alpha_g: as loaded at the grant only (the old enables); the factor a row reads is its value\n  logic [31:0] alpha_g [MCOLS];\n  always_ff @(posedge clk)\n    if (!rst && ea && al_st == 2'd3)\n      for (int j = 0; j < MCOLS; j++)\n        if (32'(j) >= 32'(al_i) && 32'(j) < 32'(al_i) + LANES)\n          alpha_g[j] <= t_rdata[$clog2(LANES)'(32'(j) - 32'(al_i))];\n  always @(posedge clk)\n    if (!rst && ea && r0.v && c_asc)\n      for (int k = 0; k < NL; k++)\n        if (r0.m[k] && alpha[r0.col[k][MW-2:0]] != alpha_g[r0.col[k][MW-2:0]])\n          $fatal(1, \"otpu_mxu: ASCALE factor %0d is %h, at the grant %h\", r0.col[k][MW-2:0],\n                 alpha[r0.col[k][MW-2:0]], alpha_g[r0.col[k][MW-2:0]]);\n`endif\n\n  // ---- statistics for the profiler (per completed command): cycles the stream was starved\n  // (work, no chunk), backpressured (chunks, no consumption), the drain frozen by the TMEM grant,\n  // the issuer denied a DRAM port. The conditions are registered (st_c) and summed a cycle\n  // late, off the grant paths: a command's count is st + g, g the last cycle's pending bit (none\n  // after a command's end: that cycle's conditions belong to no command).\n  logic [31:0] st_starve, st_bp, st_frz, st_deny;\n  logic [3:0]  st_c, st_g;                  // {deny, frz, bp, starve}\n  logic        st_f;                        // the last cycle ended a command\n  assign st_g = st_f ? 4'd0 : st_c;\n\n  // the issuer's next line compares (on the next addresses, registered)\n  function automatic logic same_line(input logic [31:0] a, input logic [31:0] b);\n    return a[31:5] == b[31:5];\n  endfunction\n\n  always_ff @(posedge clk) begin\n    done <= 1'b0;\n    pf_u <= 1'b0;\n    if (rst) begin\n      i_act <= 1'b0; i_ini <= 1'b0;\n      q_n <= '0; pn <= 1'b0; rows_p <= '0;\n      occ <= '0; tg_n <= '0; tg_t <= '0; tg_h <= '0;\n      f_head <= '0; f_tail <= '0; f_count <= '0; f_rd <= '0; f_tl <= '0; f_rdl <= '0;\n      s_head <= '0; s_tail <= '0; s_count <= '0; s_rd <= '0;\n      ck <= '0; cg <= '0; dg <= '0; dg1 <= 8'd1; c_left <= '0; c_lz <= 1'b1; cl_ld <= 1'b0; rows_live <= '0;\n      rf_q <= '0; rf_hs <= 1'b0; rf_t <= '0; rf_n <= '0; rf_nz <= 1'b0; rl_nz <= 1'b0;\n      dj <= '0; mx_done <= 1'b0; mx_have <= '0; mq_h <= '0;\n      d_last <= 1'b0; d_fin <= 1'b0; ncnt <= '0; dln <= '0; mxm <= '0;\n      al_st <= 2'd0; al_i <= '0; mx_i <= '0;\n      r0 <= '0; rA <= '0; rx <= '0; rmw_n <= '0; ln_n <= '0;\n      st_starve <= '0; st_bp <= '0; st_frz <= '0; st_deny <= '0;\n      st_c <= '0; st_f <= 1'b0; mx_q <= 1'b0; mx_gq <= 1'b0;\n    end else begin\n      logic [1:0] qn;\n      logic [RFW:0] rn;\n      logic [RFW:0] rl, rp;\n      qent_t hn, nn;                            // the entries' next values (before a swap)\n      qent_t hp, np;                            // the same without this cycle's accept (pop_q's:\n                                                // a command accepted this cycle is not popped\n                                                // before cl_ld, which reloads pop_q)\n      logic pnx;\n      qn = q_n;\n      rn = rf_n;\n      rl = rows_live;\n      rp = rows_p;\n      hn = h;\n      nn = n;\n      hp = h;\n      np = n;\n      pnx = pn;\n      cl_ld <= 1'b0;\n      if (cl_ld) begin c_left <= h.total; c_lz <= h.tz; end\n      // ---- accept a command (the head if the queue is empty, else the next entry); the issuer\n      // loads its addresses in the next cycle (i_ini)\n      if (start) begin\n        if (q_n == 0) begin\n          hn = cmd_e;                             // becomes the head now\n          cl_ld <= 1'b1;\n        end else nn = cmd_e;\n        qn = qn + 1;\n        if (!cmd_tz) begin\n          i_ini  <= 1'b1;\n          i_left <= cmd_total;\n          i_KB   <= cmd_KBa;\n          i_rs   <= cmd.w5;\n          i_srs  <= cmd.w7;\n          i_unit <= cmd.flags[0];\n          i_rsc  <= cmd.flags[7] && !cmd.flags[0];\n          i_wf   <= cmd.flags[5:4];\n          i_w4   <= (cmd.flags[5:4] != WF_W8);\n          i_pair <= cmd_pair;\n          i_k0   <= cmd.w4[31:24];\n          row_addr <= cmd.w1; chunk_addr <= cmd.w1;\n          srow_addr <= cmd.w2;\n        end\n      end\n      if (i_ini) begin\n        logic [31:0] so, sa, sn;\n        logic [4:0]  ss;\n        case (i_wf)\n          WF_W8: begin so = 32'd4 + 32'(i_k0); ss = 5'd1; end\n          WF_NV: begin so = 32'd16 + {21'd0, i_k0, 3'd0}; ss = i_pair ? 5'd16 : 5'd8; end\n          default: begin so = 32'd8 + {22'd0, i_k0, 2'd0}; ss = i_pair ? 5'd8 : 5'd4; end\n        endcase\n        sa = srow_addr + so;\n        sn = srow_addr + i_srs;\n        i_ini <= 1'b0;\n        i_act <= 1'b1;\n        i_k <= '0;\n        i_klast <= (i_KB == 16'd1);\n        i_l1 <= (i_left == 32'd1);\n        i_soff <= so;\n        i_sstep <= ss;\n        scale_addr <= sa;\n        srow_next <= sn;\n        i_swd <= 1'b0;\n        i_swh <= same_line(srow_addr, sa);\n        i_swn <= same_line(sa, sn);\n        i_sws <= !i_unit && !i_rsc && !same_line(srow_addr, sa);\n      end\n      // ---- release (in order): the head if not yet released, else the second entry\n      if (go) begin\n        if (q_n != 0 && !h.go) begin\n          hn.go = 1'b1; hp.go = 1'b1;\n        end else begin\n          nn.go = 1'b1; np.go = 1'b1;\n        end\n      end\n      // ---- issue: the row's Sw line alone, or one advance (a chunk and its line)\n      if (go_iss) begin\n        if (i_sws) begin\n          i_swd <= 1'b1;\n          i_sws <= 1'b0;\n        end else begin\n          i_left <= i_left - 1;\n          i_l1 <= (i_left == 32'd2);\n          if (i_left == 1) i_act <= 1'b0;\n          if (i_klast) begin\n            logic [31:0] sa, sn;\n            sa = srow_next + i_soff;\n            sn = srow_next + i_srs;\n            i_k <= '0;\n            i_klast <= (i_KB == 16'd1);\n            row_addr <= row_addr + i_rs;\n            chunk_addr <= row_addr + i_rs;\n            srow_addr <= srow_next;\n            srow_next <= sn;\n            scale_addr <= sa;\n            // the next row's Sw came with this line, or is in its first advance's, or needs a\n            // request of its own\n            i_swd <= a_tag.swr;\n            i_swh <= same_line(srow_next, sa);\n            i_swn <= same_line(sa, sn);\n            i_sws <= !i_unit && !i_rsc && !a_tag.swr && !same_line(srow_next, sa);\n          end else begin\n            logic [31:0] sa;\n            sa = scale_addr + 32'(i_sstep);\n            i_k <= i_k + 1;\n            i_klast <= (i_k + 16'd2 == i_KB);\n            // 4-bit: two blocks per chunk (PAIR: both in one advance)\n            if (!i_w4 || i_pair || i_k[0]) chunk_addr <= chunk_addr + D;\n            scale_addr <= sa;\n            i_swn <= same_line(sa, srow_next);\n          end\n        end\n      end\n      // ---- FIFO pushes\n      if (b_rvalid) begin\n        f_tail <= f_tail + 1;\n        for (int g = 0; g < FG; g++) f_tl[g] <= f_tl[g] + 1;\n      end\n      if (a_req) tg_t <= tg_t + 1'b1;\n      if (a_rvalid) tg_h <= tg_h + 1'b1;\n      tg_n <= tg_n + (a_req ? 1'b1 : 1'b0) - (rv1 ? 1'b1 : 1'b0);\n      if (r_cpl) s_tail <= s_tail + 1'b1;\n      f_count <= f_count + (b_rvalid ? 1 : 0) - (fpop ? 1 : 0);\n      occ <= occ + (b_req ? 1'b1 : 1'b0) - (fpop ? 1'b1 : 1'b0);\n      s_count <= s_count + (r_cpl ? 1 : 0) - ((fpop && !c_unit) ? 1 : 0);\n      // ---- pop one advance (the row's last group frees its chunk and scale entry)\n      if (fpop) begin\n        f_head <= f_head + 1;\n        if (!c_unit) s_head <= s_head + 1;\n      end\n      if (pop) begin\n        if (last_g) begin c_left <= c_left - 1; c_lz <= (c_left == 32'd1); end\n        // the next read: the next entry, or back to the head for the row's next group\n        if (last_k && !last_g) begin\n          f_rd <= f_head;\n          f_rdl <= {FG{f_head}};\n          if (!c_unit) s_rd <= s_head;\n        end else if (cdone) begin\n          f_rd <= f_rd + 1;\n          for (int g = 0; g < FG; g++) f_rdl[g] <= f_rdl[g] + 1;\n          if (!c_unit) s_rd <= s_rd + 1;\n        end\n        if (ck == 0) begin\n          if (!pn) rl = rl + 1;\n          else rp = rp + 1;\n        end\n        ck <= last_k ? '0 : ck + 1;\n        if (last_k) cg <= last_g ? '0 : cg + 1;\n      end\n      // ---- a finished row enters the result FIFO\n      if (rf_push) begin\n        rf_t <= rf_t + 1;\n        rn = rn + 1;\n      end\n      // ---- RMAX: the stage's keys into the running max (every cycle), the advance's hits into it\n      for (int j = 0; j < MCOLS; j++) begin\n        if (mx_upd[j]) mk[j] <= mq_k[j];\n        if (mq_h[j]) mx_have[j] <= 1'b1;\n      end\n      mq_h <= ea ? mx_hit : '0;\n      // ---- drain (holds while the epilogue does not advance)\n      if (ea) begin\n        r0 <= rA;\n        rA <= '0;\n        rx <= '0;\n        if (lo.v) begin\n          if (c_acc) begin\n            rA.v <= 1'b1;\n            rA.m <= lo.m;\n            rA.ad <= lo.ad;\n            for (int k = 0; k < NL; k++) rA.nv[k] <= lo_y[k];\n            rA.col <= lo.col;\n          end\n          if (c_rmax && !c_acc) begin\n            rx.v <= 1'b1;\n            rx.m <= lo.m;\n            for (int k = 0; k < NL; k++) rx.nv[k] <= lo_y[k];\n            rx.col <= lo.col;\n          end\n        end\n        if (drain_go) begin\n          if (drain_row_done) begin\n            dj <= '0;\n            if (d_last) begin                       // the next weight row, group 0\n              dg <= '0; dg1 <= 8'd1;\n              for (int j = 0; j < MCOLS; j++) begin\n                logic [31:0] a;\n                a = drow[j] + 32'd1;\n                dad[j] <= a;\n                drow[j] <= a;\n                if (j < NL) dal[j] <= a;\n              end\n            end else begin                          // the next group of this row\n              dg <= dg + 8'd1; dg1 <= dg1 + 8'd1;\n              for (int j = 0; j < MCOLS; j++) begin\n                logic [31:0] a;\n                a = dad[j] + h.gs;\n                dad[j] <= a;\n                if (j < NL) dal[j] <= a;\n              end\n            end\n            rn = rn - 1;\n            rl = rl - 1;\n          end else begin\n            dj <= dj + ncnt;\n            dal <= dlane_a(dad, dj + ncnt);\n          end\n        end\n        rmw_n <= rmw_n + ((lo.v && c_acc) ? 4'd1 : 4'd0) - (rw.v ? 4'd1 : 4'd0);\n        ln_n <= ln_n + (drain_go ? 4'd1 : 4'd0) - (lo.v ? 4'd1 : 4'd0);\n        if (mx_go) begin\n          if (32'(mx_i) + LANES >= 32'(c_M)) mx_done <= 1'b1;\n          else mx_i <= mx_i + 8'(LANES);\n        end\n        if (al_go) al_st <= 2'd1;\n        if (al_st == 2'd1) al_st <= 2'd3;     // the read leaves the request register\n        if (al_st == 2'd3) begin               // (the words into alpha: below)\n          if (32'(al_i) + LANES >= 32'(c_M)) al_st <= 2'd2;\n          else begin\n            al_i <= al_i + 8'(LANES);\n            al_st <= 2'd0;\n          end\n        end\n      end\n      rf_n <= rn;\n      rf_q <= rf_q + RFW'(rf_hs);\n      rf_hs <= d_pop;\n      // RMAX lane addresses: they advance with mx_i while the writes run, else h.mxo + k\n      for (int k = 0; k < LANES; k++)\n        if (!mx_go) mxl[k] <= h.mxo + 32'(k);\n        else if (ea && 32'(mx_i) + LANES < 32'(c_M)) mxl[k] <= mxl[k] + 32'(LANES);\n      rows_live <= rl;\n      rows_p <= rp;\n      // rn != 0, rl != 0 from the counts' own zero / one tests: the grant enters last\n      rf_nz <= rf_push || (rf_nz && !(rf_n == 1 && d_pop));\n      rl_nz <= (pop && ck == 0 && !pn) || (rl_nz && !(rows_live == 1 && d_pop));\n      // the pop head moves to the next command once the head's chunks have all popped, if the\n      // pipeline treats both alike (PAIR, and M under PAIR: pr0, hi0 and M0 are read late)\n      if (!pn && !cl_ld && c_lz && q_n == 2'd2 && n.go && !c_done &&\n          n.pair == h.pair && (!h.pair || n.M == h.M)) begin\n        pnx = 1'b1;\n        c_left <= n.total;\n        c_lz <= n.tz;\n      end\n      // ---- statistics\n      st_c <= {want_iss && !go_iss, !ea && (drain_go || lo.v || rw.v || mx_go || al_go),\n               more && f_count != 0 && !pop, more && f_count == 0};\n      st_f <= c_done;\n      mx_q <= c_drained && c_rmax && !mx_done && !c_tz;\n      // mx_q's next value and mx_done's (set by the last RMAX lanes' grant; a completing head\n      // clears it, and then mx_q's next is low: it completes only with mx_done or c_tz)\n      mx_gq <= c_drained && c_rmax && !mx_done && !c_tz &&\n               !(ea && mx_go && 32'(mx_i) + LANES >= 32'(c_M));\n      st_starve <= st_starve + 32'(st_g[0]);\n      st_bp <= st_bp + 32'(st_g[1]);\n      st_frz <= st_frz + 32'(st_g[2]);\n      st_deny <= st_deny + 32'(st_g[3]);\n      // ---- the consumer's command is complete\n      if (c_done) begin\n        done <= 1'b1;\n        qn = qn - 1;\n        dg <= '0; dg1 <= 8'd1;\n        if (!pn) begin                            // the pop head moves along\n          ck <= '0; cg <= '0;\n          // the next head's chunk count: the queued entry's, or (cl_ld) the total of a command\n          // accepted this cycle, a cycle later\n          c_left <= (q_n == 2'd2) ? n.total : '0;\n          c_lz <= (q_n == 2'd2) ? n.tz : 1'b1;\n          if (start && q_n == 2'd1) cl_ld <= 1'b1;\n        end else begin                            // it already runs the next command: its rows\n          rows_live <= rp;\n          rl_nz <= (rp != 0);\n          rows_p <= '0;\n        end\n        pnx = 1'b0;                               // the next command is both heads now\n        dj <= '0;\n        for (int j = 0; j < MCOLS; j++) begin\n          logic [31:0] a;\n          a = (start && q_n == 2'd1) ? cmd.w3 + 32'(j) * 32'(cmd.w6[15:0]) : n.out + n.jo[j];\n          dad[j] <= a;\n          drow[j] <= a;\n          if (j < NL) dal[j] <= a;\n        end\n        mx_done <= 1'b0; mx_have <= '0;\n        al_st <= 2'd0; al_i <= '0; mx_i <= '0;\n        pf_u <= 1'b1;\n        pf_uv <= {st_deny + 32'(st_g[3]), st_frz + 32'(st_g[2]), st_bp + 32'(st_g[1]),\n                  st_starve + 32'(st_g[0])};\n        st_starve <= '0; st_bp <= '0; st_frz <= '0; st_deny <= '0;\n      end\n      // the head's output base (set when a command becomes head)\n      if (start && q_n == 0) begin\n        for (int j = 0; j < MCOLS; j++) begin\n          logic [31:0] a;\n          a = cmd.w3 + 32'(j) * 32'(cmd.w6[15:0]);\n          dad[j] <= a;\n          drow[j] <= a;\n          if (j < NL) dal[j] <= a;\n        end\n      end\n      // the entries: completing the head swaps them (the next entry, or the command accepted\n      // this cycle, becomes the head; the old head stays in n)\n      begin\n        qent_t hx, nx, hpx, npx;\n        if (c_done) begin\n          hx = nn; nx = hn; hpx = np; npx = hp;\n        end else begin\n          hx = hn; nx = nn; hpx = hp; npx = np;\n        end\n        h <= hx; n <= nx;\n        // the drain's next step: a new head starts at its first row's group 0 (all of it if the\n        // row is one group); a drain step moves on in the group, or to the next group / row\n        if (c_done || (start && q_n == 0)) begin\n          logic [MW:0] st;\n          st = hx.g1 ? {hx.dfl, hx.dnl} : dstep(MW'(MCOLS), hx.run);\n          d_last <= hx.g1;\n          {d_fin, ncnt} <= st;\n          dln <= dlanes(st[MW-1:0]);\n          for (int k = 0; k < LANES; k++) mxm[k] <= 32'(k) < 32'(hx.M);\n        end else begin\n          if (ea && drain_go) begin\n            if (!d_fin) begin\n              {d_fin, ncnt} <= st_mid;\n              dln <= ln_mid;\n            end else begin\n              d_last <= d_nl;\n              {d_fin, ncnt} <= st_grp;\n              dln <= ln_grp;\n            end\n          end\n          if (ea && mx_go && 32'(mx_i) + LANES < 32'(c_M)) mxm <= mxm_nx;\n        end\n        // the pop head's entry, from the entries, not from the command being accepted: a\n        // command that becomes the head as it is accepted gets its entry a cycle later (cl_ld;\n        // the pipeline is empty then, and nothing pops before c_left loads)\n        pop_q <= pnx ? npx : hpx;\n      end\n      pn <= pnx;\n      q_n <= qn;\n    end\n  end\n`ifndef SYNTHESIS\n  // the head / next mapping relies on the rdy contract (start only with a free entry); the tags\n  // in flight never exceed TD (the issuer waits), nor the scale entries the chunk slots\n  always @(posedge clk) if (!rst) begin\n    if (start && q_n >= 2'd2) $fatal(1, \"otpu_mxu: start with %0d commands queued\", q_n);\n    if (start && (i_act || i_ini)) $fatal(1, \"otpu_mxu: start while the issuer streams\");\n    if (q_n != 0 && !cl_ld && pop_q != (pn ? n : h))\n      $fatal(1, \"otpu_mxu: pop_q is not the pop head's entry\");\n    if (32'(tg_n) > TD) $fatal(1, \"otpu_mxu: %0d port A requests in flight\", tg_n);\n    if (32'(s_count) > DEPTH) $fatal(1, \"otpu_mxu: scale FIFO overflow (%0d)\", s_count);\n    if (rv1 && tg_n == 0) $fatal(1, \"otpu_mxu: a port A response without a request\");\n  end\n`endif\n\nendmodule\n\n// A shared epilogue lane (docs/mx_mxu.md 4): one result a cycle, once per output:\n//   v  = i2f48(x)            round to nearest even (|x| < 2^47: normal or zero, no overflow)\n//   y  = (v * sw) * sa       two otpu_fmul (sa: Sa * 2^-W, already scaled)\n// Latency 4 + 2 LM: |x| | leading zeros | normalize | round | x sw (LM) | x sa (LM). Every\n// register advances with en (the MXU's TMEM grant).\nmodule otpu_mx_lane\n  import otpu_fp::*;\n#(parameter int LM = 2) (\n  input  logic         clk,\n  input  logic         en,\n  input  logic [47:0]  x,\n  input  f32_t         sw,\n  input  f32_t         sa,\n  output f32_t         y\n);\n  function automatic logic [5:0] lzc48(input logic [47:0] m);\n    if (m[47:16] != 0) return lzc32(m[47:16]);\n    return 6'd32 + 6'(lzc32({m[15:0], 16'd0}));\n  endfunction\n  logic        s1, z1, s2, z2, s3, z3;\n  logic [47:0] g1, g2, g3;\n  logic [5:0]  lz2, lz3;\n  f32_t        fv;\n  always_ff @(posedge clk) if (en) begin\n    // L1: sign, magnitude\n    s1 <= x[47];\n    z1 <= (x == 0);\n    g1 <= x[47] ? (~x + 48'd1) : x;\n    // L2: leading zeros\n    s2 <= s1; z2 <= z1; g2 <= g1;\n    lz2 <= lzc48(g1);\n    // L3: normalize (the leading one at bit 47)\n    s3 <= s2; z3 <= z2; lz3 <= lz2;\n    g3 <= g2 << lz2;\n    // L4: round to 24 bits, nearest even\n    begin\n      logic [23:0] mm;\n      logic [24:0] mr;\n      logic g, st;\n      logic [8:0] e;\n      e = 9'd174 - 9'(lz3);                     // 127 + 47 - lz\n      mm = g3[47:24];\n      g = g3[23];\n      st = |g3[22:0];\n      mr = {1'b0, mm} + ((g && (st || mm[0])) ? 25'd1 : 25'd0);\n      if (mr[24]) e = e + 9'd1;                 // mr == 2^24: its fraction bits are 0\n      fv <= z3 ? F_ZERO : {s3, e[7:0], mr[22:0]};\n    end\n  end\n  f32_t swd, sad, y1;\n  otpu_delay #(.W(32), .N(4)) u_sw (.clk, .en, .d(sw), .q(swd));\n  otpu_delay #(.W(32), .N(4 + LM)) u_sa (.clk, .en, .d(sa), .q(sad));\n  otpu_fmul #(.LAT(LM)) u_m1 (.clk, .en, .a(fv), .b(swd), .y(y1));\n  otpu_fmul #(.LAT(LM)) u_m2 (.clk, .en, .a(y1), .b(sad), .y);\nendmodule\n\n// Simple dual-port block RAM, registered read with enable (read-first: a read of the word\n// written at the same edge returns the old word).\nmodule otpu_ram_sdp #(parameter int W = 32, parameter int N = 1024) (\n  input  logic                 clk,\n  input  logic                 we,\n  input  logic [$clog2(N)-1:0] wa,\n  input  logic [W-1:0]         wd,\n  input  logic                 re,\n  input  logic [$clog2(N)-1:0] ra,\n  output logic [W-1:0]         rd\n);\n  (* ram_style = \"block\" *) logic [W-1:0] mem [N];\n  always_ff @(posedge clk) if (we) mem[wa] <= wd;\n  always_ff @(posedge clk) if (re) rd <= mem[ra];\nendmodule\n\n// N-cycle delay line with an enable: no reset and no forced last flip-flop (unlike otpu_delay), so\n// a long one maps to shift-register LUTs and its last stage may move into a DSP48's input register\n// (the systolic MXU's operand skews)\nmodule otpu_skew #(parameter int W = 8, parameter int N = 1) (\n  input  logic         clk,\n  input  logic         en,\n  input  logic [W-1:0] d,\n  output logic [W-1:0] q\n);\n  if (N == 0) begin : g_wire\n    assign q = d;\n  end else begin : g_regs\n    logic [W-1:0] r [N];\n    always_ff @(posedge clk) if (en) begin\n      r[0] <= d;\n      for (int k = 1; k < N; k++) r[k] <= r[k-1];\n    end\n    assign q = r[N-1];\n  end\nendmodule\n", "rtl/seq/otpu_seq.sv": "// Sequencer: fetches and decodes one instruction per cycle. NOP, LI, ADDI and LOOP execute\n// here; every other instruction has its register-relative fields resolved and is dispatched,\n// in program order, into a window of WIN slots together with its memory footprint.\n//\n// Scoreboard: at dispatch, the new instruction records which in-flight instructions it\n// conflicts with (RAW, WAR or WAW on any TMEM, DRAM or ACT RAM range). Each cycle every free\n// unit starts its OLDEST instruction whose dependencies have all completed -- not necessarily\n// its oldest instruction: an instruction that conflicts with an older one never becomes ready\n// before it, so starting younger independent work early is always safe. Units therefore\n// overlap freely (and fill each other's bubbles) while the results stay exactly those of\n// sequential execution (docs/isa.md). Each unit completes in start order. HALT waits for the\n// window to drain.\n//\n// The MXU is special in two ways: it starts its instructions strictly in order, and in two\n// phases. It may start streaming an MM from DRAM as soon as the MM's DRAM dependencies are\n// clear (ustart), and it may consume the stream once all dependencies are clear (urel). Deep\n// prefetch therefore overlaps the stream with whatever produces the MM's stationary operand.\n//\n// RLD (docs/isa.md) is dispatched like a unit instruction (to the collective unit, whose slice\n// reads the TMEM word itself); R then holds the next instruction until the value comes back\n// (rl_v): younger instructions may use R[rd] in their addresses and LOOP counts. The hold\n// (rl_wait) is a flip-flop, so the fetch-enable path only gains one registered term. HALT with\n// flag CHAIN reports R[ra] (the program's DRAM address) and R[rb] (its instructions) with the\n// halt (ch_*): the slice reloads IMEM from there and restarts (otpu_slice).\n//\n// IMEM is a synchronous RAM (FPGA block RAM) of rows of IPR = D/32 instructions -- one DRAM\n// chunk, so the slice's loader writes one row per cycle. It is read one instruction ahead, at\n// fa: the exact pc that R moves to next (computed from flip-flops only). When R moves on, the\n// instruction at fa is registered into ir, so no R-stage path starts at the RAM output. This\n// costs one cycle at the program start (ir is empty after reset).\nmodule otpu_seq\n  import otpu_pkg::*;\n#(\n  parameter int IMEM_WORDS = 1 << 16,\n  parameter int TMEM_WORDS = 1 << 16,\n  parameter int SID        = 0,\n  parameter int S          = 1,\n  parameter int D          = 32,\n  parameter int WIN        = 16,\n  parameter bit STREAMS    = 1'b1,    // the stream engine (otpu_slice HAS_SS); 0: DSTEP and STREAM\n                                      //   are illegal instructions (ERROR), not a wait for SE\n  // EXPERIMENTAL (docs/seq_vpu.md, docs/isa.md \"Wait counts\"): WAITC 1 takes the dependencies\n  // from a wait entry the compiler writes beside each instruction instead of comparing\n  // footprints: per in-order unit (DMA, MXU, QUANT, COLL) a 4-bit count k (0: no wait, else\n  // until the unit's k-th last instruction before this one has completed; and the MM's stream\n  // start's k for the DMA and the quantizer), and for the VPU, which starts its oldest ready\n  // instruction, a mask of the VPU instructions 1..31 back it waits for. No footprints, no range\n  // compares. 0: today's scoreboard.\n  parameter bit WAITC      = 1'b0\n) (\n  input  logic                clk,\n  input  logic                rst,\n  output cmd_t                ucmd   [NUNITS],\n  output logic [NUNITS-1:0]   ustart,\n  output logic                urel,        // MXU: release the oldest started, unreleased MM\n  input  logic [NUNITS-1:0]   urdy,\n  input  logic [NUNITS-1:0]   udone,\n  output logic                halted,\n  output logic                error,\n  output logic [31:0]         icount,\n  output seq_ev_t             ev,          // trace and activity events, a cycle late (otpu_pkg)\n  input  logic [31:0]         rinit  [8],  // R8..R15 while in reset: the run's arguments\n  input  logic                rl_v,        // RLD's value is back: R[rd] = rl_val\n  input  logic [31:0]         rl_val,\n  output logic                ch_req,      // the halt is a HALT CHAIN: to ch_addr, ch_n\n  output logic [31:0]         ch_addr,\n  output logic [31:0]         ch_n,\n  // IMEM write port (the loader; used while the slice is held in reset)\n  input  logic                im_we,\n  input  logic [31:0]         im_row,\n  input  logic [D*8-1:0]      im_data,\n  // WAITC: the wait entries' write port (the loader: a row of 4 64-bit entries as they are in\n  // DRAM, instructions 4 * sc_row .. 4 * sc_row + 3)\n  input  logic                sc_we,\n  input  logic [31:0]         sc_row,\n  input  logic [255:0]        sc_data\n);\n  localparam int SW = $clog2(WIN);\n  localparam int IPR = D / 32;                   // instructions per IMEM row\n  localparam int NROW = IMEM_WORDS / (8 * IPR);\n  localparam int RW = $clog2(NROW);\n  initial if (D % 32 != 0) $fatal(1, \"otpu_seq: D must be a multiple of 32\");\n  logic [D*8-1:0] irow;           // the RAM output: the row holding fa\n  logic [255:0]   ir;             // the instruction at pc\n  logic           ir_v;           // ir is valid (0 only in the first cycle after reset)\n  logic [31:0]    fa, fa_d;       // the pc R moves to next; its next value\n  logic [31:0]    fa_n;           // fa's next value when it moves (the RAM address)\n  logic           fe;             // fa moves (the RAM's read enable; otherwise it keeps fa's row)\n  logic           ld;             // R moves on to the instruction at fa\n\n  logic [31:0] pc, cyc;\n  logic [31:0] R [16];\n  logic        stopping;         // HALT fetched: wait for the window to drain\n  logic        rl_wait;          // an RLD is out: R holds until its value is back\n  logic [3:0]  rl_rd;\n\n  // loop stack\n  logic [2:0]  sp;\n  logic [31:0] stk_start [4];\n  logic [31:0] stk_end   [4];\n  logic [31:0] stk_rem   [4];\n  // LOOP takes two cycles: the first registers the trip count and body length (pc holds), the\n  // second enters or skips the loop from registers -- keeps the add off the fetch-address path\n  logic        lp;\n  logic [31:0] lp_cnt, lp_len;\n\n  // The footprint as the window keeps it: ranges stored by space, so ranges in different\n  // spaces, and two reads, are never compared. No valid bits: an invalid range has hi = 0,\n  // which overlaps nothing (b.lo < 0 is false) -- exactly ov()'s v terms. Routing (fp_seg):\n  //   LD:     d[0] = rd0          t0 = wr0 W\n  //   ST:     d[0] = wr0 (dw)     t0 = rd0\n  //   DSTEP:  d[0] = wr0 (dw)     t0 = wr1 W, t1 = rd0, t2 = rd1, t3 = rd2\n  //   STREAM: d = wr0, wr2 (dw)   t0 = wr1 W, t1 = rd0, t2 = rd1, t3 = rd2, t4 = rd3\n  //   MM:     d = rd0, rd1        t0 = hull(wr0, wr1) W (RMAX), t2 = rd3 (ASCALE), a = rd2\n  //   QACT:                       t0 = rd0, t1 = rd1 (CSCALE), t2 = rd2 (RSCALE), a = wr0 W\n  //   QST:    d = wr0, wr1 (dw)   t0 = rd0\n  //   VOP:                        t0 = wr0 W, t1 = rd0, t2 = rd1, t3 = rd2 (OUTER)\n  //   GATHER:                     t0 = wr0 W, t1 = rd0\n  // Only t0 may be written, so a footprint pair has 9 TMEM range pairs to compare. MM's RMAX\n  // (the row maxima, the spare row after the output tile) is folded into its output range: the\n  // hull [min lo, max hi) covers both, so every dependency on either is kept (ovr() is monotone\n  // in the range); it adds only the output tile's padding words between them (ors - N).\n  // An instruction's DRAM ranges are all reads or all writes, hence one dw bit. ACT ranges\n  // start below 2^8 (an 8-bit field) and are at most 2^16 - 1 long, so [alo, ahi) is exact.\n  // TMEM ranges keep TAW/TAW+1 bits: TMEM holds 2^16 words (more in a configuration with a\n  // larger TMEM: TAW follows it), so every access the ISA allows has lo < 2^TAW, hi <= 2^TAW.\n  // A valid TMEM range that does not fit raises all instead (the instruction then conflicts\n  // with everything, like BAR) -- conservative, never wrong.\n  localparam int TAW = (TMEM_WORDS > (1 << 16)) ? $clog2(TMEM_WORDS) : 16;\n  typedef struct packed { logic [31:0] lo, hi; } r32_t;\n  typedef struct packed { logic [TAW-1:0] lo; logic [TAW:0] hi; } rt_t;\n  typedef struct packed { logic w; rt_t r; } rtw_t;     // TMEM, may be written\n  typedef struct packed {\n    logic            all;\n    logic            dw;        // the DRAM ranges are writes\n    r32_t  [1:0]     d;         // DRAM\n    rtw_t            t0;        // TMEM, the only range that may be written\n    rt_t             t1;        // TMEM, always a read\n    rt_t             t2;        // TMEM, always a read\n    rt_t             t3;        // TMEM, always a read\n    rt_t             t4;        // TMEM, always a read (STREAM's constants)\n    logic            aw;        // ACT\n    logic [7:0]      alo;\n    logic [16:0]     ahi;\n  } fps_t;\n\n  function automatic r32_t r32(input rng_t x);\n    r32_t o;\n    o.lo = x.lo; o.hi = x.v ? x.hi : '0;\n    return o;\n  endfunction\n\n  function automatic rt_t rt(input rng_t x);\n    rt_t o;\n    o.lo = x.lo[TAW-1:0]; o.hi = x.v ? x.hi[TAW:0] : '0;\n    return o;\n  endfunction\n\n  // the TMEM range does not fit rt_t\n  function automatic logic tovf(input rng_t x);\n    return x.v && (x.lo[31:TAW] != '0 || x.hi[31:TAW+1] != '0);\n  endfunction\n\n  // the smallest range covering a and b (an invalid one, hi = 0, covers nothing)\n  function automatic rt_t hull(input rt_t a, input rt_t b);\n    rt_t o;\n    if (b.hi == '0) o = a;\n    else if (a.hi == '0) o = b;\n    else begin\n      o.lo = (b.lo < a.lo) ? b.lo : a.lo;\n      o.hi = (b.hi > a.hi) ? b.hi : a.hi;\n    end\n    return o;\n  endfunction\n\n  function automatic fps_t fp_seg(input logic [7:0] op, input fp_t f);\n    fps_t s;\n    rng_t a, t0, t1, t2, t3, t4, h;  // ACT; TMEM t0, t1, t2, t3, t4; MM's RMAX (into t0)\n    logic w0;\n    s = '0; a = '0; t0 = '0; t1 = '0; t2 = '0; t3 = '0; t4 = '0; h = '0; w0 = 1'b0;\n    case (op)\n      OP_LD: begin\n        s.d[0] = r32(f.rd[0]); t0 = f.wr[0]; w0 = 1'b1;\n      end\n      OP_ST: begin\n        s.dw = 1'b1; s.d[0] = r32(f.wr[0]); t0 = f.rd[0];\n      end\n      OP_DSTEP, OP_STREAM: begin   // (DSTEP's wr2 is empty)\n        s.dw = 1'b1; s.d[0] = r32(f.wr[0]); s.d[1] = r32(f.wr[2]);\n        t0 = f.wr[1]; w0 = 1'b1; t1 = f.rd[0]; t2 = f.rd[1]; t3 = f.rd[2]; t4 = f.rd[3];\n      end\n      OP_MM: begin\n        s.d[0] = r32(f.rd[0]); s.d[1] = r32(f.rd[1]);\n        t0 = f.wr[0]; w0 = 1'b1; h = f.wr[1]; t2 = f.rd[3];\n        a = f.rd[2];\n      end\n      OP_QACT: begin\n        t0 = f.rd[0]; t1 = f.rd[1]; t2 = f.rd[2];\n        s.aw = 1'b1; a = f.wr[0];\n      end\n      OP_QST: begin\n        s.dw = 1'b1; s.d[0] = r32(f.wr[0]); s.d[1] = r32(f.wr[1]);\n        t0 = f.rd[0];\n      end\n      OP_VOP: begin\n        t0 = f.wr[0]; w0 = 1'b1; t1 = f.rd[0]; t2 = f.rd[1]; t3 = f.rd[2];\n      end\n      OP_GATHER: begin\n        t0 = f.wr[0]; w0 = 1'b1; t1 = f.rd[0];\n      end\n      OP_RLD: t0 = f.rd[0];\n      OP_WAITW: begin\n        s.dw = 1'b1; s.d[0] = r32(f.wr[0]); t0 = f.wr[1]; w0 = 1'b1;\n      end\n      default: ;   // BAR: all\n    endcase\n    s.all = f.all || tovf(t0) || tovf(t1) || tovf(t2) || tovf(t3) || tovf(t4) || tovf(h);\n    s.t0.w = w0; s.t0.r = hull(rt(t0), rt(h));\n    s.t1 = rt(t1);\n    s.t2 = rt(t2);\n    s.t3 = rt(t3);\n    s.t4 = rt(t4);\n    s.alo = a.lo[7:0]; s.ahi = a.v ? a.hi[16:0] : '0;\n    return s;\n  endfunction\n\n  function automatic logic ovr(input r32_t a, input r32_t b);\n    return a.lo < b.hi && b.lo < a.hi;\n  endfunction\n\n  // ovr() on narrow TMEM ranges\n  function automatic logic ovr_t(input rt_t a, input rt_t b);\n    return {1'b0, a.lo} < b.hi && {1'b0, b.lo} < a.hi;\n  endfunction\n\n  // {conflict, conflict_dram} (otpu_pkg) on segregated footprints: the same-space pairs with at\n  // least one write -- 4 DRAM, 9 TMEM (t0 x t0; t0 x t1..t4 both ways) and 1 ACT range pair\n  function automatic logic [1:0] conf_s(input fps_t n, input fps_t e);\n    logic any, dram;\n    any = n.all || e.all; dram = any;\n    for (int i = 0; i < 2; i++)\n      for (int j = 0; j < 2; j++)\n        if ((n.dw || e.dw) && ovr(n.d[i], e.d[j])) begin any = 1'b1; dram = 1'b1; end\n    if ((n.t0.w || e.t0.w) && ovr_t(n.t0.r, e.t0.r)) any = 1'b1;\n    if (n.t0.w && (ovr_t(n.t0.r, e.t1) || ovr_t(n.t0.r, e.t2) || ovr_t(n.t0.r, e.t3) ||\n                   ovr_t(n.t0.r, e.t4))) any = 1'b1;\n    if (e.t0.w && (ovr_t(n.t1, e.t0.r) || ovr_t(n.t2, e.t0.r) || ovr_t(n.t3, e.t0.r) ||\n                   ovr_t(n.t4, e.t0.r))) any = 1'b1;\n    if ((n.aw || e.aw) && {9'd0, n.alo} < e.ahi && {9'd0, e.alo} < n.ahi) any = 1'b1;\n    return {any, dram};\n  endfunction\n\n`ifndef SYNTHESIS\n  // ---- EXPERIMENTAL (docs/seq_vpu.md): emulations of cheaper hazard checks, simulation only.\n  // Plusargs (the defaults are today's check, and change nothing):\n  //   +hz_tg=G / +hz_dg=G  TMEM / DRAM ranges widened to 2^G-word / -byte granules (lo down, hi\n  //                        up): a check on the ranges' top bits only, or region busy bits\n  //   +hz_rh=1             an instruction's TMEM reads as one range (their hull): 3 TMEM range\n  //                        pairs to compare instead of 9;  +hz_dh=1: its DRAM ranges as one\n  //   +hz_win=N            N window slots used;  +hz_uq=a:b:c:d:e: at most that many slots per\n  //                        unit (DMA, MXU, QUANT, VPU, COLL; 0: no cap): per-unit queues\n  //   +hz_ino=1            every unit starts its instructions in program order (as the MXU and the\n  //                        collective unit do today);  +hz_inom=M: only the units of mask M (bit u:\n  //                        unit u; 1 DMA, 4 QUANT, 8 VPU)\n  //   +hz_rob=1            window slots are freed in program order (a reorder buffer)\n  //   +hz_wc=FILE          with +hz_ino: the dependencies from per-pc wait counts (FILE, written by\n  //                        +hz_kout) instead of the ranges: wait until at most k_u - 1 of the\n  //                        instruction's older unit-u instructions are outstanding\n  //   +hz_kout=FILE        write the wait counts: per pc and unit, the least rank (1 = the unit's\n  //                        last instruction) of an older instruction it conflicts with, over the\n  //                        pc's dynamic instances (the compiler's static view, no loop peeling)\n  //   +hz_wcvx=X           with +hz_wc: a VPU producer's dependencies exact (the ranges) instead\n  //                        of its count: X = 1 for every consumer, 2 for a VPU consumer only (the\n  //                        VPU<-VPU case), 3 for the other units' consumers only\n  //   +hz_kclamp=K         with +hz_wc: each count clamped to K (fewer bits a field: K = 1 is a\n  //                        bit per unit, \"wait for all its older instructions\")\n  //   +hz_kc=1             the oracle on the window's (coarsened) footprints: a compiler that\n  //                        knows the ranges only to the granules of +hz_tg / +hz_dg\n  //   +hz_log=FILE         hazard statistics at the end of the run (stall cycles by unit and by\n  //                        what they wait for, dependencies by class and kind, rank histograms)\n  int  hz_tg = 0, hz_dg = 0, hz_win = 0, hz_kclamp = 0, hz_inom = 0, hz_wcvx = 0;\n  bit  hz_rh = 0, hz_dh = 0, hz_ino = 0, hz_rob = 0, hz_wc = 0, hz_cs = 0, hz_kc = 0;\n  int  hz_uq [NUNITS];\n  initial begin\n    string s;\n    void'($value$plusargs(\"hz_tg=%d\", hz_tg));\n    void'($value$plusargs(\"hz_dg=%d\", hz_dg));\n    void'($value$plusargs(\"hz_win=%d\", hz_win));\n    void'($value$plusargs(\"hz_kclamp=%d\", hz_kclamp));\n    void'($value$plusargs(\"hz_wcvx=%d\", hz_wcvx));\n    hz_kc = $test$plusargs(\"hz_kc=1\");\n    hz_rh = $test$plusargs(\"hz_rh=1\");\n    hz_dh = $test$plusargs(\"hz_dh=1\");\n    hz_ino = $test$plusargs(\"hz_ino=1\");\n    void'($value$plusargs(\"hz_inom=%d\", hz_inom));\n    if (hz_inom != 0) hz_ino = 1'b1;\n    else if (hz_ino) hz_inom = (1 << U_DMA) | (1 << U_Q) | (1 << U_VPU);\n    hz_rob = $test$plusargs(\"hz_rob=1\");\n    for (int u = 0; u < NUNITS; u++) hz_uq[u] = 0;\n    if ($value$plusargs(\"hz_uq=%s\", s))\n      void'($sscanf(s, \"%d:%d:%d:%d:%d\", hz_uq[0], hz_uq[1], hz_uq[2], hz_uq[3], hz_uq[4]));\n    hz_cs = hz_tg > 0 || hz_dg > 0 || hz_rh || hz_dh;\n  end\n  fps_t           c_fpx;                    // C's footprint as fp_seg makes it (the oracle's)\n  logic [WIN-1:0] sdone;                    // +hz_rob: completed, the slot not yet freed\n  logic [WIN-1:0] wc_dep, wc_depd;          // +hz_wc: the dependencies the wait counts give\n\n  // a TMEM range out to 2^g-word granules (hi stays within TAW+1 bits: TMEM ends on a granule)\n  function automatic rt_t hz_gt(input rt_t r, input int g);\n    rt_t o;\n    logic [TAW+1:0] m, h;\n    o = r;\n    if (r.hi != '0 && g > 0) begin\n      m = (g >= TAW) ? {1'b0, {(TAW + 1){1'b1}}} : (TAW + 2)'((64'd1 << g) - 1);\n      h = ({1'b0, r.hi} + m) & ~m;\n      o.lo = r.lo & ~TAW'(m);\n      o.hi = h[TAW+1] ? {1'b1, {TAW{1'b0}}} : h[TAW:0];\n    end\n    return o;\n  endfunction\n\n  function automatic r32_t hz_gd(input r32_t r, input int g);\n    r32_t o;\n    logic [63:0] m, h;\n    o = r;\n    if (r.hi != '0 && g > 0) begin\n      m = (64'd1 << g) - 1;\n      h = ({32'd0, r.hi} + m) & ~m;\n      o.lo = r.lo & ~m[31:0];\n      o.hi = (h > 64'hFFFF_FFFF) ? 32'hFFFF_FFFF : h[31:0];\n    end\n    return o;\n  endfunction\n\n  function automatic r32_t hz_hull32(input r32_t a, input r32_t b);\n    r32_t o;\n    if (b.hi == '0) o = a;\n    else if (a.hi == '0) o = b;\n    else begin\n      o.lo = (b.lo < a.lo) ? b.lo : a.lo;\n      o.hi = (b.hi > a.hi) ? b.hi : a.hi;\n    end\n    return o;\n  endfunction\n`endif\n\n  // the footprint as the window keeps it: fp_seg's, or (simulation) a cheaper check's superset\n  function automatic fps_t hz_coarse(input fps_t s);\n    fps_t o;\n    o = s;\n`ifndef SYNTHESIS\n    if (hz_rh) begin\n      rt_t h;\n      h = hull(hull(s.t1, s.t2), hull(s.t3, s.t4));\n      if (!s.t0.w) begin h = hull(h, s.t0.r); o.t0.r = '0; end\n      o.t1 = h; o.t2 = '0; o.t3 = '0; o.t4 = '0;\n    end\n    if (hz_dh) begin o.d[0] = hz_hull32(s.d[0], s.d[1]); o.d[1] = '0; end\n    if (hz_tg > 0) begin\n      o.t0.r = hz_gt(o.t0.r, hz_tg); o.t1 = hz_gt(o.t1, hz_tg); o.t2 = hz_gt(o.t2, hz_tg);\n      o.t3 = hz_gt(o.t3, hz_tg); o.t4 = hz_gt(o.t4, hz_tg);\n    end\n    if (hz_dg > 0) begin o.d[0] = hz_gd(o.d[0], hz_dg); o.d[1] = hz_gd(o.d[1], hz_dg); end\n`endif\n    return o;\n  endfunction\n\n  // window\n  logic [WIN-1:0]  sv;                       // slot valid (dispatched, not completed)\n  logic [WIN-1:0]  older [WIN];              // older[i][j]: slot j was dispatched before slot i\n  logic [NUNITS-1:0] soh [WIN];              // the slot's unit, one-hot\n  logic [WIN-1:0]  sstarted, sready;\n  logic [WIN-1:0]  sdep [WIN];               // sdep[i][j]: slot i waits for slot j\n  logic [WIN-1:0]  sdepd [WIN];              // the DRAM part of sdep (MXU stream start)\n  logic [WIN-1:0]  srel;                     // MXU: released\n  logic [SW:0]     uq_r;                     // MXU: next started slot to release\n  fps_t            sfp  [WIN];\n  logic [31:0]     srdy_c [WIN];\n  // per-unit queues of started slot ids, in start (= completion) order\n  logic [SW-1:0]   uq [NUNITS][WIN];\n  logic [SW:0]     uq_h [NUNITS], uq_t [NUNITS];\n\n  // ---- fetch: the row holding fa_d is read at the clock edge that makes it fa; ir takes the\n  // instruction at fa at the edge that makes fa pc\n  // The RAM reads fa_n on the cycles fa moves (fe) and holds fa's row otherwise: the decision\n  // whether R moves on (the dispatch, from the window) reaches the read enable, not the\n  // address multiplexer (the sequencer's worst path at 125 MHz ran window -> ld -> address)\n  // IMEM: a technology RAM (rtl/tech), one row write (the loader) and one row read per cycle\n  otpu_ram_1r1w #(.W(D*8), .N(NROW), .STYLE(\"auto\"), .ZERO(1'b0)) u_imem (\n    .clk, .we(im_we), .wa(RW'(im_row)), .wd(im_data), .re(fe), .ra(RW'(fa_n / IPR)), .rd(irow));\n  always_ff @(posedge clk) begin\n    fa <= fa_d;\n    if (rst) ir_v <= 1'b0;\n    else if (ld) begin\n      ir <= irow[256 * (fa % IPR) +: 256];\n      ir_v <= 1'b1;\n    end\n  end\n  // WAITC: the sidecar RAM of wait entries, read beside IMEM: rows of 4 entries of SWW bits\n  // (the counts' 28, the VPU mask's VMW; 1024 x 236 bits for a 4096-instruction IMEM). The\n  // loader writes a row from 4 entries as they are in DRAM (64 bits each: the counts' word,\n  // then the mask's)\n  localparam int VMW = 31;        // the VPU mask: the VPU instructions 1..VMW back\n  localparam int SWW = 28 + VMW;\n  localparam int NSROW = IMEM_WORDS / 32;\n  localparam int SRW = $clog2(NSROW);\n  logic [SWW-1:0] ir_sync;        // the wait entry of the instruction at pc\n  if (WAITC) begin : g_sync\n    logic [4*SWW-1:0] srow, sc_pk;\n    logic         sc_off;         // simulation: +hz_sync's entries stay (the loader's are dropped)\n`ifdef SYNTHESIS\n    assign sc_off = 1'b0;\n`endif\n    always_comb\n      for (int e = 0; e < 4; e++)\n        sc_pk[SWW * e +: SWW] = {sc_data[64 * e + 32 +: VMW], sc_data[64 * e +: 28]};\n    otpu_ram_1r1w #(.W(4 * SWW), .N(NSROW), .STYLE(\"auto\"), .ZERO(1'b0)) u_sync (\n      .clk, .we(sc_we && !sc_off), .wa(SRW'(sc_row)), .wd(sc_pk), .re(fe),\n      .ra(SRW'(fa_n / 4)), .rd(srow));\n    always_ff @(posedge clk) if (!rst && ld) ir_sync <= srow[SWW * (fa % 4) +: SWW];\n`ifndef SYNTHESIS\n    // simulation: the wait entries from +hz_sync_s<SID>=FILE or +hz_sync=FILE (lines \"pc k0 ..\n    // k6 n [mask]\": opentpu.waits' with the VPU mask; +hz_kout's, the oracle's, without: the\n    // mask is then the VPU instructions k3 .. VMW back), each count clamped to +hz_kclamp; an\n    // instruction the file does not name waits for every unit's last instruction and the\n    // VPU's VMW. With a file the loader's entries (boot, HALT CHAIN) are dropped\n    initial begin\n      string fn, ln;\n      int fd, pc, r, n, kc, mk;\n      int k [7];\n      kc = 0;\n      fn = \"\";\n      void'($value$plusargs(\"hz_kclamp=%d\", kc));\n      for (int rr = 0; rr < NSROW; rr++)\n        for (int w = 0; w < 4; w++) u_sync.g_auto.mem[rr][SWW * w +: SWW] = {{VMW{1'b1}}, 28'h111_1111};\n      if (!$value$plusargs($sformatf(\"hz_sync_s%0d=%%s\", SID), fn))\n        void'($value$plusargs(\"hz_sync=%s\", fn));\n      sc_off = (fn != \"\");\n      if (fn != \"\") begin\n        fd = $fopen(fn, \"r\");\n        if (fd == 0) $fatal(1, \"otpu_seq: +hz_sync=%s: cannot open\", fn);\n        while ($fgets(ln, fd) != 0) begin\n          mk = -1;\n          r = $sscanf(ln, \"%d %d %d %d %d %d %d %d %d %d\", pc, k[0], k[1], k[2], k[3], k[4],\n                      k[5], k[6], n, mk);\n          if (r >= 8 && pc >= 0 && pc < IMEM_WORDS / 8) begin\n            logic [SWW-1:0] wd;\n            wd = '0;\n            for (int j = 0; j < 7; j++)\n              wd[4 * j +: 4] = 4'((kc > 0 && k[j] > kc) ? kc : (k[j] > 15) ? 15 : k[j]);\n            if (r >= 10) wd[28 +: VMW] = VMW'(mk);\n            else if (k[3] > 0) wd[28 +: VMW] = {VMW{1'b1}} << ((k[3] > 15 ? 15 : k[3]) - 1);\n            u_sync.g_auto.mem[pc / 4][SWW * (pc % 4) +: SWW] = wd;\n          end\n        end\n        $fclose(fd);\n      end\n    end\n`endif\n  end else begin : g_nosync\n    assign ir_sync = '0;\n  end\n  logic [31:0] iw [8];\n  always_comb for (int k = 0; k < 8; k++) iw[k] = ir[32 * k +: 32];\n  wire [7:0] op    = iw[0][7:0];\n  wire [3:0] ra    = iw[0][11:8];\n  wire [3:0] rb    = iw[0][15:12];\n  wire [3:0] rc    = iw[0][19:16];\n  wire [3:0] rd    = iw[0][23:20];\n  wire [7:0] flags = iw[0][31:24];\n\n  function automatic logic [31:0] rv(input logic [3:0] r);\n    return (r == 0) ? 32'd0 : R[r];\n  endfunction\n\n  // STREAM: src (w2) and dst (w3) += R[ra], vec (w4) += R[rb], x (w5) += R[rc], k (w6) += R[rd].\n  // The others: w1 += R[ra], w2 += R[rb] and w3 += R[rc] where docs/isa.md writes the field as\n  // R[x] + w; the counts and shapes there are immediates: QACT's w2 (rows, ab, KB) and w3 (srs),\n  // LD's and ST's w3 (n), GATHER's w3 (rows, cols) (the enables decode the opcode beside the\n  // register reads)\n  cmd_t dcmd;\n  wire  is_str = (op == OP_STREAM);\n  wire  rel2 = (op != OP_QACT);\n  wire  rel3 = !(op == OP_QACT || op == OP_LD || op == OP_ST || op == OP_GATHER);\n  always_comb begin\n    dcmd.op = op; dcmd.flags = flags;\n    dcmd.w1 = iw[1] + (is_str ? 32'd0 : rv(ra));\n    dcmd.w2 = iw[2] + (is_str ? rv(ra) : rel2 ? rv(rb) : 32'd0);\n    dcmd.w3 = iw[3] + (is_str ? rv(ra) : rel3 ? rv(rc) : 32'd0);\n    dcmd.w4 = iw[4] + (is_str ? rv(rb) : 32'd0);\n    dcmd.w5 = iw[5] + (is_str ? rv(rc) : 32'd0);\n    dcmd.w6 = iw[6] + (is_str ? rv(rd) : 32'd0);\n    dcmd.w7 = iw[7] + ((op == OP_VOP) ? rv(rd) : 32'd0);        // VOP: w7 += R[rd]\n  end\n  int dunit;\n  always_comb dunit = (!STREAMS && (op == OP_DSTEP || op == OP_STREAM)) ? -1 : unit_of(op);\n\n  // ---- dispatch pipeline: R (the instruction at pc: registers resolved) -> P (footprint\n  // partial products) -> S (products) -> Q (footprint ranges) -> C (dependencies on the window,\n  // slot allocation). In order; a stage holds while the next cannot take its instruction (C:\n  // the window is full). The stages stream, so they add latency only at the program start.\n  logic        p_v, s_v, q_v, c_v;\n  cmd_t        p_cmd, s_cmd, q_cmd, c_cmd;\n  logic [2:0]  p_unit, s_unit, q_unit, c_unit;\n  logic [31:0] p_pc, s_pc, q_pc, c_pc;\n  fpp_t        s_pp;\n  fpm_t        q_pr;\n  fp_t         q_fp;             // Q's footprint ranges (otpu_pkg form)\n  fps_t        c_fp;\n  logic        have_free;\n  logic        wc_hold;          // WAITC: a VPU instruction waits for the one VMW back\n  wire         c_go = c_v && have_free && !wc_hold;\n  wire         q_adv = !c_v || c_go;            // Q hands its instruction to C\n  wire         s_adv = !q_v || q_adv;           // S hands its instruction to Q\n  // P hands its instruction to S (WAITC: to C, no footprint stages)\n  wire         p_adv = WAITC ? (!c_v || c_go) : (!s_v || s_adv);\n  logic [SWW-1:0] p_sync, c_sync;               // WAITC: the instruction's wait entry\n  wire         r_take = !p_v || p_adv;          // P can take the instruction at R\n  wire         pipe_empty = !p_v && !s_v && !q_v && !c_v;\n  // R retires a control instruction this cycle (NOP, HALT, LI, ADDI, a LOOP's second cycle)\n  logic        r_ret;\n\n  // ---- completions this cycle\n  logic [WIN-1:0] fin;\n  always_comb begin\n    fin = '0;\n    for (int u = 0; u < NUNITS; u++)\n      if (udone[u]) fin[uq[u][uq_h[u][SW-1:0]]] = 1'b1;\n  end\n\n  // ---- free slot and the new instruction's dependencies\n  logic [SW-1:0]   free_slot;\n  logic [WIN-1:0]  ndep, ndepd;\n  always_comb q_fp = fp_ranges(q_cmd, q_pr, D, S);\n  always_comb begin\n    have_free = 1'b0; free_slot = '0;\n    for (int i = WIN - 1; i >= 0; i--)\n      if (!sv[i]) begin have_free = 1'b1; free_slot = SW'(i); end\n    for (int i = 0; i < WIN; i++) begin\n      logic [1:0] cf;\n      cf = conf_s(c_fp, sfp[i]);\n      ndep[i] = sv[i] && !fin[i] && cf[1];\n      ndepd[i] = sv[i] && !fin[i] && cf[0];\n    end\n`ifndef SYNTHESIS\n    // the emulations: window / per-unit caps, the reorder buffer's held slots, wait counts\n    begin\n      int n, nu;\n      n = 0; nu = 0;\n      for (int i = 0; i < WIN; i++) begin\n        n += int'(sv[i]);\n        nu += int'(sv[i] && c_unit < NUNITS && soh[i][c_unit]);\n      end\n      if ((hz_win > 0 && n >= hz_win) ||\n          (c_unit < NUNITS && hz_uq[c_unit] > 0 && nu >= hz_uq[c_unit]))\n        have_free = 1'b0;\n      if (hz_rob) begin ndep &= ~sdone; ndepd &= ~sdone; end\n      if (hz_wc) begin ndep = wc_dep; ndepd = wc_depd; end\n    end\n`endif\n    if (WAITC) begin ndep = '0; ndepd = '0; end   // the wait counts instead (w_all, w_dram)\n  end\n\n  // ---- WAITC: per unit, its instructions dispatched (wd_n) and, the in-order units, completed\n  // (wc_n: each completes its instructions in program order); per slot the counts its waits\n  // need: wait j (j < NUNITS: unit j; 5, 6: the DMA's and the quantizer's for an MM's stream\n  // start) holds until wc_n of its unit reaches wt (its producer's index + 1; the counters wrap,\n  // so the test is on the sign of the difference: a slot's target stays within WIN of the\n  // count). The unit's own wait is ignored: the unit starts in order. The VPU starts its oldest\n  // ready instruction and completes them out of order: a slot's VPU producers are a mask over\n  // the VPU instructions outstanding (vout, by index mod VMW + 1), cleared as each completes. A\n  // VPU instruction is dispatched once the one VMW before it has completed (wc_hold), so every\n  // older one has (each younger one's dispatch waited for its own), and a mask of VMW names\n  // every one a later instruction may wait for. A VPU instruction's slot is freed when it\n  // completes, so younger ones pass an old one blocked on its producers: the hold binds when\n  // VMW of them have (docs/seq_vpu.md 4.5: VMW 15 cost up to 0.8% of prefill; 31 nothing on\n  // the runs measured)\n  localparam int CW = 8;\n  localparam int NWT = NUNITS + 2;\n  logic [CW-1:0]    wd_n [NUNITS], wc_n [NUNITS];\n  localparam int VN = VMW + 1;                // VPU indices kept (mod VN)\n  localparam int VIW = $clog2(VN);\n  logic [VN-1:0]    vout;                     // VPU instructions outstanding (index mod VN)\n  logic [VN-1:0]    vpend [WIN];              // a slot's VPU producers still outstanding\n  logic [VIW-1:0]   vix [WIN];                // a VPU slot's index mod VN\n  logic [VN-1:0]    v_fin;                    // the VPU's completion this cycle (index mod VN)\n  // vout at the next VPU instruction's index VMW back (wd_n + 1 mod VN), a flip-flop loaded with\n  // its next value (vout's, at wd_n's next): wc_hold, so the dispatch (c_go -> P -> R's advance\n  // -> the loop counters' enables, pc) starts at it, not at a 32:1 select of vout by wd_n (the m8\n  // card at 150 MHz: vout -> wc_hold -> c_go -> stk_rem's enables, 9 levels, -0.063 ns)\n  logic             vnx_q;\n  logic [CW-1:0]    wt [WIN][NWT];\n  logic [NWT-1:0]   wv [WIN];\n  logic [WIN-1:0]   w_all, w_dram;            // the slot's waits (all / the stream's) are met\n  // ... registered (release r2): what the starts, the MXU's release and the ready stamp test.\n  // The counts' compares (wc_n - wt per slot and wait) end at these flip-flops instead of\n  // running on through the start selection into every unit's command register (r2m4, 133.33\n  // MHz: wc_n -> g_cmd q, 358 endpoints, -0.482 ns, 11.5 levels, 16% of core_clk's TNS). A wait\n  // is released a cycle after its count is reached. A slot's readiness only rises while it holds\n  // its instruction (the counts and the VPU mask only move towards its targets), so last cycle's\n  // is never wrong for this one, except for the slot written this cycle: its flag clears, and\n  // an instruction starts two cycles after its dispatch at the earliest\n  logic [WIN-1:0]   w_all_q, w_dram_q;\n`ifndef SYNTHESIS\n  // EXPERIMENTAL, simulation only (docs/seq_vpu.md): +wc_vx=1 takes a slot's VPU producers from\n  // today's range check (fp_seg, conf_s: vxd) instead of its mask; +wc_vgate=G holds a VOP\n  // until the one G back has completed instead of VMW (G = 0: never; G > VMW or 0 only with\n  // +wc_vx, the mask names VMW)\n  bit             wc_vx = 1'b0;\n  int             wc_vg = VMW;\n  logic [WIN-1:0] vxd [WIN];\n  fps_t           sfpx [WIN];\n  logic [CW-1:0]  vxi [WIN];\n  initial begin\n    wc_vx = $test$plusargs(\"wc_vx=1\");\n    void'($value$plusargs(\"wc_vgate=%d\", wc_vg));\n    if ((wc_vg == 0 || wc_vg > VMW) && !wc_vx)\n      $fatal(1, \"otpu_seq: +wc_vgate=%0d needs +wc_vx=1\", wc_vg);\n  end\n`endif\n  function automatic int wunit(input int j);\n    return (j < NUNITS) ? j : (j == NUNITS) ? U_DMA : U_Q;\n  endfunction\n  always_comb begin\n    v_fin = '0;\n    if (udone[U_VPU]) v_fin[vix[uq[U_VPU][uq_h[U_VPU][SW-1:0]]]] = 1'b1;\n    wc_hold = WAITC && c_unit == U_VPU && vnx_q;\n`ifndef SYNTHESIS\n    if (wc_vg != VMW) begin\n      wc_hold = 1'b0;\n      if (WAITC && c_unit == U_VPU && wc_vg > 0)\n        for (int j = 0; j < WIN; j++)\n          if (sv[j] && soh[j][U_VPU] && CW'(wd_n[U_VPU] - vxi[j]) >= CW'(wc_vg)) wc_hold = 1'b1;\n    end\n`endif\n  end\n`ifndef SYNTHESIS\n  bit vnx_seen;                                // a reset seen (registers start arbitrary)\n  initial vnx_seen = 1'b0;\n  always @(posedge clk) if (rst) vnx_seen <= 1'b1;\n  always @(posedge clk)\n    if (WAITC && !rst && vnx_seen && vnx_q != vout[VIW'(wd_n[U_VPU] + 1'b1)])\n      $fatal(1, \"otpu_seq: vnx_q %0d is not vout[%0d]\", vnx_q, VIW'(wd_n[U_VPU] + 1'b1));\n`endif\n  always_comb\n    for (int i = 0; i < WIN; i++) begin\n      logic [NWT-1:0] ok;\n      for (int j = 0; j < NWT; j++) begin\n        logic [CW-1:0] df;\n        df = wc_n[wunit(j)] - wt[i][j];\n        ok[j] = !wv[i][j] || !df[CW-1];\n      end\n      w_all[i] = &ok[NUNITS-1:0] && vpend[i] == '0;\n`ifndef SYNTHESIS\n      if (wc_vx) w_all[i] = &ok[NUNITS-1:0] && vxd[i] == '0;\n`endif\n      w_dram[i] = ok[NUNITS] && ok[NUNITS+1];\n    end\n  always_ff @(posedge clk)\n    if (rst) begin\n      w_all_q <= '0;\n      w_dram_q <= '0;\n    end else begin\n      w_all_q <= w_all & ~(c_go ? WIN'(1) << free_slot : '0);\n      w_dram_q <= w_dram & ~(c_go ? WIN'(1) << free_slot : '0);\n    end\n\n  // ---- loop-end handling for the instruction at pc\n  logic        at_end;\n  always_comb at_end = (sp != 0) && (stk_end[sp-1] == pc);\n\n  task automatic advance();\n    if (at_end) begin\n      if (stk_rem[sp-1] > 1) stk_rem[sp-1] <= stk_rem[sp-1] - 1;\n      else sp <= sp - 1;\n    end\n  endtask\n\n  always_comb\n    r_ret = ir_v && !stopping && !halted && !rl_wait &&\n            (op == OP_NOP || op == OP_HALT || op == OP_LI || op == OP_ADDI ||\n             (op == OP_LOOP && lp));\n\n  // ---- the next fetch address (mirrors the fetch/dispatch below). fa is the successor of pc\n  // under the loop stack as it stands while R holds pc; when R moves on, fa_d is the successor\n  // of fa under the stack as R's instruction leaves it:\n  //   A: a LOOP's second cycle pushes (fa == pc + 1 then) -- a one-instruction body repeats\n  //   B: advance() at a loop end decrements the top      -- repeats if the top keeps rem > 1\n  //   C: advance() at a loop end pops                    -- the next entry decides\n  //   D: the stack is unchanged (also the load after reset and a skipped LOOP)\n  // A LOOP's first cycle picks the enter/skip target a cycle ahead (pc holds, the RAM reads it).\n  logic        adv;              // R's instruction retires or is handed over this cycle\n  logic        hit1, hit2;       // fa ends the loop on top of the stack / the one below it\n  logic        hit;              // fa's successor is a loop start ...\n  logic [31:0] hit_pc;           // ... this one\n  logic        lp_z;             // the LOOP's trip count (R[ra] + iw[2]) is 0\n  logic [31:0] lp_a;\n  logic [31:0] succ;\n  always_comb begin\n    case (op)\n      OP_NOP, OP_LI, OP_ADDI: adv = 1'b1;\n      OP_HALT: adv = 1'b0;\n      OP_LOOP: adv = lp;\n      default: adv = dunit >= 0 && r_take;\n    endcase\n    ld = !ir_v || (!stopping && !halted && !rl_wait && adv);\n    hit1 = (sp != 0) && (stk_end[sp-1] == fa);\n    hit2 = (sp >= 2) && (stk_end[sp-2] == fa);\n    hit = hit1 && stk_rem[sp-1] > 1;                                          // D\n    hit_pc = stk_start[sp-1];\n    if (ir_v && op == OP_LOOP) begin\n      if (lp_cnt != 0) begin hit = lp_len == 1 && lp_cnt > 1; hit_pc = fa; end  // A\n    end else if (ir_v && at_end) begin\n      if (stk_rem[sp-1] > 1) hit = hit1 && stk_rem[sp-1] > 2;                // B\n      else begin hit = hit2 && stk_rem[sp-2] > 1; hit_pc = stk_start[sp-2]; end // C\n    end\n    succ = hit ? hit_pc : fa + 1;\n    // a + b == 0 without the carry chain: every sum bit is 0 iff a ^ b is the carry, (a | b) << 1\n    lp_a = rv(ra);\n    lp_z = (lp_a ^ iw[2]) == ((lp_a | iw[2]) << 1);\n    if (rst) fa_n = '0;\n    else if (ir_v && op == OP_LOOP && !lp) fa_n = lp_z ? pc + 1 + iw[1] : pc + 1;\n    else fa_n = succ;\n    fe = rst || (ir_v && op == OP_LOOP && !lp && !stopping && !halted && !rl_wait) || ld;\n    fa_d = fe ? fa_n : fa;\n  end\n\n  // A dependency on an instruction that has already started on the SAME unit is satisfied:\n  // every unit processes its instructions in start order (the MXU consumes and drains its two\n  // commands strictly in order), so the older one's effects land first. This lets the MXU\n  // stream an accumulating MM while the previous one into the same tile is still finishing.\n  // The VPU is the exception: it overlaps several instructions in its pipeline (with different\n  // latencies), so a VPU instruction waits for the VPU instructions it depends on to complete.\n  logic [WIN-1:0] same_started [NUNITS];\n  always_comb begin\n    for (int u = 0; u < NUNITS; u++)\n      for (int i = 0; i < WIN; i++)\n        same_started[u][i] = sv[i] && sstarted[i] && soh[i][u] && u != U_VPU;\n  end\n\n  // ---- per-unit start: the oldest ready (all dependencies completed) instruction\n  logic [NUNITS-1:0] can_start;\n  logic [SW-1:0]     start_slot [NUNITS];\n  logic [WIN-1:0]    sel [NUNITS];           // the oldest candidate, one-hot (or none)\n  logic [NUNITS-1:0] cand_any;               // the unit has a candidate\n  logic [WIN-1:0]    mrdy, crdy;             // per slot: ready as the MXU / COLL oldest\n  // (the oldest of a set: the member none of whose older slots is in the set -- an age matrix\n  // instead of comparing dispatch numbers, so the choice is parallel logic). older is a strict\n  // total order over the valid slots, so sel has at most one bit; readiness is tested per slot\n  // in parallel with the selection and AND-ORed with sel -- no slot id on the can_start path\n  always_comb begin\n    for (int i = 0; i < WIN; i++) begin\n      mrdy[i] = WAITC ? w_dram_q[i] : (sdepd[i] & ~same_started[U_MXU]) == '0;\n      crdy[i] = WAITC ? w_all_q[i] : (sdep[i] & ~same_started[U_COLL]) == '0;\n    end\n    for (int u = 0; u < NUNITS; u++) begin\n      logic [WIN-1:0] cand;\n      start_slot[u] = '0;\n      // collectives pair up across slices, so the collective unit stays strictly in order:\n      // it only considers its oldest instruction\n      for (int i = 0; i < WIN; i++)\n        cand[i] = sv[i] && !sstarted[i] && soh[i][u] &&\n                  ((sdep[i] & ~same_started[u]) == '0 || u == U_COLL || u == U_MXU);\n      for (int i = 0; i < WIN; i++) begin\n        sel[u][i] = cand[i] && (older[i] & cand) == '0;\n        if (sel[u][i]) start_slot[u] |= SW'(i);\n      end\n      cand_any[u] = |cand;\n      if (u == U_MXU)\n        can_start[u] = |(sel[u] & mrdy) && urdy[u] && !ustart[u];\n      else if (u == U_COLL)\n        can_start[u] = |(sel[u] & crdy) && urdy[u] && !ustart[u];\n      else    // cand already requires readiness\n        can_start[u] = cand_any[u] && urdy[u] && !ustart[u];\n    end\n    // WAITC: the VPU starts its oldest ready instruction (its waits met), the others their\n    // oldest only\n    if (WAITC)\n      for (int u = 0; u < NUNITS; u++)\n        if (u != U_MXU && u != U_COLL) begin\n          logic [WIN-1:0] c2;\n          start_slot[u] = '0;\n          for (int i = 0; i < WIN; i++)\n            c2[i] = sv[i] && !sstarted[i] && soh[i][u] && (u != U_VPU || w_all_q[i]);\n          for (int i = 0; i < WIN; i++) begin\n            sel[u][i] = c2[i] && (older[i] & c2) == '0;\n            if (sel[u][i]) start_slot[u] |= SW'(i);\n          end\n          cand_any[u] = |c2;\n          can_start[u] = |(sel[u] & w_all_q) && urdy[u] && !ustart[u];\n        end\n`ifndef SYNTHESIS\n    // +hz_ino: the DMA, the quantizer and the VPU start their oldest instruction only, as the\n    // MXU and the collective unit do\n    if (hz_ino)\n      for (int u = 0; u < NUNITS; u++)\n        if (u != U_MXU && u != U_COLL && hz_inom[u]) begin\n          logic [WIN-1:0] c2, r2;\n          start_slot[u] = '0;\n          for (int i = 0; i < WIN; i++) begin\n            c2[i] = sv[i] && !sstarted[i] && soh[i][u];\n            r2[i] = (sdep[i] & ~same_started[u]) == '0;\n          end\n          for (int i = 0; i < WIN; i++) begin\n            sel[u][i] = c2[i] && (older[i] & c2) == '0;\n            if (sel[u][i]) start_slot[u] |= SW'(i);\n          end\n          cand_any[u] = |c2;\n          can_start[u] = |(sel[u] & r2) && urdy[u] && !ustart[u];\n        end\n`endif\n  end\n\n\n  // MXU release: the oldest started, unreleased MM once all its dependencies are clear\n  wire [SW-1:0] rel_slot = uq[U_MXU][uq_r[SW-1:0]];\n  wire          can_rel  = (uq_r != uq_t[U_MXU]) &&\n                           (WAITC ? w_all_q[rel_slot] : (sdep[rel_slot] & ~same_started[U_MXU]) == '0);\n\n  // Each unit's command is read from the window as the unit starts, at the slot it starts, into a\n  // register (ucmd): a slot's command is written only at dispatch and stays until the slot\n  // completes, so the copy is the slot's command for as long as the unit reads it (at ustart; the\n  // collective until its udone). The units' start decode then begins at flip-flops instead of at\n  // the LUT RAM's read (133.33 MHz, 61e015ff4: ucs -> LUT RAM -> the MXU's KBa -> DSP -> n.total,\n  // 5 levels, -0.504 ns; ucs -> the quantizer's busy, -0.417).\n  // The command store is one distributed RAM per unit (1 write, 1 asynchronous read, no reset):\n  // a single read port each, so it infers as LUT-RAM and trims the fields its unit never reads\n  // (as do the registers).\n  // Each copy loads on every cycle its unit is ready and not starting (urdy, ustart), which covers\n  // its starts: the enable is the unit's rdy and a flip-flop, not the start decode (133.33 MHz,\n  // 812bb01: sstarted -> the collective's can_start -> its copy's enable, fanout 120, 7 levels,\n  // +0.165 ns; the m8 card at a 150 MHz equivalent, unit 2's, 216 loads, -0.028). The units read\n  // their command only at ustart (the DMA, the MXU, the quantizer and the VPU copy it then; the\n  // MXU's release reads none), when the copy holds (ustart is up), and the collective only while\n  // its request is pending (urdy low). Between starts the copy follows start_slot, unread.\n  // WAITC: the store is written a cycle after the dispatch, from flip-flops: the enable and the\n  // slot a copy per unit (kept), the command one register. A slot starts two cycles after its\n  // dispatch at the earliest (w_all_q, w_dram_q), so its command is in the store by then. The\n  // dispatch decision and the free slot then end at a few flip-flops instead of every store's\n  // write port (r22's m8 at 150 MHz: sv -> the free slot -> the LUT RAMs' write addresses, 3036\n  // pins, -0.49 ns; vout -> c_go -> their write enables, 868, -0.34)\n  cmd_t c_cmd_w;\n  always_ff @(posedge clk) c_cmd_w <= c_cmd;\n  logic [SW-1:0] ucs [NUNITS];\n  for (genvar u = 0; u < NUNITS; u++) begin : g_cmd\n    (* ram_style = \"distributed\" *) logic [$bits(cmd_t)-1:0] m [WIN];\n    logic [$bits(cmd_t)-1:0] q;\n    logic          we;\n    logic [SW-1:0] wa;\n    wire q_en = urdy[u] && !ustart[u];\n    if (WAITC) begin : g_wq\n      (* keep_hierarchy = \"yes\" *)\n      otpu_delay #(.W(1 + SW), .N(1)) u_w (.clk, .en(1'b1), .d({!rst && c_go, free_slot}),\n                                          .q({we, wa}));\n    end else begin : g_wd\n      assign we = !rst && c_go;\n      assign wa = free_slot;\n    end\n    always_ff @(posedge clk) if (we) m[wa] <= WAITC ? c_cmd_w : c_cmd;\n    always_ff @(posedge clk) if (!rst && q_en) q <= m[start_slot[u]];\n    assign ucmd[u] = cmd_t'(q);\n`ifndef SYNTHESIS\n    // the copy is the started slot's command when the unit reads it (at ustart; the collective\n    // while its request is pending); no start reads a slot whose write is still on its way\n    always @(posedge clk) begin\n      if (!rst && (ustart[u] || (u == U_COLL && !urdy[u])) && sv[ucs[u]] && sstarted[ucs[u]]\n          && soh[ucs[u]][u] && q != m[ucs[u]])\n        $fatal(1, \"otpu_seq: unit %0d's command is not slot %0d's\", u, ucs[u]);\n      if (!rst && can_start[u] && !q_en)\n        $fatal(1, \"otpu_seq: unit %0d starts without loading its command\", u);\n      if (WAITC && !rst && we && can_start[u] && start_slot[u] == wa)\n        $fatal(1, \"otpu_seq: unit %0d starts slot %0d before its command is written\", u, wa);\n    end\n`endif\n  end\n\n`ifndef SYNTHESIS\n  // shadow of c_fp / sfp in otpu_pkg form: the scoreboard is checked against conflict(), on\n  // the footprints with MM's RMAX range folded into its output range as fp_seg does (ref), and\n  // for coverage on the footprints as they are (raw)\n  fp_t c_ref, c_raw;\n  fp_t sfp_ref [WIN], sfp_raw [WIN];\n  logic [7:0]  sidx [WIN];                   // WAITC: the slot's index among its unit's\n  logic [31:0] spc [WIN];\n\n  // fp_seg's hull in otpu_pkg form: two TMEM write ranges (only MM with RMAX) become one\n  function automatic fp_t fp_hull(input fp_t f);\n    fp_t o;\n    o = f;\n    if (f.wr[0].v && f.wr[0].sp == SP_TMEM && f.wr[1].v && f.wr[1].sp == SP_TMEM) begin\n      o.wr[0].lo = (f.wr[1].lo < f.wr[0].lo) ? f.wr[1].lo : f.wr[0].lo;\n      o.wr[0].hi = (f.wr[1].hi > f.wr[0].hi) ? f.wr[1].hi : f.wr[0].hi;\n      o.wr[1].v = 1'b0;\n    end\n    return o;\n  endfunction\n`endif\n\n  always_ff @(posedge clk) begin\n    ustart <= '0;\n    urel <= 1'b0;\n    if (rst) begin\n      uq_r <= '0;\n      pc <= '0; sp <= '0; cyc <= '0;\n      halted <= 1'b0; error <= 1'b0; stopping <= 1'b0;\n      rl_wait <= 1'b0; ch_req <= 1'b0;\n      p_v <= 1'b0; s_v <= 1'b0; q_v <= 1'b0; c_v <= 1'b0; lp <= 1'b0;\n      icount <= '0;\n      sv <= '0; sstarted <= '0; sready <= '0;\n      for (int i = 0; i < 8; i++) R[i] <= '0;\n      for (int i = 0; i < 8; i++) R[8 + i] <= rinit[i];\n      for (int u = 0; u < NUNITS; u++) begin uq_h[u] <= '0; uq_t[u] <= '0; end\n      for (int u = 0; u < NUNITS; u++) begin wd_n[u] <= '0; wc_n[u] <= '0; end\n      vout <= '0;\n      vnx_q <= 1'b0;\n      for (int i = 0; i < WIN; i++) sdep[i] <= '0;\n`ifndef SYNTHESIS\n      sdone <= '0;\n`endif\n    end else begin\n      cyc <= cyc + 1;\n      if (ld) pc <= fa;\n`ifndef SYNTHESIS\n      // fa is the pc the one-instruction-per-cycle fetch would move to (the next_pc rule)\n      if (ld && ir_v &&\n          fa != ((op == OP_LOOP) ? ((lp_cnt == 0) ? pc + 1 + lp_len : pc + 1) :\n                 (at_end && stk_rem[sp-1] > 1) ? stk_start[sp-1] : pc + 1))\n        $fatal(1, \"otpu_seq: fetch address %0d does not follow pc %0d\", fa, pc);\n      // the segregated footprints give exactly otpu_pkg's conflict() and conflict_dram(); a\n      // footprint whose TMEM ranges overflowed rt_t (all raised by fp_seg) conflicts with all.\n      // The hull only adds dependencies: every conflict() of the raw footprints is kept\n      if (c_v && !WAITC)\n        for (int i = 0; i < WIN; i++) begin\n          logic [1:0] cs;\n          cs = conf_s(c_fp, sfp[i]);\n          if (sv[i] && !hz_cs && (c_fp.all == c_ref.all && sfp[i].all == sfp_ref[i].all ?\n                        cs != {conflict(c_ref, sfp_ref[i]), conflict_dram(c_ref, sfp_ref[i])} :\n                        cs != 2'b11))\n            $fatal(1, \"otpu_seq: scoreboard differs from conflict() for pc %0d vs slot %0d\",\n                   c_pc, i);\n          if (sv[i] && conflict(c_raw, sfp_raw[i]) && !cs[1])\n            $fatal(1, \"otpu_seq: scoreboard misses a conflict() of pc %0d vs slot %0d\",\n                   c_pc, i);\n        end\n      // fp_seg's assumptions: ACT ranges fit [alo, ahi), DRAM ranges share their write role\n      if (q_v && q_adv) begin\n        logic dr, dwr;\n        dr = 1'b0; dwr = 1'b0;\n        for (int i = 0; i < 4; i++) begin\n          if (q_fp.rd[i].v && q_fp.rd[i].sp == SP_DRAM) dr = 1'b1;\n          if (q_fp.rd[i].v && q_fp.rd[i].sp == SP_ACT &&\n              (q_fp.rd[i].lo[31:8] != 0 || q_fp.rd[i].hi[31:17] != 0))\n            $fatal(1, \"otpu_seq: ACT read range of pc %0d exceeds 8/17 bits\", q_pc);\n        end\n        for (int i = 0; i < 3; i++) begin\n          if (q_fp.wr[i].v && q_fp.wr[i].sp == SP_DRAM) dwr = 1'b1;\n          if (q_fp.wr[i].v && q_fp.wr[i].sp == SP_ACT &&\n              (q_fp.wr[i].lo[31:8] != 0 || q_fp.wr[i].hi[31:17] != 0))\n            $fatal(1, \"otpu_seq: ACT write range of pc %0d exceeds 8/17 bits\", q_pc);\n        end\n        if (dr && dwr)\n          $fatal(1, \"otpu_seq: pc %0d both reads and writes DRAM (one dw bit)\", q_pc);\n      end\n`endif\n`ifndef SYNTHESIS\n      // WAITC: the wait entry covers every dependency conflict() finds on the window (a slot\n      // of the same unit, but the VPU, needs none: it started first); a VPU slot is at most VMW\n      // back\n      if (WAITC && c_go) begin\n        for (int i = 0; i < WIN; i++)\n          if (sv[i] && !fin[i]) begin\n            int ui;\n            ui = 0;\n            for (int u = 0; u < NUNITS; u++) if (soh[i][u]) ui = u;\n            if (ui == U_VPU && wc_vg > 0 && wc_vg <= VMW) begin\n              logic [CW-1:0] rk;\n              rk = wd_n[U_VPU] - sidx[i];\n              if (rk == 0 || rk > CW'(wc_vg))\n                $fatal(1, \"otpu_seq: WAITC: pc %0d: VPU slot %0d (pc %0d) %0d back\", c_pc, i,\n                       spc[i], rk);\n              if (conflict(c_ref, sfp_ref[i]) && !c_sync[28 + int'(rk) - 1])\n                $fatal(1, \"otpu_seq: WAITC: pc %0d's VPU mask %h misses slot %0d (pc %0d, %0d back)\",\n                       c_pc, c_sync[28 +: VMW], i, spc[i], rk);\n            end\n            for (int j = 0; j < NWT; j++)\n              if (wunit(j) == ui && ui != int'(c_unit) && ui != U_VPU &&\n                  ((j < NUNITS) ? conflict(c_ref, sfp_ref[i]) :\n                   c_cmd.op == OP_MM && conflict_dram(c_ref, sfp_ref[i]))) begin\n                logic [3:0] k;\n                logic [CW-1:0] df;\n                k = c_sync[4 * j +: 4];\n                df = wd_n[ui] - CW'(k) - sidx[i];      // the producer's index - the slot's\n                if (k == 0 || df[CW-1])\n                  $fatal(1, \"otpu_seq: WAITC: pc %0d's wait %0d (k %0d) misses slot %0d (pc %0d)\",\n                         c_pc, j, k, i, spc[i]);\n              end\n          end\n        sidx[free_slot] <= wd_n[c_unit];\n        spc[free_slot] <= c_pc;\n      end\n`endif\n      icount <= icount + 32'(r_ret) + 32'(c_go);\n      // completions\n      if (can_rel) begin\n        urel <= 1'b1;\n        uq_r <= uq_r + 1;\n      end\n      for (int i = 0; i < WIN; i++) begin\n        sdep[i] <= sdep[i] & ~fin;\n        sdepd[i] <= sdepd[i] & ~fin;\n        if (fin[i]) begin\n          sv[i] <= 1'b0;\n        end\n      end\n`ifndef SYNTHESIS\n      // +hz_rob: a completed slot is freed once every older one is\n      if (hz_rob)\n        for (int i = 0; i < WIN; i++) begin\n          logic dn;\n          dn = sdone[i] || fin[i];\n          sdone[i] <= dn;\n          sv[i] <= sv[i] && !(dn && (older[i] & sv & ~(sdone | fin)) == '0);\n        end\n`endif\n      for (int u = 0; u < NUNITS; u++) if (udone[u]) uq_h[u] <= uq_h[u] + 1;\n`ifndef SYNTHESIS\n      for (int i = 0; i < WIN; i++) vxd[i] <= vxd[i] & ~fin;\n`endif\n      if (WAITC) begin\n        for (int u = 0; u < NUNITS; u++) if (udone[u] && u != U_VPU) wc_n[u] <= wc_n[u] + 1'b1;\n        vout <= (vout & ~v_fin) |\n                ((c_go && c_unit == U_VPU) ? VN'(1) << wd_n[U_VPU][VIW-1:0] : '0);\n        // (a VPU dispatch sets bit wd_n and moves wd_n on: the next index's bit is wd_n + 2's)\n        begin\n          logic [VIW-1:0] i1, i2;\n          i1 = VIW'(wd_n[U_VPU] + 1'b1);\n          i2 = VIW'(wd_n[U_VPU] + 2'd2);\n          vnx_q <= (c_go && c_unit == U_VPU) ? vout[i2] && !v_fin[i2] : vout[i1] && !v_fin[i1];\n        end\n        for (int i = 0; i < WIN; i++) vpend[i] <= vpend[i] & ~v_fin;\n      end\n      // readiness (for the profiler: when did the dependencies clear)\n      for (int i = 0; i < WIN; i++)\n        if (sv[i] && !sready[i] && (WAITC ? w_all_q[i] : sdep[i] == '0)) begin\n          sready[i] <= 1'b1;\n          srdy_c[i] <= cyc;\n        end\n      // starts\n      for (int u = 0; u < NUNITS; u++) begin\n`ifndef SYNTHESIS\n        // the age matrix orders every pair of candidates: exactly one oldest when any\n        if (!$onehot0(sel[u]) || cand_any[u] != |sel[u])\n          $fatal(1, \"otpu_seq: unit %0d oldest-candidate select %b is not one-hot\", u, sel[u]);\n`endif\n        for (int i = 0; i < WIN; i++)\n          if (can_start[u] && sel[u][i]) sstarted[i] <= 1'b1;\n        if (can_start[u]) begin\n          ustart[u] <= 1'b1;\n          ucs[u] <= start_slot[u];\n          uq[u][uq_t[u][SW-1:0]] <= start_slot[u];\n          uq_t[u] <= uq_t[u] + 1;\n        end\n      end\n      // ---- C: dispatch into the window\n      if (c_go) begin\n        sv[free_slot] <= 1'b1;\n        older[free_slot] <= sv;           // every slot in the window is older\n        for (int i = 0; i < WIN; i++) older[i][free_slot] <= 1'b0;\n        soh[free_slot] <= NUNITS'(1) << c_unit;\n        sstarted[free_slot] <= 1'b0;\n        sready[free_slot] <= 1'b0;\n        sdep[free_slot] <= ndep;\n        sdepd[free_slot] <= ndepd;\n        sfp[free_slot] <= c_fp;\n        if (WAITC) begin\n          logic [VN-1:0] m;\n          for (int j = 0; j < NWT; j++) begin\n            logic [3:0] k;\n            k = c_sync[4 * j +: 4];\n            wv[free_slot][j] <= k != 0 && wunit(j) != int'(c_unit) && wunit(j) != U_VPU;\n            wt[free_slot][j] <= wd_n[wunit(j)] - CW'(k) + 1'b1;\n          end\n          // the VPU mask: bit r - 1 names the VPU instruction r back (index wd_n - r)\n          m = '0;\n          for (int r = 1; r <= VMW; r++)\n            if (c_sync[28 + r - 1]) m[VIW'(wd_n[U_VPU] - CW'(r))] = 1'b1;\n          vpend[free_slot] <= m & vout & ~v_fin;\n          vix[free_slot] <= VIW'(wd_n[c_unit]);\n          wd_n[c_unit] <= wd_n[c_unit] + 1'b1;\n        end\n`ifndef SYNTHESIS\n        sdone[free_slot] <= 1'b0;\n        sfpx[free_slot] <= c_fpx;\n        vxi[free_slot] <= wd_n[c_unit];\n        for (int j = 0; j < WIN; j++) begin\n          logic [1:0] cf;\n          cf = conf_s(c_fpx, sfpx[j]);\n          vxd[free_slot][j] <= sv[j] && !fin[j] && soh[j][U_VPU] && cf[1];\n        end\n`endif\n`ifndef SYNTHESIS\n        sfp_ref[free_slot] <= c_ref;\n        sfp_raw[free_slot] <= c_raw;\n`endif\n      end\n      // ---- Q: footprint ranges\n      if (!WAITC && q_adv) begin\n        c_v <= q_v;\n        if (q_v) begin\n          c_cmd <= q_cmd; c_unit <= q_unit; c_pc <= q_pc;\n          c_fp <= hz_coarse(fp_seg(q_cmd.op, q_fp));\n`ifndef SYNTHESIS\n          c_fpx <= fp_seg(q_cmd.op, q_fp);\n`endif\n`ifndef SYNTHESIS\n          c_ref <= fp_hull(q_fp);\n          c_raw <= q_fp;\n`endif\n        end\n      end\n      // ---- S: products\n      if (!WAITC && s_adv) begin\n        q_v <= s_v;\n        if (s_v) begin\n          q_cmd <= s_cmd; q_unit <= s_unit; q_pc <= s_pc;\n          q_pr <= fp_sum(s_pp);\n        end\n      end\n      // ---- P: partial products (WAITC: the instruction goes to C)\n      if (p_adv) begin\n        if (WAITC) begin\n          c_v <= p_v;\n          if (p_v) begin\n            c_cmd <= p_cmd; c_unit <= p_unit; c_pc <= p_pc; c_sync <= p_sync;\n`ifndef SYNTHESIS\n            c_ref <= fp_hull(footprint(p_cmd, D, S));\n            c_raw <= footprint(p_cmd, D, S);\n            c_fpx <= fp_seg(p_cmd.op, footprint(p_cmd, D, S));\n`endif\n          end\n        end else begin\n          s_v <= p_v;\n          if (p_v) begin\n            s_cmd <= p_cmd; s_unit <= p_unit; s_pc <= p_pc;\n            s_pp <= fp_part(fp_ops(p_cmd, D, S));\n          end\n        end\n      end\n      if (r_take) p_v <= 1'b0;\n      // ---- RLD's value (R holds meanwhile, so nothing below writes R this cycle)\n      if (rl_v) begin\n        if (rl_rd != 0) R[rl_rd] <= rl_val;\n        rl_wait <= 1'b0;\n      end\n      // ---- R: fetch / execute control / hand over\n      if (stopping) begin\n        if (sv == '0 && pipe_empty) halted <= 1'b1;\n      end else if (!halted && ir_v && !rl_wait) begin\n        case (op)\n          OP_NOP: advance();\n          OP_HALT: begin\n            stopping <= 1'b1;\n            ch_req <= flags[HF_CHAIN];\n            ch_addr <= rv(ra);\n            ch_n <= rv(rb);\n          end\n          OP_LI: begin\n            if (rd != 0) R[rd] <= iw[1];\n            advance();\n          end\n          OP_ADDI: begin\n            if (rd != 0) R[rd] <= rv(ra) + iw[1];\n            advance();\n          end\n          OP_LOOP: begin\n            if (!lp) begin\n              lp <= 1'b1;\n              lp_cnt <= rv(ra) + iw[2];\n              lp_len <= iw[1];\n            end else begin\n              lp <= 1'b0;\n                if (lp_cnt != 0) begin\n                stk_start[sp] <= pc + 1;\n                stk_end[sp]   <= pc + lp_len;\n                stk_rem[sp]   <= lp_cnt;\n                sp <= sp + 1;\n              end\n            end\n          end\n          default: begin\n            if (dunit < 0) begin\n              error <= 1'b1;\n              halted <= 1'b1;\n            end else if (r_take) begin\n              p_v <= 1'b1;\n              p_cmd <= dcmd; p_unit <= 3'(dunit); p_pc <= pc; p_sync <= ir_sync;\n              advance();\n              if (op == OP_RLD) begin\n                rl_wait <= 1'b1;\n                rl_rd <= rd;\n              end\n            end\n          end\n        endcase\n      end\n    end\n  end\n\n`ifndef SYNTHESIS\n  // ---- EXPERIMENTAL (docs/seq_vpu.md): wait counts, their oracle, and hazard statistics\n  localparam int NPC = IMEM_WORDS / 8;     // instructions IMEM holds\n  localparam int NCLS = 12;                // instruction classes of the statistics (hz_cls)\n  localparam int KMAX = 16;                // ranks the oracle looks back, per unit\n  // per pc: k for units 0..4 (any conflict), then the DRAM-only k for the DMA and the quantizer\n  // (an MM may stream once those are clear); 0: no conflict within KMAX\n  int  wc_k [NPC][7];\n  int  hz_fd = 0, hz_kfd = 0;\n  bit  hz_seen [NPC];\n  int  hz_cnt [NPC];\n  int  kmin [NPC][7];\n  fps_t hist [NUNITS][KMAX];\n  int  hist_n [NUNITS];\n  int  scls [WIN];\n  // statistics\n  longint st_cyc, st_wfull, st_rlw, st_disp, st_nodep, st_vhold;\n  longint st_u [NUNITS][6];                // busy, empty, start, unit not ready, blocked, (spare)\n  longint st_by [NUNITS][NUNITS];          // blocked cycles of unit u by producer unit p\n  longint st_bcls [NCLS][NCLS];            // blocked cycles by (waiting class, producer class)\n  longint st_rel [NUNITS + 1];             // MXU started, release waits, by producer unit; total\n  longint st_dep [NCLS][NCLS];             // dependencies at dispatch by (class, producer class)\n  longint st_kind [6];                     // TMEM RAW, WAR, WAW, DRAM, ACT, all (BAR / WAITW)\n  longint st_kh [NUNITS][NUNITS][KMAX + 1];// oracle ranks: consumer unit, producer unit, k\n  longint st_nu [NUNITS + 1];              // instructions by the number of units they depend on\n  longint st_wcmiss;\n\n  function automatic int hz_cls(input logic [7:0] op, input logic [7:0] f);\n    case (op)\n      OP_LD: return 0;\n      OP_ST: return 1;\n      OP_DSTEP, OP_STREAM: return 2;\n      OP_WAITW: return 3;\n      OP_MM: return 4;\n      OP_QACT: return 5;\n      OP_QST: return 6;\n      OP_VOP: return is_reduce(f) ? 8 : (f_cc(f) != CC_NONE) ? 9 : 7;\n      OP_RLD: return 10;\n      default: return 11;\n    endcase\n  endfunction\n\n  // which kinds a dependency is: TMEM RAW, WAR, WAW, DRAM, ACT, all\n  function automatic logic [5:0] hz_kind(input fps_t n, input fps_t e);\n    logic [5:0] k;\n    rt_t nr [5];\n    rt_t er [5];\n    k = '0;\n    if (n.all || e.all) k[5] = 1'b1;\n    nr[0] = n.t0.w ? '0 : n.t0.r; nr[1] = n.t1; nr[2] = n.t2; nr[3] = n.t3; nr[4] = n.t4;\n    er[0] = e.t0.w ? '0 : e.t0.r; er[1] = e.t1; er[2] = e.t2; er[3] = e.t3; er[4] = e.t4;\n    for (int j = 0; j < 5; j++) begin\n      if (e.t0.w && ovr_t(nr[j], e.t0.r)) k[0] = 1'b1;\n      if (n.t0.w && ovr_t(n.t0.r, er[j])) k[1] = 1'b1;\n    end\n    if (n.t0.w && e.t0.w && ovr_t(n.t0.r, e.t0.r)) k[2] = 1'b1;\n    for (int i = 0; i < 2; i++)\n      for (int j = 0; j < 2; j++)\n        if ((n.dw || e.dw) && ovr(n.d[i], e.d[j])) k[3] = 1'b1;\n    if ((n.aw || e.aw) && {9'd0, n.alo} < e.ahi && {9'd0, e.alo} < n.ahi) k[4] = 1'b1;\n    return k;\n  endfunction\n\n  function automatic int hz_unit(input logic [NUNITS-1:0] oh);\n    for (int u = 0; u < NUNITS; u++) if (oh[u]) return u;\n    return 0;\n  endfunction\n\n  initial begin\n    string fn;\n    int fd, pc, r, n;\n    int k [7];\n    for (int i = 0; i < NPC; i++) begin\n      hz_seen[i] = 1'b0; hz_cnt[i] = 0;\n      for (int j = 0; j < 7; j++) begin wc_k[i][j] = 1; kmin[i][j] = 0; end\n    end\n    for (int u = 0; u < NUNITS; u++) hist_n[u] = 0;\n    if ($value$plusargs(\"hz_wc=%s\", fn)) begin\n      fd = $fopen(fn, \"r\");\n      if (fd == 0) $fatal(1, \"otpu_seq: +hz_wc=%s: cannot open\", fn);\n      while (!$feof(fd)) begin\n        r = $fscanf(fd, \"%d %d %d %d %d %d %d %d %d\\n\", pc, k[0], k[1], k[2], k[3], k[4], k[5],\n                    k[6], n);\n        if (r >= 8 && pc >= 0 && pc < NPC)\n          for (int j = 0; j < 7; j++)\n            wc_k[pc][j] = (hz_kclamp > 0 && k[j] > hz_kclamp) ? hz_kclamp : k[j];\n      end\n      $fclose(fd);\n      hz_wc = 1'b1;\n      if (!hz_ino) $fatal(1, \"otpu_seq: +hz_wc needs +hz_ino=1 (in-order units)\");\n    end\n    if ($value$plusargs(\"hz_kout=%s\", fn)) hz_kfd = $fopen(fn, \"w\");\n    if ($value$plusargs(\"hz_log=%s\", fn)) hz_fd = $fopen(fn, \"w\");\n    st_cyc = 0; st_wfull = 0; st_rlw = 0; st_disp = 0; st_nodep = 0; st_wcmiss = 0; st_vhold = 0;\n    for (int u = 0; u < NUNITS; u++) begin\n      for (int j = 0; j < 6; j++) st_u[u][j] = 0;\n      for (int p = 0; p < NUNITS; p++) begin\n        st_by[u][p] = 0;\n        for (int j = 0; j <= KMAX; j++) st_kh[u][p][j] = 0;\n      end\n    end\n    for (int u = 0; u <= NUNITS; u++) begin st_rel[u] = 0; st_nu[u] = 0; end\n    for (int a = 0; a < NCLS; a++)\n      for (int b = 0; b < NCLS; b++) begin st_bcls[a][b] = 0; st_dep[a][b] = 0; end\n    for (int j = 0; j < 6; j++) st_kind[j] = 0;\n  end\n\n  // +hz_wc: slot i is a dependency when it is one of the older unit-u instructions beyond the\n  // k_u - 1 most recent (in-order units complete in program order, so these are outstanding)\n  always_comb begin\n    wc_dep = '0; wc_depd = '0;\n    if (hz_wc && c_v)\n      for (int i = 0; i < WIN; i++)\n        if (sv[i] && !fin[i]) begin\n          int u, y, k, kd;\n          u = hz_unit(soh[i]);\n          y = 0;\n          for (int j = 0; j < WIN; j++) y += int'(sv[j] && soh[j][u] && older[j][i]);\n          k = wc_k[c_pc % NPC][u];\n          kd = (u == U_DMA) ? wc_k[c_pc % NPC][5] : (u == U_Q) ? wc_k[c_pc % NPC][6] : 0;\n          if (u == int'(c_unit) && u != U_VPU) begin k = 0; kd = 0; end   // started first\n          wc_dep[i] = k != 0 && y >= k - 1;\n          wc_depd[i] = (c_cmd.op == OP_MM) ? (kd != 0 && y >= kd - 1) : wc_dep[i];\n          if (u == U_VPU && (hz_wcvx == 1 || (hz_wcvx == 2 && c_unit == U_VPU) ||\n                             (hz_wcvx == 3 && c_unit != U_VPU))) begin\n            logic [1:0] cf;\n            cf = conf_s(c_fp, sfp[i]);\n            wc_dep[i] = cf[1];\n            wc_depd[i] = cf[0];\n          end\n        end\n  end\n\n  always @(posedge clk) begin\n    if (rst) begin\n      for (int u = 0; u < NUNITS; u++) hist_n[u] <= 0;\n    end else begin\n      // ---- at dispatch: the oracle's ranks, the dependencies' classes and kinds\n      if (c_go && (hz_fd != 0 || hz_kfd != 0)) begin\n        int cu, cc, nu, pc;\n        int kk [NUNITS];\n        int kd [NUNITS];\n        logic [NUNITS-1:0] du;\n        cu = int'(c_unit);\n        cc = hz_cls(c_cmd.op, c_cmd.w6[23:16]);\n        scls[free_slot] <= cc;\n        st_disp++;\n        du = '0;\n        for (int i = 0; i < WIN; i++)\n          if (ndep[i]) begin\n            logic [5:0] kn;\n            kn = hz_kind(c_fpx, sfp[i]);\n            st_dep[cc][scls[i]]++;\n            for (int j = 0; j < 6; j++) if (kn[j]) st_kind[j]++;\n            du |= soh[i];\n          end\n        if (ndep == '0) st_nodep++;\n        nu = $countones(du);\n        st_nu[nu]++;\n        if (hz_wc)\n          for (int i = 0; i < WIN; i++) begin\n            logic [1:0] cf;\n            cf = conf_s(c_fpx, sfp[i]);\n            if (sv[i] && !fin[i] && cf[1] && !ndep[i] && !(soh[i][cu] && cu != U_VPU))\n              st_wcmiss++;\n          end\n        for (int u = 0; u < NUNITS; u++) begin\n          kk[u] = 0; kd[u] = 0;\n          for (int j = 0; j < KMAX; j++)\n            if (j < hist_n[u]) begin\n              logic [1:0] cf;\n              cf = conf_s(hz_kc ? c_fp : c_fpx, hist[u][j]);\n              if (cf[1] && kk[u] == 0) kk[u] = j + 1;\n              if (cf[0] && kd[u] == 0) kd[u] = j + 1;\n            end\n          st_kh[cu][u][kk[u]]++;\n        end\n        pc = int'(c_pc % NPC);\n        for (int u = 0; u < NUNITS; u++)\n          if (kk[u] != 0 && (kmin[pc][u] == 0 || kk[u] < kmin[pc][u])) kmin[pc][u] = kk[u];\n        if (kd[U_DMA] != 0 && (kmin[pc][5] == 0 || kd[U_DMA] < kmin[pc][5]))\n          kmin[pc][5] = kd[U_DMA];\n        if (kd[U_Q] != 0 && (kmin[pc][6] == 0 || kd[U_Q] < kmin[pc][6])) kmin[pc][6] = kd[U_Q];\n        hz_seen[pc] = 1'b1;\n        hz_cnt[pc]++;\n        for (int j = KMAX - 1; j > 0; j--) hist[cu][j] <= hist[cu][j - 1];\n        hist[cu][0] <= hz_kc ? c_fp : c_fpx;\n        hist_n[cu] <= (hist_n[cu] < KMAX) ? hist_n[cu] + 1 : KMAX;\n      end\n      // ---- every cycle of the run: what each unit does, and what a blocked one waits for\n      if (!halted && hz_fd != 0) begin\n        st_cyc++;\n        if (c_v && !have_free) st_wfull++;\n        if (c_v && have_free && wc_hold) st_vhold++;   // WAITC: a VOP held for the one VMW back\n        if (rl_wait) st_rlw++;\n        for (int u = 0; u < NUNITS; u++) begin\n          logic [WIN-1:0] pend;\n          for (int i = 0; i < WIN; i++) pend[i] = sv[i] && !sstarted[i] && soh[i][u];\n          if (uq_h[u] != uq_t[u]) st_u[u][0]++;\n          else if (pend == '0) st_u[u][1]++;\n          else if (can_start[u]) st_u[u][2]++;\n          else if (!urdy[u]) st_u[u][3]++;\n          else begin\n            int o;\n            logic [WIN-1:0] b;\n            st_u[u][4]++;\n            o = 0;\n            for (int i = 0; i < WIN; i++) if (pend[i] && (older[i] & pend) == '0) o = i;\n            b = ((u == U_MXU) ? sdepd[o] : sdep[o]) & ~same_started[u];\n            for (int p = 0; p < NUNITS; p++) begin\n              logic hit;\n              hit = 1'b0;\n              for (int i = 0; i < WIN; i++) if (b[i] && soh[i][p]) hit = 1'b1;\n              if (hit) st_by[u][p]++;\n            end\n            for (int i = 0; i < WIN; i++) if (b[i]) st_bcls[scls[o]][scls[i]]++;\n          end\n        end\n        if (uq_r != uq_t[U_MXU] && !can_rel) begin\n          logic [WIN-1:0] b;\n          b = sdep[rel_slot] & ~same_started[U_MXU];\n          st_rel[NUNITS]++;\n          for (int p = 0; p < NUNITS; p++) begin\n            logic hit;\n            hit = 1'b0;\n            for (int i = 0; i < WIN; i++) if (b[i] && soh[i][p]) hit = 1'b1;\n            if (hit) st_rel[p]++;\n          end\n        end\n      end\n    end\n  end\n\n  final begin\n    if (hz_kfd != 0) begin\n      for (int pc = 0; pc < NPC; pc++)\n        if (hz_seen[pc])\n          $fdisplay(hz_kfd, \"%0d %0d %0d %0d %0d %0d %0d %0d %0d\", pc, kmin[pc][0], kmin[pc][1],\n                    kmin[pc][2], kmin[pc][3], kmin[pc][4], kmin[pc][5], kmin[pc][6], hz_cnt[pc]);\n      $fclose(hz_kfd);\n    end\n    if (hz_fd != 0) begin\n      $fdisplay(hz_fd, \"HZ cycles %0d dispatched %0d nodep %0d wfull %0d rlwait %0d wcmiss %0d vhold %0d\",\n                st_cyc, st_disp, st_nodep, st_wfull, st_rlw, st_wcmiss, st_vhold);\n      $fdisplay(hz_fd, \"HZ knobs tg %0d dg %0d rh %0d dh %0d win %0d ino %0d rob %0d wc %0d uq %0d,%0d,%0d,%0d,%0d\",\n                hz_tg, hz_dg, hz_rh, hz_dh, hz_win, hz_ino, hz_rob, hz_wc, hz_uq[0], hz_uq[1],\n                hz_uq[2], hz_uq[3], hz_uq[4]);\n      for (int u = 0; u < NUNITS; u++)\n        $fdisplay(hz_fd, \"HZU %0d busy %0d empty %0d start %0d notrdy %0d blocked %0d by %0d %0d %0d %0d %0d\",\n                  u, st_u[u][0], st_u[u][1], st_u[u][2], st_u[u][3], st_u[u][4], st_by[u][0],\n                  st_by[u][1], st_by[u][2], st_by[u][3], st_by[u][4]);\n      $fdisplay(hz_fd, \"HZREL total %0d by %0d %0d %0d %0d %0d\", st_rel[NUNITS], st_rel[0],\n                st_rel[1], st_rel[2], st_rel[3], st_rel[4]);\n      $fdisplay(hz_fd, \"HZKIND tmem_raw %0d tmem_war %0d tmem_waw %0d dram %0d act %0d all %0d\",\n                st_kind[0], st_kind[1], st_kind[2], st_kind[3], st_kind[4], st_kind[5]);\n      $fdisplay(hz_fd, \"HZNU %0d %0d %0d %0d %0d %0d\", st_nu[0], st_nu[1], st_nu[2], st_nu[3],\n                st_nu[4], st_nu[5]);\n      for (int a = 0; a < NCLS; a++)\n        for (int b = 0; b < NCLS; b++) begin\n          if (st_dep[a][b] != 0) $fdisplay(hz_fd, \"HZDEP %0d %0d %0d\", a, b, st_dep[a][b]);\n          if (st_bcls[a][b] != 0) $fdisplay(hz_fd, \"HZBLK %0d %0d %0d\", a, b, st_bcls[a][b]);\n        end\n      for (int u = 0; u < NUNITS; u++)\n        for (int p = 0; p < NUNITS; p++) begin\n          string l;\n          l = $sformatf(\"HZK %0d %0d\", u, p);\n          for (int j = 0; j <= KMAX; j++) l = {l, $sformatf(\" %0d\", st_kh[u][p][j])};\n          $fdisplay(hz_fd, \"%s\", l);\n        end\n      $fclose(hz_fd);\n    end\n  end\n`endif\n\n  // ---- trace and activity events (otpu_pkg seq_ev_t): this cycle's, registered. A start's\n  // ready cycle is looked up a cycle late, from the start's registered slot (ucs): if the slot\n  // was not ready when it started, it either became ready at that cycle's edge (srdy_c = the\n  // start cycle) or is still not ready (the start cycle, ev.cyc) -- the value at the start.\n  seq_ev_t evq;\n  always_ff @(posedge clk) begin\n    evq.cyc <= cyc;\n    evq.ret <= rst ? 2'd0 : 2'(r_ret) + 2'(c_go);\n    evq.d <= !rst && c_go;\n    evq.d_slot <= 5'(free_slot);\n    evq.d_pc <= c_pc;\n    evq.d_op <= c_cmd.op;\n    evq.d_w1 <= c_cmd.w1; evq.d_w2 <= c_cmd.w2; evq.d_w3 <= c_cmd.w3;\n    evq.g <= !rst && can_rel;\n    evq.g_slot <= 5'(rel_slot);\n    evq.e <= rst ? '0 : 32'(fin);\n    for (int u = 0; u < NUNITS; u++) evq.busy[u] <= !rst && uq_h[u] != uq_t[u];\n  end\n  always_comb begin\n    ev = evq;\n    ev.s = ustart;\n    for (int u = 0; u < NUNITS; u++) begin\n      ev.s_slot[u] = 5'(ucs[u]);\n      ev.s_rdy[u] = sready[ucs[u]] ? srdy_c[ucs[u]] : evq.cyc;\n    end\n  end\n\n`ifndef SYNTHESIS\n  initial if (WIN > 32) $fatal(1, \"otpu_seq: the trace events hold 32 window slots\");\n  // WAITC: a count of 4 bits names a unit's 15 last instructions; an in-order unit's 16th last\n  // has completed only if the window holds no more than 16\n  initial if (WAITC && WIN > 16) $fatal(1, \"otpu_seq: WAITC needs WIN <= 16 (%0d)\", WIN);\n  string dir;\n  logic [31:0] init_w [IMEM_WORDS];\n  initial begin\n    for (int i = 0; i < IMEM_WORDS; i++) init_w[i] = '0;\n    if ($value$plusargs(\"dir=%s\", dir) && !$test$plusargs(\"boot\"))\n      $readmemh($sformatf(\"%s/prog_%0d.hex\", dir, SID), init_w);\n    for (int r = 0; r < NROW; r++)\n      for (int w = 0; w < 8 * IPR; w++)\n        u_imem.g_auto.mem[r][32 * w +: 32] = init_w[r * 8 * IPR + w];\n  end\n`endif\nendmodule\n", "rtl/shell/otpu_afifo.sv": "// Asynchronous FIFO, first-word fall-through: gray-coded pointers, each synchronized by two\n// flip-flops into the other clock, and a distributed-RAM array (asynchronous read), so rdata is\n// the head entry while rvalid is high. DEPTH is a power of two.\n//\n// wused counts the entries the write side still has to consider occupied: what it wrote minus\n// what the read side has popped as last seen through the synchronizer (so at most a few cycles\n// stale, always on the safe side). The channel bridge uses it for read credits. rused counts the\n// entries the read side sees: the write pointer as synchronized minus what it has popped (as stale,\n// on the same safe side). The channel bridge batches XDMA's writes on it.\n//\n// OOO = 1: entries are written out of order, each at its slot (wslot: the entry's place in the\n// FIFO's order, modulo DEPTH), and enter the FIFO in slot order: the write pointer passes an entry\n// once it and every entry before it are written (at most one a cycle; wcommit), so the read side\n// sees them in order. It passes an entry the cycle after its write, from the slots' flags alone,\n// so no write-side input reaches wcommit (the bridge's read credits follow it). The writer\n// reserves the slots (the channel bridge's read credits): a write is not checked against wready,\n// and a slot is written once per pass.\n//\n// RWR = 1: wready is a flip-flop, so the writer's enables start from flip-flops: the room after\n// this cycle's write, against the read pointer as synchronized now (at most a cycle more\n// conservative than wused), low from the cycle after wrst rises to the cycle after it falls. In\n// wrst's first cycle it keeps the last cycle's value; the channel bridge's XDMA side is in its own\n// reset then (x_crst), except in the first cycle of a hold the controller's reset raised, when a\n// beat it takes is lost with those already in the FIFO. The RAM's write address is a copy of the\n// write pointer of its own then, replicated by synthesis (MAX_FANOUT) over the RAM's width (the\n// XDMA side at 250 MHz, PCIe Gen2).\n//\n// In order (OOO = 0) the RAM writes the slot at the tail every cycle there is room (wready), and\n// a write only moves the tail: the RAM's write enables come from the pointers' registers (RWR:\n// from wready's flip-flop), not from the writer's valid (on the card the native adapter's write\n// issue, 9 levels from its hazard registers, ran into u_ad's 782 write enables). With room the\n// slot at the tail is free (wused is never under what the read side holds), and the read side\n// reads a slot as valid only once the write pointer, as synchronized, has passed it. (The room\n// is this cycle's wready, not one a cycle older: a write wready takes is always written.)\nmodule otpu_afifo #(\n  parameter int W = 32,\n  parameter int DEPTH = 16,\n  parameter bit OOO = 1'b0,\n  parameter bit RWR = 1'b0\n) (\n  input  logic         wclk,\n  input  logic         wrst,\n  input  logic         wvalid,\n  output logic         wready,\n  input  logic [W-1:0] wdata,\n  input  logic [$clog2(DEPTH)-1:0] wslot,    // OOO: the entry's slot\n  output logic         wcommit,              // OOO: an entry entered the FIFO\n  output logic [$clog2(DEPTH):0] wused,\n  input  logic         rclk,\n  input  logic         rrst,\n  output logic         rvalid,\n  input  logic         rready,\n  output logic [W-1:0] rdata,\n  output logic [$clog2(DEPTH):0] rused\n);\n  localparam int AW = $clog2(DEPTH);\n  initial if (DEPTH != (1 << AW) || DEPTH < 4) $fatal(1, \"otpu_afifo: DEPTH must be a power of two >= 4\");\n\n  (* ram_style = \"distributed\" *) logic [W-1:0] mem [DEPTH];\n  logic [AW:0] wbin, wgray, rbin, rgray;\n  (* ASYNC_REG = \"TRUE\" *) logic [AW:0] rgray_w1, rgray_w2;   // read pointer, in wclk\n  (* ASYNC_REG = \"TRUE\" *) logic [AW:0] wgray_r1, wgray_r2;   // write pointer, in rclk\n\n  function automatic logic [AW:0] g2b(input logic [AW:0] g);\n    logic [AW:0] b;\n    b[AW] = g[AW];\n    for (int i = AW - 1; i >= 0; i--) b[i] = b[i + 1] ^ g[i];\n    return b;\n  endfunction\n\n  // write side\n  logic [AW:0] rbin_w;\n  logic        wput, wadv;\n  logic [AW-1:0] waddr, wa;\n  logic [DEPTH-1:0] wvld;                  // OOO: slots written, not yet passed\n  assign rbin_w = g2b(rgray_w2);\n  assign wused  = wbin - rbin_w;\n  if (RWR) begin : g_rwr\n    logic wrdy = 1'b0;\n    always_ff @(posedge wclk)\n      wrdy <= !wrst && ((wbin + (AW + 1)'(wput)) - rbin_w) != (AW + 1)'(DEPTH);\n    assign wready = wrdy;\n    (* max_fanout = 32 *) logic [AW-1:0] wa_q;\n    always_ff @(posedge wclk)\n      if (wrst) wa_q <= '0;\n      else if (wadv) wa_q <= wbin[AW-1:0] + 1'b1;\n    assign wa = wa_q;\n  end else begin : g_cwr\n    assign wready = !wrst && (wused != (AW + 1)'(DEPTH));\n    assign wa = wbin[AW-1:0];\n  end\n  assign wput   = OOO ? (wvalid && !wrst) : (wvalid && wready);\n  assign waddr  = OOO ? wslot : wa;\n  assign wadv   = OOO ? (!wrst && wvld[wbin[AW-1:0]])\n                      : (wvalid && wready);\n  assign wcommit = OOO && wadv;\n  always_ff @(posedge wclk) begin\n    if (wrst) begin\n      wbin <= '0; wgray <= '0; rgray_w1 <= '0; rgray_w2 <= '0;\n    end else begin\n      rgray_w1 <= rgray; rgray_w2 <= rgray_w1;\n      if (wadv) begin\n        wbin  <= wbin + 1'b1;\n        wgray <= (wbin + 1'b1) ^ ((wbin + 1'b1) >> 1);\n      end\n    end\n  end\n  always_ff @(posedge wclk) if (OOO ? wput : wready) mem[waddr] <= wdata;\n  if (OOO) begin : g_ooo\n    always_ff @(posedge wclk) begin\n      if (wrst) wvld <= '0;\n      else begin\n        if (wput) wvld[wslot] <= 1'b1;\n        if (wadv) wvld[wbin[AW-1:0]] <= 1'b0;\n      end\n    end\n`ifndef SYNTHESIS\n    always_ff @(posedge wclk) if (!wrst && wput && wvld[wslot])\n      $error(\"otpu_afifo: slot %0d written twice\", wslot);\n`endif\n  end else begin : g_fifo\n    assign wvld = '0;\n  end\n\n  // read side\n  assign rvalid = !rrst && (rgray != wgray_r2);\n  assign rdata  = mem[rbin[AW-1:0]];\n  assign rused  = g2b(wgray_r2) - rbin;\n  always_ff @(posedge rclk) begin\n    if (rrst) begin\n      rbin <= '0; rgray <= '0; wgray_r1 <= '0; wgray_r2 <= '0;\n    end else begin\n      wgray_r1 <= wgray; wgray_r2 <= wgray_r1;\n      if (rvalid && rready) begin\n        rbin  <= rbin + 1'b1;\n        rgray <= (rbin + 1'b1) ^ ((rbin + 1'b1) >> 1);\n      end\n    end\n  end\nendmodule\n", "rtl/shell/otpu_axi_split2.sv": "// AXI4 1-to-2 split by address bit 31 (XDMA's M_AXI onto the two channels' bridges,\n// otpu_mem_ch; channel 0 at 0x0000_0000, channel 1 at 0x8000_0000, as the address map of\n// opentpu/host/board.py). One clock. W beats follow their AW's channel; B and R responses come\n// back in the order of their AW / AR, whatever the IDs (legal, and XDMA's own order), so a\n// response from the other channel waits for the older ones. Up to OD transactions of each kind\n// in flight. Valids to the channels depend on no ready.\nmodule otpu_axi_split2 #(\n  parameter int IDW = 4,\n  parameter int DW  = 128,\n  parameter int OD  = 16\n) (\n  input  logic                  clk,\n  input  logic                  rst,\n  // slave (XDMA)\n  input  logic                  s_awvalid,\n  output logic                  s_awready,\n  input  logic [IDW-1:0]        s_awid,\n  input  logic [31:0]           s_awaddr,\n  input  logic [7:0]            s_awlen,\n  input  logic                  s_wvalid,\n  output logic                  s_wready,\n  input  logic [DW-1:0]         s_wdata,\n  input  logic [DW/8-1:0]       s_wstrb,\n  input  logic                  s_wlast,\n  output logic                  s_bvalid,\n  input  logic                  s_bready,\n  output logic [IDW-1:0]        s_bid,\n  output logic [1:0]            s_bresp,\n  input  logic                  s_arvalid,\n  output logic                  s_arready,\n  input  logic [IDW-1:0]        s_arid,\n  input  logic [31:0]           s_araddr,\n  input  logic [7:0]            s_arlen,\n  output logic                  s_rvalid,\n  input  logic                  s_rready,\n  output logic [IDW-1:0]        s_rid,\n  output logic [DW-1:0]         s_rdata,\n  output logic [1:0]            s_rresp,\n  output logic                  s_rlast,\n  // masters, one per channel\n  output logic [1:0]            m_awvalid,\n  input  logic [1:0]            m_awready,\n  output logic [1:0]            m_wvalid,\n  input  logic [1:0]            m_wready,\n  input  logic [1:0]            m_bvalid,\n  output logic [1:0]            m_bready,\n  input  logic [1:0][IDW-1:0]   m_bid,\n  input  logic [1:0][1:0]       m_bresp,\n  output logic [1:0]            m_arvalid,\n  input  logic [1:0]            m_arready,\n  input  logic [1:0]            m_rvalid,\n  output logic [1:0]            m_rready,\n  input  logic [1:0][IDW-1:0]   m_rid,\n  input  logic [1:0][DW-1:0]    m_rdata,\n  input  logic [1:0][1:0]       m_rresp,\n  input  logic [1:0]            m_rlast\n);\n  // the address, ID, length and write data go to both channels as they are (only the valids\n  // select one)\n  logic ow_wr, ow_rv, ow_rd;              // W route (AW order)\n  logic ob_wr, ob_rv, ob_rd;              // B route (AW order)\n  logic or_wr, or_rv, or_rd;              // R route (AR order)\n  logic awc, arc;\n  assign awc = s_awaddr[31];\n  assign arc = s_araddr[31];\n\n  // the order FIFOs' flags and heads from registers (RO): they steer every channel's valids,\n  // readies and the R / B muxes\n  otpu_sfifo #(.W(1), .DEPTH(OD), .RO(1'b1)) u_ow (.clk, .rst, .wvalid(s_awvalid && s_awready),\n    .wready(ow_wr), .wdata(awc), .rvalid(ow_rv), .rready(s_wvalid && s_wready && s_wlast),\n    .rdata(ow_rd));\n  otpu_sfifo #(.W(1), .DEPTH(OD), .RO(1'b1)) u_ob (.clk, .rst, .wvalid(s_awvalid && s_awready),\n    .wready(ob_wr), .wdata(awc), .rvalid(ob_rv), .rready(s_bvalid && s_bready), .rdata(ob_rd));\n  otpu_sfifo #(.W(1), .DEPTH(OD), .RO(1'b1)) u_or (.clk, .rst, .wvalid(s_arvalid && s_arready),\n    .wready(or_wr), .wdata(arc), .rvalid(or_rv), .rready(s_rvalid && s_rready && s_rlast),\n    .rdata(or_rd));\n\n  assign m_awvalid = {s_awvalid && ow_wr && ob_wr && awc, s_awvalid && ow_wr && ob_wr && !awc};\n  assign s_awready = ow_wr && ob_wr && m_awready[awc];\n  assign m_wvalid  = {s_wvalid && ow_rv && ow_rd, s_wvalid && ow_rv && !ow_rd};\n  assign s_wready  = ow_rv && m_wready[ow_rd];\n  assign s_bvalid  = ob_rv && m_bvalid[ob_rd];\n  assign s_bid     = m_bid[ob_rd];\n  assign s_bresp   = m_bresp[ob_rd];\n  assign m_bready  = {s_bready && ob_rv && ob_rd, s_bready && ob_rv && !ob_rd};\n  assign m_arvalid = {s_arvalid && or_wr && arc, s_arvalid && or_wr && !arc};\n  assign s_arready = or_wr && m_arready[arc];\n  assign s_rvalid  = or_rv && m_rvalid[or_rd];\n  assign s_rid     = m_rid[or_rd];\n  assign s_rdata   = m_rdata[or_rd];\n  assign s_rresp   = m_rresp[or_rd];\n  assign s_rlast   = m_rlast[or_rd];\n  assign m_rready  = {s_rready && or_rv && or_rd, s_rready && or_rv && !or_rd};\nendmodule\n\n// One AXI4 channel's register slice: the payload, its valid and its ready all from flip-flops\n// (an output register and a skid entry), a beat per cycle at full rate, one cycle of latency. In\n// reset it takes nothing (s_ready low) and drops what it holds.\nmodule otpu_skid #(\n  parameter int W = 8\n) (\n  input  logic         clk,\n  input  logic         rst,\n  input  logic         s_valid,\n  output logic         s_ready,\n  input  logic [W-1:0] s_data,\n  output logic         m_valid,\n  input  logic         m_ready,\n  output logic [W-1:0] m_data\n);\n  logic         sk_v;\n  logic [W-1:0] sk_d;\n  logic         adv, take;\n  assign adv  = m_ready || !m_valid;      // the output register takes a beat\n  assign take = s_valid && s_ready;\n  always_ff @(posedge clk) begin\n    if (rst) begin m_valid <= 1'b0; sk_v <= 1'b0; s_ready <= 1'b0; end\n    else if (adv) begin m_valid <= sk_v || take; sk_v <= 1'b0; s_ready <= 1'b1; end\n    else if (take) begin sk_v <= 1'b1; s_ready <= 1'b0; end\n    else s_ready <= !sk_v;\n  end\n  // the skid entry loads whenever it is empty (taken or not: unused until sk_v), so its enable is a\n  // flip-flop's\n  always_ff @(posedge clk) begin\n    if (adv) m_data <= sk_v ? sk_d : s_data;\n    if (!sk_v) sk_d <= s_data;\n  end\nendmodule\n\n// An AXI4 register slice: otpu_skid on each of the five channels (otpu_dma_split). REG = 0: wires.\nmodule otpu_axi_slice #(\n  parameter bit REG = 1'b1,\n  parameter int IDW = 4,\n  parameter int DW  = 128\n) (\n  input  logic                  clk,\n  input  logic                  rst,\n  // slave\n  input  logic                  s_awvalid,\n  output logic                  s_awready,\n  input  logic [IDW-1:0]        s_awid,\n  input  logic [31:0]           s_awaddr,\n  input  logic [7:0]            s_awlen,\n  input  logic                  s_wvalid,\n  output logic                  s_wready,\n  input  logic [DW-1:0]         s_wdata,\n  input  logic [DW/8-1:0]       s_wstrb,\n  input  logic                  s_wlast,\n  output logic                  s_bvalid,\n  input  logic                  s_bready,\n  output logic [IDW-1:0]        s_bid,\n  output logic [1:0]            s_bresp,\n  input  logic                  s_arvalid,\n  output logic                  s_arready,\n  input  logic [IDW-1:0]        s_arid,\n  input  logic [31:0]           s_araddr,\n  input  logic [7:0]            s_arlen,\n  output logic                  s_rvalid,\n  input  logic                  s_rready,\n  output logic [IDW-1:0]        s_rid,\n  output logic [DW-1:0]         s_rdata,\n  output logic [1:0]            s_rresp,\n  output logic                  s_rlast,\n  // master\n  output logic                  m_awvalid,\n  input  logic                  m_awready,\n  output logic [IDW-1:0]        m_awid,\n  output logic [31:0]           m_awaddr,\n  output logic [7:0]            m_awlen,\n  output logic                  m_wvalid,\n  input  logic                  m_wready,\n  output logic [DW-1:0]         m_wdata,\n  output logic [DW/8-1:0]       m_wstrb,\n  output logic                  m_wlast,\n  input  logic                  m_bvalid,\n  output logic                  m_bready,\n  input  logic [IDW-1:0]        m_bid,\n  input  logic [1:0]            m_bresp,\n  output logic                  m_arvalid,\n  input  logic                  m_arready,\n  output logic [IDW-1:0]        m_arid,\n  output logic [31:0]           m_araddr,\n  output logic [7:0]            m_arlen,\n  input  logic                  m_rvalid,\n  output logic                  m_rready,\n  input  logic [IDW-1:0]        m_rid,\n  input  logic [DW-1:0]         m_rdata,\n  input  logic [1:0]            m_rresp,\n  input  logic                  m_rlast\n);\n  if (REG) begin : g_reg\n    otpu_skid #(.W(IDW + 40)) u_aw (.clk, .rst, .s_valid(s_awvalid), .s_ready(s_awready),\n      .s_data({s_awid, s_awaddr, s_awlen}), .m_valid(m_awvalid), .m_ready(m_awready),\n      .m_data({m_awid, m_awaddr, m_awlen}));\n    otpu_skid #(.W(DW + DW / 8 + 1)) u_w (.clk, .rst, .s_valid(s_wvalid), .s_ready(s_wready),\n      .s_data({s_wdata, s_wstrb, s_wlast}), .m_valid(m_wvalid), .m_ready(m_wready),\n      .m_data({m_wdata, m_wstrb, m_wlast}));\n    otpu_skid #(.W(IDW + 2)) u_b (.clk, .rst, .s_valid(m_bvalid), .s_ready(m_bready),\n      .s_data({m_bid, m_bresp}), .m_valid(s_bvalid), .m_ready(s_bready),\n      .m_data({s_bid, s_bresp}));\n    otpu_skid #(.W(IDW + 40)) u_ar (.clk, .rst, .s_valid(s_arvalid), .s_ready(s_arready),\n      .s_data({s_arid, s_araddr, s_arlen}), .m_valid(m_arvalid), .m_ready(m_arready),\n      .m_data({m_arid, m_araddr, m_arlen}));\n    otpu_skid #(.W(IDW + DW + 3)) u_r (.clk, .rst, .s_valid(m_rvalid), .s_ready(m_rready),\n      .s_data({m_rid, m_rdata, m_rresp, m_rlast}), .m_valid(s_rvalid), .m_ready(s_rready),\n      .m_data({s_rid, s_rdata, s_rresp, s_rlast}));\n  end else begin : g_wire\n    assign {m_awvalid, m_awid, m_awaddr, m_awlen} = {s_awvalid, s_awid, s_awaddr, s_awlen};\n    assign s_awready = m_awready;\n    assign {m_wvalid, m_wdata, m_wstrb, m_wlast} = {s_wvalid, s_wdata, s_wstrb, s_wlast};\n    assign s_wready = m_wready;\n    assign {s_bvalid, s_bid, s_bresp} = {m_bvalid, m_bid, m_bresp};\n    assign m_bready = s_bready;\n    assign {m_arvalid, m_arid, m_araddr, m_arlen} = {s_arvalid, s_arid, s_araddr, s_arlen};\n    assign s_arready = m_arready;\n    assign {s_rvalid, s_rid, s_rdata, s_rresp, s_rlast} =\n           {m_rvalid, m_rid, m_rdata, m_rresp, m_rlast};\n    assign m_rready = s_rready;\n  end\nendmodule\n\n// XDMA's DMA master onto the two channels' bridges (otpu_native_sys): otpu_axi_split2 and, with\n// REG (PCIe Gen2: xdma_aclk at 250 MHz), a register slice (otpu_axi_slice) on each side of it, at\n// XDMA's and at each bridge's, so no path between XDMA and a bridge, which sits by its DDR3 bank,\n// is combinational at either end (two cycles of latency each way). REG = 0: the split alone.\nmodule otpu_dma_split #(\n  parameter bit REG = 1'b0,\n  parameter int IDW = 4,\n  parameter int DW  = 128\n) (\n  input  logic                  clk,\n  input  logic                  rst,\n  // slave (XDMA)\n  input  logic                  s_awvalid,\n  output logic                  s_awready,\n  input  logic [IDW-1:0]        s_awid,\n  input  logic [31:0]           s_awaddr,\n  input  logic [7:0]            s_awlen,\n  input  logic                  s_wvalid,\n  output logic                  s_wready,\n  input  logic [DW-1:0]         s_wdata,\n  input  logic [DW/8-1:0]       s_wstrb,\n  input  logic                  s_wlast,\n  output logic                  s_bvalid,\n  input  logic                  s_bready,\n  output logic [IDW-1:0]        s_bid,\n  output logic [1:0]            s_bresp,\n  input  logic                  s_arvalid,\n  output logic                  s_arready,\n  input  logic [IDW-1:0]        s_arid,\n  input  logic [31:0]           s_araddr,\n  input  logic [7:0]            s_arlen,\n  output logic                  s_rvalid,\n  input  logic                  s_rready,\n  output logic [IDW-1:0]        s_rid,\n  output logic [DW-1:0]         s_rdata,\n  output logic [1:0]            s_rresp,\n  output logic                  s_rlast,\n  // masters, one per channel (the bridges)\n  output logic [1:0]            m_awvalid,\n  input  logic [1:0]            m_awready,\n  output logic [1:0][IDW-1:0]   m_awid,\n  output logic [1:0][31:0]      m_awaddr,\n  output logic [1:0][7:0]       m_awlen,\n  output logic [1:0]            m_wvalid,\n  input  logic [1:0]            m_wready,\n  output logic [1:0][DW-1:0]    m_wdata,\n  output logic [1:0][DW/8-1:0]  m_wstrb,\n  output logic [1:0]            m_wlast,\n  input  logic [1:0]            m_bvalid,\n  output logic [1:0]            m_bready,\n  input  logic [1:0][IDW-1:0]   m_bid,\n  input  logic [1:0][1:0]       m_bresp,\n  output logic [1:0]            m_arvalid,\n  input  logic [1:0]            m_arready,\n  output logic [1:0][IDW-1:0]   m_arid,\n  output logic [1:0][31:0]      m_araddr,\n  output logic [1:0][7:0]       m_arlen,\n  input  logic [1:0]            m_rvalid,\n  output logic [1:0]            m_rready,\n  input  logic [1:0][IDW-1:0]   m_rid,\n  input  logic [1:0][DW-1:0]    m_rdata,\n  input  logic [1:0][1:0]       m_rresp,\n  input  logic [1:0]            m_rlast\n);\n  // XDMA's side of the split (i_*) and its masters (j_*; the address, ID, length and write data\n  // go to both from i_*)\n  logic             i_awvalid, i_awready, i_wvalid, i_wready, i_wlast, i_bvalid, i_bready;\n  logic             i_arvalid, i_arready, i_rvalid, i_rready, i_rlast;\n  logic [IDW-1:0]   i_awid, i_arid, i_bid, i_rid;\n  logic [31:0]      i_awaddr, i_araddr;\n  logic [7:0]       i_awlen, i_arlen;\n  logic [DW-1:0]    i_wdata, i_rdata;\n  logic [DW/8-1:0]  i_wstrb;\n  logic [1:0]       i_bresp, i_rresp;\n  logic [1:0]           j_awvalid, j_awready, j_wvalid, j_wready, j_bvalid, j_bready;\n  logic [1:0]           j_arvalid, j_arready, j_rvalid, j_rready, j_rlast;\n  logic [1:0][IDW-1:0]  j_bid, j_rid;\n  logic [1:0][1:0]      j_bresp, j_rresp;\n  logic [1:0][DW-1:0]   j_rdata;\n\n  otpu_axi_slice #(.REG(REG), .IDW(IDW), .DW(DW)) u_xs (.clk, .rst,\n    .s_awvalid, .s_awready, .s_awid, .s_awaddr, .s_awlen, .s_wvalid, .s_wready, .s_wdata,\n    .s_wstrb, .s_wlast, .s_bvalid, .s_bready, .s_bid, .s_bresp, .s_arvalid, .s_arready, .s_arid,\n    .s_araddr, .s_arlen, .s_rvalid, .s_rready, .s_rid, .s_rdata, .s_rresp, .s_rlast,\n    .m_awvalid(i_awvalid), .m_awready(i_awready), .m_awid(i_awid), .m_awaddr(i_awaddr),\n    .m_awlen(i_awlen), .m_wvalid(i_wvalid), .m_wready(i_wready), .m_wdata(i_wdata),\n    .m_wstrb(i_wstrb), .m_wlast(i_wlast), .m_bvalid(i_bvalid), .m_bready(i_bready),\n    .m_bid(i_bid), .m_bresp(i_bresp), .m_arvalid(i_arvalid), .m_arready(i_arready),\n    .m_arid(i_arid), .m_araddr(i_araddr), .m_arlen(i_arlen), .m_rvalid(i_rvalid),\n    .m_rready(i_rready), .m_rid(i_rid), .m_rdata(i_rdata), .m_rresp(i_rresp), .m_rlast(i_rlast));\n\n  otpu_axi_split2 #(.IDW(IDW), .DW(DW)) u_split (.clk, .rst,\n    .s_awvalid(i_awvalid), .s_awready(i_awready), .s_awid(i_awid), .s_awaddr(i_awaddr),\n    .s_awlen(i_awlen), .s_wvalid(i_wvalid), .s_wready(i_wready), .s_wdata(i_wdata),\n    .s_wstrb(i_wstrb), .s_wlast(i_wlast), .s_bvalid(i_bvalid), .s_bready(i_bready),\n    .s_bid(i_bid), .s_bresp(i_bresp), .s_arvalid(i_arvalid), .s_arready(i_arready),\n    .s_arid(i_arid), .s_araddr(i_araddr), .s_arlen(i_arlen), .s_rvalid(i_rvalid),\n    .s_rready(i_rready), .s_rid(i_rid), .s_rdata(i_rdata), .s_rresp(i_rresp), .s_rlast(i_rlast),\n    .m_awvalid(j_awvalid), .m_awready(j_awready), .m_wvalid(j_wvalid), .m_wready(j_wready),\n    .m_bvalid(j_bvalid), .m_bready(j_bready), .m_bid(j_bid), .m_bresp(j_bresp),\n    .m_arvalid(j_arvalid), .m_arready(j_arready), .m_rvalid(j_rvalid), .m_rready(j_rready),\n    .m_rid(j_rid), .m_rdata(j_rdata), .m_rresp(j_rresp), .m_rlast(j_rlast));\n\n  for (genvar c = 0; c < 2; c++) begin : g_cs\n    otpu_axi_slice #(.REG(REG), .IDW(IDW), .DW(DW)) u_cs (.clk, .rst,\n      .s_awvalid(j_awvalid[c]), .s_awready(j_awready[c]), .s_awid(i_awid), .s_awaddr(i_awaddr),\n      .s_awlen(i_awlen), .s_wvalid(j_wvalid[c]), .s_wready(j_wready[c]), .s_wdata(i_wdata),\n      .s_wstrb(i_wstrb), .s_wlast(i_wlast), .s_bvalid(j_bvalid[c]), .s_bready(j_bready[c]),\n      .s_bid(j_bid[c]), .s_bresp(j_bresp[c]), .s_arvalid(j_arvalid[c]),\n      .s_arready(j_arready[c]), .s_arid(i_arid), .s_araddr(i_araddr), .s_arlen(i_arlen),\n      .s_rvalid(j_rvalid[c]), .s_rready(j_rready[c]), .s_rid(j_rid[c]), .s_rdata(j_rdata[c]),\n      .s_rresp(j_rresp[c]), .s_rlast(j_rlast[c]),\n      .m_awvalid(m_awvalid[c]), .m_awready(m_awready[c]), .m_awid(m_awid[c]),\n      .m_awaddr(m_awaddr[c]), .m_awlen(m_awlen[c]), .m_wvalid(m_wvalid[c]),\n      .m_wready(m_wready[c]), .m_wdata(m_wdata[c]), .m_wstrb(m_wstrb[c]), .m_wlast(m_wlast[c]),\n      .m_bvalid(m_bvalid[c]), .m_bready(m_bready[c]), .m_bid(m_bid[c]), .m_bresp(m_bresp[c]),\n      .m_arvalid(m_arvalid[c]), .m_arready(m_arready[c]), .m_arid(m_arid[c]),\n      .m_araddr(m_araddr[c]), .m_arlen(m_arlen[c]), .m_rvalid(m_rvalid[c]),\n      .m_rready(m_rready[c]), .m_rid(m_rid[c]), .m_rdata(m_rdata[c]), .m_rresp(m_rresp[c]),\n      .m_rlast(m_rlast[c]));\n  end\nendmodule\n\n// A register slice on one channel of the native port between otpu_native_dram and otpu_mem_ch\n// (otpu_board's n_*): the command and write-data streams through otpu_skid, the read data, the\n// write count and the error flag through a flip-flop each, so every signal both ways leaves and\n// enters from flip-flops (an SLR crossing on the BCU1525: one slice on each side,\n// constraints/bcu1525_floorplan.xdc). The native port's contract holds through it: commands keep\n// their order, the write data its write-command order, the read data its command order (no\n// backpressure, one cycle later); n_wdone comes a cycle late, so the adapter's WR_IDLE does too\n// (it counts a write taken here, and waits for the controller's count). In reset it holds nothing.\nmodule otpu_native_reg (\n  input  logic         clk,\n  input  logic         rst,\n  // the adapter's side\n  input  logic         s_cvalid,\n  output logic         s_cready,\n  input  logic         s_cwe,\n  input  logic [24:0]  s_caddr,\n  input  logic         s_wvalid,\n  output logic         s_wready,\n  input  logic [511:0] s_wdata,\n  input  logic [63:0]  s_wmask,\n  output logic         s_rvalid,\n  output logic [511:0] s_rdata,\n  output logic [15:0]  s_wdone,\n  output logic         s_err,\n  // the channel's side (otpu_mem_ch, the memory model)\n  output logic         m_cvalid,\n  input  logic         m_cready,\n  output logic         m_cwe,\n  output logic [24:0]  m_caddr,\n  output logic         m_wvalid,\n  input  logic         m_wready,\n  output logic [511:0] m_wdata,\n  output logic [63:0]  m_wmask,\n  input  logic         m_rvalid,\n  input  logic [511:0] m_rdata,\n  input  logic [15:0]  m_wdone,\n  input  logic         m_err\n);\n  otpu_skid #(.W(26)) u_cmd (.clk, .rst, .s_valid(s_cvalid), .s_ready(s_cready),\n    .s_data({s_cwe, s_caddr}), .m_valid(m_cvalid), .m_ready(m_cready), .m_data({m_cwe, m_caddr}));\n  otpu_skid #(.W(576)) u_wd (.clk, .rst, .s_valid(s_wvalid), .s_ready(s_wready),\n    .s_data({s_wmask, s_wdata}), .m_valid(m_wvalid), .m_ready(m_wready),\n    .m_data({m_wmask, m_wdata}));\n  always_ff @(posedge clk) begin\n    s_rvalid <= m_rvalid && !rst;\n    s_rdata  <= m_rdata;\n    s_wdone  <= m_wdone;\n    s_err    <= m_err;\n  end\nendmodule\n", "rtl/shell/otpu_board.sv": "// The accelerator as built for the PCIe boards: S slices (one on the YPCB-00338, two on the\n// BCU1525), each with its DRAM adapter otpu_native_dram onto two memory channels' native ports\n// n_* (one command per 64-byte beat, for otpu_mem_ch in front of LiteDRAM's native port: slice\n// s on channels 2s and 2s + 1), the collective unit, and the host control registers (AXI4-Lite\n// slave). Everything runs on the core clock; the board's top does the clock crossings to the\n// memory controllers and the PCIe bridge (otpu_native_sys on the YPCB). The slices share one\n// control block: RUN, LOAD (each slice loads the program from its own DRAM) and the arguments\n// go to every slice; HALTED when every slice halted, ERROR / WAIT_TO when any did; ICOUNT is\n// slice 0's, ICOUNT_s each slice's (0xC0 + 4s); the trace and the activity counters are slice\n// 0's, except DRAM_RD / DRAM_WR (every channel) and INSTR (every slice). Slice 0's instances\n// keep the one-slice names (u_slice, u_mem), the others are g_slice[s]. The control\n// block also holds the free-running activity counters and reads out the hardware trace\n// (otpu_trace; docs/observability.md); it also drives the I2C pins low when the host asks and\n// reads their levels back (the host bit-bangs I2C).\n// At S > 1 every slice sits in its own SLR (the BCU1525's), a crossing away from the control\n// block and the collective unit: everything between a slice and them goes through two register\n// stages each way (otpu_xr: one on each side of the crossing; g_xs), the slices' control too (so\n// they keep starting together), and the collective runs through otpu_coll_hub and a port per\n// slice (otpu_coll_port: each slice grants the collective's TMEM accesses on its own). At S = 1\n// the signals are wired as before (g_x1: the same logic, tools/synth/board_equiv.sh).\nmodule otpu_board #(\n  parameter int S          = 1,         // slices, each on two memory channels\n  parameter int D          = 128,\n  parameter int MCOLS      = 2,\n  parameter int ACT_BLOCKS = 128,\n  parameter int ACT_ROWS   = MCOLS,\n  parameter int TMEM_WORDS = 1 << 16,\n  parameter int IMEM_WORDS = 1 << 15,\n  parameter int FIFO_DEPTH = 1024,\n  parameter int LANES      = 8,\n  parameter int WIN        = 16,\n  parameter int TMEM_IMPL  = 0,         // TMEM: 0 a copy per read port, 1 banked (three copies;\n                                         //   otpu_slice: RPB 1, WPB 1)\n  parameter bit TMEM_RQ    = 1'b0,      // TMEM_IMPL 1: request-priority bank addresses\n  parameter int TMEM_NSB   = 8,         // TMEM_IMPL 3 (one copy, docs/tmem_nocopy.md): RAMs a bank,\n  parameter int TMEM_SBP   = 3,         //   the sub-bank's word-address bit, its hash, replays,\n  parameter int TMEM_SBH   = 0,         //   true dual-port RAMs, QUANT 3 and COLL the DMA's guests,\n  parameter bit TMEM_RPL   = 1'b0,      //   the RAMs pumped at 2x on clk_f (1), the read ports'\n  parameter bit TMEM_TDP   = 1'b0,      //   ranks and RAM sides (otpu_slice)\n  parameter bit TMEM_GST   = 1'b0,\n  parameter int TMEM_PMP   = 0,\n  parameter int TMEM_PRK   = 0,\n  parameter int TMEM_SDM   = -1,\n  parameter int RPB        = (TMEM_IMPL == 1) ? 1 : 8 * LANES,  // every read lane (TMEM is\n                                          // replicated per read port): the slice's shallow\n                                          // write-mask arbiter\n  parameter int WPB        = 1,\n  parameter int MXU_IMPL   = 2,\n  parameter int MXU_CL     = 16,\n  parameter int MXU_E      = 0,       // MXU epilogue lanes (0: MCOLS / 2; otpu_mxu E)\n  parameter int VPU_CL     = (LANES >= 8) ? LANES / 4 : 1,  // VPU lanes with exp2/recip/rsqrt\n  parameter int ULANES     = LANES,   // TMEM lanes of the MXU and the quantizer\n  parameter int CORE_KHZ    = 100000,  // the core clock (CORE_KHZ register)\n  parameter logic [31:0] BUILD_ID = 32'h0,\n  parameter int DDR_MTS     = 0,       // DDR3 data rate (DDR_MTS register; 0: not given)\n  parameter int TRACE_DEPTH = 16384,   // trace records (a power of two; 0: no trace buffer)\n  parameter int TRACE_QD    = 32,      // trace capture queue (cycles with events)\n  parameter int PQ_WIN      = 1024,    // cycles per P/Q counter window\n  parameter bit HAS_I2C     = 1'b1,    // the I2C pins are wired (CAPS bit2)\n  parameter bit CHASH       = 1'b1,    // hashed channel interleave (otpu_native_dram; CAPS bit7)\n  parameter bit DSTEP       = 1'b1,    // the DMA's DSTEP datapath (CAPS bit6; 0 leaves it out)\n  parameter bit HOSTCAL     = 1'b0,    // the host calibrates the DDR3 controllers (CAPS bit27: LiteDRAM)\n  parameter bit COLL_GATHER = 1'b1,    // 0 (S = 1 only): the collective unit runs BAR alone, no\n                                       // GATHER (otpu_coll_bar; CAPS2 bit0 = 0, docs/infra_hunt.md 5)\n  parameter bit SEQ_WC     = 1'b0,    // EXPERIMENTAL: otpu_seq's wait entries (WAITC, docs/seq_vpu.md; CFG_UARCH bit24)\n  parameter int PLATFORM    = 0,       // the target's platform id (CFG_PLATFORM; opentpu/target.py)\n  parameter logic [31:0] ARCH_HASH = 32'h0  // the target's arch_hash (CFG_HASH)\n) (\n  input  logic         clk,\n  input  logic         clk_f,          // TMEM_PMP 1: 2 x clk, rising with it (the MMCM's); else unused\n  input  logic         rst,            // synchronous, active high\n  input  logic         ctl_mrst,       // the control master's reset (the SmartConnect's, in clk:\n                                       //   PCIe hot reset or link down too): otpu_axil_iso\n  input  logic [2*S-1:0] calib,        // memory controllers calibrated (any clock domain)\n  input  logic [2*S-1:0] ded,          // a channel's ECC counted an uncorrectable word (any clock\n                                       //   domain; STATUS ECC_DED)\n  input  logic [11:0]  temp,           // XADC die-temperature code (any clock domain, slow)\n  output logic [2:0]   led,\n  // ---- I2C pins (otpu_fpga_top_ld's IOBUFs): 1 drives the line low; the levels (any clock)\n  output logic [3:0]   i2c_lo,         // SCL0 SDA0 (LM73 bus), SCL1 SDA1 (PCIe SMBus)\n  input  logic [4:0]   i2c_pin,        // the same four lines, then ALERT0 (LM73, active low)\n  // ---- control: AXI4-Lite slave\n  input  logic [11:0]  s_ctl_awaddr,\n  input  logic         s_ctl_awvalid,\n  output logic         s_ctl_awready,\n  input  logic [31:0]  s_ctl_wdata,\n  input  logic [3:0]   s_ctl_wstrb,\n  input  logic         s_ctl_wvalid,\n  output logic         s_ctl_wready,\n  output logic [1:0]   s_ctl_bresp,\n  output logic         s_ctl_bvalid,\n  input  logic         s_ctl_bready,\n  input  logic [11:0]  s_ctl_araddr,\n  input  logic         s_ctl_arvalid,\n  output logic         s_ctl_arready,\n  output logic [31:0]  s_ctl_rdata,\n  output logic [1:0]   s_ctl_rresp,\n  output logic         s_ctl_rvalid,\n  input  logic         s_ctl_rready,\n  // ---- memory channels 0 .. 2S-1: native masters (otpu_native_dram; slice s on 2s, 2s + 1)\n  output logic [2*S-1:0]        n_cvalid,\n  input  logic [2*S-1:0]        n_cready,\n  output logic [2*S-1:0]        n_cwe,\n  output logic [2*S-1:0][24:0]  n_caddr,   // the 64-byte beat in the channel (address bits 30:6)\n  output logic [2*S-1:0]        n_wvalid,  // write data: a beat per write command, in their order\n  input  logic [2*S-1:0]        n_wready,\n  output logic [2*S-1:0][511:0] n_wdata,\n  output logic [2*S-1:0][63:0]  n_wmask,   // 1 = write the byte\n  input  logic [2*S-1:0]        n_rvalid,  // read data in read-command order, no backpressure\n  input  logic [2*S-1:0][511:0] n_rdata,\n  input  logic [2*S-1:0][15:0]  n_wdone,   // write beats the controller has taken (mod 2^16)\n  input  logic [2*S-1:0]        n_err      // a channel's controller broke its port contract (sticky)\n);\n  import otpu_pkg::*;\n  localparam int XR = 2;              // register stages each way across an SLR (S > 1)\n\n  // ---- calibration and uncorrectable-ECC flags from the memory controllers' clock domains\n  // (registers there; levels, each bit on its own)\n  (* ASYNC_REG = \"TRUE\" *) logic [2*S-1:0] cal_s1, cal_s2, ded_s1, ded_s2;\n  // CALIB0 / CALIB1: every slice's first / second channel\n  logic [1:0] cal_all;\n  always_comb begin\n    cal_all = 2'b11;\n    for (int k = 0; k < S; k++) cal_all &= cal_s2[2*k +: 2];\n  end\n  always_ff @(posedge clk) begin\n    cal_s1 <= calib;\n    cal_s2 <= cal_s1;\n    ded_s1 <= ded;\n    ded_s2 <= ded_s1;\n  end\n\n  // ---- die temperature: two flip-flops per bit, then a code is taken only when two\n  // consecutive samples agree (it changes slowly: a sample caught mid-change is skipped). Valid\n  // once the XADC (the block design's, on the core clock) has reported a reading; it does not\n  // wait for the memory (the MIG builds' XADC was channel 0's, valid once it was calibrated).\n  (* ASYNC_REG = \"TRUE\" *) logic [11:0] tmp_s1, tmp_s2;\n  logic [11:0] tmp_s3, temp_q;\n  logic        temp_v;\n  always_ff @(posedge clk) begin\n    tmp_s1 <= temp;\n    tmp_s2 <= tmp_s1;\n    tmp_s3 <= tmp_s2;\n    if (rst) begin\n      temp_q <= '0;\n      temp_v <= 1'b0;\n    end else if (tmp_s2 == tmp_s3 && tmp_s3 != '0) begin\n      temp_q <= tmp_s3;\n      temp_v <= 1'b1;\n    end\n  end\n\n  // ---- I2C pin levels: two flip-flops each (the host samples them at microsecond pace)\n  (* ASYNC_REG = \"TRUE\" *) logic [4:0] i2c_s1, i2c_s2;\n  always_ff @(posedge clk) begin\n    i2c_s1 <= i2c_pin;\n    i2c_s2 <= i2c_s1;\n  end\n\n  // ---- control (slice 0's signals; the others' in g_slice)\n  logic run, ld_start, ld_busy, halted, error, wait_to, wr_idle, rd_idle, a_inval;\n  logic [31:0] ld_addr, ld_n;\n  logic [S-1:0][31:0] icount;        // each slice's\n  // every slice's, as the control block sees it: [0] slice 0's, [s] g_slice[s]'s\n  logic [S-1:0] sl_ld_busy, sl_halted, sl_error, sl_wait_to, sl_wr_idle, sl_rd_idle;\n  logic [S-1:0][1:0] sl_ret;         // instructions retired this cycle\n  // the slices' own (q_*) and what each slice is given (x_*): the same at S = 1, two register\n  // stages apart at S > 1 (g_xs)\n  logic [S-1:0] q_ld_busy, q_halted, q_error, q_wait_to, q_wr_idle, q_rd_idle;\n  logic [S-1:0][1:0] q_ret;\n  logic [S-1:0][31:0] q_icount;\n  logic [S-1:0] x_rst, x_srst, x_ld_start;\n  logic [S-1:0][31:0] x_ld_addr, x_ld_n;\n  logic [31:0] x_arg [S][8];\n  // the free-running counters' increments: every channel's beats, every slice's instructions\n  localparam int CW = $clog2(S * 2 + 1), IW = $clog2(2 * S + 1);\n  logic [CW-1:0] dram_rd, dram_wr;\n  logic [IW-1:0] instr;\n  logic [31:0] arg [8];               // the run's arguments (ARG0..7: R8..R15 at the start)\n  logic a_req, a_we, a_rvalid, a_rdy, b_req, b_tag, b_we, b_par, b_rvalid, b_rtag, b_rdy;\n  logic [31:0] a_addr, a_wdata, b_addr;\n  logic [255:0] a_rdata;\n  logic [3:0]  a_be, sw_be;\n  logic        sw_req, sw_rdy;\n  logic        m_wr_idle, m_rd_idle;   // slice 0's adapter's wr_idle and rd_idle (q_wr_idle[0],\n  logic        m_rv;                   //   q_rd_idle[0]: with its SW and port registers, below);\n                                       //   m_rv: a b_rvalid the cycle before\n  logic [31:0] sw_addr, sw_wdata;\n  logic [D/4-1:0] b_wmask;\n  logic [D*8-1:0] b_wdata, b_rdata;\n\n  perf_t pf, pf_c;                   // slice 0's, and as the control block sees it\n  logic        tr_en, tr_stop, tr_clear, tr_busy;\n  logic [31:0] tr_addr, tr_count, tr_drop;\n  logic [63:0] tr_rdata;\n\n  // the registers reset with rst (PERST#), the master also on a hot reset: an access in flight\n  // then is completed here and its response dropped (otpu_axil_iso)\n  logic [11:0] c_awaddr, c_araddr;\n  logic [31:0] c_wdata, c_rdata;\n  logic [3:0]  c_wstrb;\n  logic [1:0]  c_bresp, c_rresp;\n  logic c_awvalid, c_awready, c_wvalid, c_wready, c_bvalid, c_bready;\n  logic c_arvalid, c_arready, c_rvalid, c_rready;\n  otpu_axil_iso #(.AW(12)) u_iso (\n    .clk, .m_rst(ctl_mrst), .s_rst(rst),\n    .m_awaddr(s_ctl_awaddr), .m_awvalid(s_ctl_awvalid), .m_awready(s_ctl_awready),\n    .m_wdata(s_ctl_wdata), .m_wstrb(s_ctl_wstrb), .m_wvalid(s_ctl_wvalid),\n    .m_wready(s_ctl_wready), .m_bresp(s_ctl_bresp), .m_bvalid(s_ctl_bvalid),\n    .m_bready(s_ctl_bready), .m_araddr(s_ctl_araddr), .m_arvalid(s_ctl_arvalid),\n    .m_arready(s_ctl_arready), .m_rdata(s_ctl_rdata), .m_rresp(s_ctl_rresp),\n    .m_rvalid(s_ctl_rvalid), .m_rready(s_ctl_rready),\n    .s_awaddr(c_awaddr), .s_awvalid(c_awvalid), .s_awready(c_awready), .s_wdata(c_wdata),\n    .s_wstrb(c_wstrb), .s_wvalid(c_wvalid), .s_wready(c_wready), .s_bresp(c_bresp),\n    .s_bvalid(c_bvalid), .s_bready(c_bready), .s_araddr(c_araddr), .s_arvalid(c_arvalid),\n    .s_arready(c_arready), .s_rdata(c_rdata), .s_rresp(c_rresp), .s_rvalid(c_rvalid),\n    .s_rready(c_rready));\n\n  otpu_ctrl #(.D(D), .MCOLS(MCOLS), .ACT_ROWS(ACT_ROWS), .LANES(LANES), .CORE_KHZ(CORE_KHZ), .BUILD_ID(BUILD_ID),\n              .DDR_MTS(DDR_MTS), .TRACE_DEPTH(TRACE_DEPTH), .PQ_WIN(PQ_WIN), .HAS_TEMP(1'b1),\n              .HAS_I2C(HAS_I2C), .CHASH(CHASH), .DSTEP(DSTEP), .HOSTCAL(HOSTCAL),\n              .COLL_GATHER(COLL_GATHER),\n              .LDP(S > 1 ? 2 + 2 * XR : 2),  // LOAD to a slice's busy and back\n              // each slice on its two channels' 2 GiB each (otpu_native_dram): 4 GiB\n              .S(S), .TMEM_WORDS(TMEM_WORDS), .IMEM_WORDS(IMEM_WORDS), .ACT_BLOCKS(ACT_BLOCKS),\n              .DRAM_LOG2(32), .NCH(2), .CH_LOG2(31), .MXU_IMPL(MXU_IMPL), .TMEM_IMPL(TMEM_IMPL),\n              .VPU_CL(VPU_CL), .ULANES(ULANES), .SEQ_WC(SEQ_WC), .PLATFORM(PLATFORM),\n              .ARCH_HASH(ARCH_HASH)) u_ctrl (\n    .clk, .rst,\n    .s_awaddr(c_awaddr), .s_awvalid(c_awvalid), .s_awready(c_awready),\n    .s_wdata(c_wdata), .s_wstrb(c_wstrb), .s_wvalid(c_wvalid),\n    .s_wready(c_wready), .s_bresp(c_bresp), .s_bvalid(c_bvalid),\n    .s_bready(c_bready), .s_araddr(c_araddr), .s_arvalid(c_arvalid),\n    .s_arready(c_arready), .s_rdata(c_rdata), .s_rresp(c_rresp),\n    .s_rvalid(c_rvalid), .s_rready(c_rready),\n    .run, .ld_start, .arg, .ld_addr, .ld_n, .ld_busy, .halted, .error, .wait_to, .icount, .wr_idle,\n    .axi_err(|n_err),                  // the channels' bridges (otpu_mem_ch)\n    .calib(cal_all), .ecc_ded(|ded_s2),\n    .b_rd(b_req && b_rdy && !b_we), .b_wr(b_req && b_rdy && b_we),\n    .a_rd(a_req && a_rdy && !a_we), .a_wr(sw_req && sw_rdy), .b_wait(pf_c.bwait),\n    .temp_v, .temp(temp_q),\n    .mxu_busy(pf_c.sq.busy[U_MXU]), .mxu_mac(pf_c.mac), .mxu_starve(pf_c.starve),\n    .vpu_busy(pf_c.sq.busy[U_VPU]),\n    .qnt_busy(pf_c.sq.busy[U_Q]), .dma_busy(pf_c.sq.busy[U_DMA]), .tmem_deny(pf_c.deny),\n    .dram_rd, .dram_wr,\n    .dram_wait(pf_c.dwait),           // the units' waits (otpu_slice), not a parked register's\n    .instr,\n    .tr_en, .tr_stop, .tr_clear, .tr_addr, .tr_count, .tr_drop, .tr_busy, .tr_rdata,\n    .i2c_lo, .i2c_in(i2c_s2));\n\n  // ---- hardware trace\n  if (TRACE_DEPTH != 0) begin : g_trace\n    otpu_trace #(.DEPTH(TRACE_DEPTH), .QD(TRACE_QD), .WIN(WIN)) u_trace (\n      .clk, .rst, .pf(pf_c), .en(tr_en && run), .stop(tr_stop), .clear(tr_clear), .raddr(tr_addr),\n      .rdata(tr_rdata), .count(tr_count), .drop(tr_drop), .busy(tr_busy));\n  end else begin : g_no_trace\n    assign tr_rdata = '0;\n    assign tr_count = '0;\n    assign tr_drop = '0;\n    assign tr_busy = 1'b0;\n  end\n\n  // ---- the slices (held in reset while RUN is 0) and the collective unit.\n  // core_rst reaches ~15k flip-flops across the die: synthesis replicates it (a single copy's\n  // net took 9.6 ns, the worst core_clk path at 100 MHz). A run starts from a quiet memory\n  // adapter (go_ok: no read in flight, every write taken, sampled while RUN is 0 and until the\n  // run starts): the adapter does not reset with RUN, so a run the host stopped leaves its reads\n  // and writes going, and the next run's units would take the old reads' data\n  (* max_fanout = 256 *) logic core_rst;\n  logic go_ok;\n  always_ff @(posedge clk) begin\n    go_ok <= !rst && ((run && go_ok) || (rd_idle && wr_idle));\n    core_rst <= rst || !run || !go_ok;\n  end\n\n  // the run's status from every slice\n  assign ld_busy = |sl_ld_busy;\n  assign halted  = &sl_halted;\n  logic  coll_gerr;                    // a GATHER on the BAR-only collective unit (COLL_GATHER 0)\n  assign error   = |sl_error || coll_gerr;\n  assign wait_to = |sl_wait_to;\n  assign wr_idle = &sl_wr_idle;\n  assign rd_idle = &sl_rd_idle;\n  assign q_ret[0] = pf.sq.ret;\n\n  // the collective unit's ports (coll_*) and each slice's (sc_*): wired together at S = 1, the\n  // hub and a port per slice between them at S > 1\n  logic [S-1:0] coll_req;\n  logic         coll_ack, coll_gnt;\n  cmd_t         coll_cmds [S];\n  logic [S-1:0][LANES-1:0]       coll_ren;\n  logic [S-1:0][LANES-1:0][31:0] coll_raddr, coll_rdata;\n  logic [LANES-1:0]              coll_wen;\n  logic [LANES-1:0][31:0]        coll_waddr, coll_wdata;\n  logic [S-1:0]                  sc_req, sc_ack, sc_gl, sc_gnt;\n  cmd_t                          sc_cmd [S];\n  logic [S-1:0][LANES-1:0]       sc_ren, sc_wen;\n  logic [S-1:0][LANES-1:0][31:0] sc_raddr, sc_rdata, sc_waddr, sc_wdata;\n\n  otpu_slice #(.SID(0), .S(S), .D(D), .MCOLS(MCOLS), .ACT_BLOCKS(ACT_BLOCKS), .ACT_ROWS(ACT_ROWS),\n               .TMEM_WORDS(TMEM_WORDS), .IMEM_WORDS(IMEM_WORDS), .FIFO_DEPTH(FIFO_DEPTH),\n               .LANES(LANES), .WIN(WIN), .RPB(RPB), .WPB(WPB), .MXU_IMPL(MXU_IMPL),\n               .MXU_CL(MXU_CL), .MXU_E(MXU_E), .VPU_CL(VPU_CL), .ULANES(ULANES), .PQ_WIN(PQ_WIN),\n               .SEQ_WC(SEQ_WC), .HAS_DSTEP(DSTEP), .TMEM_IMPL(TMEM_IMPL), .TMEM_RQ(TMEM_RQ),\n               .TMEM_NSB(TMEM_NSB), .TMEM_SBP(TMEM_SBP), .TMEM_SBH(TMEM_SBH), .TMEM_RPL(TMEM_RPL), .TMEM_TDP(TMEM_TDP),\n               .TMEM_GST(TMEM_GST), .TMEM_PMP(TMEM_PMP), .TMEM_PRK(TMEM_PRK), .TMEM_SDM(TMEM_SDM)) u_slice (\n    .clk, .clk_f, .sys_rst(x_srst[0]), .rst(x_rst[0]), .rinit(x_arg[0]), .ld_start(x_ld_start[0]),\n    .ld_addr(x_ld_addr[0]), .ld_n(x_ld_n[0]),\n    .ld_busy(q_ld_busy[0]), .a_rdy, .b_rdy, .sw_rdy, .wr_idle(m_wr_idle),\n    .rd_idle(m_rd_idle),\n    .a_req, .a_we, .a_addr, .a_wdata, .a_be, .a_rvalid, .a_rdata,\n    .sw_req, .sw_addr, .sw_wdata, .sw_be,\n    .b_req, .b_tag, .b_we, .b_wmask, .b_wdata, .b_addr, .b_par, .b_rvalid, .b_rtag, .b_rdata,\n    .coll_req(sc_req[0]), .coll_cmd(sc_cmd[0]), .coll_ack(sc_ack[0]),\n    .coll_ren(sc_ren[0]), .coll_raddr(sc_raddr[0]), .coll_rdata(sc_rdata[0]),\n    .coll_wen(sc_wen[0]), .coll_waddr(sc_waddr[0]), .coll_wdata(sc_wdata[0]),\n    .coll_gnt_local(sc_gl[0]), .coll_gnt(sc_gnt[0]),\n    .halted(q_halted[0]), .error(q_error[0]), .wait_to(q_wait_to[0]), .a_inval,\n    .icount(q_icount[0]), .pf, .dump(1'b0));\n\n  // the collective's reset through a register of its own, next to it: it leaves reset a cycle\n  // after the slice, idle either way (133.33 MHz, 110ec6d: core_rst -> u_coll's state, 0 levels,\n  // 97% route, +0.162 ns); a request can only come many cycles after reset (checked)\n  logic coll_rst;\n  always_ff @(posedge clk) coll_rst <= core_rst;\n`ifndef SYNTHESIS\n  always @(posedge clk)\n    if (coll_rst && |coll_req) $fatal(1, \"otpu_board: a collective request in reset\");\n`endif\n  initial if (S > 1 && !COLL_GATHER) $fatal(1, \"otpu_board: COLL_GATHER 0 needs S = 1\");\n  if (COLL_GATHER) begin : g_coll\n    // RQ: its reads from its own request register on the slice's port at S = 1; at S > 1 each\n    // slice's otpu_coll_port presents them a cycle later (TMEM's input stage)\n    otpu_coll #(.S(S), .LANES(LANES), .RQ(S == 1)) u_coll (\n      .clk, .rst(coll_rst), .req(coll_req), .cmds(coll_cmds), .gnt(coll_gnt), .ack(coll_ack),\n      .r_en(coll_ren), .r_addr(coll_raddr), .r_data(coll_rdata),\n      .w_en(coll_wen), .w_addr(coll_waddr), .w_data(coll_wdata));\n    assign coll_gerr = 1'b0;\n  end else begin : g_coll_bar\n    otpu_coll_bar #(.S(S), .LANES(LANES)) u_coll (\n      .clk, .rst(coll_rst), .req(coll_req), .cmds(coll_cmds), .gnt(coll_gnt), .ack(coll_ack),\n      .r_en(coll_ren), .r_addr(coll_raddr), .r_data(coll_rdata),\n      .w_en(coll_wen), .w_addr(coll_waddr), .w_data(coll_wdata), .gerr(coll_gerr));\n  end\n\n  // ---- memory: the native adapter\n  // port A's held beats go where the host may have written: between runs, a load, a WAITW.\n  // Every write the slice gave is taken (STATUS WR_IDLE, go_ok) once the adapter has none\n  // pending and neither the slice's SW register nor its port B output register holds one (sw_req,\n  // b_req: the registers' valid bits); no read of the slice's is in flight (go_ok) once the\n  // adapter has none, neither port A's nor port B's output register holds one (a_req: port A\n  // reads only) and port B's input register holds no data (a b_rvalid the cycle before, m_rv). A\n  // request or data there is in neither the slice's units nor the adapter (otpu_slice)\n  assign q_wr_idle[0] = m_wr_idle && !sw_req && !(b_req && b_we);\n  assign q_rd_idle[0] = m_rd_idle && !a_req && !(b_req && !b_we) && !m_rv;\n  always_ff @(posedge clk) m_rv <= !x_srst[0] && b_rvalid;\n  otpu_native_dram #(.D(D), .CHASH(CHASH)) u_mem (\n    .clk, .rst(x_srst[0]), .a_flush(x_rst[0] || x_ld_start[0] || a_inval),\n    .a_rdy_x(a_rdy), .a_req_x(a_req), .a_we_x(a_we), .a_addr_x(a_addr), .a_wdata_x(a_wdata),\n        .a_be_x(a_be), .a_rvalid, .a_rdata,\n    .sw_rdy, .sw_req, .sw_addr, .sw_wdata, .sw_be,\n    .b_rdy, .b_req, .b_tag, .b_we, .b_wmask, .b_wdata, .b_addr, .b_par, .b_rvalid, .b_rtag,\n    .b_rdata, .wr_idle(m_wr_idle), .rd_idle(m_rd_idle),\n    .n_cvalid(n_cvalid[1:0]), .n_cready(n_cready[1:0]), .n_cwe(n_cwe[1:0]),\n    .n_caddr(n_caddr[1:0]), .n_wvalid(n_wvalid[1:0]), .n_wready(n_wready[1:0]),\n    .n_wdata(n_wdata[1:0]), .n_wmask(n_wmask[1:0]), .n_rvalid(n_rvalid[1:0]),\n    .n_rdata(n_rdata[1:0]), .n_wdone(n_wdone[1:0]));\n\n  // ---- slices 1 .. S-1, each on its two channels\n  for (genvar s = 1; s < S; s++) begin : g_slice\n    logic           a_req, a_we, a_rvalid, a_rdy, b_req, b_tag, b_we, b_par, b_rvalid, b_rtag;\n    logic           b_rdy, a_inval, sw_req, sw_rdy, m_wr_idle, m_rd_idle, m_rv;\n    logic [31:0]    a_addr, a_wdata, b_addr, sw_addr, sw_wdata;\n    logic [255:0]   a_rdata;\n    logic [3:0]     a_be, sw_be;\n    logic [D/4-1:0] b_wmask;\n    logic [D*8-1:0] b_wdata, b_rdata;\n    perf_t          pf;\n    assign q_ret[s] = pf.sq.ret;\n\n    otpu_slice #(.SID(s), .S(S), .D(D), .MCOLS(MCOLS), .ACT_BLOCKS(ACT_BLOCKS),\n                 .ACT_ROWS(ACT_ROWS), .TMEM_WORDS(TMEM_WORDS), .IMEM_WORDS(IMEM_WORDS),\n                 .FIFO_DEPTH(FIFO_DEPTH), .LANES(LANES), .WIN(WIN), .RPB(RPB), .WPB(WPB),\n                 .MXU_IMPL(MXU_IMPL), .MXU_CL(MXU_CL), .MXU_E(MXU_E), .VPU_CL(VPU_CL),\n                 .ULANES(ULANES), .PQ_WIN(PQ_WIN), .SEQ_WC(SEQ_WC), .HAS_DSTEP(DSTEP),\n                 .TMEM_IMPL(TMEM_IMPL), .TMEM_RQ(TMEM_RQ),\n                 .TMEM_NSB(TMEM_NSB), .TMEM_SBP(TMEM_SBP), .TMEM_SBH(TMEM_SBH), .TMEM_RPL(TMEM_RPL), .TMEM_TDP(TMEM_TDP),\n                 .TMEM_GST(TMEM_GST), .TMEM_PMP(TMEM_PMP), .TMEM_PRK(TMEM_PRK), .TMEM_SDM(TMEM_SDM)) u_slice (\n      .clk, .clk_f, .sys_rst(x_srst[s]), .rst(x_rst[s]), .rinit(x_arg[s]), .ld_start(x_ld_start[s]),\n      .ld_addr(x_ld_addr[s]), .ld_n(x_ld_n[s]),\n      .ld_busy(q_ld_busy[s]), .a_rdy, .b_rdy, .sw_rdy, .wr_idle(m_wr_idle),\n      .rd_idle(m_rd_idle),\n      .a_req, .a_we, .a_addr, .a_wdata, .a_be, .a_rvalid, .a_rdata,\n      .sw_req, .sw_addr, .sw_wdata, .sw_be,\n      .b_req, .b_tag, .b_we, .b_wmask, .b_wdata, .b_addr, .b_par, .b_rvalid, .b_rtag, .b_rdata,\n      .coll_req(sc_req[s]), .coll_cmd(sc_cmd[s]), .coll_ack(sc_ack[s]),\n      .coll_ren(sc_ren[s]), .coll_raddr(sc_raddr[s]), .coll_rdata(sc_rdata[s]),\n      .coll_wen(sc_wen[s]), .coll_waddr(sc_waddr[s]), .coll_wdata(sc_wdata[s]),\n      .coll_gnt_local(sc_gl[s]), .coll_gnt(sc_gnt[s]),\n      .halted(q_halted[s]), .error(q_error[s]), .wait_to(q_wait_to[s]), .a_inval,\n      .icount(q_icount[s]), .pf, .dump(1'b0));\n\n    otpu_native_dram #(.D(D), .CHASH(CHASH)) u_mem (\n      .clk, .rst(x_srst[s]), .a_flush(x_rst[s] || x_ld_start[s] || a_inval),\n      .a_rdy_x(a_rdy), .a_req_x(a_req), .a_we_x(a_we), .a_addr_x(a_addr), .a_wdata_x(a_wdata),\n          .a_be_x(a_be), .a_rvalid, .a_rdata,\n      .sw_rdy, .sw_req, .sw_addr, .sw_wdata, .sw_be,\n      .b_rdy, .b_req, .b_tag, .b_we, .b_wmask, .b_wdata, .b_addr, .b_par, .b_rvalid, .b_rtag,\n      .b_rdata, .wr_idle(m_wr_idle), .rd_idle(m_rd_idle),\n      .n_cvalid(n_cvalid[2*s +: 2]), .n_cready(n_cready[2*s +: 2]), .n_cwe(n_cwe[2*s +: 2]),\n      .n_caddr(n_caddr[2*s +: 2]), .n_wvalid(n_wvalid[2*s +: 2]),\n      .n_wready(n_wready[2*s +: 2]), .n_wdata(n_wdata[2*s +: 2]), .n_wmask(n_wmask[2*s +: 2]),\n      .n_rvalid(n_rvalid[2*s +: 2]), .n_rdata(n_rdata[2*s +: 2]), .n_wdone(n_wdone[2*s +: 2]));\n    assign q_wr_idle[s] = m_wr_idle && !sw_req && !(b_req && b_we);     // as slice 0's\n    assign q_rd_idle[s] = m_rd_idle && !a_req && !(b_req && !b_we) && !m_rv;\n    always_ff @(posedge clk) m_rv <= !x_srst[s] && b_rvalid;\n  end\n\n  if (S == 1) begin : g_x1\n    // ---- one slice: wired\n    assign x_rst[0] = core_rst;\n    assign x_srst[0] = rst;\n    assign x_ld_start[0] = ld_start;\n    assign x_ld_addr[0] = ld_addr;\n    assign x_ld_n[0] = ld_n;\n    assign x_arg[0] = arg;\n    assign sl_ld_busy = q_ld_busy;\n    assign sl_halted = q_halted;\n    assign sl_error = q_error;\n    assign sl_wait_to = q_wait_to;\n    assign sl_wr_idle = q_wr_idle;\n    assign sl_rd_idle = q_rd_idle;\n    assign sl_ret = q_ret;\n    assign icount = q_icount;\n    assign pf_c = pf;\n    always_comb begin\n      dram_rd = '0;\n      dram_wr = '0;\n      instr = '0;\n      for (int c = 0; c < 2 * S; c++) begin\n        dram_rd += CW'(n_rvalid[c]);\n        dram_wr += CW'(n_wvalid[c] && n_wready[c]);\n      end\n      for (int k = 0; k < S; k++) instr += IW'(sl_ret[k]);\n    end\n    assign coll_req = sc_req;\n    assign coll_cmds = sc_cmd;\n    assign sc_ack = coll_ack;\n    assign sc_ren = coll_ren;\n    assign sc_raddr = coll_raddr;\n    assign coll_rdata = sc_rdata;\n    assign sc_wen[0] = coll_wen;\n    assign sc_waddr[0] = coll_waddr;\n    assign sc_wdata[0] = coll_wdata;\n    assign coll_gnt = &sc_gl;           // every slice's TMEM grant\n    assign sc_gnt = coll_gnt;\n  end else begin : g_xs\n    // ---- S slices, each in its own SLR: two register stages each way between a slice and the\n    // control block / the collective unit (otpu_xr: u_*_tx on the sending side, u_*_rx on the\n    // receiving one; bcu1525_floorplan.tcl places them), so every signal crosses from a flip-flop\n    // into one. Every slice's control goes through them, slice 0's too (the slices start\n    // together); what comes back is XR cycles late, which the control block's LOAD window\n    // (LDP) covers. The collective: otpu_coll_hub next to the unit, an otpu_coll_port per slice.\n    localparam int L = LANES, CB = $bits(cmd_t), PB = $bits(perf_t);\n    // down, per slice: pulses (ack, read, write; cleared by reset), the collective's read and\n    // write, the control\n    localparam int DW = 3 + L + 32 * L + L + 64 * L + 3 + 64 + 256;\n    // up, per slice: levels / pulses (request, read data, pop; cleared by reset), the data, the\n    // command, the status, the channels' beats this cycle\n    localparam int UW = 3 + 32 * L + CB + 6 + 2 + 32 + 4;\n    logic                   h_ack, h_wv;\n    logic [S-1:0]           h_rv, h_req, h_dv, h_pop;\n    logic [L-1:0]           h_rm, h_wm;\n    logic [L-1:0][31:0]     h_ra, h_wa, h_wd;\n    logic [S-1:0][L-1:0][31:0] h_dd;\n    cmd_t                   h_cmd [S];\n    logic [S-1:0][1:0]      sl_drd, sl_dwr;\n\n    otpu_coll_hub #(.S(S), .LANES(L)) u_chub (\n      .clk, .rst(coll_rst),\n      .u_req(coll_req), .u_cmds(coll_cmds), .u_gnt(coll_gnt), .u_ack(coll_ack),\n      .u_ren(coll_ren), .u_raddr(coll_raddr), .u_rdata(coll_rdata),\n      .u_wen(coll_wen), .u_waddr(coll_waddr), .u_wdata(coll_wdata),\n      .x_req(h_req), .x_cmds(h_cmd), .x_ack(h_ack), .x_rv(h_rv), .x_rm(h_rm), .x_ra(h_ra),\n      .x_dv(h_dv), .x_dd(h_dd), .x_wv(h_wv), .x_wm(h_wm), .x_wa(h_wa), .x_wd(h_wd),\n      .x_pop(h_pop));\n\n    for (genvar s = 0; s < S; s++) begin : g_x\n      logic [DW-1:0] dn_d, dn_m, dn_q;\n      logic [UW-1:0] up_d, up_m, up_q;\n      logic [255:0]  arg_d, arg_q;\n      logic          p_dv, p_pop;\n      logic [L-1:0][31:0] p_dd;\n      logic [L-1:0]       p_rm, p_wm;\n      logic [L-1:0][31:0] p_ra, p_wa, p_wd;\n      logic          p_rv, p_wv, rx_crst;\n      logic [1:0]    drd, dwr;\n      for (genvar k = 0; k < 8; k++) begin : g_arg\n        assign arg_d[32*k +: 32] = arg[k];\n        assign x_arg[s][k] = arg_q[32*k +: 32];\n      end\n      assign dn_d = {arg_d, ld_n, ld_addr, ld_start, core_rst, rst, h_wd, h_wa, h_wm, h_ra, h_rm,\n                     h_wv, h_rv[s], h_ack};\n      otpu_xr #(.W(DW), .RW(3)) u_dn_tx (.clk, .rst(coll_rst), .d(dn_d), .q(dn_m));\n      otpu_xr #(.W(DW), .RW(3)) u_dn_rx (.clk, .rst(rx_crst), .d(dn_m), .q(dn_q));\n      assign {arg_q, x_ld_n[s], x_ld_addr[s], x_ld_start[s], rx_crst, x_srst[s], p_wd, p_wa,\n              p_wm, p_ra, p_rm, p_wv, p_rv, sc_ack[s]} = dn_q;\n      assign x_rst[s] = rx_crst;\n\n      otpu_coll_port #(.LANES(L)) u_cport (\n        .clk, .rst(x_rst[s]), .rv(p_rv), .rm(p_rm), .ra(p_ra), .wv(p_wv), .wm(p_wm), .wa(p_wa),\n        .wd(p_wd), .dv(p_dv), .dd(p_dd), .pop(p_pop),\n        .coll_ren(sc_ren[s]), .coll_raddr(sc_raddr[s]), .coll_rdata(sc_rdata[s]),\n        .coll_wen(sc_wen[s]), .coll_waddr(sc_waddr[s]), .coll_wdata(sc_wdata[s]),\n        .gnt_local(sc_gl[s]), .gnt(sc_gnt[s]));\n\n      // the slice's channels' beats this cycle (DRAM_RD / DRAM_WR), counted on its side\n      always_comb begin\n        drd = '0;\n        dwr = '0;\n        for (int c = 2 * s; c < 2 * s + 2; c++) begin\n          drd += 2'(n_rvalid[c]);\n          dwr += 2'(n_wvalid[c] && n_wready[c]);\n        end\n      end\n      assign up_d = {drd, dwr, q_icount[s], q_ret[s], q_ld_busy[s], q_halted[s], q_error[s],\n                     q_wait_to[s], q_wr_idle[s], q_rd_idle[s], sc_cmd[s], p_dd, p_pop, p_dv,\n                     sc_req[s]};\n      otpu_xr #(.W(UW), .RW(3)) u_up_tx (.clk, .rst(x_rst[s]), .d(up_d), .q(up_m));\n      otpu_xr #(.W(UW), .RW(3)) u_up_rx (.clk, .rst(coll_rst), .d(up_m), .q(up_q));\n      assign {sl_drd[s], sl_dwr[s], icount[s], sl_ret[s], sl_ld_busy[s], sl_halted[s],\n              sl_error[s], sl_wait_to[s], sl_wr_idle[s], sl_rd_idle[s], h_cmd[s], h_dd[s],\n              h_pop[s], h_dv[s], h_req[s]} = up_q;\n\n      if (s == 0) begin : g_pf          // slice 0's activity (the counters, the trace)\n        logic [PB-1:0] pf_m;\n        otpu_xr #(.W(PB)) u_pf_tx (.clk, .rst(1'b0), .d(pf), .q(pf_m));\n        otpu_xr #(.W(PB)) u_pf_rx (.clk, .rst(1'b0), .d(pf_m), .q(pf_c));\n      end\n    end\n\n    always_comb begin\n      dram_rd = '0;\n      dram_wr = '0;\n      instr = '0;\n      for (int k = 0; k < S; k++) begin\n        dram_rd += CW'(sl_drd[k]);\n        dram_wr += CW'(sl_dwr[k]);\n        instr += IW'(sl_ret[k]);\n      end\n    end\n  end\n\n  // ---- LEDs: heartbeat, running, halted/error\n  logic [26:0] hb;\n  always_ff @(posedge clk) hb <= hb + 1;\n  assign led = {halted && !error, run && !halted, hb[26]};\nendmodule\n\n// One register stage of an SLR crossing (otpu_board at S > 1: a pair per direction and slice, one\n// stage on each side). The low RW bits (valid pulses, request levels) clear with rst; the others\n// are data. max_fanout: a stage's reset bit drives a slice's whole core reset (as core_rst).\nmodule otpu_xr #(\n  parameter int W  = 1,\n  parameter int RW = 0\n) (\n  input  logic         clk,\n  input  logic         rst,\n  input  logic [W-1:0] d,\n  output logic [W-1:0] q\n);\n  (* max_fanout = 256 *) logic [W-1:0] r;     // r_reg: the floorplan's USER_SLL_REG cells\n  assign q = r;\n  always_ff @(posedge clk) begin\n    r <= d;\n    if (rst) for (int i = 0; i < RW; i++) r[i] <= 1'b0;\n  end\nendmodule\n", "rtl/shell/otpu_ctrl.sv": "// Host control registers (AXI4-Lite slave, reached from the host through the PCIe bridge's\n// BAR). All in the core clock domain. Register map version 5 (docs/observability.md: the\n// contract with the host); 12 address bits are decoded (the map repeats every 4 KiB).\n//\n//   0x00 ID        RO  0x4F545055 (\"OTPU\")\n//   0x04 VERSION   RO  {D[15:0], MCOLS[7:0], LANES[7:0]}\n//   0x08 CTRL      RW  bit0 RUN: 1 releases the slice from reset (write 0, then 1, per run); it\n//                      rises only while both channels are calibrated (CALIB0 and CALIB1), else\n//                      the write leaves it 0 (STATUS RUN)\n//                      bit1 LOAD (write 1: copy PROG_N instructions from PROG_ADDR into IMEM;\n//                      only while RUN = 0 and both channels are calibrated)\n//                      bit2 CLEAR: zero the per-run counters (0x18 .. 0x34)\n//                      Stopping a run (RUN 1 -> 0) stops the slice at once; what it gave the memory\n//                      still goes: wait for WR_IDLE before writing the DRAM the run wrote or read.\n//                      Its reads still in flight are dropped (a LOAD and the next run start after\n//                      them)\n//   0x0C STATUS    RO  bit0 HALTED, bit1 ERROR (illegal instruction; or WAIT_TO), bit2 LOADING,\n//                      bit3 WR_IDLE (every write the slice gave the memory is taken by the DDR3\n//                      controllers), bit4 AXI_ERR (sticky: a DDR3 controller broke its port contract,\n//                      otpu_mem_ch n_err; on the MIG builds an AXI error response), bit5 CALIB0,\n//                      bit6 CALIB1, bit7 RUN,\n//                      bit8 WAIT_TO (with ERROR: a WAITW timed out; as ERROR, until RUN falls),\n//                      bit9 ECC_DED (a channel's ECC counted an uncorrectable 64-bit word since its\n//                      counters were last cleared: the LiteDRAM CSR ecc_clear / ecc1_clear; the\n//                      word's data was wrong, and a partial write merged into it wrote it back\n//                      with good check bits)\n//   0x10 PROG_ADDR RW  program byte address in the slice's DRAM (chunk aligned)\n//   0x14 PROG_N    RW  program length in instructions\n//   0x18 CYCLES    RO  core cycles since RUN rose, until HALTED (low 32 bits)\n//   0x1C CYCLES_HI RO\n//   0x20 ICOUNT    RO  instructions retired\n//   0x24 B_RD      RO  port B read requests taken (chunks)\n//   0x28 B_WR      RO  port B write requests taken\n//   0x2C A_RD      RO  port A read requests taken\n//   0x30 SW_WR     RO  scalar (QST) write requests taken\n//   0x34 B_STALL   RO  cycles a port B request waited for the memory\n//   0x38 SCRATCH   RW  (host bring-up test)\n//   0x3C REGMAP    RO  register map version (5; 4 before CAPS2, 3 before the CFG_* registers)\n//   0x40 CAPS      RO  bit0 trace buffer, bit1 temperature, bit2 I2C pins, bit3 DDR_MTS,\n//                      bit4 4-bit MM weights (MM flags WF, docs/isa.md), bit5 column reuse (MM\n//                      PAIR / QACT DUP), bit6 DSTEP (the DMA's DeltaNet head step), bit7\n//                      hashed channel interleave (otpu_native_dram CHASH), bit24 ACT_ROWS,\n//                      [15:8] log2(trace depth), [23:16] log2(P/Q window cycles),\n//                      bit25 the run's arguments (ARG0..7), bit26 STREAM (the stream engine's\n//                      hardware subset, docs/stream.md; with DSTEP), bit27 the DDR3\n//                      controllers want the host's calibration (LiteDRAM:\n//                      opentpu/host/memcal.py), bit29 MX: the MX numerics (MM's exact\n//                      accumulation with power-of-two block scales, QACT / QST's offsets;\n//                      docs/isa.md, docs/mx_mxu.md; every bitstream since), bit30 GEN: the\n//                      decode loop's instructions\n//                      (RLD, VOP ARGMAX, HALT CHAIN; docs/isa.md, docs/autodecode.md), bit31\n//                      WAITW (the DMA waits for a word the host writes; docs/isa.md)\n//   0x44 CORE_KHZ  RO  the core clock in kHz (build parameter)\n//   0x48 BUILD_ID  RO  build parameter (the low 32 bits of the git commit)\n//   0x4C TEMP      RO  bit31 valid, [11:0] XADC die-temperature code\n//   0x50 SNAP      W   latch every free-running counter into its shadow; R: snapshots taken\n//   0x54 DDR_MTS   RO  the DDR3 data rate in MT/s (build parameter; CAPS bit3 when nonzero)\n//   0x58 ACT_ROWS  RO  ACT RAM rows: the most rows of one MM (build parameter; CAPS bit24)\n//   0x5C CAPS2     RO  (version 5; CAPS is full) bit0 GATHER: the collective unit runs GATHER\n//                      (always at S > 1; at S = 1 unless built without it, otpu_board COLL_GATHER:\n//                      then BAR alone, and a GATHER raises ERROR)\n//   0x60 + 4k      RW  ARG0..ARG7: the run's arguments, R8..R15 when RUN rises (CAPS bit25;\n//                      docs/isa.md \"Arguments\"); reset 0\n//   0x80 CFG_SLICES   RO  slices S (version 4: the configuration the target file built,\n//                         opentpu/target.py; docs/targets.md)\n//   0x84 CFG_TMEM     RO  TMEM words per slice\n//   0x88 CFG_IMEM     RO  IMEM words per slice (8 per instruction)\n//   0x8C CFG_ACT      RO  ACT RAM blocks\n//   0x90 CFG_DRAM     RO  [7:0] log2 DRAM bytes per slice, [15:8] memory channels per slice,\n//                         [23:16] log2 bytes a slice addresses per channel\n//   0x94 CFG_UARCH    RO  [3:0] MXU_IMPL, [7:4] TMEM_IMPL, [15:8] VPU_CL, [23:16] ULANES,\n//                         [24] SEQ_WC (otpu_seq's wait entries: every program needs them, docs/isa.md)\n//   0x98 CFG_PLATFORM RO  the target's platform id (1 YPCB-00338, 2 BCU1525; 256 and up ASICs)\n//   0x9C CFG_HASH     RO  opentpu.target.arch_hash of the target's Config at build time\n//   0xA0 + 4s         (reserved: slice s's DRAM window, docs/targets.md)\n//   0xC0 + 4s ICOUNT_s RO slice s's instructions retired (S > 1; ICOUNT is slice 0's)\n//   0x100 + 8k     RO  free-running counter k's shadow (64 bits, low word first), k =\n//                      UPTIME RUNNING MXU_BUSY MXU_MAC VPU_BUSY QNT_BUSY DMA_BUSY TMEM_DENY\n//                      DRAM_RD DRAM_WR DRAM_WAIT INSTR MXU_STARVE (version 3); cleared by\n//                      reset only\n//   0x200 TRACE_CTRL RW  bit0 ENABLE (record while RUN), bit1 CLEAR (write 1), bit2 STOP_WHEN_FULL,\n//                        bit3 BUSY (read only: events not yet in the buffer)\n//   0x204 TRACE_COUNT RO records written since the clear (saturating in its high bits: otpu_trace)\n//   0x208 TRACE_DROP RO  events lost to a full capture queue\n//   0x20C TRACE_ADDR RW  the record to read\n//   0x210 TRACE_LO   RO  its bits [31:0]\n//   0x214 TRACE_HI   RO  its bits [63:32]; reading it increments TRACE_ADDR\n//   0x220 I2C_CTRL   RW  open-drain pins, 1 = drive low, 0 = release: bit0 SCL0, bit1 SDA0\n//                        (LM73 sensor bus), bit2 SCL1, bit3 SDA1 (PCIe edge SMBus); reset 0\n//   0x224 I2C_IN     RO  the pin levels (synchronized by otpu_board): bit0 SCL0, bit1 SDA0,\n//                        bit2 SCL1, bit3 SDA1, bit4 ALERT0 (LM73 ALERT, active low)\n// Reads answer three cycles after the address is taken (a registered address, a registered\n// multiplexer, the data register), which also gives the trace RAM time after TRACE_ADDR moves.\nmodule otpu_ctrl #(\n  parameter int D     = 128,\n  parameter int MCOLS = 2,\n  parameter int LANES = 8,\n  parameter int ACT_ROWS = MCOLS,\n  parameter int CORE_KHZ = 100000,\n  parameter logic [31:0] BUILD_ID = 32'h0,\n  parameter int DDR_MTS = 0,             // DDR3 data rate (MT/s); 0: not given\n  parameter int TRACE_DEPTH = 16384,     // 0: no trace buffer\n  parameter int PQ_WIN = 1024,           // the trace's P/Q window (cycles)\n  parameter bit HAS_TEMP = 1'b1,\n  parameter bit HAS_I2C = 1'b1,          // CAPS bit2: the I2C pins are wired (otpu_fpga_top_ld)\n  parameter bit CHASH = 1'b0,            // CAPS bit7: the hashed channel interleave (otpu_native_dram)\n  parameter bit DSTEP = 1'b1,            // CAPS bit6 and bit26: the stream engine (DSTEP, STREAM)\n  parameter bit HOSTCAL = 1'b0,          // CAPS bit27: the host calibrates the DDR3 controllers\n  parameter bit COLL_GATHER = 1'b1,      // CAPS2 bit0 (with S > 1): the collective unit runs GATHER\n  parameter int LDP = 2,                 // cycles after LOAD before the loaders' busy shows (>= 2)\n  // the configuration registers (CFG_*, register map 4): the target's values\n  parameter int S          = 1,\n  parameter int TMEM_WORDS = 1 << 16,\n  parameter int IMEM_WORDS = 1 << 15,\n  parameter int ACT_BLOCKS = 128,\n  parameter int DRAM_LOG2  = 32,         // log2 DRAM bytes per slice\n  parameter int NCH        = 2,          // memory channels per slice\n  parameter int CH_LOG2    = 31,         // log2 bytes a slice addresses per channel\n  parameter int MXU_IMPL   = 2,\n  parameter int TMEM_IMPL  = 0,\n  parameter int VPU_CL     = 2,\n  parameter int ULANES     = 8,\n  parameter bit SEQ_WC     = 1'b0,    // EXPERIMENTAL: otpu_seq's wait entries (WAITC, docs/seq_vpu.md; CFG_UARCH bit24)\n  parameter int PLATFORM   = 0,\n  parameter logic [31:0] ARCH_HASH = 32'h0,\n  // the free-running counters' increment widths (2 and 2 for the YPCB's one slice on two\n  // channels): DRAM_RD / DRAM_WR the beats every slice's channels move in a cycle, INSTR the\n  // instructions every slice retires in a cycle (up to 2 each)\n  parameter int CW         = $clog2(S * NCH + 1),\n  parameter int IW         = $clog2(2 * S + 1)\n) (\n  input  logic        clk,\n  input  logic        rst,\n  // AXI4-Lite slave\n  input  logic [11:0] s_awaddr,\n  input  logic        s_awvalid,\n  output logic        s_awready,\n  input  logic [31:0] s_wdata,\n  input  logic [3:0]  s_wstrb,\n  input  logic        s_wvalid,\n  output logic        s_wready,\n  output logic [1:0]  s_bresp,\n  output logic        s_bvalid,\n  input  logic        s_bready,\n  input  logic [11:0] s_araddr,\n  input  logic        s_arvalid,\n  output logic        s_arready,\n  output logic [31:0] s_rdata,\n  output logic [1:0]  s_rresp,\n  output logic        s_rvalid,\n  input  logic        s_rready,\n  // core\n  output logic        run,\n  output logic        ld_start,\n  output logic [31:0] arg [8],           // ARG0..7 -> the sequencer's R8..R15\n  output logic [31:0] ld_addr,\n  output logic [31:0] ld_n,\n  input  logic        ld_busy,\n  input  logic        halted,\n  input  logic        error,\n  input  logic        wait_to,\n  input  logic [S-1:0][31:0] icount,  // each slice's (ICOUNT: slice 0's; ICOUNT_s at 0xC0 + 4s)\n  input  logic        wr_idle,\n  input  logic        axi_err,\n  input  logic [1:0]  calib,\n  input  logic        ecc_ded,           // STATUS ECC_DED (synchronized: otpu_board)\n  input  logic        b_rd, b_wr, a_rd, a_wr, b_wait,\n  input  logic        temp_v,\n  input  logic [11:0] temp,\n  // activity for the free-running counters (any registered or combinational source)\n  input  logic        mxu_busy, mxu_mac, vpu_busy, qnt_busy, dma_busy, tmem_deny,\n  input  logic        mxu_starve,        // the MXU streams a command and has no chunk\n  input  logic [CW-1:0] dram_rd, dram_wr,  // 64-byte beats this cycle (every slice's channels)\n  input  logic        dram_wait,\n  input  logic [IW-1:0] instr,           // instructions retired this cycle (every slice's)\n  // trace buffer (otpu_trace)\n  output logic        tr_en,\n  output logic        tr_stop,\n  output logic        tr_clear,\n  output logic [31:0] tr_addr,\n  input  logic [31:0] tr_count,\n  input  logic [31:0] tr_drop,\n  input  logic        tr_busy,\n  input  logic [63:0] tr_rdata,\n  // I2C pins (the host bit-bangs them: opentpu/host/i2c.py)\n  output logic [3:0]  i2c_lo,\n  input  logic [4:0]  i2c_in\n);\n  localparam int NFR = 13;\n  localparam logic [31:0] CAPS = {1'b1, 1'b1, 1'b1, 1'b0, HOSTCAL, DSTEP, 2'd3,  // bit31 WAITW, bit30 GEN, bit29 MX, bit27 HOSTCAL, bit26 STREAM, bit25 ARG, bit24 ACT_ROWS\n                                  8'($clog2(PQ_WIN)),\n                                  8'(TRACE_DEPTH != 0 ? $clog2(TRACE_DEPTH) : 0),\n                                  CHASH, DSTEP, 1'b1, 1'b1, DDR_MTS != 0, HAS_I2C, HAS_TEMP,\n                                  TRACE_DEPTH != 0};\n\n  localparam logic [31:0] CAPS2 = {31'd0, COLL_GATHER || S > 1};   // bit0 GATHER\n\n  logic [63:0] cycles;\n  logic [31:0] n_brd, n_bwr, n_ard, n_awr, n_bst, scratch;\n  logic        clear, snap;\n  logic [LDP-1:0] ld_pend_q;               // LOAD written, loader not yet visibly busy\n  wire         ld_pend = ld_start || (|ld_pend_q);\n  always_ff @(posedge clk) ld_pend_q <= rst ? '0 : {ld_pend_q[LDP-2:0], ld_start};\n\n  // ---- write channel: take address and data together\n  logic       w_go, tr_inc;\n  assign s_awready = s_awvalid && s_wvalid && !s_bvalid;\n  assign s_wready  = s_awready;\n  assign w_go      = s_awready;\n  assign s_bresp   = 2'b00;\n\n  always_ff @(posedge clk) begin\n    ld_start <= 1'b0;\n    clear <= 1'b0;\n    snap <= 1'b0;\n    tr_clear <= 1'b0;\n    if (rst) begin\n      run <= 1'b0;\n      s_bvalid <= 1'b0;\n      ld_addr <= '0; ld_n <= '0; scratch <= '0;\n      tr_en <= 1'b0; tr_stop <= 1'b0; tr_addr <= '0;\n      i2c_lo <= '0;\n      for (int k = 0; k < 8; k++) arg[k] <= '0;\n    end else begin\n      if (s_bvalid && s_bready) s_bvalid <= 1'b0;\n      if (tr_inc) tr_addr <= tr_addr + 1;\n      if (w_go) begin\n        s_bvalid <= 1'b1;\n        case (s_awaddr[11:2])\n          10'h002: begin\n            run <= s_wdata[0] && (run || &calib);\n            ld_start <= s_wdata[1] && !s_wdata[0] && !run && &calib;\n            clear <= s_wdata[2];\n          end\n          10'h004: ld_addr <= s_wdata;\n          10'h005: ld_n <= s_wdata;\n          10'h00E: scratch <= s_wdata;\n          10'h014: snap <= 1'b1;\n          10'h080: begin\n            tr_en <= s_wdata[0];\n            tr_clear <= s_wdata[1];\n            tr_stop <= s_wdata[2];\n          end\n          10'h083: tr_addr <= s_wdata;\n          10'h088: i2c_lo <= s_wdata[3:0];\n          10'h018, 10'h019, 10'h01A, 10'h01B, 10'h01C, 10'h01D, 10'h01E, 10'h01F:\n            arg[s_awaddr[4:2]] <= s_wdata;\n          default: ;\n        endcase\n      end\n    end\n  end\n\n  // ---- per-run counters\n  always_ff @(posedge clk) begin\n    if (rst || clear) begin\n      cycles <= '0; n_brd <= '0; n_bwr <= '0; n_ard <= '0; n_awr <= '0; n_bst <= '0;\n    end else begin\n      if (run && !halted) cycles <= cycles + 1;\n      if (b_rd) n_brd <= n_brd + 1;\n      if (b_wr) n_bwr <= n_bwr + 1;\n      if (a_rd) n_ard <= n_ard + 1;\n      if (a_wr) n_awr <= n_awr + 1;\n      if (b_wait) n_bst <= n_bst + 1;\n    end\n  end\n\n  // ---- free-running counters (reset only), their increments registered first; SNAP copies\n  // them all into the shadows in one cycle\n  localparam int FW = CW > IW ? CW : IW;\n  logic [15:0][31:0] ic_all;  // ICOUNT_s (S > 1)\n  always_comb begin\n    ic_all = '0;\n    ic_all[S-1:0] = icount;\n  end\n  logic [FW-1:0] fr_inc [NFR];\n  logic [63:0] fr [NFR], fr_s [NFR];\n  logic [31:0] n_snap;\n  always_ff @(posedge clk) begin\n    fr_inc[0]  <= FW'(1);\n    fr_inc[1]  <= FW'(run && !halted);\n    fr_inc[2]  <= FW'(mxu_busy);\n    fr_inc[3]  <= FW'(mxu_mac);\n    fr_inc[4]  <= FW'(vpu_busy);\n    fr_inc[5]  <= FW'(qnt_busy);\n    fr_inc[6]  <= FW'(dma_busy);\n    fr_inc[7]  <= FW'(tmem_deny);\n    fr_inc[8]  <= FW'(dram_rd);\n    fr_inc[9]  <= FW'(dram_wr);\n    fr_inc[10] <= FW'(dram_wait);\n    fr_inc[11] <= FW'(instr);\n    fr_inc[12] <= FW'(mxu_starve);\n    if (rst) begin\n      for (int k = 0; k < NFR; k++) begin fr[k] <= '0; fr_s[k] <= '0; fr_inc[k] <= '0; end\n      n_snap <= '0;\n    end else begin\n      for (int k = 0; k < NFR; k++) fr[k] <= fr[k] + 64'(fr_inc[k]);\n      if (snap) begin\n        for (int k = 0; k < NFR; k++) fr_s[k] <= fr[k];\n        n_snap <= n_snap + 1;\n      end\n    end\n  end\n\n  // ---- read channel: one read at a time; address, multiplexer and data registered\n  logic [9:0]  r_a;\n  logic [1:0]  r_p;\n  logic [31:0] r_d;\n  assign s_arready = !s_rvalid && r_p == 2'b00;\n  assign s_rresp = 2'b00;\n  assign tr_inc = r_p[1] && r_a == 10'h085;\n  always_ff @(posedge clk) begin\n    if (rst) begin\n      s_rvalid <= 1'b0;\n      r_p <= 2'b00;\n    end else begin\n      if (s_rvalid && s_rready) s_rvalid <= 1'b0;\n      r_p <= {r_p[0], s_arvalid && s_arready};\n      if (r_p[1]) begin\n        s_rvalid <= 1'b1;\n        s_rdata <= r_d;\n      end\n    end\n    if (s_arvalid && s_arready) r_a <= s_araddr[11:2];\n    case (r_a)\n      10'h000: r_d <= 32'h4F54_5055;\n      10'h001: r_d <= {16'(D), 8'(MCOLS), 8'(LANES)};\n      10'h002: r_d <= {31'd0, run};\n      10'h003: r_d <= {22'd0, ecc_ded, wait_to, run, calib, axi_err, wr_idle, ld_busy || ld_pend,\n                       error, halted};\n      10'h004: r_d <= ld_addr;\n      10'h005: r_d <= ld_n;\n      10'h006: r_d <= cycles[31:0];\n      10'h007: r_d <= cycles[63:32];\n      10'h008: r_d <= icount[0];\n      10'h009: r_d <= n_brd;\n      10'h00A: r_d <= n_bwr;\n      10'h00B: r_d <= n_ard;\n      10'h00C: r_d <= n_awr;\n      10'h00D: r_d <= n_bst;\n      10'h00E: r_d <= scratch;\n      10'h00F: r_d <= 32'd5;\n      10'h010: r_d <= CAPS;\n      10'h011: r_d <= 32'(CORE_KHZ);\n      10'h012: r_d <= BUILD_ID;\n      10'h013: r_d <= {temp_v, 19'd0, temp};\n      10'h014: r_d <= n_snap;\n      10'h015: r_d <= 32'(DDR_MTS);\n      10'h016: r_d <= 32'(ACT_ROWS);\n      10'h017: r_d <= CAPS2;\n      10'h018, 10'h019, 10'h01A, 10'h01B, 10'h01C, 10'h01D, 10'h01E, 10'h01F:\n        r_d <= arg[r_a[2:0]];\n      10'h020: r_d <= 32'(S);\n      10'h021: r_d <= 32'(TMEM_WORDS);\n      10'h022: r_d <= 32'(IMEM_WORDS);\n      10'h023: r_d <= 32'(ACT_BLOCKS);\n      10'h024: r_d <= {8'd0, 8'(CH_LOG2), 8'(NCH), 8'(DRAM_LOG2)};\n      10'h025: r_d <= {7'd0, SEQ_WC, 8'(ULANES), 8'(VPU_CL), 4'(TMEM_IMPL), 4'(MXU_IMPL)};\n      10'h026: r_d <= 32'(PLATFORM);\n      10'h027: r_d <= ARCH_HASH;\n      10'h080: r_d <= {28'd0, tr_busy, tr_stop, 1'b0, tr_en};\n      10'h081: r_d <= tr_count;\n      10'h082: r_d <= tr_drop;\n      10'h083: r_d <= tr_addr;\n      10'h084: r_d <= tr_rdata[31:0];\n      10'h085: r_d <= tr_rdata[63:32];\n      10'h088: r_d <= {28'd0, i2c_lo};\n      10'h089: r_d <= {27'd0, i2c_in};\n      default:\n        if (S > 1 && r_a[9:4] == 6'h03 && 32'(r_a[3:0]) < 32'(S))\n          r_d <= ic_all[r_a[3:0]];\n        else if (r_a[9:6] == 4'h1 && r_a[5:1] < 5'(NFR))\n          r_d <= r_a[0] ? fr_s[r_a[5:1]][63:32] : fr_s[r_a[5:1]][31:0];\n        else\n          r_d <= 32'hDEAD_BEEF;\n    endcase\n  end\nendmodule\n\n// AXI4-Lite between a master and a slave that reset apart (otpu_board: the control registers;\n// otpu_fpga_top_ld: the LiteDRAM core's CSR port). The block design's SmartConnect, the master,\n// resets with XDMA's axi_aresetn (PERST#, and a PCIe hot reset or link down too); the control\n// registers reset with the core reset (PERST#, not a hot reset), the LiteDRAM core's CSR port with\n// the core's own clocks only. A slave that answered an access after its master's reset handed the\n// fresh master a response it never asked for. One access at a time: a write's AW and W are taken\n// together (as otpu_ctrl takes them), a read's AR, and given to the slave; its response is taken\n// from the slave and held for the master. m_rst, the master's reset: the master's side forgets\n// the access (a held response is dropped), but what the slave was given is completed with it (AW\n// and W both, its response taken and dropped), so the slave never sees half an access or answers\n// into the master's next one; a new access waits for that. s_rst, the slave's reset (the LiteDRAM\n// core's sys reset: its PLL, or its ctrl_reset CSR): an access it had is answered SLVERR. An access\n// costs three cycles more (the request and the response registered).\nmodule otpu_axil_iso #(\n  parameter int AW = 32\n) (\n  input  logic          clk,\n  input  logic          m_rst,\n  input  logic          s_rst,\n  // the master's side\n  input  logic [AW-1:0] m_awaddr,\n  input  logic          m_awvalid,\n  output logic          m_awready,\n  input  logic [31:0]   m_wdata,\n  input  logic [3:0]    m_wstrb,\n  input  logic          m_wvalid,\n  output logic          m_wready,\n  output logic [1:0]    m_bresp,\n  output logic          m_bvalid,\n  input  logic          m_bready,\n  input  logic [AW-1:0] m_araddr,\n  input  logic          m_arvalid,\n  output logic          m_arready,\n  output logic [31:0]   m_rdata,\n  output logic [1:0]    m_rresp,\n  output logic          m_rvalid,\n  input  logic          m_rready,\n  // the slave's side\n  output logic [AW-1:0] s_awaddr,\n  output logic          s_awvalid,\n  input  logic          s_awready,\n  output logic [31:0]   s_wdata,\n  output logic [3:0]    s_wstrb,\n  output logic          s_wvalid,\n  input  logic          s_wready,\n  input  logic [1:0]    s_bresp,\n  input  logic          s_bvalid,\n  output logic          s_bready,\n  output logic [AW-1:0] s_araddr,\n  output logic          s_arvalid,\n  input  logic          s_arready,\n  input  logic [31:0]   s_rdata,\n  input  logic [1:0]    s_rresp,\n  input  logic          s_rvalid,\n  output logic          s_rready\n);\n  // busy: an access is with the slave, or its response with the master (m_bvalid / m_rvalid);\n  // wr: it is a write; drop: the master was reset since it gave it (its response goes nowhere).\n  // Both resets are on at configuration (the valids clear)\n  logic busy = 1'b0, wr = 1'b0, drop = 1'b0;\n  // a write's ready waits for both its valids (as otpu_ctrl's), a read's does not (as otpu_ctrl's)\n  assign m_awready = !s_rst && !m_rst && !busy && m_awvalid && m_wvalid;\n  assign m_wready  = m_awready;\n  assign m_arready = !s_rst && !m_rst && !busy && !(m_awvalid && m_wvalid);\n  assign s_bready  = busy && wr && !m_bvalid;\n  assign s_rready  = busy && !wr && !m_rvalid;\n  always_ff @(posedge clk) begin\n    if (m_awready) begin\n      busy <= 1'b1; wr <= 1'b1; drop <= 1'b0;\n      s_awvalid <= 1'b1; s_wvalid <= 1'b1;\n      s_awaddr <= m_awaddr; s_wdata <= m_wdata; s_wstrb <= m_wstrb;\n    end else if (m_arvalid && m_arready) begin\n      busy <= 1'b1; wr <= 1'b0; drop <= 1'b0;\n      s_arvalid <= 1'b1;\n      s_araddr <= m_araddr;\n    end\n    if (s_awvalid && s_awready) s_awvalid <= 1'b0;\n    if (s_wvalid && s_wready) s_wvalid <= 1'b0;\n    if (s_arvalid && s_arready) s_arvalid <= 1'b0;\n    // the slave's response: to the master, or dropped (the access is then over)\n    if (s_bvalid && s_bready) begin\n      if (drop || m_rst) busy <= 1'b0;\n      else m_bvalid <= 1'b1;\n      m_bresp <= s_bresp;\n    end\n    if (s_rvalid && s_rready) begin\n      if (drop || m_rst) busy <= 1'b0;\n      else m_rvalid <= 1'b1;\n      m_rresp <= s_rresp; m_rdata <= s_rdata;\n    end\n    if ((m_bvalid && m_bready) || (m_rvalid && m_rready)) begin\n      busy <= 1'b0; m_bvalid <= 1'b0; m_rvalid <= 1'b0;\n    end\n    // the master's reset: a held response is dropped (the access is over), one still with the\n    // slave will be\n    if (m_rst) begin\n      m_bvalid <= 1'b0; m_rvalid <= 1'b0;\n      if (m_bvalid || m_rvalid) busy <= 1'b0;\n      else if (busy) drop <= 1'b1;\n    end\n    // the slave's reset: what it was given is gone; an access still with it is answered SLVERR\n    // (the master is not left waiting), or over if its master was reset too\n    if (s_rst) begin\n      s_awvalid <= 1'b0; s_wvalid <= 1'b0; s_arvalid <= 1'b0;\n      if (busy && !m_bvalid && !m_rvalid) begin\n        if (drop || m_rst) busy <= 1'b0;\n        else begin m_bvalid <= wr; m_rvalid <= !wr; m_bresp <= 2'b10; m_rresp <= 2'b10; end\n      end\n    end\n  end\nendmodule\n", "rtl/shell/otpu_mem_ch.sv": "// One DDR3 channel's user side: the accelerator's native master (otpu_native_dram, core clock,\n// one 64-byte beat per command) and XDMA's AXI master (host loads and reads, axi_aclk, 128-bit)\n// onto the two native ports of the channel's controller (uclk: LiteDRAM's sys). With\n// otpu_axi_split2 it replaced the MIG builds' SmartConnect and the MIG's AXI front end.\n//\n// Each master's commands cross into uclk through its own asynchronous FIFOs (commands, write\n// data) and its read data comes back through another; an arbiter in uclk takes up to RUN commands\n// from one master before it lets the other in, one command per cycle, and each master's commands\n// in its order (XDMA's writes held back into batches while the accelerator streams: XT, XB, below).\n// The accelerator's write data comes in write-command order, before or after its command: a write\n// goes when both are at the heads of their FIFOs. The controller returns a port's read data in\n// that port's command order and cannot hold it back, so one tag per read (its master, its slot)\n// routes the data back, and a master's read is issued only when its read-data FIFO has\n// room for it and for every read not yet through (credits). The accelerator's read data leaves\n// without backpressure too (its master reserves room for its reads), from a register.\n//\n// Two ports: LiteDRAM's crossbar lets a master have commands in one bank at a time (the next\n// bank's command waits until the previous bank's last column command), which idles the channel\n// at every bank change (docs/litedram.md section 11). So each command goes to the port of its\n// beat's bank parity (beat bit 7: ROW_BANK_COLUMN, 8 KiB rows), through that port's own output\n// command queue (OQ entries, then a register), write-data FIFO and read tags, and a port whose\n// bank waits holds back only its own commands. A beat is always on the same port and each port\n// keeps its commands in order, so the ordering below holds per beat; the two ports' commands are\n// not ordered against each other. They share the channel's data bus: read data comes back from\n// one port at a time, each port's in its order. Each read takes the next slot of its master's\n// read-data FIFO when it issues (the credits keep it free); its data is written there when its\n// port returns it, and the FIFO lets it through once every earlier slot is written (otpu_afifo\n// OOO), so a master sees its read data in command order.\n//\n// The controller port has LiteDRAM's native-port semantics: commands (we, beat), write data taken\n// (wdata ready) some cycles after its command, in write-command order, and read data in command\n// order. LiteDRAM's crossbar takes the write data when the bank asks for it without looking at\n// wdata valid, so a write's data enters its port's output data FIFO (only the controller's reset\n// clears it) in the cycle its command enters the port's output command queue (the arbiter sees\n// only registered state): the data is there before the controller can take the command, and the\n// per-master holds cannot take either back. (LiteDRAMNativePortECC puts a one-beat register\n// in front of the crossbar that takes the head as soon as it is empty; it is loaded well before\n// the bank asks, which is at least 4 cycles after the command. Its rdata ready must be tied high.)\n//\n// Partial beats (any byte not written): LiteDRAM's ECC port rejects partial writes, and the board\n// has no DM pins, so the read-modify-write is done here. The arbiter issues a read of the beat and\n// stops; the write's command and data stay at the heads of their master's FIFOs; when the read's\n// data comes back (its tag), the old bytes fill the lanes not written and the whole beat is\n// written, and only then does the arbiter go on. So nothing reaches the controller between the\n// read and the write: the read comes after every command issued before it, the write before every\n// command issued after it (both on the beat's port), and the controller keeps one port's commands\n// in order (LiteDRAM locks a port to one bank until that bank's queue has drained; each bank\n// machine is a FIFO). A partial beat costs about one read latency of the whole channel.\n//\n// n_wdone counts the accelerator's write beats the controller has taken on either port (the\n// command handshake; the data is then already in the output FIFO), gray-coded across into the\n// core clock. Every command to the same beat issued after that, from either master, reaches the\n// controller behind the write (on the same port), so the write is visible to both masters. An\n// XDMA write burst gets its B the same way, once all of its 64-byte beats are taken (and its\n// WLAST is in). XDMA's 16-byte beats are packed into 64-byte beats per burst (a partial beat at\n// either end is a partial write). The counts cross per port and per master: the two ports can\n// each take a write in the same cycle, and a count of both then stepped by two, two bits of its\n// gray code, so a sample caught between them read one beat ahead (from an even count) or one back\n// (from an odd one). Each port's count moves at most one a cycle, one bit; the master's side adds\n// its ports' counts as synchronized, each a value its count had, so the sum never runs ahead.\n//\n// Addresses: n_caddr and bits 30:6 of XDMA's byte address select the 64-byte beat in the channel\n// (2 GiB; XDMA's bit 31, the channel, is dropped by otpu_axi_split2). XDMA's bursts are INCR of\n// 16-byte beats (AxSIZE 4) and may start anywhere in a 64-byte beat; narrow bursts are not\n// supported (XDMA issues none). Its reads return in order (legal for any IDs); responses are OKAY.\n//\n// n_err: the controller broke its side of the port contract -- read data from both ports in one\n// cycle, or on a port with no read outstanding. Sticky until the controller's reset, in the core\n// clock (otpu_board: STATUS AXI_ERR), so the card shows it too; the simulation stops on it.\n//\n// Resets: each master's path has a hold in uclk -- the controller's reset, or the master's own\n// reset (synchronized, and kept up until the hold is seen in the master's clock, so that a reset\n// of a cycle gets a whole hold too), then 16 cycles, and on until its reads in flight have come\n// back (their data is dropped), a read-modify-write of its own is done and no command of its own\n// is left in the output command queues (a write counted after the hold would count one the\n// master issued before its reset: its write count restarts from n_wdone's reset value, 0) -- and\n// the same hold, synchronized, in the master's clock. The clock-crossing FIFOs reset only on the\n// hold, in both clocks, so neither side ever sees the other's pointers reset under it; the\n// master's side of the bridge resets on its reset or the hold. What the arbiter has issued is\n// finished regardless (a merged write whose master is held is dropped: its data went with the\n// FIFO). So a PCIe link reset (XDMA's axi_aresetn) while the accelerator runs costs neither the\n// other master nor the memory.\n//\n// Clock-domain crossings: every synchronizer carries ASYNC_REG; their constraints (max delay\n// without skew, bus skew for the gray counts) are in boards/ypcb-00338/constraints/otpu_mem_ch.tcl.\nmodule otpu_mem_ch #(\n  parameter int XIDW = 4,         // XDMA M_AXI ID width\n  parameter int ARD  = 64,        // accelerator read-data FIFO (read credits), beats\n  parameter int XRD  = 16,        // XDMA read-data FIFO, beats\n  parameter int RUN  = 32,        // commands from one master before the arbiter may switch\n  parameter int OQ   = 32,        // output command queue per port (and one register)\n  parameter int OD   = 32,        // output write-data FIFO per port: writes issued, data not taken\n  parameter int XQD  = 32,        // XDMA's command and write-data FIFOs, beats (a batch's room)\n  parameter int XT   = 256,       // XDMA's batches: uclk cycles a ready X waits for one (0: none)\n  parameter int XB   = 24         // ... or until XB of its commands are queued (0: the wait alone)\n) (\n  // accelerator (otpu_native_dram), core clock\n  input  logic            clk,\n  input  logic            rst,\n  input  logic            n_cvalid,\n  output logic            n_cready,\n  input  logic            n_cwe,\n  input  logic [24:0]     n_caddr,    // 64-byte beat in the channel\n  input  logic            n_wvalid,   // one beat per write command, in write-command order\n  output logic            n_wready,\n  input  logic [511:0]    n_wdata,\n  input  logic [63:0]     n_wmask,    // 1 = write the byte\n  output logic            n_rvalid,   // in read-command order, no backpressure\n  output logic [511:0]    n_rdata,\n  output logic [15:0]     n_wdone,    // write beats taken by the controller, mod 2^16\n  output logic            n_err,      // the controller broke the port contract (sticky)\n  // XDMA, axi_aclk\n  input  logic            xclk,\n  input  logic            xrst,\n  input  logic            x_awvalid,\n  output logic            x_awready,\n  input  logic [XIDW-1:0] x_awid,\n  input  logic [31:0]     x_awaddr,\n  input  logic [7:0]      x_awlen,\n  input  logic            x_wvalid,\n  output logic            x_wready,\n  input  logic [127:0]    x_wdata,\n  input  logic [15:0]     x_wstrb,\n  input  logic            x_wlast,\n  output logic            x_bvalid,\n  input  logic            x_bready,\n  output logic [XIDW-1:0] x_bid,\n  output logic [1:0]      x_bresp,\n  input  logic            x_arvalid,\n  output logic            x_arready,\n  input  logic [XIDW-1:0] x_arid,\n  input  logic [31:0]     x_araddr,\n  input  logic [7:0]      x_arlen,\n  output logic            x_rvalid,\n  input  logic            x_rready,\n  output logic [XIDW-1:0] x_rid,\n  output logic [127:0]    x_rdata,\n  output logic [1:0]      x_rresp,\n  output logic            x_rlast,\n  // the controller's two native ports, uclk: port p takes the beats of the banks of parity p\n  input  logic            uclk,\n  input  logic            urst,\n  output logic [1:0]      c_cmd_valid,\n  input  logic [1:0]      c_cmd_ready,\n  output logic [1:0]      c_cmd_we,\n  output logic [1:0][24:0] c_cmd_addr,\n  output logic [1:0]      c_wdata_valid,\n  input  logic [1:0]      c_wdata_ready,\n  output logic [1:0][511:0] c_wdata_data,\n  output logic [1:0][63:0] c_wdata_we,    // 1 = write the byte (all ones: whole beats)\n  input  logic [1:0]      c_rdata_valid,  // each port's in its command order, no backpressure;\n                                          //   one port at a time\n  input  logic [1:0][511:0] c_rdata_data  // one bus: port 1's is port 0's (only port 0's is read)\n);\n  localparam int QW = 26;                  // command: {write, beat[24:0]}\n  localparam int DW = 577;                 // write data: {partial, byte enables[63:0], data[511:0]}\n  localparam int CW = 16;                  // write-accept counters (beats, modulo 2^16)\n  localparam int AOW = $clog2(ARD) + 1;\n  localparam int XOW = $clog2(XRD) + 1;\n  localparam int ASW = $clog2(ARD);        // read slots\n  localparam int XSW = $clog2(XRD);\n  localparam int TW  = 2 + ASW;            // read tag: {read-modify-write, xdma, slot}\n  // the read tags' FIFO per port: every read in flight (ARD + XRD and a read-modify-write's), a\n  // power of two (128 at the board's ARD 64, XRD 16)\n  localparam int TGD = 2 ** $clog2(ARD + XRD + 1);\n  initial if (XRD > ARD) $fatal(1, \"otpu_mem_ch: XRD > ARD (the tag's slot)\");\n\n  function automatic logic [CW-1:0] b2g(input logic [CW-1:0] b);\n    return b ^ (b >> 1);\n  endfunction\n  function automatic logic [CW-1:0] g2b(input logic [CW-1:0] g);\n    logic [CW-1:0] b;\n    b[CW-1] = g[CW-1];\n    for (int i = CW - 2; i >= 0; i--) b[i] = b[i + 1] ^ g[i];\n    return b;\n  endfunction\n\n  // ================================================================ resets\n  // The controller's reset (urst: the core's sys reset register, which drives both channels'\n  // bridges and the core's own loads) registered once here (keep), by this channel's bridge; the\n  // bridge's controller side takes it (urq), a cycle after the controller. In the fused c2830d6\n  // build at 133.33 MHz, crg_rst1 -> u_ch0 g_port[*].u_oq wp / rp R (fanout 500, 0 levels,\n  // 6.6 ns of route, +0.059) was the worst path. The cycle in which the controller is out of\n  // reset and the bridge not: every master is held (the holds last 15 cycles past urq), so no\n  // command enters the queues, and the controller, reset with no reads, returns no data (checked\n  // below); on the way in, the bridge runs a cycle into the controller's reset, and what it\n  // queues then goes with its own reset a cycle later.\n  (* keep = \"true\" *) logic urq = 1'b1;\n  always_ff @(posedge uclk) urq <= urst;\n  (* ASYNC_REG = \"TRUE\" *) logic a_rs1, a_rs2, x_rs1, x_rs2;    // master resets in uclk\n  (* ASYNC_REG = \"TRUE\" *) logic a_hs1 = 1'b1, a_hs2 = 1'b1;     // holds in the masters' clocks\n  (* ASYNC_REG = \"TRUE\" *) logic x_hs1 = 1'b1, x_hs2 = 1'b1;\n  logic a_hold = 1'b1, x_hold = 1'b1;\n  logic [3:0] a_hcnt, x_hcnt;\n  logic a_crst = 1'b1, x_crst = 1'b1;      // the masters' sides of the bridge\n  logic a_req = 1'b0, x_req = 1'b0;        // a master's reset, held until its hold is seen back\n  logic [AOW-1:0] a_out;                   // reads in flight (issued, data not yet in the FIFO)\n  logic [XOW-1:0] x_out;\n  logic rm_busy, rm_x;                     // a read-modify-write in progress, and its master\n  logic a_oc, x_oc;                        // a command of the master's in the output queues\n  always_ff @(posedge uclk) begin\n    a_rs1 <= a_req; a_rs2 <= a_rs1;\n    x_rs1 <= x_req; x_rs2 <= x_rs1;\n    a_hcnt <= (urq || a_rs2) ? 4'hF : (a_hcnt != 0) ? a_hcnt - 1'b1 : a_hcnt;\n    x_hcnt <= (urq || x_rs2) ? 4'hF : (x_hcnt != 0) ? x_hcnt - 1'b1 : x_hcnt;\n    a_hold <= urq || a_rs2 ||\n              (a_hold && (a_hcnt != 0 || a_out != 0 || (rm_busy && !rm_x) || a_oc));\n    x_hold <= urq || x_rs2 ||\n              (x_hold && (x_hcnt != 0 || x_out != 0 || (rm_busy && rm_x) || x_oc));\n  end\n  // A reset shorter than the round trip through the synchronizers would otherwise release the\n  // master's side before its hold arrives, with the old read data still in its FIFO: the request\n  // stays up until the hold is seen here, and the side stays in reset until the hold is over.\n  always_ff @(posedge clk) begin\n    a_req <= rst || (a_req && !a_hs2);\n    a_hs1 <= a_hold; a_hs2 <= a_hs1;\n    a_crst <= rst || a_req || a_hs2;\n  end\n  always_ff @(posedge xclk) begin\n    x_req <= xrst || (x_req && !x_hs2);\n    x_hs1 <= x_hold; x_hs2 <= x_hs1;\n    x_crst <= xrst || x_req || x_hs2;\n  end\n\n  // ================================================================ clock crossings\n  logic          aq_wv, aq_wr, aq_rv, aq_rr;  logic [QW-1:0] aq_wd, aq_rd;\n  logic          ad_wv, ad_wr, ad_rv, ad_rr;  logic [DW-1:0] ad_wd, ad_rd;\n  logic          ar_wv, ar_wr, ar_rv, ar_rr;  logic [511:0]  ar_wd, ar_rd;\n  logic          xq_wv, xq_wr, xq_rv, xq_rr;  logic [QW-1:0] xq_wd, xq_rd;\n  logic          xd_wv, xd_wr, xd_rv, xd_rr;  logic [DW-1:0] xd_wd, xd_rd;\n  logic          xr_wv, xr_wr, xr_rv, xr_rr;  logic [511:0]  xr_wd, xr_rd;\n  logic [AOW-1:0] ar_used;\n  logic [XOW-1:0] xr_used;\n  logic [5:0] unused_aq, unused_ad;\n  logic [$clog2(XQD):0] unused_xq, unused_xd, xq_used;\n  logic [$clog2(ARD)-1:0] ar_slot;         // the read-data FIFOs' slots (out-of-order writes)\n  logic [$clog2(XRD)-1:0] xr_slot;\n  logic ar_cmt, xr_cmt;\n\n  otpu_afifo #(.W(QW), .DEPTH(32)) u_aq (.wclk(clk), .wrst(a_hs2), .wvalid(aq_wv), .wready(aq_wr),\n    .wdata(aq_wd), .wslot('0), .wcommit(), .wused(unused_aq), .rclk(uclk), .rrst(a_hold),\n    .rvalid(aq_rv), .rready(aq_rr), .rdata(aq_rd), .rused());\n  otpu_afifo #(.W(DW), .DEPTH(32)) u_ad (.wclk(clk), .wrst(a_hs2), .wvalid(ad_wv), .wready(ad_wr),\n    .wdata(ad_wd), .wslot('0), .wcommit(), .wused(unused_ad), .rclk(uclk), .rrst(a_hold),\n    .rvalid(ad_rv), .rready(ad_rr), .rdata(ad_rd), .rused());\n  // the read data, written out of order at each read's slot (the two ports return independently)\n  otpu_afifo #(.W(512), .DEPTH(ARD), .OOO(1'b1)) u_ar (.wclk(uclk), .wrst(a_hold), .wvalid(ar_wv),\n    .wready(ar_wr), .wdata(ar_wd), .wslot(ar_slot), .wcommit(ar_cmt), .wused(ar_used), .rclk(clk),\n    .rrst(a_hs2), .rvalid(ar_rv), .rready(ar_rr), .rdata(ar_rd), .rused());\n  // the XDMA side's write enables start from flip-flops (RWR: a registered wready)\n  otpu_afifo #(.W(QW), .DEPTH(XQD), .RWR(1'b1)) u_xq (.wclk(xclk), .wrst(x_hs2), .wvalid(xq_wv),\n    .wready(xq_wr), .wdata(xq_wd), .wslot('0), .wcommit(), .wused(unused_xq), .rclk(uclk),\n    .rrst(x_hold), .rvalid(xq_rv), .rready(xq_rr), .rdata(xq_rd), .rused(xq_used));\n  otpu_afifo #(.W(DW), .DEPTH(XQD), .RWR(1'b1)) u_xd (.wclk(xclk), .wrst(x_hs2), .wvalid(xd_wv),\n    .wready(xd_wr), .wdata(xd_wd), .wslot('0), .wcommit(), .wused(unused_xd), .rclk(uclk),\n    .rrst(x_hold), .rvalid(xd_rv), .rready(xd_rr), .rdata(xd_rd), .rused());\n  otpu_afifo #(.W(512), .DEPTH(XRD), .OOO(1'b1)) u_xr (.wclk(uclk), .wrst(x_hold), .wvalid(xr_wv),\n    .wready(xr_wr), .wdata(xr_wd), .wslot(xr_slot), .wcommit(xr_cmt), .wused(xr_used), .rclk(xclk),\n    .rrst(x_hs2), .rvalid(xr_rv), .rready(xr_rr), .rdata(xr_rd), .rused());\n\n  // write beats taken by the controller, per master: the ports' counts (gray counters from uclk,\n  // g_port) as synchronized and decoded in the master's clock, summed\n  logic [CW-1:0] x_wacc_c;\n\n`ifndef SYNTHESIS\n  // +cdc_skew=P (tb_memch): a model of the skew set_bus_skew allows between the bits of a gray\n  // count (up to a source period). In P percent of the first stage's samples each bit is the\n  // count's bit a source cycle earlier or now, at random: a count that moved one bit is seen old\n  // or new, one that moved two bits mixed. A bit once seen new stays new (`seen`, the stage's\n  // last sample: a wire's change arrives once, so a faster destination does not see it undone).\n  // A sample ahead of the count (a mix of a two-bit step) is an error\n  int cdc_skew = 0;\n  initial void'($value$plusargs(\"cdc_skew=%d\", cdc_skew));\n  function automatic logic [CW-1:0] cdc_smp(input string nm, input logic [CW-1:0] now,\n                                            input logic [CW-1:0] was, input logic [CW-1:0] seen);\n    logic [CW-1:0] m, r;\n    m = (cdc_skew != 0 && int'($urandom % 100) < cdc_skew) ? CW'($urandom) & (seen ^ now) : '0;\n    r = (now & ~m) | (was & m);\n    if (CW'(g2b(now) - g2b(r)) >= CW'(1 << (CW - 1)))\n      $error(\"otpu_mem_ch: %s's sample %0d ahead of the count, %0d\", nm, g2b(r), g2b(now));\n    return r;\n  endfunction\n`endif\n\n  // ================================================================ accelerator side (clk)\n  assign n_cready = !a_crst && aq_wr;\n  assign aq_wv    = n_cvalid && n_cready;\n  assign aq_wd    = {n_cwe, n_caddr};\n  assign n_wready = !a_crst && ad_wr;\n  assign ad_wv    = n_wvalid && n_wready;\n  assign ad_wd    = {~&n_wmask, n_wmask, n_wdata};\n  assign ar_rr    = 1'b1;\n  always_ff @(posedge clk) begin\n    n_rvalid <= ar_rv && !a_crst;\n    n_rdata  <= ar_rd;\n  end\n  // the ports' counts as synchronized (g_port), summed: a cycle after their decode\n  always_ff @(posedge clk)\n    if (a_crst) n_wdone <= '0;\n    else n_wdone <= g_port[0].a_wb + g_port[1].a_wb;\n\n  // ================================================================ XDMA side (xclk)\n  // Read bursts: one command per 64-byte beat touched; the R channel hands out the 16-byte lanes\n  // from the burst's first lane. Write bursts: 16-byte beats packed into 64-byte beats.\n  localparam int XRQ = XIDW + 10;\n  logic       xai_wv, xai_wr, xai_rv, xai_rr;  logic [31:0] xai_rd;      // {n - 1, beat}\n  logic       xwi_wv, xwi_wr, xwi_rv, xwi_rr;  logic [26:0] xwi_rd;      // {lane, beat}\n  logic       xrq_wv, xrq_wr, xrq_rv, xrq_rr;  logic [XRQ-1:0] xrq_rd;   // {id, len, lane}\n  logic       xbq_wv, xbq_wr, xbq_rv, xbq_rr;  logic [XIDW+6:0] xbq_rd;  // {id, n - 1}\n  logic [6:0] x_arn, x_awn;                // 64-byte beats of the burst, minus one\n  assign x_arn = 7'(({1'b0, x_arlen} + {7'b0, x_araddr[5:4]}) >> 2);\n  assign x_awn = 7'(({1'b0, x_awlen} + {7'b0, x_awaddr[5:4]}) >> 2);\n  // their heads from registers (RO): the R, B and write-packing logic starts from flip-flops\n  otpu_sfifo #(.W(32), .DEPTH(4), .RO(1'b1)) u_xai (.clk(xclk), .rst(x_crst), .wvalid(xai_wv),\n    .wready(xai_wr), .wdata({x_arn, x_araddr[30:6]}), .rvalid(xai_rv), .rready(xai_rr),\n    .rdata(xai_rd));\n  otpu_sfifo #(.W(27), .DEPTH(4), .RO(1'b1)) u_xwi (.clk(xclk), .rst(x_crst), .wvalid(xwi_wv),\n    .wready(xwi_wr), .wdata({x_awaddr[5:4], x_awaddr[30:6]}), .rvalid(xwi_rv), .rready(xwi_rr),\n    .rdata(xwi_rd));\n  otpu_sfifo #(.W(XRQ), .DEPTH(16), .RO(1'b1)) u_xrq (.clk(xclk), .rst(x_crst), .wvalid(xrq_wv),\n    .wready(xrq_wr), .wdata({x_arid, x_arlen, x_araddr[5:4]}), .rvalid(xrq_rv), .rready(xrq_rr),\n    .rdata(xrq_rd));\n  otpu_sfifo #(.W(XIDW + 7), .DEPTH(16), .RO(1'b1)) u_xbq (.clk(xclk), .rst(x_crst),\n    .wvalid(xbq_wv), .wready(xbq_wr), .wdata({x_awid, x_awn}), .rvalid(xbq_rv), .rready(xbq_rr),\n    .rdata(xbq_rd));\n  assign x_arready = !x_crst && xai_wr && xrq_wr;\n  assign xai_wv    = x_arvalid && x_arready;\n  assign xrq_wv    = xai_wv;\n  assign x_awready = !x_crst && xwi_wr && xbq_wr;\n  assign xwi_wv    = x_awvalid && x_awready;\n  assign xbq_wv    = xwi_wv;\n\n  // write packing: the burst's current 64-byte beat collects its lanes; it goes out with its\n  // last lane or the burst's last beat. A completed write beat goes first, else a read beat.\n  logic [6:0]   x_roff, x_woff;\n  logic [1:0]   x_wlane_r, x_wlane;\n  logic         x_wfirst, x_wpush, x_selw, x_rlastb;\n  logic [511:0] x_wbuf, x_wdata_full;\n  logic [63:0]  x_wstb, x_wstb_full;\n  logic [3:0]   x_wsfull;                // the lanes of x_wstb with every strobe set\n  logic         x_wfull;                 // x_wstb_full all set (no AND over its 64 bits)\n  assign x_wlane  = x_wfirst ? xwi_rd[26:25] : x_wlane_r;\n  assign x_wpush  = x_wlane == 2'd3 || x_wlast;\n  assign x_selw   = xwi_rv && x_wvalid && x_wpush;\n  assign x_rlastb = x_roff == xai_rd[31:25];\n  always_comb begin\n    x_wdata_full = x_wbuf;\n    x_wstb_full  = x_wstb;\n    x_wdata_full[x_wlane * 128 +: 128] = x_wdata;\n    x_wstb_full[x_wlane * 16 +: 16]    = x_wstrb;\n  end\n  assign xq_wv    = !x_crst && xq_wr && (x_selw ? xd_wr : xai_rv);\n  assign xq_wd    = x_selw ? {1'b1, 25'(xwi_rd[24:0] + x_woff)} : {1'b0, 25'(xai_rd[24:0] + x_roff)};\n  assign x_wready = !x_crst && xwi_rv && (!x_wpush || (xq_wr && xd_wr));\n  assign xd_wv    = x_wvalid && x_wready && x_wpush;\n  assign x_wfull  = &x_wstrb && &(x_wsfull | (4'b1 << x_wlane));\n  assign xd_wd    = {~x_wfull, x_wstb_full, x_wdata_full};\n  assign xai_rr   = xq_wv && !x_selw && x_rlastb;\n  assign xwi_rr   = x_wvalid && x_wready && x_wlast;\n  always_ff @(posedge xclk) begin\n    if (x_crst) begin\n      x_roff <= '0; x_woff <= '0; x_wlane_r <= '0; x_wfirst <= 1'b1; x_wstb <= '0;\n      x_wsfull <= '0;\n    end else begin\n      if (xq_wv && !x_selw) x_roff <= x_rlastb ? '0 : x_roff + 1'b1;\n      if (x_wvalid && x_wready) begin\n        x_wfirst  <= x_wlast;\n        x_wlane_r <= x_wlane + 1'b1;\n        if (x_wpush) begin\n          x_woff <= x_wlast ? '0 : x_woff + 1'b1;\n          x_wstb <= '0; x_wsfull <= '0;\n        end else begin\n          x_wstb <= x_wstb_full;\n          x_wsfull[x_wlane] <= &x_wstrb;\n        end\n      end\n    end\n  end\n\n  // the lanes' data, neither cleared nor reset: the strobes say which bytes a beat writes (a\n  // partial beat is read-modify-written, its other bytes the memory's). A lane loads while its\n  // beat is offered (the same beat until it is taken; x_wlane's lane holds nothing collected yet:\n  // the beat's lanes come in order, and a new 64-byte beat starts with nothing), so its enable is\n  // x_wvalid and the lane, not the handshake: one LUT from the W channel and the head (the\n  // handshake's push and room cleared or loaded all 580 of x_wbuf / x_wstb / x_wsfull, 3 levels)\n  always_ff @(posedge xclk)\n    for (int l = 0; l < 4; l++)\n      if (x_wvalid && x_wlane == 2'(l)) x_wbuf[l * 128 +: 128] <= x_wdata;\n\n  // R: lanes of the returned 64-byte beats\n  logic [7:0] x_rcnt;\n  logic [1:0] x_rlane_r, x_rlane;\n  logic       x_rfirst;\n  assign x_rlane  = x_rfirst ? xrq_rd[1:0] : x_rlane_r;\n  assign x_rvalid = xr_rv && xrq_rv;\n  assign x_rdata  = xr_rd[x_rlane * 128 +: 128];\n  assign x_rid    = xrq_rd[XRQ-1 -: XIDW];\n  assign x_rlast  = x_rcnt == xrq_rd[9:2];\n  assign x_rresp  = 2'b00;\n  assign xr_rr    = x_rvalid && x_rready && (x_rlane == 2'd3 || x_rlast);\n  assign xrq_rr   = x_rvalid && x_rready && x_rlast;\n  always_ff @(posedge xclk) begin\n    if (x_crst) begin x_rcnt <= '0; x_rlane_r <= '0; x_rfirst <= 1'b1; end\n    else if (x_rvalid && x_rready) begin\n      x_rcnt    <= x_rlast ? '0 : x_rcnt + 1'b1;\n      x_rlane_r <= x_rlane + 1'b1;\n      x_rfirst  <= x_rlast;\n    end\n  end\n\n  // B: a burst's response once its last W beat is in and the controller has taken all its beats.\n  // x_wd: the beats taken (x_wacc_c, the ports' counts as synchronized, summed) past those of the\n  // bursts answered (x_wdone). Each synchronized count is a value its count had, so x_wd is never\n  // negative; compared as signed all the same, so that a count read ahead (which made x_wd -1, and\n  // every burst queued behind it answered at once) gives no B. x_wlb: the bursts whose WLAST was\n  // taken and that have no B yet (W follows AW, so the head burst's WLAST is in when x_wlb != 0)\n  logic [CW-1:0] x_wdone, x_wd;\n  logic [4:0]    x_wlb;\n  always_ff @(posedge xclk)\n    if (x_crst) x_wacc_c <= '0;\n    else x_wacc_c <= g_port[0].x_wb + g_port[1].x_wb;\n  assign x_wd     = x_wacc_c - x_wdone;\n  assign x_bvalid = xbq_rv && x_wlb != 0 && !x_wd[CW-1] && (x_wd[CW-2:0] > (CW - 1)'(xbq_rd[6:0]));\n  assign x_bid    = xbq_rd[XIDW+6 -: XIDW];\n  assign x_bresp  = 2'b00;\n  assign xbq_rr   = x_bvalid && x_bready;\n  always_ff @(posedge xclk) begin\n    if (x_crst) begin x_wdone <= '0; x_wlb <= '0; end\n    else begin\n      if (x_bvalid && x_bready) x_wdone <= x_wdone + CW'(xbq_rd[6:0]) + 1'b1;\n      x_wlb <= x_wlb + 5'(xwi_rr) - 5'(xbq_rr);\n    end\n  end\n\n  // ================================================================ controller side (uclk)\n  // Read credits (registered, one beat of margin: at most one read issues per cycle): a master\n  // may issue a read while its reads not yet in its read-data FIFO (a_pend: issued, not yet\n  // passed by the FIFO's write pointer) plus the FIFO's entries leave room for one more. Each read\n  // takes the next slot of its master's FIFO (a_seq), which the credits keep free, and its data is\n  // written there when its port returns it.\n  logic a_rok, x_rok;\n  logic [AOW-1:0] a_pend;\n  logic [XOW-1:0] x_pend;\n  logic [ASW-1:0] a_seq;\n  logic [XSW-1:0] x_seq;\n  always_ff @(posedge uclk) begin\n    a_rok <= (a_pend + ar_used) <= AOW'(ARD - 2);\n    x_rok <= (x_pend + xr_used) <= XOW'(XRD - 2);\n  end\n\n  // the arbiter: the chosen master's head command (a write with its data) goes when its port's\n  // output command queue has room and, for a write, the port's output data FIFO too. Each master's\n  // room (its head's port) is found alongside the pick, so go and the counts of the head that goes\n  // (a_rgo: an accelerator read issued) follow the pick by a mux, not by the heads' mux (sel_x).\n  logic          a_ok, x_ok, pick_x, cur_x, sel_x, go, we, part, rmw, tp;\n  logic          a_room, x_room, a_rgo, x_rgo;\n  logic [5:0]    run;\n  logic [24:0]   addr;\n  logic [DW-1:0] wd;\n  logic [1:0]    oq_wv, oq_wr, of_wv, of_wr, tg_wr, tg_rv;\n  logic [511:0]  of_wd;\n  logic [1:0][TW-1:0] tg_rd;\n  logic          rm_ret, rm_ok;\n  assign a_ok = aq_rv && (aq_rd[QW-1] ? ad_rv : a_rok);\n  assign x_ok = xq_rv && (xq_rd[QW-1] ? xd_rv : x_rok);\n  // XDMA's batches (XT > 0). Once the accelerator has had its RUN, a ready X goes only when it has\n  // waited XT cycles since its last command or has XB commands queued (x_ripe), so its FIFOs (XQD)\n  // fill and its turn carries a batch: the controller turns its bus from the accelerator's reads\n  // and changes rows once a batch instead of every burst. Host writes streaming during a run then\n  // cost the accelerator a quarter to a half less (co-simulated layer runs: 0.20 -> 0.10 s a GB\n  // written at 1 GB/s, 0.13 -> 0.08 at 2, 0.10 -> 0.075 at 3; docs/offload.md 13.19). XB lets a\n  // fast stream go once its batch is in, so the batches never hold XDMA under the link's rate (the\n  // wait alone gives it at most RUN commands per XT + RUN cycles: 2.8 of 3 GB/s beside a layer\n  // run); 24 leaves room for what arrives at that rate while the accelerator ends its RUN. A ready\n  // X still goes at once when the accelerator has nothing to issue (the card waiting on a miss),\n  // and with XDMA idle the arbiter is the one without batches (XT 0).\n  logic x_ripe;\n  if (XT > 0) begin : g_xt\n    localparam int XAW = $clog2(XT + 1);\n    logic [XAW-1:0] x_age;               // cycles X has been ready since its last command\n    always_ff @(posedge uclk)\n      if (urq || (go && pick_x) || !x_ok) begin\n        x_age  <= '0;\n        x_ripe <= 1'b0;\n      end else begin\n        if (x_age != XAW'(XT)) x_age <= x_age + 1'b1;\n        x_ripe <= x_age >= XAW'(XT - 1) || (XB > 0 && xq_used >= ($clog2(XQD) + 1)'(XB));\n      end\n  end else begin : g_nxt\n    assign x_ripe = 1'b1;\n  end\n  always_comb begin\n    if (!cur_x) pick_x = x_ok && (!a_ok || (run >= 6'(RUN) && x_ripe));\n    else        pick_x = !a_ok || (x_ok && run < 6'(RUN));\n  end\n  assign sel_x = rm_busy ? rm_x : pick_x;  // a read-modify-write: its master's heads\n  assign we    = sel_x ? xq_rd[QW-1] : aq_rd[QW-1];\n  assign addr  = sel_x ? xq_rd[24:0] : aq_rd[24:0];\n  assign wd    = sel_x ? xd_rd : ad_rd;\n  assign tp    = addr[7];                  // the port: the beat's bank parity\n  assign part  = we && wd[DW-1];\n  assign rmw   = part;\n  assign a_room = oq_wr[aq_rd[7]] && (!aq_rd[QW-1] || of_wr[aq_rd[7]]);\n  assign x_room = oq_wr[xq_rd[7]] && (!xq_rd[QW-1] || of_wr[xq_rd[7]]);\n  assign go    = !rm_busy && (pick_x ? x_ok && x_room : a_ok && a_room);\n  assign a_rgo = !rm_busy && !pick_x && a_ok && a_room && !aq_rd[QW-1];\n  assign x_rgo = !rm_busy && pick_x && x_ok && x_room && !xq_rd[QW-1];\n\n  // read data: at most one port returns a beat in a cycle (they share the channel's data bus);\n  // its tag, at the head of that port's tag FIFO, says where it goes. The core's ports carry one\n  // read bus (tools/litedram/ecc_ports.py: one decoder, and each port's register behind it loads\n  // every cycle, their rdata ready being tied high), so the beat is on port 0's data whichever\n  // port returns it: no port mux on the valids.\n  logic          rv, rp;\n  logic [511:0]  rdat;\n  logic [TW-1:0] rtag;\n  assign rv   = |c_rdata_valid;\n  assign rp   = c_rdata_valid[1];\n  assign rdat = c_rdata_data[0];\n  assign rtag = tg_rd[rp];\n\n  // read-modify-write: the read goes with an RMW tag, the write's command and data stay at the\n  // heads; its data merges the returning beat into the lanes not written (the same beat: the same\n  // port)\n  assign rm_ret = rv && rtag[TW-1];\n  assign rm_ok  = rm_ret && (rm_x ? !x_hold : !a_hold);\n  always_ff @(posedge uclk) begin\n    if (urq) rm_busy <= 1'b0;\n    else if (go && rmw) rm_busy <= 1'b1;\n    else if (rm_ret) rm_busy <= 1'b0;\n    if (go && rmw) rm_x <= pick_x;\n  end\n\n  assign aq_rr = (go && !pick_x && !rmw) || (rm_ret && !rm_x);\n  assign xq_rr = (go && pick_x && !rmw) || (rm_ret && rm_x);\n  assign ad_rr = (go && !pick_x && we && !rmw) || (rm_ret && !rm_x);\n  assign xd_rr = (go && pick_x && we && !rmw) || (rm_ret && rm_x);\n\n  // output write data: whole beats, a merged one with the read's data in the lanes not written.\n  // While an RMW is in progress only its merged write enters the queues (go waits), so the merge\n  // follows rm_busy, a flip-flop, rather than the returning beat's tag.\n  always_comb\n    for (int k = 0; k < 64; k++)\n      of_wd[8 * k +: 8] = (rm_busy && !wd[512 + k]) ? rdat[8 * k +: 8] : wd[8 * k +: 8];\n\n  // per port: the output command queue (a FIFO behind a register: the crossbar's inputs come from\n  // flip-flops; a command bypasses the empty FIFO), the output write-data FIFO (pushed with the\n  // write's command) and the read tags ({read-modify-write, xdma, slot}, in the port's order)\n  logic [26:0]   ocn;\n  logic [1:0]    opop, opw_a, opw_x, opc_a, opc_x;\n  assign ocn = {rm_busy || (we && !rmw), sel_x, addr};\n  for (genvar p = 0; p < 2; p++) begin : g_port\n    logic        oq_rv, oq_rr, byp, oc_v;\n    logic [26:0] oq_rd, oc;\n    assign oq_wv[p] = (go || rm_ok) && tp == 1'(p);\n    assign byp      = oq_wv[p] && !oq_rv && (!oc_v || c_cmd_ready[p]);\n    assign oq_rr    = oq_rv && (!oc_v || c_cmd_ready[p]);\n    otpu_sfifo #(.W(27), .DEPTH(OQ)) u_oq (.clk(uclk), .rst(urq), .wvalid(oq_wv[p] && !byp),\n      .wready(oq_wr[p]), .wdata(ocn), .rvalid(oq_rv), .rready(oq_rr), .rdata(oq_rd));\n    always_ff @(posedge uclk) begin\n      if (urq) oc_v <= 1'b0;\n      else if (!oc_v || c_cmd_ready[p]) oc_v <= oq_rv || byp;\n      if (!oc_v || c_cmd_ready[p]) oc <= oq_rv ? oq_rd : ocn;\n    end\n    assign c_cmd_valid[p] = oc_v;\n    assign c_cmd_we[p]    = oc[26];\n    assign c_cmd_addr[p]  = oc[24:0];\n    assign opop[p]  = oc_v && c_cmd_ready[p];\n    assign opw_a[p] = opop[p] && oc[26] && !oc[25];      // a write taken, per master (n_wdone, B)\n    assign opw_x[p] = opop[p] && oc[26] && oc[25];\n    assign opc_a[p] = opop[p] && !oc[25];                // a command taken, per master\n    assign opc_x[p] = opop[p] && oc[25];\n\n    // the port's write beats taken, per master (n_wdone, B): at most one a cycle, so the gray\n    // code (registered) moves one bit per uclk cycle; synchronized and decoded in the master's\n    // clock (a_wb, x_wb; summed over the ports above). Restarted with the master's hold\n    logic [CW-1:0] a_wacc, a_wacc_g, x_wacc, x_wacc_g, a_wb, x_wb;\n    (* ASYNC_REG = \"TRUE\" *) logic [CW-1:0] a_wacc_s1, a_wacc_s2;\n    (* ASYNC_REG = \"TRUE\" *) logic [CW-1:0] x_wacc_s1, x_wacc_s2;\n    always_ff @(posedge uclk) begin\n      if (a_hold) a_wacc <= '0; else a_wacc <= a_wacc + CW'(opw_a[p]);\n      if (x_hold) x_wacc <= '0; else x_wacc <= x_wacc + CW'(opw_x[p]);\n      a_wacc_g <= b2g(a_wacc);\n      x_wacc_g <= b2g(x_wacc);\n    end\n`ifndef SYNTHESIS\n    logic [CW-1:0] a_wacc_gq, x_wacc_gq;                 // (cdc_smp: the counts a cycle earlier)\n    always_ff @(posedge uclk) begin a_wacc_gq <= a_wacc_g; x_wacc_gq <= x_wacc_g; end\n`endif\n    always_ff @(posedge clk)\n      if (a_crst) begin a_wacc_s1 <= '0; a_wacc_s2 <= '0; a_wb <= '0; end\n      else begin\n`ifdef SYNTHESIS\n        a_wacc_s1 <= a_wacc_g;\n`else\n        a_wacc_s1 <= cdc_smp(\"a_wacc\", a_wacc_g, a_wacc_gq, a_wacc_s1);\n`endif\n        a_wacc_s2 <= a_wacc_s1; a_wb <= g2b(a_wacc_s2);\n      end\n    always_ff @(posedge xclk)\n      if (x_crst) begin x_wacc_s1 <= '0; x_wacc_s2 <= '0; x_wb <= '0; end\n      else begin\n`ifdef SYNTHESIS\n        x_wacc_s1 <= x_wacc_g;\n`else\n        x_wacc_s1 <= cdc_smp(\"x_wacc\", x_wacc_g, x_wacc_gq, x_wacc_s1);\n`endif\n        x_wacc_s2 <= x_wacc_s1; x_wb <= g2b(x_wacc_s2);\n      end\n\n    assign of_wv[p] = ((go && we && !rmw) || rm_ok) && tp == 1'(p);\n    otpu_sfifo #(.W(512), .DEPTH(OD)) u_of (.clk(uclk), .rst(urq), .wvalid(of_wv[p]),\n      .wready(of_wr[p]), .wdata(of_wd), .rvalid(c_wdata_valid[p]), .rready(c_wdata_ready[p]),\n      .rdata(c_wdata_data[p]));\n    assign c_wdata_we[p] = '1;\n\n    otpu_sfifo #(.W(TW), .DEPTH(TGD)) u_tag (.clk(uclk), .rst(urq),\n      .wvalid(go && (!we || rmw) && tp == 1'(p)), .wready(tg_wr[p]),\n      .wdata({rmw, pick_x, pick_x ? ASW'(x_seq) : a_seq}), .rvalid(tg_rv[p]),\n      .rready(c_rdata_valid[p]), .rdata(tg_rd[p]));\n  end\n  // each master's commands in the output queues (a hold waits for its own to leave)\n  logic [5:0] a_nq, x_nq;\n  assign a_oc = a_nq != 0;\n  assign x_oc = x_nq != 0;\n\n  // a read's data to its master's slot (dropped under its hold) or to the merge\n  assign ar_wv   = rv && rtag[TW-1 -: 2] == 2'b00 && !a_hold;\n  assign xr_wv   = rv && rtag[TW-1 -: 2] == 2'b01 && !x_hold;\n  assign ar_slot = rtag[ASW-1:0];\n  assign xr_slot = rtag[XSW-1:0];\n  assign ar_wd   = rdat;\n  assign xr_wd   = rdat;\n\n  always_ff @(posedge uclk) begin\n    if (urq) begin\n      cur_x <= 1'b0; run <= '0; a_out <= '0; x_out <= '0; a_nq <= '0; x_nq <= '0;\n    end else begin\n      if (go) begin\n        run   <= (pick_x != cur_x) ? 6'd1 : (run == 6'd63) ? run : run + 1'b1;\n        cur_x <= pick_x;\n      end\n      // reads in flight (issued, data not yet back), for the holds\n      a_out <= a_out + AOW'(a_rgo) - AOW'(rv && rtag[TW-1 -: 2] == 2'b00);\n      x_out <= x_out + XOW'(x_rgo) - XOW'(rv && rtag[TW-1 -: 2] == 2'b01);\n      a_nq  <= a_nq + 6'((go || rm_ok) && !sel_x) - 6'(opc_a[0]) - 6'(opc_a[1]);\n      x_nq  <= x_nq + 6'((go || rm_ok) && sel_x) - 6'(opc_x[0]) - 6'(opc_x[1]);\n    end\n    // reads not yet in their FIFO, and the next slot (the FIFO restarts at slot 0 on its hold)\n    if (a_hold) begin a_pend <= '0; a_seq <= '0; end\n    else begin\n      a_pend <= a_pend + AOW'(a_rgo) - AOW'(ar_cmt);\n      if (a_rgo) a_seq <= a_seq + 1'b1;\n    end\n    if (x_hold) begin x_pend <= '0; x_seq <= '0; end\n    else begin\n      x_pend <= x_pend + XOW'(x_rgo) - XOW'(xr_cmt);\n      if (x_rgo) x_seq <= x_seq + 1'b1;\n    end\n  end\n\n  // the controller's side of the contract, checked in the build too (STATUS AXI_ERR): read data\n  // from one port at a time, each beat on a port with a read outstanding. Sticky until the\n  // controller's reset; into the core clock through two flip-flops.\n  logic c_err = 1'b0;\n  (* ASYNC_REG = \"TRUE\" *) logic e_s1 = 1'b0, e_s2 = 1'b0;\n  always_ff @(posedge uclk)\n    if (urq) c_err <= 1'b0;\n    else if (&c_rdata_valid || |(c_rdata_valid & ~tg_rv)) c_err <= 1'b1;\n  always_ff @(posedge clk) begin\n    e_s1 <= c_err; e_s2 <= e_s1;\n  end\n  assign n_err = e_s2;\n\n`ifndef SYNTHESIS\n  // read data comes from one port at a time and always finds a tag and a free slot (the credits);\n  // the merged write finds room (the arbiter has stopped since the read, whose own command has\n  // left the queue)\n  // the cycle the bridge's controller side is still in reset and the controller is not (urq\n  // after urst): no command enters the queues, and the controller returns no read data\n  always_ff @(posedge uclk)\n    if (urq && !urst && (go || rm_ok || |oq_wv || |of_wv || |c_rdata_valid))\n      $fatal(1, \"otpu_mem_ch: a queue write or read data in the bridge's last reset cycle\");\n  always_ff @(posedge uclk) if (!urq) begin\n    if (&c_rdata_valid) $error(\"otpu_mem_ch: read data from both ports in one cycle\");\n    if (go != (!rm_busy && (pick_x ? x_ok : a_ok) && oq_wr[tp] && (!we || of_wr[tp])))\n      $error(\"otpu_mem_ch: go is not the chosen head's\");\n    if (a_rgo != (go && !we && !pick_x) || x_rgo != (go && !we && pick_x))\n      $error(\"otpu_mem_ch: a read's issue is not go's\");\n    if (c_rdata_valid[1] && c_rdata_data[1] != c_rdata_data[0])\n      $error(\"otpu_mem_ch: port 1's read data is not on port 0's bus\");\n    for (int p = 0; p < 2; p++)\n      if (c_rdata_valid[p] && !tg_rv[p]) $error(\"otpu_mem_ch: port %0d read data without a tag\", p);\n    if (rm_ret && !rm_busy) $error(\"otpu_mem_ch: read-modify-write data without its read\");\n    if (rm_ok && (!oq_wr[tp] || !of_wr[tp])) $error(\"otpu_mem_ch: no room for the merged write\");\n    if (go && (!we || rmw) && !tg_wr[tp]) $error(\"otpu_mem_ch: tag FIFO full\");\n    if (a_pend + ar_used > AOW'(ARD)) $error(\"otpu_mem_ch: accelerator read slots overrun\");\n    if (x_pend + xr_used > XOW'(XRD)) $error(\"otpu_mem_ch: XDMA read slots overrun\");\n  end\n  // a hold ends with none of its master's commands left to count (n_wdone / B restart from 0)\n  logic a_hold_q, x_hold_q;\n  always_ff @(posedge uclk) begin\n    a_hold_q <= a_hold;\n    x_hold_q <= x_hold;\n    if (a_hold_q && !a_hold && a_oc) $error(\"otpu_mem_ch: accelerator hold over, command pending\");\n    if (x_hold_q && !x_hold && x_oc) $error(\"otpu_mem_ch: XDMA hold over, command pending\");\n  end\n  // the synchronized counts never run ahead: XDMA's beats taken never behind its answered bursts'\n  always_ff @(posedge xclk)\n    if (!x_crst && x_wd[CW-1])\n      $error(\"otpu_mem_ch: XDMA's beats taken (%0d) behind its answered bursts' (%0d)\", x_wacc_c,\n             x_wdone);\n`endif\nendmodule\n\n// Synchronous FIFO, first-word fall-through, distributed RAM (the channel bridge's queues).\n// RO = 1: rvalid, wready and the head entry from registers (their next values), so no path from\n// them starts at the pointers or goes through the RAM; the same cycles (rdata differs only while\n// rvalid is low).\nmodule otpu_sfifo #(\n  parameter int W = 8,\n  parameter int DEPTH = 16,\n  parameter bit RO = 1'b0\n) (\n  input  logic         clk,\n  input  logic         rst,\n  input  logic         wvalid,\n  output logic         wready,\n  input  logic [W-1:0] wdata,\n  output logic         rvalid,\n  input  logic         rready,\n  output logic [W-1:0] rdata\n);\n  localparam int AW = $clog2(DEPTH);\n  (* ram_style = \"distributed\" *) logic [W-1:0] mem [DEPTH];\n  logic [AW:0] wp, rp;\n  always_ff @(posedge clk) begin\n    if (rst) begin wp <= '0; rp <= '0; end\n    else begin\n      if (wvalid && wready) wp <= wp + 1'b1;\n      if (rvalid && rready) rp <= rp + 1'b1;\n    end\n  end\n  always_ff @(posedge clk) if (wvalid && wready) mem[wp[AW-1:0]] <= wdata;\n  if (RO) begin : g_ro\n    // the next head: on a pop the entry after it (this cycle's write if there is none), into an\n    // empty FIFO this cycle's write; the flags from the pointers after this cycle's push and pop\n    logic [W-1:0]  head;\n    logic [AW-1:0] rp1;\n    logic [AW:0]   wp_n, rp_n;\n    logic          one, rv = 1'b0, wr = 1'b1;\n    assign rp1  = rp[AW-1:0] + 1'b1;\n    assign one  = (wp - rp) == (AW + 1)'(1);\n    assign wp_n = wp + (AW + 1)'(wvalid && wready);\n    assign rp_n = rp + (AW + 1)'(rvalid && rready);\n    always_ff @(posedge clk) begin\n      if (rvalid && rready) head <= one ? wdata : mem[rp1];\n      else if (!rvalid)     head <= wdata;\n      if (rst) begin rv <= 1'b0; wr <= 1'b1; end\n      else begin rv <= wp_n != rp_n; wr <= (wp_n - rp_n) != (AW + 1)'(DEPTH); end\n    end\n    assign rvalid = rv;\n    assign wready = wr;\n    assign rdata  = head;\n  end else begin : g_ra\n    assign wready = (wp - rp) != (AW + 1)'(DEPTH);\n    assign rvalid = wp != rp;\n    assign rdata  = mem[rp[AW-1:0]];\n  end\nendmodule\n", "rtl/shell/otpu_trace.sv": "// Hardware trace: the slice's trace events (otpu_pkg perf_t: the lines +trace prints in\n// simulation, opentpu/profile.py) as 64-bit records in a block-RAM ring the host reads through\n// the control registers (otpu_ctrl.sv; the record format is in docs/observability.md, the host\n// decoder is opentpu/hwtrace.py).\n//\n//   S0  the events are registered (and dropped unless recording: en, and not stopped)\n//   S1  a cycle with events becomes one bundle in a small queue (QD bundles, LUT RAM); a bundle\n//       that finds the queue full is lost and its events (trace lines) are counted in drop\n//   U   the unpacker turns the head bundle into its records, one per cycle, in the order the\n//       simulator prints the lines: G, E (by slot), S (by unit; R after an S whose delay field\n//       saturated), D + two O, U + V (MXU, QUANT, VPU), H + V, P + V, Q + V\n//   W   the record is written to the ring (DEPTH records, simple dual-port block RAM) at\n//       count mod DEPTH; with stop, recording ends once DEPTH records are written. count\n//       saturates in its high bits only: past 2^32 - DEPTH records its low log2(DEPTH) bits keep\n//       counting, so count mod DEPTH is the next record's slot (the host's oldest record) on any\n//       run, and count stays >= DEPTH\n// Reading: rdata is the record at raddr, two cycles after raddr (the block RAM's output register).\n// busy: events are on their way to the ring; after the halt the host waits for it to clear\n// (the events of the last cycles, up to QD bundles of up to 61 records, are still draining).\nmodule otpu_trace\n  import otpu_pkg::*;\n#(\n  parameter int DEPTH = 16384,        // records (a power of two)\n  parameter int QD    = 32,           // bundles in the capture queue (a power of two)\n  parameter int WIN   = 16            // the sequencer's window slots (<= 16: 4-bit slot fields)\n) (\n  input  logic        clk,\n  input  logic        rst,\n  input  perf_t       pf,\n  input  logic        en,             // record (ENABLE and RUN)\n  input  logic        stop,           // STOP_WHEN_FULL\n  input  logic        clear,          // empty the ring, zero count and drop\n  input  logic [31:0] raddr,\n  output logic [63:0] rdata,\n  output logic [31:0] count,          // records written since the clear (saturating; the low\n                                      //   log2(DEPTH) bits always the write slot)\n  output logic [31:0] drop,           // events lost to a full queue (saturating)\n  output logic        busy            // events taken and not yet written (or dropped)\n);\n  localparam int LD = $clog2(DEPTH);\n  localparam int QW = $clog2(QD);\n  initial begin\n    if (DEPTH != (1 << LD) || QD != (1 << QW)) $fatal(1, \"otpu_trace: DEPTH, QD: powers of two\");\n    if (WIN > 16) $fatal(1, \"otpu_trace: slot fields are 4 bits (WIN <= 16)\");\n  end\n`ifndef SYNTHESIS\n  // +trace_count0=<hex> (tests/test_observability.py): a clear starts count (and the write slot)\n  // there instead of 0, to run a ring past 2^32 records in a short simulation\n  logic [31:0] cnt0;\n  initial if (!$value$plusargs(\"trace_count0=%h\", cnt0)) cnt0 = '0;\n`endif\n  localparam logic [3:0] T_D = 1, T_S = 2, T_G = 3, T_E = 4, T_U = 5, T_P = 6, T_Q = 7, T_H = 8,\n                         T_O = 9, T_R = 10, T_V = 11;\n\n  wire stopped = stop && (count[31:LD] != '0);        // count >= DEPTH\n\n  // ------------------------------------------------------------------ P: the slice's events,\n  // registered as they come (with the enable): the sequencer's start events look up the started\n  // slot's ready cycle combinationally (otpu_seq), a 0.27 ns path into S0 at 125.49 MHz\n  perf_t pr;\n  logic  pr_en, pr_any;\n  always_ff @(posedge clk) begin\n    pr <= pf;\n    pr_en <= en;\n    pr_any <= !rst && (pf.sq.d || (|pf.sq.s) || pf.sq.g || (|pf.sq.e) || pf.u_mxu || pf.u_q ||\n                       pf.u_vpu || pf.h || pf.w);\n  end\n\n  // ------------------------------------------------------------------ S0: input register\n  perf_t      ev;\n  logic [5:0] ev_n;                                    // events (trace lines) in ev\n  always_ff @(posedge clk) begin\n    logic [5:0] n;\n    n = 6'(pr.sq.d) + 6'(pr.sq.g) + 6'(pr.u_mxu) + 6'(pr.u_q) + 6'(pr.u_vpu) + 6'(pr.h) +\n        6'({pr.w, 1'b0});\n    for (int u = 0; u < NUNITS; u++) n = n + 6'(pr.sq.s[u]);\n    for (int i = 0; i < 16; i++) n = n + 6'(pr.sq.e[i]);\n    ev <= pr;\n    ev_n <= n;\n    if (rst || clear || !pr_en || stopped) begin\n      ev.sq.d <= 1'b0; ev.sq.s <= '0; ev.sq.g <= 1'b0; ev.sq.e <= '0;\n      ev.u_mxu <= 1'b0; ev.u_q <= 1'b0; ev.u_vpu <= 1'b0; ev.h <= 1'b0; ev.w <= 1'b0;\n    end\n  end\n  wire ev_any = ev.sq.d || (|ev.sq.s) || ev.sq.g || (|ev.sq.e) || ev.u_mxu || ev.u_q ||\n                ev.u_vpu || ev.h || ev.w;\n\n  // ------------------------------------------------------------------ S1: bundle, queue\n  typedef struct packed {\n    logic [31:0]              cyc;\n    logic                     g;\n    logic [3:0]               g_slot;\n    logic [15:0]              e;\n    logic [NUNITS-1:0]        s;\n    logic [NUNITS-1:0][3:0]   s_slot;\n    logic [NUNITS-1:0][15:0]  s_dt;        // cycle - ready; 16'hFFFF: s_x, an R record follows\n    logic [NUNITS-1:0]        s_x;\n    logic [NUNITS-1:0][31:0]  s_rdy;\n    logic                     d;\n    logic [3:0]               d_slot;\n    logic [15:0]              d_pc;\n    logic [103:0]             d_ow;        // {op, w3, w2, w1}\n    logic                     u_mxu;\n    logic [3:0][31:0]         u_mxu_v;\n    logic                     u_q;\n    logic [31:0]              u_q_v;\n    logic                     u_vpu;\n    logic [31:0]              u_vpu_v;\n    logic                     h;\n    logic [NH-1:0][31:0]      h_v;\n    logic                     w;\n    logic [23:0]              w_n;\n    logic [NP-1:0][31:0]      w_p;\n    logic [NQ-1:0][31:0]      w_q;\n  } bnd_t;\n\n  bnd_t nb;\n  always_comb begin\n    nb.cyc = ev.sq.cyc;\n    nb.g = ev.sq.g;\n    nb.g_slot = ev.sq.g_slot[3:0];\n    nb.e = ev.sq.e[15:0];\n    nb.s = ev.sq.s;\n    for (int u = 0; u < NUNITS; u++) begin\n      logic [31:0] dt;\n      dt = ev.sq.cyc - ev.sq.s_rdy[u];\n      nb.s_slot[u] = ev.sq.s_slot[u][3:0];\n      nb.s_x[u] = dt >= 32'hFFFF;\n      nb.s_dt[u] = nb.s_x[u] ? 16'hFFFF : dt[15:0];\n      nb.s_rdy[u] = ev.sq.s_rdy[u];\n    end\n    nb.d = ev.sq.d;\n    nb.d_slot = ev.sq.d_slot[3:0];\n    nb.d_pc = ev.sq.d_pc[15:0];\n    nb.d_ow = {ev.sq.d_op, ev.sq.d_w3, ev.sq.d_w2, ev.sq.d_w1};\n    nb.u_mxu = ev.u_mxu;\n    nb.u_mxu_v = ev.u_mxu_v;\n    nb.u_q = ev.u_q;\n    nb.u_q_v = ev.u_q_frz;\n    nb.u_vpu = ev.u_vpu;\n    nb.u_vpu_v = ev.u_vpu_frz;\n    nb.h = ev.h;\n    nb.h_v = ev.h_v;\n    nb.w = ev.w;\n    nb.w_n = ev.w_n[23:0];\n    nb.w_p = ev.w_p;\n    nb.w_q = ev.w_q;\n  end\n\n  (* ram_style = \"distributed\" *) bnd_t qm [QD];\n  logic [QW-1:0] q_t, q_hd;\n  logic [QW:0]   q_n;\n  wire push = ev_any && q_n < (QW+1)'(QD);\n  always_ff @(posedge clk) if (push) qm[q_t] <= nb;\n  bnd_t qh;\n  assign qh = qm[q_hd];\n\n  // ------------------------------------------------------------------ U: unpacker\n  // a bundle's items, in record order\n  localparam int I_G = 0, I_E = 1, I_S = 17, I_D = 27, I_U1 = 30, I_U2 = 35, I_U3 = 37,\n                 I_H = 39, I_P = 44, I_Q = 54, NI = 61;\n  function automatic logic [NI-1:0] items(input bnd_t b);\n    logic [NI-1:0] m;\n    m = '0;\n    m[I_G] = b.g;\n    for (int i = 0; i < 16; i++) m[I_E + i] = b.e[i];\n    for (int u = 0; u < NUNITS; u++) begin\n      m[I_S + 2 * u] = b.s[u];\n      m[I_S + 2 * u + 1] = b.s[u] && b.s_x[u];\n    end\n    for (int i = 0; i < 3; i++) m[I_D + i] = b.d;\n    for (int i = 0; i < 5; i++) m[I_U1 + i] = b.u_mxu;\n    for (int i = 0; i < 2; i++) m[I_U2 + i] = b.u_q;\n    for (int i = 0; i < 2; i++) m[I_U3 + i] = b.u_vpu;\n    for (int i = 0; i < 1 + NH; i++) m[I_H + i] = b.h;\n    for (int i = 0; i < 1 + NP; i++) m[I_P + i] = b.w;\n    for (int i = 0; i < 1 + NQ; i++) m[I_Q + i] = b.w;\n    return m;\n  endfunction\n\n  // a V record: a counter value\n  function automatic logic [63:0] val(input logic [3:0] idx, input logic [31:0] v);\n    return {T_V, idx, 24'd0, v};\n  endfunction\n\n  bnd_t          cur;                                  // the bundle being unpacked\n  logic [NI-1:0] pend, first;                          // its items left; the next one\n  logic [63:0]   irec [NI];\n  logic [63:0]   rec;\n  assign first = pend & (~pend + 1'b1);\n  wire   last = (pend & (pend - 1'b1)) == '0;          // at most one item left\n  wire   load = last && q_n != 0;\n  always_comb begin\n    for (int i = 0; i < NI; i++) irec[i] = '0;\n    irec[I_G] = {T_G, 4'd0, cur.g_slot, 20'd0, cur.cyc};\n    for (int i = 0; i < 16; i++) irec[I_E + i] = {T_E, 4'd0, 4'(i), 20'd0, cur.cyc};\n    for (int u = 0; u < NUNITS; u++) begin\n      irec[I_S + 2 * u] = {T_S, 4'd0, cur.s_slot[u], 4'(u), cur.s_dt[u], cur.cyc};\n      irec[I_S + 2 * u + 1] = {T_R, 28'd0, cur.s_rdy[u]};\n    end\n    irec[I_D] = {T_D, 4'd0, cur.d_slot, 4'd0, cur.d_pc, cur.cyc};\n    irec[I_D + 1] = {T_O, 7'd0, 1'b0, cur.d_ow[51:0]};\n    irec[I_D + 2] = {T_O, 7'd0, 1'b1, cur.d_ow[103:52]};\n    irec[I_U1] = {T_U, 8'd0, 4'd1, 16'd0, cur.cyc};\n    for (int i = 0; i < 4; i++) irec[I_U1 + 1 + i] = val(4'(i), cur.u_mxu_v[i]);\n    irec[I_U2] = {T_U, 8'd0, 4'd2, 16'd0, cur.cyc};\n    irec[I_U2 + 1] = val(4'd0, cur.u_q_v);\n    irec[I_U3] = {T_U, 8'd0, 4'd3, 16'd0, cur.cyc};\n    irec[I_U3 + 1] = val(4'd0, cur.u_vpu_v);\n    irec[I_H] = {T_H, 28'd0, cur.cyc};\n    for (int i = 0; i < NH; i++) irec[I_H + 1 + i] = val(4'(i), cur.h_v[i]);\n    irec[I_P] = {T_P, 4'd0, cur.w_n, cur.cyc};\n    for (int i = 0; i < NP; i++) irec[I_P + 1 + i] = val(4'(i), cur.w_p[i]);\n    irec[I_Q] = {T_Q, 4'd0, cur.w_n, cur.cyc};\n    for (int i = 0; i < NQ; i++) irec[I_Q + 1 + i] = val(4'(i), cur.w_q[i]);\n    // the next item's record: per bit, an AND-OR over the items (a balanced tree, not a chain)\n    for (int b = 0; b < 64; b++) begin\n      logic [NI-1:0] col;\n      for (int i = 0; i < NI; i++) col[i] = irec[i][b];\n      rec[b] = |(first & col);\n    end\n  end\n\n  // ------------------------------------------------------------------ W: the ring\n  (* ram_style = \"block\" *) logic [63:0] mem [DEPTH];\n  logic          r_v;\n  logic [63:0]   r_rec;\n  logic [LD-1:0] wp;\n  wire           wr = r_v && !stopped;\n  always_ff @(posedge clk) if (wr) mem[wp] <= r_rec;\n  logic [63:0] rd_q;\n  always_ff @(posedge clk) begin\n    rd_q <= mem[raddr[LD-1:0]];\n    rdata <= rd_q;\n  end\n\n  assign busy = (pr_any && pr_en) || ev_any || q_n != 0 || pend != '0 || r_v;\n\n  always_ff @(posedge clk) begin\n    if (rst || clear) begin\n      q_t <= '0; q_hd <= '0; q_n <= '0;\n      pend <= '0; r_v <= 1'b0;\n`ifdef SYNTHESIS\n      wp <= '0; count <= '0;\n`else\n      wp <= cnt0[LD-1:0]; count <= cnt0;\n`endif\n      drop <= '0;\n    end else begin\n      if (push) q_t <= q_t + 1'b1;\n      if (load) begin\n        cur <= qh;\n        pend <= items(qh);\n        q_hd <= q_hd + 1'b1;\n      end else begin\n        pend <= pend & ~first;\n      end\n      q_n <= q_n + (QW+1)'(push) - (QW+1)'(load);\n      if (ev_any && !push) drop <= (drop > ~32'(ev_n)) ? '1 : drop + 32'(ev_n);\n      r_v <= pend != '0;\n      r_rec <= rec;\n      if (wr) begin\n        wp <= wp + 1'b1;\n        count[LD-1:0] <= count[LD-1:0] + 1'b1;\n        if (count[LD-1:0] == '1 && count[31:LD] != '1) count[31:LD] <= count[31:LD] + 1'b1;\n      end\n    end\n  end\n\n`ifndef SYNTHESIS\n  always_ff @(posedge clk)\n    if (!rst && pf.sq.d && pf.sq.d_pc[31:16] != '0)\n      $fatal(1, \"otpu_trace: pc %0d does not fit the D record's 16 bits\", pf.sq.d_pc);\n  // the write slot is count mod DEPTH\n  always_ff @(posedge clk)\n    if (!rst && !clear && wp != count[LD-1:0])\n      $fatal(1, \"otpu_trace: write slot %0d, count %0d\", wp, count);\n`endif\nendmodule\n"});
